function supplier_view_field_label(string $kind, string $name): string
{
  if ($kind === 'standard') {
    $labels = supplier_view_standard_field_labels();
    return (string)($labels[$name] ?? $name);
  }
  if ($kind === 'feature') {
    return 'Фишка';
  }
  if ($kind === 'attr' && $name !== '' && $name[0] !== '@') {
    return '@' . $name;
  }
  return $name;
}

function supplier_view_offer_display_id(string $offerId, string $supplierCode): string
{
