function supplier_view_status_filter_label(string $token): string
{
  $token = trim($token);
  if (str_starts_with($token, 'state:')) {
    $status = substr($token, 6);
    $labels = supplier_view_marketplace_status_labels();
    return (string)($labels[$status] ?? $status);
  }
  if (str_starts_with($token, 'issue:')) {
    return trim(substr($token, 6));
  }
  return $token;
}

function supplier_view_marking_code_required_issue_message(): string
{
  return 'Нужен код маркировки';
}

function supplier_view_marking_code_required_issue_token(): string
{
  return 'issue:' . supplier_view_marking_code_required_issue_message();
}

function supplier_view_normalize_status_message(string $message): string
{
  $message = trim($message);
  if ($message === '') {
    return '';
  }
  $lower = function_exists('mb_strtolower') ? mb_strtolower($message, 'UTF-8') : strtolower($message);

  if (
    str_contains($lower, 'нужен код маркировки')
    || str_contains($lower, 'требуется код маркировки')
    || str_contains($lower, 'нужна маркировка')
  ) {
    return supplier_view_marking_code_required_issue_message();
  }

  if (
    str_contains($lower, 'не удалось объедин')
    || str_contains($lower, 'объединить в похожие товары')
    || str_contains($lower, 'объединить с другими товарами')
  ) {
    return 'ошибка объединения';
  }
  if (preg_match('~ошибка\s+характеристики\s*:\s*(тип|type)\s*$~iu', $message)) {
    return 'ошибка категории';
  }
  if (preg_match('~ошибка\s+характеристики\s*:\s*(название|name|title)\s*$~iu', $message)) {
    return 'ошибка в названии';
  }

  return $message;
}

function supplier_view_normalize_status_filter_token(string $token): string
{
  $token = trim($token);
  if (!str_starts_with($token, 'issue:')) {
    return $token;
  }
  $message = supplier_view_normalize_status_message(substr($token, 6));
  return $message !== '' ? ('issue:' . $message) : '';
}

function supplier_view_ozon_marking_error_from_raw($raw): bool
{
  if (is_string($raw)) {
    $raw = json_decode($raw, true);
  }
  if (!is_array($raw)) {
    return false;
  }

  foreach ((array)($raw['errors'] ?? []) as $error) {
    if (!is_array($error)) {
      continue;
    }
    $code = strtolower(trim((string)($error['code'] ?? '')));
    if (!in_array($code, ['error_attribute_values_empty', 'warning_attribute_values_empty'], true)) {
      continue;
    }
    $texts = is_array($error['texts'] ?? null) ? $error['texts'] : [];
    $attribute = trim((string)($texts['attribute_name'] ?? ''));
    $attribute = function_exists('mb_strtolower') ? mb_strtolower($attribute, 'UTF-8') : strtolower($attribute);
    if (in_array($attribute, ['нужен код маркировки', 'требуется код маркировки'], true)) {
      return true;
    }
  }
  return false;
}

function supplier_view_ozon_marking_error_codes(PDO $pdo, int $connectionId): array
{
  if ($connectionId <= 0) {
    return [];
  }
  $st = $pdo->prepare("
    SELECT offer_id, raw_json
    FROM feedtools_ozon_products
    WHERE connection_id = ?
      AND marketplace_status IN ('error', 'revision')
      AND COALESCE(offer_id, '') <> ''
      AND (
        raw_json LIKE '%Нужен код маркировки%'
        OR raw_json LIKE '%Требуется код маркировки%'
      )
  ");
  $st->execute([$connectionId]);

  $codes = [];
  while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
    if (!supplier_view_ozon_marking_error_from_raw((string)($row['raw_json'] ?? ''))) {
      continue;
    }
    $code = trim((string)($row['offer_id'] ?? ''));
    if ($code !== '') {
      $codes[$code] = true;
    }
  }
  return array_keys($codes);
}

function supplier_view_offer_has_ozon_marking_error(array $offer): bool
{
  if (!in_array((string)($offer['status_ozon'] ?? ''), ['error', 'revision'], true)) {
    return false;
  }
  return in_array(
    supplier_view_marking_code_required_issue_message(),
    supplier_view_status_message_lines((array)($offer['status_ozon_messages'] ?? [])),
    true
  );
}

function supplier_view_status_filter_tokens(string $status, array $messages = []): array
{
  $status = trim($status);
  $messages = supplier_view_status_message_lines($messages);
  $tokens = [];
  if ($status !== '') {
    $tokens[] = 'state:' . $status;
  }
  foreach ($messages as $message) {
    $message = trim((string)$message);
    if ($message !== '') {
      $tokens[] = 'issue:' . $message;
    }
  }
  return array_values(array_unique($tokens));
}

function supplier_view_offer_status_filter_tokens(array $offer, string $marketplace): array
{
  $marketplace = $marketplace === 'wb' ? 'wb' : 'ozon';
  return supplier_view_status_filter_tokens(
    (string)($offer['status_' . $marketplace] ?? ''),
    (array)($offer['status_' . $marketplace . '_messages'] ?? [])
  );
}

function supplier_view_status_filter_matches(array $offer, string $marketplace, ?array $selectedSet): bool
{
  if ($selectedSet === null) {
    return true;
  }
  foreach (supplier_view_offer_status_filter_tokens($offer, $marketplace) as $token) {
    if (isset($selectedSet[$token])) {
      return true;
    }
  }
  return false;
}

function supplier_view_status_filter_sql_supported(?array $selectedSet): bool
{
  if ($selectedSet === null) {
    return true;
  }
  foreach (array_keys($selectedSet) as $token) {
    $token = (string)$token;
    if (!str_starts_with($token, 'state:') && !str_starts_with($token, 'issue:')) {
      return false;
    }
  }
  return true;
}

function supplier_view_add_status_filter_facets(array &$target, string $status, array $messages = []): void
{
  foreach (supplier_view_status_filter_tokens($status, $messages) as $token) {
    $target[$token] = true;
  }
}

function supplier_view_sort_status_filter_tokens(array $tokens): array
{
  $rank = static function (string $token): int {
    if ($token === 'state:ready') return 20;
    if ($token === 'state:revision') return 30;
    if ($token === 'state:error') return 40;
    if ($token === 'state:not_created') return 50;
    if ($token === 'state:auto_archived') return 60;
    if ($token === 'state:archived') return 65;
    if (str_starts_with($token, 'issue:')) return 100;
    return 90;
  };
  usort($tokens, static function ($a, $b) use ($rank) {
    $ra = $rank((string)$a);
    $rb = $rank((string)$b);
    if ($ra !== $rb) {
      return $ra <=> $rb;
    }
    return strcasecmp(supplier_view_status_filter_label((string)$a), supplier_view_status_filter_label((string)$b));
  });
  return $tokens;
}

function supplier_view_default_status_filter_tokens(bool $includeAutoArchived = false): array
{
  $tokens = [
    'state:ready',
    'state:revision',
    'state:error',
    'state:not_created',
    'state:archived',
  ];
  if ($includeAutoArchived) {
    $tokens[] = 'state:auto_archived';
  }
  return supplier_view_sort_status_filter_tokens($tokens);
}

function supplier_view_default_brand_status_filter_tokens(): array
{
  return supplier_view_sort_brand_status_tokens([
    'ok',
    'category_mismatch',
    'not_found',
    'missing_brand',
    'category_not_selected',
  ]);
}

function supplier_view_status_message_lines($messages): array
{
  if (!is_array($messages)) {
    $messages = preg_split('~[\n;]+~u', (string)$messages, -1, PREG_SPLIT_NO_EMPTY) ?: [];
  }
  $out = [];
  foreach ($messages as $message) {
    $message = supplier_view_normalize_status_message((string)$message);
    if ($message !== '') {
      $out[$message] = true;
    }
    if (count($out) >= 8) {
      break;
    }
  }
  return array_keys($out);
}

function supplier_view_marketplace_status_html(string $status, string $title = '', array $messages = [], array $meta = []): string
{
  $status = trim($status);
  if ($status === '') {
    return '<span class="muted">—</span>';
  }
  $labels = supplier_view_marketplace_status_labels();
  $label = (string)($labels[$status] ?? $status);
  $class = str_replace('_', '-', preg_replace('~[^a-z0-9_-]+~i', '-', $status) ?: 'unknown');
  $title = trim(preg_replace('~\s+~u', ' ', $title));
  $titleAttr = $title !== '' ? ' title="' . h($title) . '"' : '';
  $messages = supplier_view_status_message_lines($messages);
  $messageTitles = [];
  if (!empty($meta['message_titles']) && is_array($meta['message_titles'])) {
    foreach ($meta['message_titles'] as $message => $messageTitle) {
      $message = trim((string)$message);
      $messageTitle = trim((string)$messageTitle);
      if ($message !== '' && $messageTitle !== '') {
        $messageTitles[$message] = $messageTitle;
      }
    }
  }
  $qualityScore = null;
  if (array_key_exists('quality_score', $meta) && $meta['quality_score'] !== null && $meta['quality_score'] !== '') {
    $value = is_string($meta['quality_score']) ? str_replace(',', '.', trim($meta['quality_score'])) : $meta['quality_score'];
    if (is_numeric($value)) {
      $qualityScore = max(0.0, min(10.0, round((float)$value, 1)));
    }
  }
  $contentRating = null;
  if (array_key_exists('content_rating', $meta) && $meta['content_rating'] !== null && $meta['content_rating'] !== '') {
    if (function_exists('ozon_products_content_rating_number')) {
      $contentRating = ozon_products_content_rating_number($meta['content_rating']);
    } else {
      $value = is_string($meta['content_rating']) ? str_replace(',', '.', trim($meta['content_rating'])) : $meta['content_rating'];
      if (is_numeric($value)) {
        $contentRating = max(0.0, min(100.0, round((float)$value, 1)));
      }
    }
  }
  $qualityHints = [];
  if (!empty($meta['quality_hints']) && is_array($meta['quality_hints'])) {
    foreach ($meta['quality_hints'] as $hint) {
      $hint = trim((string)$hint);
      if ($hint !== '') {
        $qualityHints[$hint] = true;
      }
      if (count($qualityHints) >= 5) {
        break;
      }
    }
  }
  if ($messages || $qualityScore !== null || $contentRating !== null || $qualityHints) {
    $html = '<div class="supplier-market-status-stack">';
    if ($status !== 'error' || !$messages) {
      $statusTooltip = $title !== '' ? ($label . "\n" . $title) : $label;
      $html .= '<span class="supplier-market-status supplier-market-status--' . h($class) . '" title="' . h($statusTooltip) . '">' . h($label) . '</span>';
    }
    if ($qualityScore !== null) {
      $scoreLabel = rtrim(rtrim(number_format($qualityScore, 1, '.', ''), '0'), '.');
      $html .= '<span class="supplier-market-status supplier-market-status--quality" title="' . h('Рейтинг качества карточки WB: ' . $scoreLabel) . '">' . h('качество ' . $scoreLabel) . '</span>';
    }
    if ($contentRating !== null) {
      $scoreLabel = rtrim(rtrim(number_format($contentRating, 1, '.', ''), '0'), '.');
      $html .= '<span class="supplier-market-status supplier-market-status--content-rating" title="' . h('Контент-рейтинг Ozon: ' . $scoreLabel) . '">' . h('контент ' . $scoreLabel) . '</span>';
    }
    if ($qualityHints) {
      $hintLabels = array_keys($qualityHints);
      $hintText = 'улучшить: ' . implode(', ', $hintLabels);
      $hintTitle = 'Что улучшить для рейтинга: ' . implode(', ', $hintLabels);
      $html .= '<span class="supplier-market-status supplier-market-status--quality-hints" title="' . h($hintTitle) . '">' . h($hintText) . '</span>';
    }
    foreach ($messages as $message) {
      $messageTitle = $messageTitles[$message] ?? $message;
      $issueClass = isset($messageTitles[$message]) ? ' supplier-market-status--quality-rec' : '';
      $html .= '<span class="supplier-market-status supplier-market-status--' . h($class) . ' supplier-market-status--issue' . $issueClass . '" title="' . h($messageTitle) . '">' . h($message) . '</span>';
    }
    $html .= '</div>';
    return $html;
  }
  return '<span class="supplier-market-status supplier-market-status--' . h($class) . '"' . $titleAttr . '>' . h($label) . '</span>';
}

function supplier_view_brand_statuses_html(array $statuses): string
{
  $sources = [
    'ozon' => 'Ozon',
    'wb' => 'WB',
  ];
  $html = '<div class="supplier-brand-statuses" data-brand-statuses>';
  foreach ($sources as $source => $sourceLabel) {
    $row = $statuses[$source] ?? null;
    $badge = '<span class="muted">—</span>';
    if (!is_array($row)) {
      $html .= '<div class="supplier-brand-cell-section" data-brand-status-section="' . h($source) . '"><div class="supplier-brand-cell-label">' . h($sourceLabel) . '</div><div class="supplier-brand-status-slot" data-brand-status-slot="' . h($source) . '">' . $badge . '</div></div>';
      continue;
    }
    $status = trim((string)($row['status'] ?? ''));
    $label = trim((string)($row['label'] ?? marketplace_brand_status_label($status)));
    if ($status !== '' && $label !== '') {
      $class = str_replace('_', '-', preg_replace('~[^a-z0-9_-]+~i', '-', $status) ?: 'unknown');
      $badge = '<span class="supplier-brand-status supplier-brand-status--' . h($class) . '" data-brand-status-source="' . h($source) . '" data-brand-status="' . h($status) . '">' . h($label) . '</span>';
    }
    $html .= '<div class="supplier-brand-cell-section" data-brand-status-section="' . h($source) . '"><div class="supplier-brand-cell-label">' . h($sourceLabel) . '</div><div class="supplier-brand-status-slot" data-brand-status-slot="' . h($source) . '">' . $badge . '</div></div>';
  }
  return $html . '</div>';
}

function supplier_view_brand_status_slot_html(array $statuses, string $source): string
{
  $row = $statuses[$source] ?? null;
  if (!is_array($row)) {
    return '<div class="supplier-brand-status-slot" data-brand-status-slot="' . h($source) . '"><span class="muted">—</span></div>';
  }
  $status = trim((string)($row['status'] ?? ''));
  $label = trim((string)($row['label'] ?? marketplace_brand_status_label($status)));
  if ($status === '' || $label === '') {
    return '<div class="supplier-brand-status-slot" data-brand-status-slot="' . h($source) . '"><span class="muted">—</span></div>';
  }
  $class = str_replace('_', '-', preg_replace('~[^a-z0-9_-]+~i', '-', $status) ?: 'unknown');
  return '<div class="supplier-brand-status-slot" data-brand-status-slot="' . h($source) . '"><span class="supplier-brand-status supplier-brand-status--' . h($class) . '" data-brand-status-source="' . h($source) . '" data-brand-status="' . h($status) . '">' . h($label) . '</span></div>';
}

function supplier_view_apply_brand_statuses(array &$offers): void
{
  if (!$offers) {
    return;
  }

  $products = [];
  foreach ($offers as $idx => $offer) {
    if (!is_array($offer)) {
      continue;
    }
    $products[$idx] = [
      'brand' => (string)($offer['brand_effective'] ?? ''),
      'brand_ozon' => (string)($offer['brand_ozon_effective'] ?? ($offer['brand_effective'] ?? '')),
      'brand_wb' => (string)($offer['brand_wb_effective'] ?? ($offer['brand_effective'] ?? '')),
      'ozon_category' => (string)($offer['ozon_category'] ?? ''),
      'wb_category' => (string)($offer['wb_category'] ?? ($offer['wb_subject_id'] ?? '')),
    ];
  }

  $statuses = marketplace_brand_status_for_products($products);
  foreach ($offers as $idx => &$offer) {
    $offer['brand_statuses'] = (array)($statuses[$idx] ?? []);
  }
  unset($offer);
}

function supplier_view_brand_status_value(array $offer, string $source): string
{
  $source = $source === 'wb' ? 'wb' : 'ozon';
  $row = (array)(($offer['brand_statuses'] ?? [])[$source] ?? []);
  return trim((string)($row['status'] ?? ''));
}

function supplier_view_sort_brand_status_tokens(array $tokens): array
{
  $rank = static function (string $token): int {
    return [
      'ok' => 10,
      'category_mismatch' => 20,
      'not_found' => 30,
      'missing_brand' => 40,
      'category_not_selected' => 50,
    ][$token] ?? 90;
  };
  $tokens = array_values(array_unique(array_filter(array_map('strval', $tokens), static fn(string $v): bool => trim($v) !== '')));
  usort($tokens, static function ($a, $b) use ($rank) {
    $ra = $rank((string)$a);
    $rb = $rank((string)$b);
    if ($ra !== $rb) {
      return $ra <=> $rb;
    }
    return strcasecmp(marketplace_brand_status_label((string)$a), marketplace_brand_status_label((string)$b));
  });
  return $tokens;
}

function supplier_view_offer_marketplace_candidates(array $offer, string $supplierCode): array
{
  $candidates = [];
  foreach ([
    (string)($offer['id'] ?? ''),
    supplier_view_offer_display_id((string)($offer['id'] ?? ''), $supplierCode),
    (string)($offer['article'] ?? ''),
    (string)($offer['vendorCode'] ?? ''),
    (string)($offer['vendor_code'] ?? ''),
  ] as $candidate) {
    $candidate = trim($candidate);
    if ($candidate !== '') {
      $candidates[$candidate] = true;
    }
  }
  return array_keys($candidates);
}

function supplier_view_marketplace_status_query_map(PDO $pdo, string $sql, array $ids): array
{
  $map = [];
  $ids = array_values(array_unique(array_filter(array_map('strval', $ids), static fn(string $id): bool => trim($id) !== '')));
  foreach (array_chunk($ids, 1000) as $chunk) {
    $placeholders = implode(',', array_fill(0, count($chunk), '?'));
    $st = $pdo->prepare(str_replace('__IDS__', $placeholders, $sql));
    $st->execute($chunk);
    while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
      $key = trim((string)($row['_key'] ?? ''));
      if ($key !== '') {
        $map[$key] = $row;
      }
    }
  }
  return $map;
}

function supplier_view_analytics_int($value): string
{
  return number_format((int)round((float)$value), 0, '.', ' ');
}

function supplier_view_analytics_pct($value): string
{
  if ($value === null || $value === '') {
    return '—';
  }
  $formatted = number_format((float)$value, 1, '.', ' ');
  $formatted = preg_replace('~\.0$~', '', $formatted) ?? $formatted;
  return $formatted . '%';
}

function supplier_view_analytics_period_label(string $dateFrom, string $dateTo): string
{
  $from = DateTimeImmutable::createFromFormat('!Y-m-d', trim($dateFrom));
  $to = DateTimeImmutable::createFromFormat('!Y-m-d', trim($dateTo));
  if ($from instanceof DateTimeImmutable && $to instanceof DateTimeImmutable) {
    return $from->format('d.m.y') . '-' . $to->format('d.m.y');
  }
  if ($dateFrom !== '' && $dateTo !== '') {
    return $dateFrom . '-' . $dateTo;
  }
  return 'последние 90 дней';
}

function supplier_view_ozon_analytics_date_to(int $connectionId): string
{
  if ($connectionId <= 0) {
    return date('Y-m-d', strtotime('yesterday'));
  }
  try {
    $st = db()->prepare("
      SELECT MAX(analytics_date)
      FROM feedtools_ozon_product_analytics_daily
      WHERE connection_id = ?
    ");
    $st->execute([$connectionId]);
    $date = trim((string)($st->fetchColumn() ?: ''));
    if (preg_match('~^\d{4}-\d{2}-\d{2}$~', $date)) {
      return $date;
    }
  } catch (Throwable) {
    // Use yesterday when analytics tables are not ready yet.
  }
  return date('Y-m-d', strtotime('yesterday'));
}

function supplier_view_default_ozon_analytics(string $dateFrom, string $dateTo): array
{
  return [
    'has_data' => false,
    'rows_count' => 0,
    'date_from' => $dateFrom,
    'date_to' => $dateTo,
    'hits_view' => 0,
    'session_view_pdp' => 0,
    'cancellations_count' => 0,
    'ordered_units' => 0,
    'view_to_card_pct' => null,
    'card_to_order_pct' => null,
    'cancellation_pct' => null,
  ];
}

function supplier_view_ozon_analytics_map_for_ids(int $ozonConnectionId, array $ids, string $dateFrom, string $dateTo): array
{
  if ($ozonConnectionId <= 0 || !$ids) {
    return [];
  }

  $ids = array_values(array_unique(array_filter(array_map(
    static fn($value): string => trim((string)$value),
    $ids
  ), static fn(string $value): bool => $value !== '')));
  if (!$ids) {
    return [];
  }

  $map = [];
  foreach (array_chunk($ids, 1000) as $chunk) {
    $placeholders = implode(',', array_fill(0, count($chunk), '?'));
    $sql = "
      SELECT
        offer_id,
        COUNT(*) AS rows_count,
        MIN(analytics_date) AS date_from,
        MAX(analytics_date) AS date_to,
        SUM(COALESCE(hits_view,0)) AS hits_view,
        SUM(COALESCE(session_view_pdp,0)) AS session_view_pdp,
        SUM(COALESCE(cancellations_count,0)) AS cancellations_count,
        SUM(COALESCE(ordered_units,0)) AS ordered_units
      FROM feedtools_ozon_product_analytics_daily
      WHERE connection_id = ?
        AND analytics_date BETWEEN ? AND ?
        AND offer_id IN ({$placeholders})
      GROUP BY offer_id
    ";
    $st = db()->prepare($sql);
    $st->execute(array_merge([$ozonConnectionId, $dateFrom, $dateTo], $chunk));
    while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
      $offerId = trim((string)($row['offer_id'] ?? ''));
      if ($offerId === '') {
        continue;
      }
      $hitsView = (int)($row['hits_view'] ?? 0);
      $sessionViewPdp = (int)($row['session_view_pdp'] ?? 0);
      $cancellationsCount = (int)($row['cancellations_count'] ?? 0);
      $orderedUnits = (int)($row['ordered_units'] ?? 0);
      $map[$offerId] = [
        'has_data' => ((int)($row['rows_count'] ?? 0)) > 0,
        'rows_count' => (int)($row['rows_count'] ?? 0),
        'date_from' => (string)($row['date_from'] ?? $dateFrom),
        'date_to' => (string)($row['date_to'] ?? $dateTo),
        'hits_view' => $hitsView,
        'session_view_pdp' => $sessionViewPdp,
        'cancellations_count' => $cancellationsCount,
        'ordered_units' => $orderedUnits,
        'view_to_card_pct' => $hitsView > 0 ? ($sessionViewPdp / $hitsView) * 100 : null,
        'card_to_order_pct' => $sessionViewPdp > 0 ? ($orderedUnits / $sessionViewPdp) * 100 : null,
        'cancellation_pct' => $orderedUnits > 0 ? ($cancellationsCount / $orderedUnits) * 100 : null,
      ];
    }
  }

  return $map;
}

function supplier_view_apply_ozon_analytics(array &$offers, int $ozonConnectionId, string $supplierCode, array $cfg): void
{
  if (!$offers || $ozonConnectionId <= 0 || !function_exists('ozon_analytics_tables_ensure')) {
    return;
  }

  try {
    ozon_analytics_tables_ensure($cfg);
  } catch (Throwable) {
    return;
  }

  $dateTo = supplier_view_ozon_analytics_date_to($ozonConnectionId);
  $dateFrom = date('Y-m-d', strtotime($dateTo . ' -89 days'));
  $defaultAnalytics = supplier_view_default_ozon_analytics($dateFrom, $dateTo);

  $offerCandidates = [];
  $allIds = [];
  foreach ($offers as $idx => $offer) {
    if (!is_array($offer)) {
      continue;
    }
    $ids = supplier_view_offer_marketplace_candidates($offer, $supplierCode);
    $offerCandidates[$idx] = $ids;
    foreach ($ids as $id) {
      $allIds[$id] = true;
    }
    $offers[$idx]['ozon_analytics_90d'] = $defaultAnalytics;
  }

  $allIds = array_keys($allIds);
  if (!$allIds) {
    return;
  }

  $map = supplier_view_ozon_analytics_map_for_ids($ozonConnectionId, $allIds, $dateFrom, $dateTo);

  foreach ($offers as $idx => &$offer) {
    foreach (($offerCandidates[$idx] ?? []) as $id) {
      if (isset($map[$id])) {
        $offer['ozon_analytics_90d'] = $map[$id];
        break;
      }
    }
  }
  unset($offer);
}

function supplier_view_ozon_analytics_filter_bounds(int $supplierId, int $ozonConnectionId, string $supplierCode, array $cfg): array
{
  $bounds = [
    'date_from' => '',
    'date_to' => '',
    'hits_view_max' => 1,
    'ordered_units_max' => 1,
    'view_to_card_pct_max' => 100.0,
    'card_to_order_pct_max' => 100.0,
  ];
  if ($supplierId <= 0 || $ozonConnectionId <= 0 || !function_exists('ozon_analytics_tables_ensure')) {
    return $bounds;
  }

  try {
    ozon_analytics_tables_ensure($cfg);
    $dateTo = supplier_view_ozon_analytics_date_to($ozonConnectionId);
    $dateFrom = date('Y-m-d', strtotime($dateTo . ' -89 days'));
    $bounds['date_from'] = $dateFrom;
    $bounds['date_to'] = $dateTo;

    $stamp = supplier_view_supplier_products_cache_stamp($supplierId)
      . ':ozon_analytics_bounds:' . $ozonConnectionId
      . ':supplier:' . md5($supplierCode)
      . ':date_to:' . $dateTo;
    $cacheKey = 'ozon_analytics_bounds_' . $supplierId . '_' . md5($stamp);
    $cached = supplier_view_cache_read($cacheKey, $stamp, 300);
    if (is_array($cached)) {
      return array_merge($bounds, $cached);
    }

    $ids = [];
    $st = db()->prepare("
      SELECT offer_id, vendor_code
      FROM feedtools_supplier_products
      WHERE supplier_id = ?
    ");
    $st->execute([$supplierId]);
    while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
      foreach ([
        (string)($row['offer_id'] ?? ''),
        supplier_view_offer_display_id((string)($row['offer_id'] ?? ''), $supplierCode),
        (string)($row['vendor_code'] ?? ''),
        supplier_view_offer_display_id((string)($row['vendor_code'] ?? ''), $supplierCode),
      ] as $id) {
        $id = trim($id);
        if ($id !== '') {
          $ids[$id] = true;
        }
      }
    }

    $map = supplier_view_ozon_analytics_map_for_ids($ozonConnectionId, array_keys($ids), $dateFrom, $dateTo);
    foreach ($map as $analytics) {
      $bounds['hits_view_max'] = max((int)$bounds['hits_view_max'], (int)($analytics['hits_view'] ?? 0));
      $bounds['ordered_units_max'] = max((int)$bounds['ordered_units_max'], (int)($analytics['ordered_units'] ?? 0));
      if (($analytics['view_to_card_pct'] ?? null) !== null) {
        $bounds['view_to_card_pct_max'] = max((float)$bounds['view_to_card_pct_max'], (float)$analytics['view_to_card_pct']);
      }
      if (($analytics['card_to_order_pct'] ?? null) !== null) {
        $bounds['card_to_order_pct_max'] = max((float)$bounds['card_to_order_pct_max'], (float)$analytics['card_to_order_pct']);
      }
    }
  } catch (Throwable) {
    return $bounds;
  }

  $bounds['hits_view_max'] = max(1, (int)ceil((float)$bounds['hits_view_max']));
  $bounds['ordered_units_max'] = max(1, (int)ceil((float)$bounds['ordered_units_max']));
  $bounds['view_to_card_pct_max'] = max(100.0, min(1000.0, ceil((float)$bounds['view_to_card_pct_max'] * 10) / 10));
  $bounds['card_to_order_pct_max'] = max(100.0, min(1000.0, ceil((float)$bounds['card_to_order_pct_max'] * 10) / 10));
  if (isset($cacheKey, $stamp)) {
    supplier_view_cache_write($cacheKey, $stamp, $bounds);
  }
  return $bounds;
}

function supplier_view_ozon_analytics_filter_value(array $offer, string $metric)
{
  $analytics = $offer['ozon_analytics_90d'] ?? null;
  if (!is_array($analytics)) {
    if ($metric === 'hits_view' || $metric === 'ordered_units') {
      return 0;
    }
    return null;
  }
  if ($metric === 'hits_view' || $metric === 'ordered_units') {
    return (int)($analytics[$metric] ?? 0);
  }
  if ($metric === 'view_to_card_pct' || $metric === 'card_to_order_pct') {
    return array_key_exists($metric, $analytics) && $analytics[$metric] !== null ? (float)$analytics[$metric] : null;
  }
  return null;
}

function supplier_view_analytics_filter_matches(array $offer, string $metric, ?float $min, ?float $max): bool
{
  if ($min === null && $max === null) {
    return true;
  }
  $value = supplier_view_ozon_analytics_filter_value($offer, $metric);
  if ($value === null) {
    return false;
  }
  if ($min !== null && (float)$value < $min) {
    return false;
  }
  if ($max !== null && (float)$value > $max) {
    return false;
  }
  return true;
}

function supplier_view_ozon_analytics_html(array $offer): string
{
  $analytics = $offer['ozon_analytics_90d'] ?? null;
  if (!is_array($analytics)) {
    return '';
  }

  $dateFrom = trim((string)($analytics['date_from'] ?? ''));
  $dateTo = trim((string)($analytics['date_to'] ?? ''));
  $period = ($dateFrom !== '' && $dateTo !== '') ? ($dateFrom . ' - ' . $dateTo) : 'последние 90 дней';
  $periodLabel = supplier_view_analytics_period_label($dateFrom, $dateTo);
  $hitsView = (int)($analytics['hits_view'] ?? 0);
  $sessionViewPdp = (int)($analytics['session_view_pdp'] ?? 0);
  $orderedUnits = (int)($analytics['ordered_units'] ?? 0);
  $cancellationsCount = (int)($analytics['cancellations_count'] ?? 0);
  $viewToCard = $analytics['view_to_card_pct'] ?? null;
  $cardToOrder = $analytics['card_to_order_pct'] ?? null;
  $cancellationPct = $analytics['cancellation_pct'] ?? null;
  $hasData = !empty($analytics['has_data']);

  $title = 'Аналитика Ozon за ' . $period
    . "\nПоказы: " . supplier_view_analytics_int($hitsView)
    . "\nПереходы в карточку: " . supplier_view_analytics_int($sessionViewPdp)
    . "\nПродажи: " . supplier_view_analytics_int($orderedUnits)
    . "\nКонверсия из просмотра в карточку: " . supplier_view_analytics_pct($viewToCard)
    . "\nКонверсия из карточки в заказ: " . supplier_view_analytics_pct($cardToOrder)
    . "\nОтмены: " . supplier_view_analytics_int($cancellationsCount)
    . "\nПроцент отмен: " . supplier_view_analytics_pct($cancellationPct);

  $html = '<div class="supplier-ozon-analytics' . ($hasData ? '' : ' is-empty') . '" title="' . h($title) . '">';
  $html .= '<div class="supplier-analytics-period"><span>период</span><strong>' . h($periodLabel) . '</strong></div>';
  $html .= '<div><span>показы</span><strong>' . h(supplier_view_analytics_int($hitsView)) . '</strong></div>';
  $html .= '<div><span>переходы</span><strong>' . h(supplier_view_analytics_int($sessionViewPdp)) . '</strong></div>';
  $html .= '<div><span>продажи</span><strong>' . h(supplier_view_analytics_int($orderedUnits)) . '</strong></div>';
  $html .= '<div><span>в карточку</span><strong>' . h(supplier_view_analytics_pct($viewToCard)) . '</strong></div>';
  $html .= '<div><span>в заказ</span><strong>' . h(supplier_view_analytics_pct($cardToOrder)) . '</strong></div>';
  $html .= '<div><span>отмены</span><strong>' . h(supplier_view_analytics_pct($cancellationPct)) . '</strong></div>';
  $html .= '</div>';
  return $html;
}

function supplier_view_wb_analytics_date_to(int $connectionId): string
{
  if ($connectionId <= 0) {
    return date('Y-m-d', strtotime('yesterday'));
  }
  $dates = [];
  try {
    $st = db()->prepare("
      SELECT MAX(analytics_date)
      FROM feedtools_wb_product_analytics_daily
      WHERE connection_id = ?
    ");
    $st->execute([$connectionId]);
    $date = trim((string)($st->fetchColumn() ?: ''));
    if (preg_match('~^\d{4}-\d{2}-\d{2}$~', $date)) {
      $dates[] = $date;
    }
  } catch (Throwable) {
    // Use yesterday when analytics tables are not ready yet.
  }
  try {
    $st = db()->prepare("
      SELECT MAX(date_to)
      FROM feedtools_wb_product_search_analytics_period
      WHERE connection_id = ?
    ");
    $st->execute([$connectionId]);
    $date = trim((string)($st->fetchColumn() ?: ''));
    if (preg_match('~^\d{4}-\d{2}-\d{2}$~', $date)) {
      $dates[] = $date;
    }
  } catch (Throwable) {
    // Search analytics is optional; the daily report date is enough when it exists.
  }
  if ($dates) {
    rsort($dates);
    return (string)$dates[0];
  }
  return date('Y-m-d', strtotime('yesterday'));
}

function supplier_view_default_wb_analytics(string $dateFrom, string $dateTo): array
{
  return [
    'has_data' => false,
    'rows_count' => 0,
    'date_from' => $dateFrom,
    'date_to' => $dateTo,
    'open_card_count' => 0,
    'add_to_cart_count' => 0,
    'orders_count' => 0,
    'buyouts_count' => 0,
    'cancel_count' => 0,
    'card_to_cart_pct' => null,
    'card_to_order_pct' => null,
    'cart_to_order_pct' => null,
    'buyout_pct' => null,
    'cancellation_pct' => null,
    'search_visibility' => null,
    'search_open_card_count' => 0,
    'search_avg_position' => null,
  ];
}

function supplier_view_wb_analytics_map_for_ids(int $wbConnectionId, array $ids, string $dateFrom, string $dateTo): array
{
  if ($wbConnectionId <= 0 || !$ids) {
    return [];
  }

  $ids = array_values(array_unique(array_filter(array_map(
    static fn($value): string => trim((string)$value),
    $ids
  ), static fn(string $value): bool => $value !== '')));
  if (!$ids) {
    return [];
  }

  $map = [];
  foreach (array_chunk($ids, 1000) as $chunk) {
    $placeholders = implode(',', array_fill(0, count($chunk), '?'));
    $sql = "
      SELECT
        vendor_code,
        COUNT(*) AS rows_count,
        MIN(analytics_date) AS date_from,
        MAX(analytics_date) AS date_to,
        SUM(COALESCE(open_card_count,0)) AS open_card_count,
        SUM(COALESCE(add_to_cart_count,0)) AS add_to_cart_count,
        SUM(COALESCE(orders_count,0)) AS orders_count,
        SUM(COALESCE(buyouts_count,0)) AS buyouts_count,
        SUM(COALESCE(cancel_count,0)) AS cancel_count
      FROM feedtools_wb_product_analytics_daily
      WHERE connection_id = ?
        AND analytics_date BETWEEN ? AND ?
        AND vendor_code IN ({$placeholders})
      GROUP BY vendor_code
    ";
    $st = db()->prepare($sql);
    $st->execute(array_merge([$wbConnectionId, $dateFrom, $dateTo], $chunk));
    while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
      $vendorCode = trim((string)($row['vendor_code'] ?? ''));
      if ($vendorCode === '') {
        continue;
      }
      $openCards = (int)($row['open_card_count'] ?? 0);
      $cartCount = (int)($row['add_to_cart_count'] ?? 0);
      $ordersCount = (int)($row['orders_count'] ?? 0);
      $buyoutsCount = (int)($row['buyouts_count'] ?? 0);
      $cancelCount = (int)($row['cancel_count'] ?? 0);
      $map[$vendorCode] = [
        'has_data' => ((int)($row['rows_count'] ?? 0)) > 0,
        'rows_count' => (int)($row['rows_count'] ?? 0),
        'date_from' => (string)($row['date_from'] ?? $dateFrom),
        'date_to' => (string)($row['date_to'] ?? $dateTo),
        'open_card_count' => $openCards,
        'add_to_cart_count' => $cartCount,
        'orders_count' => $ordersCount,
        'buyouts_count' => $buyoutsCount,
        'cancel_count' => $cancelCount,
        'card_to_cart_pct' => $openCards > 0 ? ($cartCount / $openCards) * 100 : null,
        'card_to_order_pct' => $openCards > 0 ? ($ordersCount / $openCards) * 100 : null,
        'cart_to_order_pct' => $cartCount > 0 ? ($ordersCount / $cartCount) * 100 : null,
        'buyout_pct' => $ordersCount > 0 ? ($buyoutsCount / $ordersCount) * 100 : null,
        'cancellation_pct' => $ordersCount > 0 ? ($cancelCount / $ordersCount) * 100 : null,
      ];
    }
  }

  if (function_exists('wb_analytics_search_period_map_for_vendors')) {
    try {
      $searchMap = wb_analytics_search_period_map_for_vendors($wbConnectionId, $ids, $dateFrom, $dateTo);
      foreach ($searchMap as $vendorCode => $searchRow) {
        if (!is_array($searchRow)) {
          continue;
        }
        if (!isset($map[$vendorCode])) {
          $map[$vendorCode] = [
            'has_data' => true,
            'rows_count' => 0,
            'date_from' => $dateFrom,
            'date_to' => $dateTo,
            'open_card_count' => 0,
            'add_to_cart_count' => 0,
            'orders_count' => 0,
            'buyouts_count' => 0,
            'cancel_count' => 0,
            'card_to_cart_pct' => null,
            'card_to_order_pct' => null,
            'cart_to_order_pct' => null,
            'buyout_pct' => null,
            'cancellation_pct' => null,
          ];
        }
        $map[$vendorCode]['search_visibility'] = $searchRow['search_visibility'] ?? null;
        $map[$vendorCode]['search_open_card_count'] = (int)($searchRow['search_open_card_count'] ?? 0);
        $map[$vendorCode]['search_avg_position'] = $searchRow['search_avg_position'] ?? null;
        $map[$vendorCode]['has_data'] = true;
      }
    } catch (Throwable) {
      // Offers table should stay fast even if optional search analytics is not ready.
    }
  }

  return $map;
}

function supplier_view_apply_wb_analytics(array &$offers, int $wbConnectionId, string $supplierCode, array $cfg): void
{
  if (!$offers || $wbConnectionId <= 0 || !function_exists('wb_analytics_tables_ensure')) {
    return;
  }

  try {
    wb_analytics_tables_ensure($cfg);
  } catch (Throwable) {
    return;
  }

  $dateTo = supplier_view_wb_analytics_date_to($wbConnectionId);
  $dateFrom = date('Y-m-d', strtotime($dateTo . ' -89 days'));
  $defaultAnalytics = supplier_view_default_wb_analytics($dateFrom, $dateTo);

  $offerCandidates = [];
  $allIds = [];
  foreach ($offers as $idx => $offer) {
    if (!is_array($offer)) {
      continue;
    }
    $ids = supplier_view_offer_marketplace_candidates($offer, $supplierCode);
    $offerCandidates[$idx] = $ids;
    foreach ($ids as $id) {
      $allIds[$id] = true;
    }
    $offers[$idx]['wb_analytics_90d'] = $defaultAnalytics;
  }

  $allIds = array_keys($allIds);
  if (!$allIds) {
    return;
  }

  $map = supplier_view_wb_analytics_map_for_ids($wbConnectionId, $allIds, $dateFrom, $dateTo);

  foreach ($offers as $idx => &$offer) {
    foreach (($offerCandidates[$idx] ?? []) as $id) {
      if (isset($map[$id])) {
        $offer['wb_analytics_90d'] = $map[$id];
        break;
      }
    }
  }
  unset($offer);
}

function supplier_view_wb_analytics_dataset_summary(int $supplierId, int $wbConnectionId, string $supplierCode, array $cfg): array
{
  $summary = [
    'date_from' => '',
    'date_to' => '',
    'total_offers' => 0,
    'with_any_data' => 0,
    'with_daily_data' => 0,
    'with_search_data' => 0,
  ];
  if ($supplierId <= 0 || $wbConnectionId <= 0 || !function_exists('wb_analytics_tables_ensure')) {
    return $summary;
  }

  try {
    wb_analytics_tables_ensure($cfg);
    $dateTo = supplier_view_wb_analytics_date_to($wbConnectionId);
    $dateFrom = date('Y-m-d', strtotime($dateTo . ' -89 days'));
    $summary['date_from'] = $dateFrom;
    $summary['date_to'] = $dateTo;

    $stamp = supplier_view_supplier_products_cache_stamp($supplierId)
      . ':wb_analytics_dataset_summary:' . $wbConnectionId
      . ':supplier:' . md5($supplierCode)
      . ':date_to:' . $dateTo;
    $cacheKey = 'wb_analytics_dataset_summary_' . $supplierId . '_' . md5($stamp);
    $cached = supplier_view_cache_read($cacheKey, $stamp, 300);
    if (is_array($cached)) {
      return array_merge($summary, $cached);
    }

    $offerCandidates = [];
    $allIds = [];
    $st = db()->prepare("
      SELECT offer_id, vendor_code
      FROM feedtools_supplier_products
      WHERE supplier_id = ?
    ");
    $st->execute([$supplierId]);
    while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
      $offer = [
        'id' => (string)($row['offer_id'] ?? ''),
        'article' => (string)($row['vendor_code'] ?? ''),
        'vendorCode' => (string)($row['vendor_code'] ?? ''),
        'vendor_code' => (string)($row['vendor_code'] ?? ''),
      ];
      $candidates = supplier_view_offer_marketplace_candidates($offer, $supplierCode);
      $offerCandidates[] = $candidates;
      foreach ($candidates as $candidate) {
        $allIds[$candidate] = true;
      }
    }

    $summary['total_offers'] = count($offerCandidates);
    $map = supplier_view_wb_analytics_map_for_ids($wbConnectionId, array_keys($allIds), $dateFrom, $dateTo);
    foreach ($offerCandidates as $candidates) {
      $matched = null;
      foreach ($candidates as $candidate) {
        if (isset($map[$candidate]) && is_array($map[$candidate])) {
          $matched = $map[$candidate];
          break;
        }
      }
      if (!$matched) {
        continue;
      }

      $hasDaily = ((int)($matched['rows_count'] ?? 0)) > 0;
      $hasSearch = ($matched['search_visibility'] ?? null) !== null
        || ($matched['search_avg_position'] ?? null) !== null
        || ((int)($matched['search_open_card_count'] ?? 0)) > 0;
      if ($hasDaily || $hasSearch) {
        $summary['with_any_data']++;
      }
      if ($hasDaily) {
        $summary['with_daily_data']++;
      }
      if ($hasSearch) {
        $summary['with_search_data']++;
      }
    }

    supplier_view_cache_write($cacheKey, $stamp, $summary);
  } catch (Throwable) {
    return $summary;
  }

  return $summary;
}

function supplier_view_wb_analytics_html(array $offer): string
{
  $analytics = $offer['wb_analytics_90d'] ?? null;
  if (!is_array($analytics)) {
    return '';
  }

  $dateFrom = trim((string)($analytics['date_from'] ?? ''));
  $dateTo = trim((string)($analytics['date_to'] ?? ''));
  $period = ($dateFrom !== '' && $dateTo !== '') ? ($dateFrom . ' - ' . $dateTo) : 'последние 90 дней';
  $periodLabel = supplier_view_analytics_period_label($dateFrom, $dateTo);
  $openCards = (int)($analytics['open_card_count'] ?? 0);
  $cartCount = (int)($analytics['add_to_cart_count'] ?? 0);
  $ordersCount = (int)($analytics['orders_count'] ?? 0);
  $buyoutsCount = (int)($analytics['buyouts_count'] ?? 0);
  $cancelCount = (int)($analytics['cancel_count'] ?? 0);
  $searchVisibility = $analytics['search_visibility'] ?? null;
  $searchOpenCards = (int)($analytics['search_open_card_count'] ?? 0);
  $searchAvgPosition = $analytics['search_avg_position'] ?? null;
  $cardToCart = $analytics['card_to_cart_pct'] ?? null;
  $cardToOrder = $analytics['card_to_order_pct'] ?? null;
  $buyoutPct = $analytics['buyout_pct'] ?? null;
  $cancellationPct = $analytics['cancellation_pct'] ?? null;
  $hasData = !empty($analytics['has_data']);

  $title = 'Аналитика WB за ' . $period
    . "\nПереходы в карточку: " . supplier_view_analytics_int($openCards)
    . "\nВидимость WB: " . supplier_view_analytics_pct($searchVisibility)
    . "\nПереходы из поиска: " . supplier_view_analytics_int($searchOpenCards)
    . "\nСредняя позиция: " . ($searchAvgPosition === null || $searchAvgPosition === '' ? '-' : number_format((float)$searchAvgPosition, 1, '.', ' '))
    . "\nВ корзину: " . supplier_view_analytics_int($cartCount)
    . "\nЗаказы: " . supplier_view_analytics_int($ordersCount)
    . "\nВыкупы: " . supplier_view_analytics_int($buyoutsCount)
    . "\nКонверсия из карточки в корзину: " . supplier_view_analytics_pct($cardToCart)
    . "\nКонверсия из карточки в заказ: " . supplier_view_analytics_pct($cardToOrder)
    . "\nПроцент выкупа: " . supplier_view_analytics_pct($buyoutPct)
    . "\nОтмены: " . supplier_view_analytics_int($cancelCount)
    . "\nПроцент отмен: " . supplier_view_analytics_pct($cancellationPct);

  if (!$hasData) {
    return '<div class="supplier-analytics-empty supplier-wb-analytics-empty" title="' . h($title) . '">нет данных WB<span class="supplier-analytics-empty-period">за ' . h($periodLabel) . '</span></div>';
  }

  $html = '<div class="supplier-ozon-analytics supplier-wb-analytics' . ($hasData ? '' : ' is-empty') . '" title="' . h($title) . '">';
  $html .= '<div class="supplier-analytics-period"><span>период</span><strong>' . h($periodLabel) . '</strong></div>';
  $html .= '<div><span>переходы</span><strong>' . h(supplier_view_analytics_int($openCards)) . '</strong></div>';
  $html .= '<div><span>видимость</span><strong>' . h(supplier_view_analytics_pct($searchVisibility)) . '</strong></div>';
  $html .= '<div><span>из поиска</span><strong>' . h(supplier_view_analytics_int($searchOpenCards)) . '</strong></div>';
  $html .= '<div><span>корзина</span><strong>' . h(supplier_view_analytics_int($cartCount)) . '</strong></div>';
  $html .= '<div><span>заказы</span><strong>' . h(supplier_view_analytics_int($ordersCount)) . '</strong></div>';
  $html .= '<div><span>выкупы</span><strong>' . h(supplier_view_analytics_int($buyoutsCount)) . '</strong></div>';
  $html .= '<div><span>в заказ</span><strong>' . h(supplier_view_analytics_pct($cardToOrder)) . '</strong></div>';
  $html .= '<div><span>выкуп</span><strong>' . h(supplier_view_analytics_pct($buyoutPct)) . '</strong></div>';
  $html .= '<div><span>отмены</span><strong>' . h(supplier_view_analytics_pct($cancellationPct)) . '</strong></div>';
  $html .= '</div>';
  return $html;
}

function supplier_view_ozon_status_from_row(array $row): string
{
  $status = trim((string)($row['marketplace_status'] ?? ''));
  $isArchived = (int)($row['is_archived'] ?? 0) === 1 || in_array($status, ['archived', 'auto_archived'], true);
  $isAutoArchived = (int)($row['is_autoarchived'] ?? 0) === 1
    || $status === 'auto_archived'
    || ($isArchived && function_exists('ozon_products_autoarchive_marker') && ozon_products_autoarchive_marker($row));
  if ($isArchived && $isAutoArchived) {
    return 'auto_archived';
  }
  if ($status !== '') {
    return $status;
  }
  if ($isArchived) {
    return 'archived';
  }
  if ((int)($row['is_active'] ?? 0) === 1) {
    return 'ready';
  }
  return 'not_created';
}

function supplier_view_wb_status_from_row(array $row): string
{
  $status = trim((string)($row['marketplace_status'] ?? ''));
  if ($status !== '') {
    return $status;
  }
  if ((int)($row['is_trash'] ?? 0) === 1) {
    return 'archived';
  }
  if ((int)($row['is_active'] ?? 0) === 1) {
    return 'ready';
  }
  return 'not_created';
}

function supplier_view_ozon_issue_messages(array $row): array
{
  $raw = trim((string)($row['raw_json'] ?? ''));
  if ($raw !== '') {
    $decoded = json_decode($raw, true);
    if (is_array($decoded) && function_exists('ozon_products_error_labels')) {
      $labels = ozon_products_error_labels($decoded);
      if ($labels) {
        return supplier_view_status_message_lines($labels);
      }
    }
  }

  $text = trim((string)($row['status_description'] ?? ''));
  if ($text !== '') {
    return supplier_view_status_message_lines($text);
  }
  return [];
}

function supplier_view_wb_issue_messages(array $row): array
{
  $text = trim((string)($row['status_text'] ?? ''));
  if ($text !== '' && function_exists('wb_products_issue_labels_from_text')) {
    $labels = wb_products_issue_labels_from_text($text);
    if ($labels) {
      return supplier_view_status_message_lines($labels);
    }
  }
  if ($text !== '') {
    return supplier_view_status_message_lines($text);
  }
  return [];
}

function supplier_view_wb_quality_decode_recommendations($value): array
{
  if (is_string($value)) {
    $value = trim($value);
    if ($value === '') {
      return [];
    }
    $decoded = json_decode($value, true);
    $value = is_array($decoded) ? $decoded : [];
  }
  if (!is_array($value)) {
    return [];
  }

  $out = [];
  foreach ($value as $item) {
    if (is_string($item)) {
      $item = ['text' => $item];
    }
    if (!is_array($item)) {
      continue;
    }
    if (function_exists('wb_products_quality_recommendation')) {
      $item = wb_products_quality_recommendation($item);
    }
    $text = trim((string)($item['text'] ?? ''));
    if ($text === '') {
      continue;
    }
    $out[] = [
      'type' => trim((string)($item['type'] ?? 'content')),
      'label' => trim((string)($item['label'] ?? 'Контент')),
      'short' => trim((string)($item['short'] ?? 'улучшить')),
      'text' => $text,
      'comment' => trim((string)($item['comment'] ?? '')),
    ];
  }
  if (function_exists('wb_products_quality_deduplicate_recommendations')) {
    return wb_products_quality_deduplicate_recommendations($out);
  }
  return array_slice($out, 0, 12);
}

function supplier_view_wb_quality_score($value): ?float
{
  if (function_exists('wb_products_quality_number')) {
    return wb_products_quality_number($value);
  }
  if (is_string($value)) {
    $value = str_replace(',', '.', trim($value));
  }
  if (!is_numeric($value)) {
    return null;
  }
  return max(0.0, min(10.0, round((float)$value, 1)));
}

function supplier_view_ozon_content_rating(array $row): ?float
{
  if (array_key_exists('content_rating', $row) && $row['content_rating'] !== null && $row['content_rating'] !== '') {
    if (function_exists('ozon_products_content_rating_number')) {
      $rating = ozon_products_content_rating_number($row['content_rating']);
      if ($rating !== null) {
        return $rating;
      }
    }
    $value = is_string($row['content_rating']) ? str_replace(',', '.', trim($row['content_rating'])) : $row['content_rating'];
    if (is_numeric($value)) {
      return max(0.0, min(100.0, round((float)$value, 1)));
    }
  }

  $raw = trim((string)($row['raw_json'] ?? ''));
  if ($raw !== '' && function_exists('ozon_products_content_rating_from_raw')) {
    return ozon_products_content_rating_from_raw($raw, false);
  }
  return null;
}

function supplier_view_ozon_quality_decode_recommendations($value): array
{
  if (is_string($value)) {
    $value = trim($value);
    if ($value === '') {
      return [];
    }
    $decoded = json_decode($value, true);
    $value = is_array($decoded) ? $decoded : [];
  }
  if (!is_array($value)) {
    return [];
  }
  if (function_exists('ozon_products_content_rating_deduplicate_recommendations')) {
    return ozon_products_content_rating_deduplicate_recommendations($value);
  }
  return array_slice($value, 0, 12);
}

function supplier_view_ozon_quality_payload(array $row): array
{
  $score = supplier_view_ozon_content_rating($row);
  $recommendations = supplier_view_ozon_quality_decode_recommendations($row['content_rating_recommendations_json'] ?? null);

  $raw = trim((string)($row['raw_json'] ?? ''));
  if (!$recommendations && $raw !== '' && function_exists('ozon_products_content_rating_recommendations_from_raw')) {
    $recommendations = supplier_view_ozon_quality_decode_recommendations(
      ozon_products_content_rating_recommendations_from_raw($raw)
    );
  }

  return [
    'score' => $score,
    'recommendations' => $recommendations,
  ];
}

function supplier_view_quality_hint_label_from_text(string $text, string $type = ''): string
{
  if (function_exists('ozon_products_content_rating_recommendation_type')) {
    [$normalizedType] = ozon_products_content_rating_recommendation_type($text, $type);
    $normalizedLabels = [
      'photo' => 'фото',
      'video' => 'видео',
      'characteristics' => 'характеристики',
      'rich' => 'rich контент',
      'name' => 'название',
      'description' => 'описание',
      'brand' => 'бренд',
    ];
    if (isset($normalizedLabels[$normalizedType])) {
      return $normalizedLabels[$normalizedType];
    }
  }

  $lower = function_exists('mb_strtolower') ? mb_strtolower($text . ' ' . $type, 'UTF-8') : strtolower($text . ' ' . $type);
  $contains = static function (array $needles) use ($lower): bool {
    foreach ($needles as $needle) {
      $needle = (string)$needle;
      if ($needle !== '' && str_contains($lower, $needle)) {
        return true;
      }
    }
    return false;
  };

  if ($contains(['rich', 'рич'])) {
    return 'rich контент';
  }
  if ($contains(['видео', 'video'])) {
    return 'видео';
  }
  if ($contains(['фото', 'изображ', 'картин', 'photo', 'image', 'picture', 'media', 'cover', 'облож'])) {
    return 'фото';
  }
  if ($contains(['характерист', 'атрибут', 'параметр', 'attribute', 'characteristic', 'param', 'spec'])) {
    return 'характеристики';
  }
  if ($contains(['назван', 'наимен', 'title', 'name'])) {
    return 'название';
  }
  if ($contains(['описан', 'аннотац', 'description', 'annotation'])) {
    return 'описание';
  }
  if ($contains(['бренд', 'brand'])) {
    return 'бренд';
  }
  return '';
}

function supplier_view_quality_hint_filter_defs(): array
{
  return [
    'photo' => 'фото',
    'video' => 'видео',
    'characteristics' => 'характеристики',
    'rich' => 'rich контент',
    'name' => 'название',
    'description' => 'описание',
    'brand' => 'бренд',
  ];
}

function supplier_view_quality_hint_filter_key(string $value): string
{
  $value = trim($value);
  if ($value === '') {
    return '';
  }
  $defs = supplier_view_quality_hint_filter_defs();
  if (isset($defs[$value])) {
    return $value;
  }
  $normalizedLabel = supplier_view_quality_hint_label_from_text($value);
  if ($normalizedLabel !== '') {
    foreach ($defs as $key => $label) {
      if ($normalizedLabel === $label) {
        return $key;
      }
    }
  }

  $lower = function_exists('mb_strtolower') ? mb_strtolower($value, 'UTF-8') : strtolower($value);
  $map = [
    'rich' => ['rich', 'рич'],
    'video' => ['видео', 'video'],
    'photo' => ['фото', 'изображ', 'картин', 'photo', 'image', 'picture', 'media', 'cover', 'облож'],
    'characteristics' => ['характерист', 'атрибут', 'параметр', 'attribute', 'characteristic', 'param', 'spec'],
    'name' => ['назван', 'наимен', 'title', 'name'],
    'description' => ['описан', 'аннотац', 'description', 'annotation'],
    'brand' => ['бренд', 'brand'],
  ];
  foreach ($map as $key => $needles) {
    foreach ($needles as $needle) {
      if ($needle !== '' && str_contains($lower, $needle)) {
        return $key;
      }
    }
  }
  return '';
}

function supplier_view_quality_hint_filter_keys_from_labels(array $labels): array
{
  $out = [];
  foreach ($labels as $label) {
    $key = supplier_view_quality_hint_filter_key((string)$label);
    if ($key !== '') {
      $out[$key] = true;
    }
  }
  return array_keys($out);
}

function supplier_view_quality_hint_filter_matches(array $offer, ?array $selectedSet): bool
{
  if ($selectedSet === null) {
    return true;
  }
  $keys = array_fill_keys(array_merge(
    supplier_view_quality_hint_filter_keys_from_labels((array)($offer['status_ozon_quality_hints'] ?? [])),
    supplier_view_quality_hint_filter_keys_from_labels((array)($offer['status_wb_quality_hints'] ?? []))
  ), true);
  foreach (array_keys($selectedSet) as $selectedKey) {
    if (!isset($keys[$selectedKey])) {
      return false;
    }
  }
  return true;
}

function supplier_view_marketplace_key_collation(string $marketplace): string
{
  return $marketplace === 'ozon' ? 'utf8mb4_general_ci' : 'utf8mb4_unicode_ci';
}

function supplier_view_collate_sql_expr(string $expr, string $collation): string
{
  $collation = preg_replace('~[^a-zA-Z0-9_]+~', '', $collation);
  if ($collation === '') {
    return $expr;
  }
  return '(' . $expr . ') COLLATE ' . $collation;
}

function supplier_view_quality_hint_sql_fragments(string $key): array
{
  return [
    'photo' => ['"type":"photo"', '"type": "photo"', 'Фото', 'фото', 'Изображ', 'изображ', 'Картин', 'картин', 'photo', 'image', 'picture', 'media', 'cover', 'облож'],
    'video' => ['"type":"video"', '"type": "video"', 'Видео', 'видео', 'video'],
    'characteristics' => ['"type":"characteristics"', '"type": "characteristics"', 'improve_attributes', 'Характерист', 'характерист', 'Атрибут', 'атрибут', 'Параметр', 'параметр', 'attribute', 'characteristic', 'param', 'spec', 'Название цвета', 'название цвета', 'Подходит для', 'подходит для'],
    'rich' => ['"type":"rich"', '"type": "rich"', 'Rich', 'rich', 'Рич', 'рич'],
    'name' => ['"type":"name"', '"type": "name"', '"type":"title"', '"type": "title"', '"label":"Название"', '"label": "Название"', '"short":"название"', '"short": "название"'],
    'description' => ['"type":"description"', '"type": "description"', 'Описание', 'описание', 'Аннотац', 'аннотац', 'description', 'annotation'],
    'brand' => ['"type":"brand"', '"type": "brand"', 'Бренд', 'бренд', 'brand'],
  ][$key] ?? [];
}

function supplier_view_quality_hint_marketplace_codes(PDO $pdo, string $marketplace, int $connectionId, array $fragments): array
{
  if ($connectionId <= 0 || !$fragments) {
    return [];
  }

  if ($marketplace === 'ozon') {
    $table = 'feedtools_ozon_products';
    $keyColumn = 'offer_id';
    $recommendationsColumn = 'content_rating_recommendations_json';
    if (function_exists('ozon_products_table_has_column') && !ozon_products_table_has_column($pdo, $table, $recommendationsColumn)) {
      return [];
    }
  } elseif ($marketplace === 'wb') {
    $table = 'feedtools_wb_products';
    $keyColumn = 'vendor_code';
    $recommendationsColumn = 'quality_recommendations_json';
    if (function_exists('wb_products_table_has_column') && !wb_products_table_has_column($pdo, $table, $recommendationsColumn)) {
      return [];
    }
  } else {
    return [];
  }

  $where = [];
  $args = [$connectionId];
  foreach ($fragments as $fragment) {
    $fragment = trim((string)$fragment);
    if ($fragment === '') {
      continue;
    }
    $where[] = "{$recommendationsColumn} LIKE ? ESCAPE '\\\\'";
    $args[] = '%' . str_replace(['\\', '%', '_'], ['\\\\', '\\%', '\\_'], $fragment) . '%';
  }
  if (!$where) {
    return [];
  }

  $st = $pdo->prepare("
    SELECT DISTINCT {$keyColumn} AS code
    FROM {$table}
    WHERE connection_id = ?
      AND COALESCE({$recommendationsColumn}, '') <> ''
      AND (" . implode(' OR ', $where) . ")
  ");
  $st->execute($args);

  $codes = [];
  while (($code = $st->fetchColumn()) !== false) {
    $code = trim((string)$code);
    if ($code !== '') {
      $codes[$code] = true;
    }
  }
  return array_keys($codes);
}

function supplier_view_marketplace_code_temp_table(PDO $pdo, array $codes, string $supplierCode, string $prefix = 'tmp_ft_market_codes', bool $includeBaseCode = true): ?string
{
  $normalized = [];
  $suffix = trim($supplierCode) !== '' ? '__' . trim($supplierCode) : '';
  $suffixLen = strlen($suffix);
  foreach ($codes as $code) {
    $code = trim((string)$code);
    if ($code === '') {
      continue;
    }
    $code = function_exists('mb_substr') ? mb_substr($code, 0, 255, 'UTF-8') : substr($code, 0, 255);
    $normalized[$code] = true;
    if ($includeBaseCode && $suffix !== '' && str_ends_with($code, $suffix)) {
      $baseCode = substr($code, 0, -$suffixLen);
      $baseCode = trim((string)$baseCode);
      if ($baseCode !== '') {
        $normalized[$baseCode] = true;
      }
    }
  }

  $codes = array_keys($normalized);
  if (!$codes) {
    return null;
  }

  static $counter = 0;
  $counter++;
  $prefix = preg_replace('~[^a-zA-Z0-9_]+~', '_', $prefix);
  if ($prefix === '') {
    $prefix = 'tmp_ft_market_codes';
  }
  $prefix = substr($prefix, 0, 48);
  $tableName = $prefix . '_' . bin2hex(random_bytes(4)) . '_' . $counter;
  $quotedTable = '`' . $tableName . '`';

  $pdo->exec("
    CREATE TEMPORARY TABLE {$quotedTable} (
      code VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
      PRIMARY KEY (code)
    ) ENGINE=InnoDB
  ");

  foreach (array_chunk($codes, 500) as $chunk) {
    $placeholders = implode(',', array_fill(0, count($chunk), '(?)'));
    $st = $pdo->prepare("INSERT IGNORE INTO {$quotedTable} (code) VALUES {$placeholders}");
    $st->execute(array_values($chunk));
  }

  return $quotedTable;
}

function supplier_view_quality_hint_temp_table(PDO $pdo, array $codes, string $supplierCode): ?string
{
  return supplier_view_marketplace_code_temp_table($pdo, $codes, $supplierCode, 'tmp_ft_quality_codes');
}

function supplier_view_marketplace_resolved_status_sql(string $alias, string $marketplace): string
{
  $alias = preg_replace('~[^a-zA-Z0-9_]+~', '', $alias);
  if ($alias === '') {
    $alias = 'm';
  }
  $archiveColumn = $marketplace === 'wb' ? 'is_trash' : 'is_archived';
  if ($marketplace !== 'wb') {
    return "CASE
      WHEN COALESCE({$alias}.{$archiveColumn}, 0) = 1 AND COALESCE({$alias}.is_autoarchived, 0) = 1 THEN 'auto_archived'
      WHEN COALESCE({$alias}.marketplace_status, '') = 'auto_archived' THEN 'auto_archived'
      WHEN COALESCE({$alias}.marketplace_status, '') <> '' THEN {$alias}.marketplace_status
      WHEN COALESCE({$alias}.{$archiveColumn}, 0) = 1 THEN 'archived'
      WHEN COALESCE({$alias}.is_active, 0) = 1 THEN 'ready'
      ELSE 'not_created'
    END";
  }
  return "CASE
      WHEN COALESCE({$alias}.marketplace_status, '') <> '' THEN {$alias}.marketplace_status
      WHEN COALESCE({$alias}.{$archiveColumn}, 0) = 1 THEN 'archived'
      WHEN COALESCE({$alias}.is_active, 0) = 1 THEN 'ready'
      ELSE 'not_created'
    END";
}

function supplier_view_marketplace_status_codes(PDO $pdo, string $marketplace, int $connectionId, array $states): array
{
  if ($connectionId <= 0 || !$states) {
    return [];
  }

  $isWb = $marketplace === 'wb';
  $table = $isWb ? 'feedtools_wb_products' : 'feedtools_ozon_products';
  $keyColumn = $isWb ? 'vendor_code' : 'offer_id';
  $resolvedStatusSql = supplier_view_marketplace_resolved_status_sql('m', $isWb ? 'wb' : 'ozon');
  $placeholders = implode(',', array_fill(0, count($states), '?'));
  $args = array_merge([$connectionId], array_values($states));

  $st = $pdo->prepare("
    SELECT DISTINCT m.{$keyColumn} AS code
    FROM {$table} m
    WHERE m.connection_id = ?
      AND COALESCE(m.{$keyColumn}, '') <> ''
      AND {$resolvedStatusSql} IN ({$placeholders})
  ");
  $st->execute($args);

  $codes = [];
  while (($code = $st->fetchColumn()) !== false) {
    $code = trim((string)$code);
    if ($code !== '') {
      $codes[$code] = true;
    }
  }
  return array_keys($codes);
}

function supplier_view_status_issue_set(array $issues): array
{
  $set = [];
  foreach ($issues as $issue) {
