      $message = trim((string)$message);
      if ($message !== '') {
        $set[$message] = true;
      }
    }
  }
  return $set;
}

function supplier_view_marketplace_issue_scan(PDO $pdo, string $marketplace, int $connectionId, ?array $issueSet = null, ?array $allowedCodeSet = null): array
{
  if ($connectionId <= 0) {
    return ['codes' => [], 'tokens' => []];
  }

  $isWb = $marketplace === 'wb';
  if ($isWb) {
    $sql = "
      SELECT vendor_code AS code, status_text, raw_json
      FROM feedtools_wb_products
      WHERE connection_id = ?
        AND COALESCE(vendor_code, '') <> ''
        AND (
          COALESCE(marketplace_status, '') IN ('error', 'revision')
          OR COALESCE(status_text, '') <> ''
        )
    ";
  } elseif ($marketplace === 'ozon') {
    $sql = "
      SELECT offer_id AS code, status_description, raw_json
      FROM feedtools_ozon_products
      WHERE connection_id = ?
        AND COALESCE(offer_id, '') <> ''
        AND COALESCE(marketplace_status, '') IN ('error', 'revision')
    ";
  } else {
    return ['codes' => [], 'tokens' => []];
  }

  $codes = [];
  $tokens = [];
  $st = $pdo->prepare($sql);
  $st->execute([$connectionId]);
  while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
    $code = trim((string)($row['code'] ?? ''));
    if ($code === '') {
      continue;
    }
    if ($allowedCodeSet !== null && !isset($allowedCodeSet[$code])) {
      continue;
    }

    $messages = $isWb ? supplier_view_wb_issue_messages($row) : supplier_view_ozon_issue_messages($row);
    $matched = false;
    foreach ($messages as $message) {
      $message = trim((string)$message);
      if ($message === '') {
        continue;
      }
      $tokens['issue:' . $message] = true;
      if ($issueSet !== null && isset($issueSet[$message])) {
        $matched = true;
      }
    }
    if ($issueSet !== null && $matched) {
      $codes[$code] = true;
    }
  }

  return [
    'codes' => array_keys($codes),
    'tokens' => array_keys($tokens),
  ];
}

function supplier_view_marketplace_issue_codes(PDO $pdo, string $marketplace, int $connectionId, array $issues): array
{
  $issueSet = supplier_view_status_issue_set($issues);
  if (!$issueSet) {
    return [];
  }
  $scan = supplier_view_marketplace_issue_scan($pdo, $marketplace, $connectionId, $issueSet);
  return (array)($scan['codes'] ?? []);
}

function supplier_view_marketplace_issue_tokens(PDO $pdo, string $marketplace, int $connectionId, ?array $allowedCodeSet = null): array
{
  $scan = supplier_view_marketplace_issue_scan($pdo, $marketplace, $connectionId, null, $allowedCodeSet);
  return supplier_view_sort_status_filter_tokens((array)($scan['tokens'] ?? []));
}

function supplier_view_marketplace_present_codes(PDO $pdo, string $marketplace, int $connectionId): array
{
  if ($connectionId <= 0) {
    return [];
  }

  $isWb = $marketplace === 'wb';
  $table = $isWb ? 'feedtools_wb_products' : 'feedtools_ozon_products';
  $keyColumn = $isWb ? 'vendor_code' : 'offer_id';

  $st = $pdo->prepare("
    SELECT DISTINCT {$keyColumn} AS code
    FROM {$table}
    WHERE connection_id = ?
      AND COALESCE({$keyColumn}, '') <> ''
  ");
  $st->execute([$connectionId]);

  $codes = [];
  while (($code = $st->fetchColumn()) !== false) {
    $code = trim((string)$code);
    if ($code !== '') {
      $codes[$code] = true;
    }
  }
  return array_keys($codes);
}

function supplier_view_product_id_temp_table(PDO $pdo, string $prefix = 'tmp_ft_product_ids'): string
{
  static $counter = 0;
  $counter++;
  $prefix = preg_replace('~[^a-zA-Z0-9_]+~', '_', $prefix);
  if ($prefix === '') {
    $prefix = 'tmp_ft_product_ids';
  }
  $prefix = substr($prefix, 0, 48);
  $tableName = $prefix . '_' . bin2hex(random_bytes(4)) . '_' . $counter;
  $quotedTable = '`' . $tableName . '`';

  $pdo->exec("
    CREATE TEMPORARY TABLE {$quotedTable} (
      product_id BIGINT UNSIGNED NOT NULL,
      PRIMARY KEY (product_id)
    ) ENGINE=InnoDB
  ");

  return $quotedTable;
}

function supplier_view_marketplace_status_product_ids_temp_table(PDO $pdo, int $supplierId, string $marketplace, int $connectionId, array $states, string $supplierCode, array $issues = []): ?string
{
  if ($supplierId <= 0 || $connectionId <= 0 || (!$states && !$issues)) {
    return null;
  }

  $productTmpTable = supplier_view_product_id_temp_table($pdo, 'tmp_ft_' . $marketplace . '_status_product_ids');

  if (isset($states['not_created'])) {
    $presentCodes = supplier_view_marketplace_present_codes($pdo, $marketplace, $connectionId);
    $presentTmpTable = supplier_view_marketplace_code_temp_table($pdo, $presentCodes, $supplierCode, 'tmp_ft_' . $marketplace . '_present_codes');
    if ($presentTmpTable !== null) {
      $st = $pdo->prepare("
        INSERT IGNORE INTO {$productTmpTable} (product_id)
        SELECT p.id
        FROM feedtools_supplier_products p
        LEFT JOIN {$presentTmpTable} sp_offer ON sp_offer.code = p.offer_id
        LEFT JOIN {$presentTmpTable} sp_vendor ON sp_vendor.code = p.vendor_code AND COALESCE(p.vendor_code, '') <> ''
        WHERE p.supplier_id = ?
          AND sp_offer.code IS NULL
          AND sp_vendor.code IS NULL
      ");
      $st->execute([$supplierId]);
    } else {
      $st = $pdo->prepare("
        INSERT IGNORE INTO {$productTmpTable} (product_id)
        SELECT p.id
        FROM feedtools_supplier_products p
        WHERE p.supplier_id = ?
      ");
      $st->execute([$supplierId]);
    }
  }

  $stateValues = array_keys($states);
  if ($stateValues) {
    $statusCodes = supplier_view_marketplace_status_codes($pdo, $marketplace, $connectionId, $stateValues);
    $statusTmpTable = supplier_view_marketplace_code_temp_table($pdo, $statusCodes, $supplierCode, 'tmp_ft_' . $marketplace . '_status_codes');
    if ($statusTmpTable !== null) {
      $st = $pdo->prepare("
        INSERT IGNORE INTO {$productTmpTable} (product_id)
        SELECT p.id
        FROM feedtools_supplier_products p
        JOIN {$statusTmpTable} ss_offer ON ss_offer.code = p.offer_id
        WHERE p.supplier_id = ?
      ");
      $st->execute([$supplierId]);

      $st = $pdo->prepare("
        INSERT IGNORE INTO {$productTmpTable} (product_id)
        SELECT p.id
        FROM feedtools_supplier_products p
        JOIN {$statusTmpTable} ss_vendor ON ss_vendor.code = p.vendor_code
        WHERE p.supplier_id = ?
          AND COALESCE(p.vendor_code, '') <> ''
      ");
      $st->execute([$supplierId]);
    }
  }

  $issueValues = array_keys($issues);
  if ($issueValues) {
    $issueCodes = supplier_view_marketplace_issue_codes($pdo, $marketplace, $connectionId, $issueValues);
    $issueTmpTable = supplier_view_marketplace_code_temp_table($pdo, $issueCodes, $supplierCode, 'tmp_ft_' . $marketplace . '_issue_codes');
    if ($issueTmpTable !== null) {
      $st = $pdo->prepare("
        INSERT IGNORE INTO {$productTmpTable} (product_id)
        SELECT p.id
        FROM feedtools_supplier_products p
        JOIN {$issueTmpTable} si_offer ON si_offer.code = p.offer_id
        WHERE p.supplier_id = ?
      ");
      $st->execute([$supplierId]);

      $st = $pdo->prepare("
        INSERT IGNORE INTO {$productTmpTable} (product_id)
        SELECT p.id
        FROM feedtools_supplier_products p
        JOIN {$issueTmpTable} si_vendor ON si_vendor.code = p.vendor_code
        WHERE p.supplier_id = ?
          AND COALESCE(p.vendor_code, '') <> ''
      ");
      $st->execute([$supplierId]);
    }
  }

  $count = (int)$pdo->query("SELECT COUNT(*) FROM {$productTmpTable}")->fetchColumn();
  return $count > 0 ? $productTmpTable : null;
}

function supplier_view_quality_hint_labels(array $recommendations): array
{
  $out = [];
  foreach ($recommendations as $recommendation) {
    if (is_string($recommendation)) {
      $recommendation = ['text' => $recommendation];
    }
    if (!is_array($recommendation)) {
      continue;
    }
    $type = trim((string)($recommendation['type'] ?? ''));
    $text = trim(implode(' ', array_filter([
      (string)($recommendation['label'] ?? ''),
      (string)($recommendation['short'] ?? ''),
      (string)($recommendation['text'] ?? ''),
      (string)($recommendation['comment'] ?? ''),
    ], static fn($value): bool => trim((string)$value) !== '')));
    $label = supplier_view_quality_hint_label_from_text($text, $type);
    if ($label === '') {
      $fallback = trim((string)($recommendation['label'] ?? ($recommendation['short'] ?? '')));
      if ($fallback !== '') {
        $fallback = function_exists('mb_strtolower') ? mb_strtolower($fallback, 'UTF-8') : strtolower($fallback);
        $label = function_exists('mb_substr') ? mb_substr($fallback, 0, 24, 'UTF-8') : substr($fallback, 0, 24);
      }
    }
    if ($label !== '') {
      $out[$label] = true;
    }
    if (count($out) >= 5) {
      break;
    }
  }
  return array_keys($out);
}

function supplier_view_wb_quality_payload(array $row): array
{
  $score = supplier_view_wb_quality_score($row['quality_score'] ?? null);
  $recommendations = supplier_view_wb_quality_decode_recommendations($row['quality_recommendations_json'] ?? null);

  $raw = trim((string)($row['raw_json'] ?? ''));
  if (($score === null || !$recommendations) && $raw !== '' && function_exists('wb_products_card_quality_summary')) {
    $decoded = json_decode($raw, true);
    if (is_array($decoded)) {
      $summary = wb_products_card_quality_summary($decoded, (string)($row['status_text'] ?? ''));
      if ($score === null) {
        $score = supplier_view_wb_quality_score($summary['score'] ?? null);
      }
      if (!$recommendations) {
        $recommendations = supplier_view_wb_quality_decode_recommendations($summary['recommendations'] ?? []);
      }
    }
  }

  return [
    'score' => $score,
    'recommendations' => $recommendations,
  ];
}

function supplier_view_wb_quality_message(array $recommendation): string
{
  $label = trim((string)($recommendation['label'] ?? 'Контент'));
  $short = trim((string)($recommendation['short'] ?? 'улучшить'));
  if ($label === '') {
    $label = 'Контент';
  }
  if ($short === '') {
    $short = 'улучшить';
  }
  return $label . ': ' . $short;
}

function supplier_view_wb_quality_messages(array $recommendations): array
{
  $messages = [];
  foreach ($recommendations as $recommendation) {
    if (!is_array($recommendation)) {
      continue;
    }
    $message = supplier_view_wb_quality_message($recommendation);
    if ($message !== '') {
      $messages[$message] = true;
    }
  }
  return array_keys($messages);
}

function supplier_view_wb_quality_message_titles(array $recommendations): array
{
  $titles = [];
  foreach ($recommendations as $recommendation) {
    if (!is_array($recommendation)) {
      continue;
    }
    $message = supplier_view_wb_quality_message($recommendation);
    $text = trim((string)($recommendation['text'] ?? ''));
    $comment = trim((string)($recommendation['comment'] ?? ''));
    if ($message === '' || $text === '') {
      continue;
    }
    $titles[$message] = $comment !== '' ? ($text . "\n" . $comment) : $text;
  }
  return $titles;
}

function supplier_view_apply_marketplace_statuses(array &$offers, int $ozonConnectionId, int $wbConnectionId, string $supplierCode): void
{
  if (!$offers) {
    return;
  }
  $pdo = db();
  $offerCandidates = [];
  $allIds = [];
  foreach ($offers as $idx => $offer) {
    if (!is_array($offer)) {
      continue;
    }
    $ids = supplier_view_offer_marketplace_candidates($offer, $supplierCode);
    $offerCandidates[$idx] = $ids;
    foreach ($ids as $id) {
      $allIds[$id] = true;
    }
  }
  $allIds = array_keys($allIds);

  $ozonMap = [];
  if ($ozonConnectionId > 0 && $allIds) {
    $ozonContentRatingSelect = (function_exists('ozon_products_table_has_column') && ozon_products_table_has_column($pdo, 'feedtools_ozon_products', 'content_rating'))
      ? 'content_rating'
      : 'NULL AS content_rating';
    $ozonContentRatingRecommendationsSelect = (function_exists('ozon_products_table_has_column') && ozon_products_table_has_column($pdo, 'feedtools_ozon_products', 'content_rating_recommendations_json'))
      ? 'content_rating_recommendations_json'
      : 'NULL AS content_rating_recommendations_json';
    $ozonAutoArchivedSelect = (function_exists('ozon_products_table_has_column') && ozon_products_table_has_column($pdo, 'feedtools_ozon_products', 'is_autoarchived'))
      ? 'is_autoarchived'
      : '0 AS is_autoarchived';
    $ozonMap = supplier_view_marketplace_status_query_map($pdo, "
      SELECT
        offer_id AS _key,
        marketplace_status,
        status_name,
        status_description,
        {$ozonContentRatingSelect},
        {$ozonContentRatingRecommendationsSelect},
        raw_json,
        is_active,
        is_archived,
        {$ozonAutoArchivedSelect}
      FROM feedtools_ozon_products
      WHERE connection_id = {$ozonConnectionId} AND offer_id IN (__IDS__)
    ", $allIds);
  }

  $wbMap = [];
  if ($wbConnectionId > 0 && $allIds) {
    $wbQualityScoreSelect = (function_exists('wb_products_table_has_column') && wb_products_table_has_column($pdo, 'feedtools_wb_products', 'quality_score'))
      ? 'quality_score'
      : 'NULL AS quality_score';
    $wbQualityRecommendationsSelect = (function_exists('wb_products_table_has_column') && wb_products_table_has_column($pdo, 'feedtools_wb_products', 'quality_recommendations_json'))
      ? 'quality_recommendations_json'
      : 'NULL AS quality_recommendations_json';
    $wbMap = supplier_view_marketplace_status_query_map($pdo, "
      SELECT
        vendor_code AS _key,
        marketplace_status,
        status_text,
        {$wbQualityScoreSelect},
        {$wbQualityRecommendationsSelect},
        raw_json,
        is_active,
        is_trash
      FROM feedtools_wb_products
      WHERE connection_id = {$wbConnectionId} AND vendor_code IN (__IDS__)
    ", $allIds);
  }

  foreach ($offers as $idx => &$offer) {
    $ids = $offerCandidates[$idx] ?? [];
    if ($ozonConnectionId > 0) {
      $row = null;
      foreach ($ids as $id) {
        if (isset($ozonMap[$id])) {
          $row = $ozonMap[$id];
          break;
        }
      }
      if (is_array($row)) {
        $ozonQuality = supplier_view_ozon_quality_payload($row);
        $messages = supplier_view_ozon_issue_messages($row);
        $offer['status_ozon'] = in_array('ошибка объединения', $messages, true) ? 'error' : supplier_view_ozon_status_from_row($row);
        $offer['status_ozon_title'] = trim((string)($row['status_name'] ?? '') . ' ' . (string)($row['status_description'] ?? ''));
        $offer['status_ozon_messages'] = $messages;
        $offer['status_ozon_content_rating'] = $ozonQuality['score'] ?? null;
        $offer['status_ozon_quality_hints'] = supplier_view_quality_hint_labels((array)($ozonQuality['recommendations'] ?? []));
        $offer['status_ozon_characteristic_error_names'] = supplier_view_marketplace_characteristic_error_names_from_row($row, 'ozon');
      } else {
        $offer['status_ozon'] = 'not_created';
        $offer['status_ozon_title'] = '';
        $offer['status_ozon_messages'] = [];
        $offer['status_ozon_content_rating'] = null;
        $offer['status_ozon_quality_hints'] = [];
        $offer['status_ozon_characteristic_error_names'] = [];
      }
    }
    if ($wbConnectionId > 0) {
      $row = null;
      foreach ($ids as $id) {
        if (isset($wbMap[$id])) {
          $row = $wbMap[$id];
          break;
        }
      }
      if (is_array($row)) {
        $quality = supplier_view_wb_quality_payload($row);
        $messages = supplier_view_status_message_lines(supplier_view_wb_issue_messages($row));
        $offer['status_wb'] = in_array('ошибка объединения', $messages, true) ? 'error' : supplier_view_wb_status_from_row($row);
        $offer['status_wb_title'] = trim((string)($row['status_text'] ?? ''));
        $offer['status_wb_messages'] = $messages;
        $offer['status_wb_quality_score'] = $quality['score'] ?? null;
        $offer['status_wb_quality_hints'] = supplier_view_quality_hint_labels((array)($quality['recommendations'] ?? []));
        $offer['status_wb_message_titles'] = supplier_view_wb_quality_message_titles((array)($quality['recommendations'] ?? []));
        $offer['status_wb_characteristic_error_names'] = supplier_view_marketplace_characteristic_error_names_from_row($row, 'wb');
      } else {
        $offer['status_wb'] = 'not_created';
        $offer['status_wb_title'] = '';
        $offer['status_wb_messages'] = [];
        $offer['status_wb_quality_score'] = null;
        $offer['status_wb_quality_hints'] = [];
        $offer['status_wb_message_titles'] = [];
        $offer['status_wb_characteristic_error_names'] = [];
      }
    }
  }
  unset($offer);
}

function supplier_view_supplier_product_status_facets(int $supplierId, int $ozonConnectionId, int $wbConnectionId, string $supplierCode): array
{
  $facets = [
    'status_ozon' => [],
    'status_wb' => [],
  ];
  if ($supplierId <= 0 || ($ozonConnectionId <= 0 && $wbConnectionId <= 0)) {
    return $facets;
  }

  $pdo = db();
  $codeSet = [];
  $st = $pdo->prepare("
    SELECT offer_id, vendor_code
    FROM feedtools_supplier_products
    WHERE supplier_id = ?
  ");
  $st->execute([$supplierId]);
  while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
    $offerId = trim((string)($row['offer_id'] ?? ''));
    $vendorCode = trim((string)($row['vendor_code'] ?? ''));
    foreach ([
      $offerId,
      supplier_view_offer_display_id($offerId, $supplierCode),
      $vendorCode,
    ] as $code) {
      $code = trim((string)$code);
      if ($code !== '') {
        $codeSet[$code] = true;
      }
    }
  }

  $baseOzon = supplier_view_default_status_filter_tokens(true);
  $baseWb = supplier_view_default_status_filter_tokens(false);
  $allowedCodeSet = $codeSet ?: [];
  $facets['status_ozon'] = $ozonConnectionId > 0
    ? supplier_view_sort_status_filter_tokens(array_merge($baseOzon, supplier_view_marketplace_issue_tokens($pdo, 'ozon', $ozonConnectionId, $allowedCodeSet)))
    : [];
  $facets['status_wb'] = $wbConnectionId > 0
    ? supplier_view_sort_status_filter_tokens(array_merge($baseWb, supplier_view_marketplace_issue_tokens($pdo, 'wb', $wbConnectionId, $allowedCodeSet)))
    : [];
  return $facets;
}

function supplier_view_cache_dir(): string
{
  $dir = dirname(__DIR__) . '/storage/cache/supplier_products_view';
  if (!is_dir($dir)) {
    @mkdir($dir, 0775, true);
  }
  return is_dir($dir) && is_writable($dir) ? $dir : '';
}

function supplier_view_cache_file(string $key): string
{
  $dir = supplier_view_cache_dir();
  if ($dir === '') return '';
  return $dir . '/' . preg_replace('/[^a-zA-Z0-9_.-]+/', '_', $key) . '.json';
}

function supplier_view_supplier_products_cache_stamp(int $supplierId): string
{
  if ($supplierId <= 0) return '0';
  static $memory = [];
  if (isset($memory[$supplierId])) {
    return $memory[$supplierId];
  }
  try {
    $pdo = db();
    $products = $pdo->prepare("
      SELECT COALESCE(UNIX_TIMESTAMP(MAX(updated_at)), 0) AS u
      FROM feedtools_supplier_products
      WHERE supplier_id = ?
    ");
    $products->execute([$supplierId]);
    $p = $products->fetch(PDO::FETCH_ASSOC) ?: [];

    $fields = $pdo->prepare("
      SELECT COALESCE(UNIX_TIMESTAMP(MAX(updated_at)), 0) AS u
      FROM feedtools_supplier_product_fields
      WHERE supplier_id = ?
    ");
    $fields->execute([$supplierId]);
    $f = $fields->fetch(PDO::FETCH_ASSOC) ?: [];

    $stamp = implode(':', [
      $supplierId,
      (int)($p['u'] ?? 0),
      (int)($f['u'] ?? 0),
    ]);
    $memory[$supplierId] = $stamp;
    return $stamp;
  } catch (Throwable $e) {
    return 'uncached:' . time();
  }
}

function supplier_view_cache_read(string $key, string $stamp, int $ttlSeconds = 600): ?array
{
  $file = supplier_view_cache_file($key);
  if ($file === '' || !is_file($file)) return null;
  if ($ttlSeconds > 0 && (time() - (int)@filemtime($file)) > $ttlSeconds) return null;
  $raw = @file_get_contents($file);
  if (!is_string($raw) || $raw === '') return null;
  $payload = json_decode($raw, true);
  if (!is_array($payload)) return null;
  if ((string)($payload['stamp'] ?? '') !== $stamp) return null;
  $data = $payload['data'] ?? null;
  return is_array($data) ? $data : null;
}

function supplier_view_cache_write(string $key, string $stamp, array $data): void
{
  $file = supplier_view_cache_file($key);
  if ($file === '') return;
  $tmp = $file . '.tmp.' . getmypid();
  $payload = json_encode([
    'stamp' => $stamp,
    'created_at' => time(),
    'data' => $data,
  ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
  if (!is_string($payload)) return;
  if (@file_put_contents($tmp, $payload, LOCK_EX) === false) return;
  @rename($tmp, $file);
}

function supplier_view_supplier_product_facets_cached(int $supplierId, array $catMap = [], array $cfg = [], bool $includeParams = true): array
{
  $stamp = supplier_view_supplier_products_cache_stamp($supplierId);
  $key = ($includeParams ? 'facets_full_' : 'facets_basic_') . $supplierId . '_' . md5($stamp);
  $cached = supplier_view_cache_read($key, $stamp, 900);
  if (is_array($cached)) return $cached;
  $facets = supplier_view_supplier_product_facets($supplierId, $catMap, $cfg, $includeParams);
  supplier_view_cache_write($key, $stamp, $facets);
  return $facets;
}

function supplier_view_param_facet_display_name(string $kind, string $name): string
{
  $name = trim($name);
  return $kind === 'wb_param' ? '[WB] ' . $name : $name;
}

function supplier_view_parse_param_facet_display_name(string $facetName): array
{
  $facetName = trim($facetName);
  if (str_starts_with($facetName, '[WB] ')) {
    return ['wb_param', trim(substr($facetName, 5))];
  }
  return ['param', $facetName];
}

function supplier_view_supplier_product_param_facets_cached(int $supplierId): array
{
  if ($supplierId <= 0) return [];
  $stamp = supplier_view_supplier_products_cache_stamp($supplierId);
  $key = 'param_names_' . $supplierId . '_' . md5($stamp);
  $cached = supplier_view_cache_read($key, $stamp, 900);
  if (is_array($cached)) return $cached;

  $params = [];
  $st = db()->prepare("
    SELECT field_kind, field_name
    FROM feedtools_supplier_product_fields
    WHERE supplier_id = ?
      AND field_kind IN ('param', 'wb_param')
      AND field_name <> ''
    GROUP BY field_kind, field_name
  ");
  $st->execute([$supplierId]);
  while ($field = $st->fetch(PDO::FETCH_ASSOC)) {
    $kind = (string)($field['field_kind'] ?? '');
    $name = trim((string)($field['field_name'] ?? ''));
    if ($name === '' || !in_array($kind, ['param', 'wb_param'], true)) continue;
    $params[supplier_view_param_facet_display_name($kind, $name)] = [];
  }

  uksort($params, static function ($a, $b) {
    return strcasecmp((string)$a, (string)$b);
  });
  supplier_view_cache_write($key, $stamp, $params);
  return $params;
}

function supplier_view_supplier_product_param_values_cached(int $supplierId, string $facetName, int $limit = 800): array
{
  if ($supplierId <= 0) return [];
  [$kind, $name] = supplier_view_parse_param_facet_display_name($facetName);
  if ($name === '' || !in_array($kind, ['param', 'wb_param'], true)) return [];

  $limit = max(20, min(2000, $limit));
  $stamp = supplier_view_supplier_products_cache_stamp($supplierId) . ':param:' . md5($kind . "\n" . $name) . ':limit:' . $limit;
  $key = 'param_values_' . $supplierId . '_' . md5($stamp);
  $cached = supplier_view_cache_read($key, $stamp, 900);
  if (is_array($cached)) return $cached;

  $sql = "
    SELECT field_value, COUNT(*) AS c
    FROM feedtools_supplier_product_fields
    WHERE supplier_id = ?
      AND field_kind = ?
      AND field_name = ?
    GROUP BY field_value
    ORDER BY c DESC
    LIMIT {$limit}
  ";
  $st = db()->prepare($sql);
  $st->execute([$supplierId, $kind, $name]);
  $valsMap = [];
  while ($value = $st->fetchColumn()) {
    $value = trim((string)$value);
    $valsMap[$value === '' ? EMPTY_TOKEN : $value] = true;
  }

  $vals = array_keys($valsMap);
  usort($vals, static function ($a, $b) {
    $la = ($a === EMPTY_TOKEN) ? '∅ (пусто)' : $a;
    $lb = ($b === EMPTY_TOKEN) ? '∅ (пусто)' : $b;
    return strcasecmp($la, $lb);
  });
  supplier_view_cache_write($key, $stamp, $vals);
  return $vals;
}

function supplier_view_supplier_product_status_facets_cached(int $supplierId, int $ozonConnectionId, int $wbConnectionId, string $supplierCode): array
{
  $baseOzon = supplier_view_default_status_filter_tokens(true);
  $baseWb = supplier_view_default_status_filter_tokens(false);
  if ($supplierId <= 0 || ($ozonConnectionId <= 0 && $wbConnectionId <= 0)) {
    return [
      'status_ozon' => $ozonConnectionId > 0 ? $baseOzon : [],
      'status_wb' => $wbConnectionId > 0 ? $baseWb : [],
    ];
  }

  $pdo = db();
  $marketplaceStamp = static function (string $table, int $connectionId) use ($pdo): string {
    if ($connectionId <= 0) {
      return '0:0';
    }
    try {
      $st = $pdo->prepare("SELECT COUNT(*) AS c, COALESCE(UNIX_TIMESTAMP(MAX(updated_at)), 0) AS u FROM {$table} WHERE connection_id = ?");
      $st->execute([$connectionId]);
      $row = $st->fetch(PDO::FETCH_ASSOC) ?: [];
      return (int)($row['c'] ?? 0) . ':' . (int)($row['u'] ?? 0);
    } catch (Throwable $e) {
      return 'uncached:' . time();
    }
  };

  $stamp = implode(':', [
    'status_facets_v4_marking_error',
    supplier_view_supplier_products_cache_stamp($supplierId),
    $ozonConnectionId,
    $marketplaceStamp('feedtools_ozon_products', $ozonConnectionId),
    $wbConnectionId,
    $marketplaceStamp('feedtools_wb_products', $wbConnectionId),
    md5($supplierCode),
  ]);
  $key = 'status_facets_' . $supplierId . '_' . md5($stamp);
  $cached = supplier_view_cache_read($key, $stamp, 900);
  if (is_array($cached)) return $cached;

  $facets = supplier_view_supplier_product_status_facets($supplierId, $ozonConnectionId, $wbConnectionId, $supplierCode);
  supplier_view_cache_write($key, $stamp, $facets);
  return $facets;
}

function supplier_view_basic_editable(array $offer, string $field, string $value, bool $rich = false): string
{
  $productId = supplier_view_product_id($offer);
  if ($productId <= 0) {
    return '<div style="white-space:pre-wrap;line-height:1.25;">' . h($value) . '</div>';
  }

  $attrs = [
    'class' => 'supplier-inline-edit supplier-inline-edit--basic' . ($rich ? ' supplier-inline-edit--rich' : ''),
    'contenteditable' => 'true',
    'spellcheck' => 'false',
    'data-product-id' => (string)$productId,
    'data-basic-field' => $field,
    'data-rich' => $rich ? '1' : '0',
  ];
  $htmlAttrs = '';
  foreach ($attrs as $k => $v) {
    $htmlAttrs .= ' ' . $k . '="' . h($v) . '"';
  }
  $content = $rich ? h(supplier_view_description_plain_text($value)) : h($value);
  $toolbar = '';
  if ($rich) {
    $toolbar = '<div class="supplier-rich-toolbar" aria-label="Форматирование описания">'
      . '<button type="button" data-rich-command="insertUnorderedList" title="Маркированный список">• список</button>'
      . '<button type="button" data-rich-command="insertOrderedList" title="Нумерованный список">1. список</button>'
      . '<button type="button" data-rich-command="bold" title="Жирный текст">B</button>'
      . '<button type="button" data-rich-command="italic" title="Курсив">I</button>'
      . '<button type="button" data-rich-command="removeFormat" title="Убрать формат">Aa</button>'
      . '</div>';
  }
  return '<div class="supplier-edit-wrap">' . $toolbar . '<div' . $htmlAttrs . '>' . $content . '</div><span class="supplier-edit-state" aria-live="polite"></span></div>';
}

function supplier_view_same_model_editable(array $offer): string
{
  $productId = supplier_view_product_id($offer);
  $value = trim((string)($offer['same_model'] ?? ''));
  $fieldId = (int)($offer['same_model_field_id'] ?? 0);
  if ($productId <= 0) {
    return $value !== '' ? '<div class="supplier-same-model"><span class="supplier-same-model-label">модель:</span> ' . h($value) . '</div>' : '';
  }

  return '<div class="supplier-same-model" data-product-id="' . h($productId) . '" data-field-id="' . h($fieldId) . '">'
    . '<button type="button" class="supplier-same-model-delete" title="Удалить модель" aria-label="Удалить модель">×</button>'
    . '<span class="supplier-same-model-label">модель:</span> '
    . '<span class="supplier-same-model-value" contenteditable="true" spellcheck="false">' . h($value) . '</span>'
    . '<span class="supplier-edit-state" aria-live="polite"></span>'
    . '</div>';
}

function supplier_view_fields_for_kinds(array $offer, array $kinds): array
{
  $fields = $offer['_supplier_fields'] ?? [];
  if (!is_array($fields)) {
    return [];
  }
  $out = [];
  foreach ($kinds as $kind) {
    foreach ((array)($fields[$kind] ?? []) as $field) {
      if (is_array($field)) {
        $out[] = $field;
      }
    }
  }
  return $out;
}

function supplier_view_norm_characteristic_name(string $name): string
{
  $name = trim(preg_replace('~\s+~u', ' ', $name) ?? $name);
  if ($name === '') {
    return '';
  }
  $name = function_exists('mb_strtolower') ? mb_strtolower($name, 'UTF-8') : strtolower($name);
  return str_replace('ё', 'е', $name);
}

function supplier_view_characteristic_alias_groups(): array
{
  return [
    'color' => ['цвет', 'цвет товара', 'название цвета', 'основной цвет'],
    'material' => ['материал', 'материал изделия', 'основной материал', 'материал корпуса'],
    'country_of_origin' => ['страна производства', 'страна-изготовитель', 'страна изготовитель', 'страна происхождения'],
    'unit_quantity' => ['количество товара в уеи', 'количество_в_единице_товара', 'количество в упаковке шт', 'количество штук в упаковке', 'количество в упаковке'],
    'model_name' => ['модель', 'модель товара', 'название модели', 'название модели для объединения в одну карточку'],
  ];
}

function supplier_view_characteristic_alias_names(string $name): array
{
  if (function_exists('supplier_push_attribute_alias_names')) {
    return supplier_push_attribute_alias_names($name);
  }
  $names = [$name];
  $norm = supplier_view_norm_characteristic_name($name);
  if ($norm !== '') {
    foreach (supplier_view_characteristic_alias_groups() as $group) {
      $groupNorms = [];
      foreach ($group as $alias) {
        $aliasNorm = supplier_view_norm_characteristic_name((string)$alias);
        if ($aliasNorm !== '') {
          $groupNorms[$aliasNorm] = true;
        }
      }
      if (isset($groupNorms[$norm])) {
        $names = array_merge($names, $group);
      }
    }
  }
  $out = [];
  foreach ($names as $candidate) {
    $candidate = trim((string)$candidate);
    $candidateNorm = supplier_view_norm_characteristic_name($candidate);
    if ($candidate !== '' && $candidateNorm !== '' && !isset($out[$candidateNorm])) {
      $out[$candidateNorm] = $candidate;
    }
  }
  return array_values($out);
}

function supplier_view_characteristic_candidate_norms(string $name): array
{
  $out = [];
  foreach (supplier_view_characteristic_alias_names($name) as $candidate) {
    $norm = supplier_view_norm_characteristic_name((string)$candidate);
    if ($norm !== '') {
      $out[$norm] = true;
    }
  }
  return array_keys($out);
}

function supplier_view_split_characteristic_values(array $values): array
{
  if (function_exists('supplier_products_normalize_characteristic_values')) {
    return supplier_products_normalize_characteristic_values($values);
  }
  if (function_exists('supplier_push_split_attribute_values')) {
    return supplier_push_split_attribute_values($values);
  }
  $out = [];
  $seen = [];
  foreach ($values as $value) {
    $value = is_array($value) ? (string)($value['value'] ?? ($value['name'] ?? '')) : (string)$value;
    foreach (preg_split('/\s*[;\|\n\r]+\s*/u', trim($value), -1, PREG_SPLIT_NO_EMPTY) ?: [] as $part) {
      $part = trim((string)$part);
      $key = supplier_view_norm_characteristic_name($part);
      if ($part !== '' && $key !== '' && !isset($seen[$key])) {
        $seen[$key] = true;
        $out[] = $part;
      }
    }
  }
  return $out;
}

function supplier_view_is_hashtags_field_name(string $name): bool
{
  $norm = supplier_view_norm_characteristic_name(ltrim(trim($name), "# \t\n\r\0\x0B"));
  return in_array($norm, ['hashtags', 'hashtag', 'хештеги', 'хэштеги'], true);
}

function supplier_view_characteristic_exclude_map(string $source): array
{
  static $cache = [];
  $source = trim($source);
  if ($source === '') {
    return [];
  }
  if (array_key_exists($source, $cache)) {
    return $cache[$source];
  }

  $out = [];
  $names = [];
  try {
    global $cfg;
    $names = taxonomy_get_global_exclude_attribute_names($source, is_array($cfg ?? null) ? $cfg : null);
  } catch (Throwable $e) {
    global $cfg;
    $names = taxonomy_global_exclusions_config_fallback($source, is_array($cfg ?? null) ? $cfg : null);
  }
  foreach ($names as $name) {
    $key = supplier_view_norm_characteristic_name((string)$name);
    if ($key !== '') {
      $out[$key] = true;
    }
  }
  $cache[$source] = $out;
  return $out;
}

function supplier_view_is_excluded_characteristic(string $source, string $name): bool
{
  $key = supplier_view_norm_characteristic_name($name);
  if ($key === '') {
    return false;
  }
  $map = supplier_view_characteristic_exclude_map($source);
  return isset($map[$key]);
}

function supplier_view_hashtag_values_from_text(string $value): array
{
  $parts = preg_split('/[\s,;]+/u', trim($value), -1, PREG_SPLIT_NO_EMPTY) ?: [];
  $set = [];
  foreach ($parts as $part) {
    $part = trim((string)$part);
    if ($part === '') continue;
    $part = ltrim($part, '#');
    $part = preg_replace('/[^\p{L}\p{N}_]+/u', '_', (string)$part);
    $part = preg_replace('/_+/u', '_', (string)$part);
    $part = trim((string)$part, '_');
    if ($part === '') continue;
    if (mb_strlen($part, 'UTF-8') > 29) {
      $part = trim((string)mb_substr($part, 0, 29, 'UTF-8'), '_');
    }
    if ($part === '') continue;
    $part = '#' . $part;
    $set[$part] = true;
  }
  return array_keys($set);
}

function supplier_view_characteristic_names_from_meta(array $meta, string $source): array
{
  $rows = supplier_view_characteristic_rows_from_meta($meta, $source);
  $out = [];
  foreach ($rows as $norm => $row) {
    $name = trim((string)($row['name'] ?? ''));
    if ($norm !== '' && $name !== '') {
      $out[$norm] = $name;
    }
  }
  return $out;
}

function supplier_view_characteristic_rows_from_meta(array $meta, string $source): array
{
  if (function_exists('supplier_products_characteristic_rows_from_taxonomy_meta')) {
    $rows = supplier_products_characteristic_rows_from_taxonomy_meta($meta, $source === 'wb' ? 'wildberries' : $source, is_array($GLOBALS['cfg'] ?? null) ? $GLOBALS['cfg'] : []);
    $out = [];
    foreach ($rows as $norm => $row) {
      $name = trim((string)($row['name'] ?? ''));
      if ($name !== '' && $norm !== '') {
        $out[$norm] = [
          'name' => $name,
          'allowed_values' => array_values((array)($row['allowed_values'] ?? [])),
          'required' => !empty($row['required']) || !empty($row['is_required']),
          'has_dictionary' => !empty($row['has_dictionary']) || (int)($row['dictionary_id'] ?? 0) > 0 || !empty($row['allowed_values']),
          'dictionary_id' => (int)($row['dictionary_id'] ?? 0),
        ];
      }
    }
    return $out;
  }

  $listKey = $source === 'ozon' ? 'ozon_required_attributes' : 'wb_required_attributes';
  $metaKey = $source === 'ozon' ? 'ozon_required_attributes_meta' : 'wb_characteristics_meta';
  $names = [];
  $excludeMap = supplier_view_characteristic_exclude_map($source);

  foreach ((array)($meta[$listKey] ?? []) as $name) {
    $name = trim((string)$name);
    if ($name !== '') {
      $names[] = $name;
    }
  }

  if (!$names) {
    foreach ((array)($meta[$metaKey] ?? []) as $row) {
      if (!is_array($row)) {
        continue;
      }
      $name = trim((string)($row['name'] ?? ''));
      if ($name !== '') {
        $names[] = $name;
      }
    }
  }

  $out = [];
  foreach ($names as $name) {
    $norm = supplier_view_norm_characteristic_name($name);
    if ($norm !== '' && !isset($excludeMap[$norm]) && !isset($out[$norm])) {
      $out[$norm] = [
        'name' => $name,
        'allowed_values' => [],
        'required' => false,
      ];
    }
  }
  foreach ((array)($meta[$metaKey] ?? []) as $row) {
    if (!is_array($row)) {
      continue;
    }
    $name = trim((string)($row['name'] ?? ''));
    $norm = supplier_view_norm_characteristic_name($name);
    if ($name !== '' && $norm !== '' && isset($out[$norm])) {
      $out[$norm]['required'] = !empty($row['required']) || !empty($row['is_required']);
      if (empty($out[$norm]['allowed_values'])) {
        $out[$norm]['allowed_values'] = supplier_view_marketplace_attr_allowed_values($row);
      }
    }
  }
  return $out;
}

function supplier_view_marketplace_attr_is_required($attr): bool
{
  return is_array($attr) && (!empty($attr['required']) || !empty($attr['is_required']));
}

function supplier_view_sort_marketplace_characteristics(array $attrs): array
{
  $decorated = [];
  $idx = 0;
  foreach ($attrs as $key => $attr) {
    $decorated[$key] = [
      'attr' => $attr,
      'idx' => $idx++,
      'required' => supplier_view_marketplace_attr_is_required($attr) ? 1 : 0,
    ];
  }
  uasort($decorated, static function (array $a, array $b): int {
    if ($a['required'] !== $b['required']) {
      return $b['required'] <=> $a['required'];
    }
    return $a['idx'] <=> $b['idx'];
  });
  $out = [];
  foreach ($decorated as $key => $row) {
    $out[$key] = $row['attr'];
  }
  return $out;
}

function supplier_view_taxonomy_meta_has_characteristic_schema(array $meta, string $source): bool
{
  $source = $source === 'wb' ? 'wildberries' : $source;
  $listKey = $source === 'ozon' ? 'ozon_required_attributes' : 'wb_required_attributes';
  $metaKey = $source === 'ozon' ? 'ozon_required_attributes_meta' : 'wb_characteristics_meta';

  foreach ((array)($meta[$listKey] ?? []) as $name) {
    if (trim((string)$name) !== '') {
      return true;
    }
  }
  foreach ((array)($meta[$metaKey] ?? []) as $row) {
    if (is_array($row) && trim((string)($row['name'] ?? '')) !== '') {
      return true;
    }
  }
  return false;
}

function supplier_view_marketplace_characteristic_sets(array $offers): array
{
  $sets = [
    'ozon' => [],
    'wb' => [],
    '_analysis' => [
      'ozon' => [],
      'wb' => [],
    ],
  ];

  $ozonPairs = [];
  $ozonLooseValues = [];
  $wbIds = [];
  $wbLooseValues = [];
  foreach ($offers as $offer) {
    $ozon = trim((string)($offer['ozon_category'] ?? ''));
    if ($ozon !== '') {
      if (preg_match('~^(\d+)_(\d+)$~', $ozon)) {
        $ozonPairs[$ozon] = true;
      } elseif (preg_match('~^leaf:(\d+_\d+)$~', $ozon, $m)) {
        $ozonPairs[(string)$m[1]] = true;
      } else {
        $ozonLooseValues[$ozon] = true;
      }
    }
    $wb = trim((string)($offer['wb_category'] ?? ($offer['wb_subject_id'] ?? '')));
    if ($wb !== '') {
      if (ctype_digit($wb)) {
        $wbIds[$wb] = true;
      } elseif (preg_match('~^wb:(?:subject|parent):(\d+)$~', $wb, $m)) {
        $wbIds[(string)$m[1]] = true;
      } else {
        $wbLooseValues[$wb] = true;
      }
    }
  }

  $pdo = db();
  foreach (array_chunk(array_keys($ozonPairs), 100) as $chunk) {
    $clauses = [];
    $args = ['ozon'];
    foreach ($chunk as $pair) {
      if (!preg_match('~^(\d+)_(\d+)$~', (string)$pair, $m)) {
        continue;
      }
      $clauses[] = '(ozon_parent_id = ? AND ozon_leaf_id = ?)';
      $args[] = $m[1];
      $args[] = $m[2];
    }
    if (!$clauses) {
      continue;
    }
    $st = $pdo->prepare("
      SELECT ozon_parent_id, ozon_leaf_id, meta_json
      FROM feedtools_taxonomy_categories
      WHERE source = ? AND is_leaf = 1 AND (" . implode(' OR ', $clauses) . ")
    ");
    $st->execute($args);
    while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
      $value = (string)($row['ozon_parent_id'] ?? '') . '_' . (string)($row['ozon_leaf_id'] ?? '');
      $meta = json_decode((string)($row['meta_json'] ?? ''), true);
      $sets['_analysis']['ozon'][$value] = is_array($meta) && supplier_view_taxonomy_meta_has_characteristic_schema($meta, 'ozon');
      $sets['ozon'][$value] = is_array($meta) ? supplier_view_characteristic_rows_from_meta($meta, 'ozon') : [];
    }
  }

  foreach (array_chunk(array_keys($ozonLooseValues), 100) as $chunk) {
    $where = [];
    $args = [];
    foreach ($chunk as $value) {
      $where[] = '(name = ? OR full_path = ? OR full_path LIKE ?)';
      $args[] = $value;
      $args[] = $value;
      $args[] = '% > ' . $value;
    }
    if (!$where) {
      continue;
    }
    $st = $pdo->prepare("
      SELECT name, full_path, ozon_parent_id, ozon_leaf_id, meta_json
      FROM feedtools_taxonomy_categories
      WHERE source = 'ozon' AND is_leaf = 1 AND (" . implode(' OR ', $where) . ")
      ORDER BY full_path ASC
    ");
    $st->execute($args);
    while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
      $value = (string)($row['ozon_parent_id'] ?? '') . '_' . (string)($row['ozon_leaf_id'] ?? '');
      if ($value === '_' || $value === '') {
        continue;
      }
      $meta = json_decode((string)($row['meta_json'] ?? ''), true);
      $hasSchema = is_array($meta) && supplier_view_taxonomy_meta_has_characteristic_schema($meta, 'ozon');
      $names = is_array($meta) ? supplier_view_characteristic_rows_from_meta($meta, 'ozon') : [];
      foreach ($chunk as $rawValue) {
        if (
          (string)($row['name'] ?? '') === $rawValue
          || (string)($row['full_path'] ?? '') === $rawValue
          || str_ends_with((string)($row['full_path'] ?? ''), ' > ' . $rawValue)
        ) {
          $sets['_analysis']['ozon'][$rawValue] = $hasSchema;
          $sets['ozon'][$rawValue] = $names;
        }
      }
      $sets['_analysis']['ozon'][$value] = $hasSchema;
      $sets['ozon'][$value] = $names;
    }
  }

  foreach (array_chunk(array_keys($wbIds), 200) as $chunk) {
    $externalIds = [];
    foreach ($chunk as $id) {
      $externalIds[] = 'wb:subject:' . $id;
      $externalIds[] = 'wb:parent:' . $id;
    }
    if (!$externalIds) {
      continue;
    }
    $placeholders = implode(',', array_fill(0, count($externalIds), '?'));
    $st = $pdo->prepare("
      SELECT external_id, is_leaf, meta_json
      FROM feedtools_taxonomy_categories
      WHERE source = 'wildberries' AND external_id IN ({$placeholders})
      ORDER BY is_leaf DESC
    ");
    $st->execute($externalIds);
    while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
      $externalId = (string)($row['external_id'] ?? '');
      if (!preg_match('~^wb:(?:subject|parent):(\d+)$~', $externalId, $m)) {
        continue;
      }
      $id = (string)$m[1];
      if (isset($sets['wb'][$id]) && $sets['wb'][$id]) {
        continue;
      }
      $meta = json_decode((string)($row['meta_json'] ?? ''), true);
      $sets['_analysis']['wb'][$id] = is_array($meta) && supplier_view_taxonomy_meta_has_characteristic_schema($meta, 'wb');
      $sets['wb'][$id] = is_array($meta) ? supplier_view_characteristic_rows_from_meta($meta, 'wb') : [];
    }
  }

  foreach (array_chunk(array_keys($wbLooseValues), 100) as $chunk) {
    $where = [];
    $args = [];
    foreach ($chunk as $value) {
      $where[] = '(external_id = ? OR name = ? OR full_path = ? OR full_path LIKE ?)';
      $args[] = $value;
      $args[] = $value;
      $args[] = $value;
      $args[] = '% > ' . $value;
    }
    if (!$where) {
      continue;
    }
    $st = $pdo->prepare("
      SELECT external_id, name, full_path, is_leaf, meta_json
      FROM feedtools_taxonomy_categories
      WHERE source = 'wildberries' AND is_leaf = 1 AND (" . implode(' OR ', $where) . ")
      ORDER BY full_path ASC
    ");
    $st->execute($args);
    while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
      $externalId = (string)($row['external_id'] ?? '');
      $id = preg_match('~^wb:(?:subject|parent):(\d+)$~', $externalId, $m) ? (string)$m[1] : '';
      $meta = json_decode((string)($row['meta_json'] ?? ''), true);
      $hasSchema = is_array($meta) && supplier_view_taxonomy_meta_has_characteristic_schema($meta, 'wb');
      $names = is_array($meta) ? supplier_view_characteristic_rows_from_meta($meta, 'wb') : [];
      if ($id !== '') {
        $sets['_analysis']['wb'][$id] = $hasSchema;
        $sets['wb'][$id] = $names;
      }
      foreach ($chunk as $rawValue) {
        if (
          $externalId === $rawValue
          || (string)($row['name'] ?? '') === $rawValue
          || (string)($row['full_path'] ?? '') === $rawValue
          || str_ends_with((string)($row['full_path'] ?? ''), ' > ' . $rawValue)
        ) {
          $sets['_analysis']['wb'][$rawValue] = $hasSchema;
          $sets['wb'][$rawValue] = $names;
        }
      }
    }
  }

  return $sets;
}

function supplier_view_characteristic_fields_by_norm(array $offer, string $kind): array
{
  $out = [];
  foreach ((array)(($offer['_supplier_fields'] ?? [])[$kind] ?? []) as $field) {
    if (!is_array($field)) {
      continue;
    }
    $name = trim((string)($field['field_name'] ?? ''));
    $norm = supplier_view_norm_characteristic_name($name);
    if ($norm === '') {
      continue;
    }
    $out[$norm][] = $field;
  }
  return $out;
}

function supplier_view_characteristic_value_from_fields(array $fields, array $allowedValues = [], string $source = '', string $marketName = ''): string
{
  $values = [];
  foreach ($fields as $field) {
    if (!is_array($field)) {
      continue;
    }
    $value = trim((string)($field['field_value'] ?? ''));
    if ($value !== '') {
      $values[] = $value;
    }
  }
  $restrict = false;
  if (function_exists('supplier_products_characteristic_should_restrict_to_allowed')) {
    $restrict = supplier_products_characteristic_should_restrict_to_allowed($source, $marketName);
  }
  if (function_exists('supplier_products_normalize_characteristic_values')) {
    return implode('; ', supplier_products_normalize_characteristic_values($values, $allowedValues, $restrict));
  }
  return implode('; ', supplier_view_split_characteristic_values($values));
}

function supplier_view_content_plain_text(string $value): string
{
  $text = html_entity_decode(strip_tags($value), ENT_QUOTES | ENT_HTML5, 'UTF-8');
  $text = str_replace(["\xc2\xa0", "\r", "\n", "\t"], ' ', $text);
  $text = preg_replace('~\s+~u', ' ', $text);
  return trim(is_string($text) ? $text : strip_tags($value));
}

function supplier_view_content_text_len(string $value): int
{
  return function_exists('mb_strlen') ? mb_strlen($value, 'UTF-8') : strlen($value);
}

function supplier_view_content_value_is_filled($value): bool
{
  $text = supplier_view_content_plain_text((string)$value);
  if ($text === '') {
    return false;
  }
  $norm = supplier_view_norm_characteristic_name($text);
  return !in_array($norm, ['-', '—', 'нет', 'не указано', 'не заполнено', 'n/a', 'na', 'none', 'null'], true);
}

function supplier_view_content_fields_by_norm(array $offer, array $kinds): array
{
  $out = [];
  foreach ($kinds as $kind) {
    foreach ((array)(($offer['_supplier_fields'] ?? [])[$kind] ?? []) as $field) {
      if (!is_array($field)) {
        continue;
      }
      $name = trim((string)($field['field_name'] ?? ''));
      $norm = supplier_view_norm_characteristic_name($name);
      if ($norm === '') {
        continue;
      }
      $out[$norm][] = $field;
    }
  }
  return $out;
}

function supplier_view_content_characteristic_value(array $offer, array $names, array $kinds = ['param', 'wb_param']): string
{
  $byNorm = supplier_view_content_fields_by_norm($offer, $kinds);
  foreach ($names as $name) {
    foreach (supplier_view_characteristic_candidate_norms((string)$name) as $norm) {
      foreach ((array)($byNorm[$norm] ?? []) as $field) {
        $value = trim((string)($field['field_value'] ?? ''));
        if (supplier_view_content_value_is_filled($value)) {
          return $value;
        }
      }
    }
  }
  return '';
}

function supplier_view_content_generated_picture_count(array $pictures, array $needles): int
{
  $count = 0;
  foreach ($pictures as $picture) {
    $relative = function_exists('supplier_products_local_image_relative_from_url')
      ? supplier_products_local_image_relative_from_url((string)$picture)
      : (string)$picture;
    $relative = str_replace('\\', '/', $relative);
    foreach ($needles as $needle) {
      if ($needle !== '' && str_contains($relative, $needle)) {
        $count++;
        break;
      }
    }
  }
  return $count;
}

function supplier_view_content_has_tnved_code(array $offer): bool
{
  foreach ((array)(($offer['_supplier_fields'] ?? [])['standard'] ?? []) as $field) {
    if (!is_array($field)) {
      continue;
    }
    $name = trim((string)($field['field_name'] ?? ''));
    $value = trim((string)($field['field_value'] ?? ''));
    if ($name === 'tnved_code' && preg_match('~\b\d{4,10}\b~u', $value)) {
      return true;
    }
  }
  foreach (['param', 'wb_param'] as $kind) {
    foreach ((array)(($offer['_supplier_fields'] ?? [])[$kind] ?? []) as $field) {
      if (!is_array($field)) {
        continue;
      }
      $name = trim((string)($field['field_name'] ?? ''));
      $value = trim((string)($field['field_value'] ?? ''));
      if ($name === '' || $value === '' || !supplier_view_text_mentions_tnved($name)) {
        continue;
      }
      if (preg_match('~\b\d{4,10}\b~u', $value)) {
        return true;
      }
    }
  }
  return false;
}

function supplier_view_content_ignore_characteristic_name(string $name): bool
{
  $norm = supplier_view_norm_characteristic_name($name);
  if ($norm === '') {
    return true;
  }
  if (supplier_view_is_hashtags_field_name($name) || supplier_view_text_mentions_tnved($name)) {
    return true;
  }
  $exact = [
    'длина', 'ширина', 'высота', 'вес', 'вес товара без упаковки г', 'вес товара с упаковкой г',
    'гарантия', 'гарантийный срок', 'срок гарантии', 'срок годности', 'возраст', 'возрастные ограничения',
    'количество товара в уеи', 'количество товара в единице', 'количество в единице товара',
    'количество в упаковке', 'количество штук в упаковке', 'страна производства', 'страна производитель',
    'страна изготовитель', 'страна-изготовитель', 'класс опасности товара', 'партномер',
  ];
  if (in_array($norm, $exact, true)) {
    return true;
  }
  foreach (['тн вэд', 'тнвэд', 'гарант', 'срок годности', 'возраст', 'количество товара в уеи'] as $part) {
    if (str_contains($norm, $part)) {
      return true;
    }
  }
  return false;
}

function supplier_view_content_marketplace_category_key(array $offer, string $source): string
{
  if ($source === 'ozon') {
    $category = trim((string)($offer['ozon_category'] ?? ''));
    if (preg_match('~^leaf:(\d+_\d+)$~', $category, $m)) {
      return (string)$m[1];
    }
    return $category;
  }
  $category = trim((string)($offer['wb_category'] ?? ($offer['wb_subject_id'] ?? '')));
  if (preg_match('~^wb:(?:subject|parent):(\d+)$~', $category, $m)) {
    return (string)$m[1];
  }
  return $category;
}

function supplier_view_content_meaningful_characteristics_count(array $offer): int
{
  $seen = [];
  foreach (['param', 'wb_param'] as $kind) {
    foreach ((array)(($offer['_supplier_fields'] ?? [])[$kind] ?? []) as $field) {
      if (!is_array($field)) {
        continue;
      }
      $name = trim((string)($field['field_name'] ?? ''));
      $value = trim((string)($field['field_value'] ?? ''));
      $norm = supplier_view_norm_characteristic_name($name);
      if (
        $norm === ''
        || supplier_view_content_ignore_characteristic_name($name)
        || !supplier_view_content_value_is_filled($value)
      ) {
        continue;
      }
      $seen[$kind . ':' . $norm] = true;
    }
  }
  return count($seen);
}

function supplier_view_content_characteristics_score(array $offer, array $marketplaceSets): array
{
  $paramByNorm = supplier_view_characteristic_fields_by_norm($offer, 'param');
  $wbParamByNorm = supplier_view_characteristic_fields_by_norm($offer, 'wb_param');
  $filled = 0;
  $total = 0;
  $seenRequired = [];
  $meaningfulFilled = supplier_view_content_meaningful_characteristics_count($offer);

  foreach (['ozon', 'wb'] as $source) {
    $category = supplier_view_content_marketplace_category_key($offer, $source);
    $attrs = (array)(($marketplaceSets[$source] ?? [])[$category] ?? []);
    foreach ($attrs as $norm => $attr) {
      $name = supplier_view_marketplace_attr_name($attr);
      if ($name === '' || supplier_view_content_ignore_characteristic_name($name)) {
        continue;
      }
      if ($source === 'ozon' && supplier_view_is_excluded_characteristic('ozon', $name)) {
        continue;
      }
      if ($source === 'wb' && supplier_view_is_excluded_characteristic('wb', $name)) {
        continue;
      }
      $key = $source . ':' . supplier_view_norm_characteristic_name($name);
      if ($key === $source . ':' || isset($seenRequired[$key])) {
        continue;
      }
      $seenRequired[$key] = true;
      $total++;

      $allowedValues = supplier_view_marketplace_attr_allowed_values($attr);
      $primary = $source === 'wb' ? $wbParamByNorm : $paramByNorm;
      $fallback = $source === 'wb' ? $paramByNorm : $wbParamByNorm;
      $fields = supplier_view_characteristic_fields_for_market_name($primary, $name);
      $value = supplier_view_characteristic_value_from_fields($fields, $allowedValues, $source === 'wb' ? 'wildberries' : 'ozon', $name);
      if ($value === '') {
        $fallbackFields = supplier_view_characteristic_fields_for_market_name($fallback, $name);
        $value = supplier_view_characteristic_value_from_fields($fallbackFields, $allowedValues, $source === 'wb' ? 'wildberries' : 'ozon', $name);
      }
      if (supplier_view_content_value_is_filled($value)) {
        $filled++;
      }
    }
  }

  if ($total === 0) {
    return [
      'filled' => $meaningfulFilled,
      'total' => 0,
      'ok' => $meaningfulFilled >= 5,
      'label' => $meaningfulFilled . ' заполненных характеристик',
    ];
  }

  $need = max(1, (int)ceil($total * 0.6));
  $contentNeed = $total <= 3 ? max(1, $total) : min(5, max(3, (int)ceil($total * 0.25)));
  $schemaOk = $filled >= $need;
  $contentOk = $meaningfulFilled >= $contentNeed;
  return [
    'filled' => $filled,
    'total' => $total,
    'ok' => $schemaOk || $contentOk,
    'label' => $filled . ' из ' . $total . ' по схемам, нужно ' . $need
      . '; всего полезных ' . $meaningfulFilled . ', контентный минимум ' . $contentNeed,
  ];
}

function supplier_view_content_title_ready(array $offer): array
{
  $name = supplier_view_content_plain_text((string)($offer['name'] ?? ''));
  $len = supplier_view_content_text_len($name);
  $hasCyrillic = (bool)preg_match('/\p{Cyrillic}{5}/u', $name);
  $hasNoise = (bool)preg_match('~(__|\(orig\)|\borig\b|https?://|<|>)~iu', $name);
  $ok = $len >= 16 && $len <= 200 && $hasCyrillic && !$hasNoise;
  $reason = $ok
    ? 'название выглядит подготовленным'
    : 'нужно русское чистое название 16-200 символов без служебного мусора';
  return ['ok' => $ok, 'title' => $reason . '; сейчас ' . $len . ' симв.'];
}

function supplier_view_content_readiness_items(array $offer, array $marketplaceSets): array
{
  $title = supplier_view_content_title_ready($offer);
  $description = supplier_view_content_plain_text((string)($offer['description_html'] ?? ''));
  $descriptionLen = supplier_view_content_text_len($description);
  $featureTarget = defined('SUPPLIER_PRODUCTS_FEATURE_MAX') ? max(1, min(3, (int)SUPPLIER_PRODUCTS_FEATURE_MAX)) : 3;
  $featureCount = 0;
  foreach ((array)(($offer['_supplier_fields'] ?? [])['feature'] ?? []) as $field) {
    $value = trim((string)($field['field_value'] ?? ''));
    if ($value !== '') {
      $featureCount++;
    }
  }
  $hashtagsCount = count((array)($offer['hashtags'] ?? []));
  $characteristics = supplier_view_content_characteristics_score($offer, $marketplaceSets);
  $color = supplier_view_content_characteristic_value($offer, ['цвет', 'цвет товара', 'название цвета', 'основной цвет']);
  $pictures = array_values(array_filter(array_map('strval', (array)($offer['pictures'] ?? [])), static fn(string $v): bool => trim($v) !== ''));
  $coverCount = supplier_view_content_generated_picture_count($pictures, ['/gpt_cover/']);
  $videoCoverUrl = trim((string)(supplier_view_video_cover_field($offer)['value'] ?? ''));
  $videoUrls = supplier_view_video_urls($offer, true);
  $generatedExtraCount = supplier_view_content_generated_picture_count($pictures, ['/gpt_photo_variant/', '/photo_collage/', '/product_specs_photo/']);
  $extraPhotosCount = max(0, count($pictures) - 1);
  $model = trim((string)($offer['same_model'] ?? ''));
  $tnvedOk = supplier_view_content_has_tnved_code($offer);

  return [
    'title' => [
      'label' => 'название',
      'ok' => (bool)$title['ok'],
      'title' => (string)$title['title'],
    ],
    'description' => [
      'label' => 'описание',
      'ok' => $descriptionLen >= 180,
      'title' => 'описание: ' . $descriptionLen . ' симв.; нужно минимум 180',
    ],
    'color' => [
      'label' => 'цвет',
      'ok' => supplier_view_content_value_is_filled($color),
      'title' => supplier_view_content_value_is_filled($color) ? 'цвет заполнен: ' . $color : 'характеристика цвета не заполнена',
    ],
    'params' => [
      'label' => 'характеристики',
      'ok' => !empty($characteristics['ok']),
      'title' => 'характеристики: ' . (string)($characteristics['label'] ?? ''),
    ],
    'features' => [
      'label' => 'фишки',
      'ok' => $featureCount >= $featureTarget,
      'title' => 'фишки: ' . $featureCount . ' из ' . $featureTarget,
    ],
    'cover' => [
      'label' => 'обложка',
      'ok' => $coverCount > 0,
      'title' => $coverCount > 0 ? 'сгенерированная обложка найдена' : 'сгенерированная обложка не найдена',
    ],
    'video' => [
      'label' => 'видео',
      'ok' => $videoUrls !== [],
      'title' => $videoUrls !== []
        ? (($videoCoverUrl !== '' ? 'видео-обложка' : 'видео') . ' найдено: ' . count($videoUrls))
        : 'видео не найдено',
    ],
    'model' => [
      'label' => 'модель',
      'ok' => supplier_view_content_value_is_filled($model),
      'title' => supplier_view_content_value_is_filled($model) ? 'same_model заполнен: ' . $model : 'same_model не заполнен',
    ],
    'hashtags' => [
      'label' => 'хештеги',
      'ok' => $hashtagsCount > 0,
      'title' => 'хештеги: ' . $hashtagsCount,
    ],
    'extra_photos' => [
      'label' => 'доп.фото',
      'ok' => $generatedExtraCount > 0,
      'title' => 'фото-вариаций, маркетинговых фото с характеристиками или коллажей: ' . $generatedExtraCount . '; всего доп. фото: ' . $extraPhotosCount,
    ],
    'tnved' => [
      'label' => 'ТНВЭД',
      'ok' => $tnvedOk,
      'title' => $tnvedOk ? 'код ТНВЭД найден' : 'код ТНВЭД не найден',
    ],
  ];
}

function supplier_view_content_readiness_defs(): array
{
  return [
    'title' => 'название',
    'description' => 'описание',
    'color' => 'цвет',
    'params' => 'характеристики',
    'features' => 'фишки',
    'cover' => 'обложка',
    'video' => 'видео',
    'model' => 'модель',
    'hashtags' => 'хештеги',
    'extra_photos' => 'доп.фото',
    'tnved' => 'ТНВЭД',
  ];
}

function supplier_view_content_readiness_filter_mode($value): string
{
  $value = trim((string)$value);
  return $value === 'ready' ? 'ready' : 'missing';
}

function supplier_view_content_readiness_filter_states(array $readyKeys, array $missingKeys, array $defs): array
{
  $out = [];
  foreach ($readyKeys as $key) {
    $key = (string)$key;
    if (isset($defs[$key])) {
      $out[$key] = 'ready';
    }
  }
  foreach ($missingKeys as $key) {
    $key = (string)$key;
    if (isset($defs[$key])) {
      $out[$key] = 'missing';
    }
  }
  return $out;
}

function supplier_view_content_readiness_filter_matches_states(array $offer, array $marketplaceSets, array $states): bool
{
  if (!$states) {
    return true;
  }

  $items = supplier_view_content_readiness_items($offer, $marketplaceSets);
  foreach ($states as $key => $state) {
    $key = (string)$key;
    if (!isset($items[$key])) {
      continue;
    }
    $ok = !empty($items[$key]['ok']);
    if ($state === 'ready') {
      if (!$ok) {
        return false;
      }
    } elseif ($ok) {
      return false;
    }
  }
  return true;
}

function supplier_view_content_readiness_filter_matches(array $offer, array $marketplaceSets, array $keys, string $mode): bool
{
  $items = supplier_view_content_readiness_items($offer, $marketplaceSets);
  $keys = array_values(array_intersect($keys, array_keys($items)));
  if (!$keys) {
    return true;
  }

  if (supplier_view_content_readiness_filter_mode($mode) === 'ready') {
    foreach ($keys as $key) {
      if (empty($items[$key]['ok'])) {
        return false;
      }
    }
    return true;
  }

  foreach ($keys as $key) {
    if (!empty($items[$key]['ok'])) {
      return false;
    }
  }
  return true;
}

function supplier_view_content_readiness_html(array $offer, array $marketplaceSets): string
{
  $items = supplier_view_content_readiness_items($offer, $marketplaceSets);
  $done = 0;
  foreach ($items as $item) {
    if (!empty($item['ok'])) {
      $done++;
    }
  }
  $html = '<div class="supplier-content-readiness" title="' . h('Готовность контента: ' . $done . ' из ' . count($items)) . '">';
  foreach ($items as $key => $item) {
    $ok = !empty($item['ok']);
    $html .= '<span class="supplier-content-readiness-item ' . ($ok ? 'is-on' : 'is-off') . '" title="' . h((string)($item['title'] ?? '')) . '" data-ready-key="' . h((string)$key) . '">'
      . '<span class="supplier-content-readiness-lamp" aria-hidden="true"></span>'
      . '<span class="supplier-content-readiness-label">' . h((string)($item['label'] ?? $key)) . '</span>'
      . '</span>';
  }
  $html .= '</div>';
  return $html;
}

function supplier_view_characteristic_fields_for_market_name(array $fieldsByNorm, string $name): array
{
  $out = [];
  $seen = [];
  foreach (supplier_view_characteristic_candidate_norms($name) as $candidateNorm) {
    foreach ((array)($fieldsByNorm[$candidateNorm] ?? []) as $field) {
      if (!is_array($field)) {
        continue;
      }
      $fieldId = (int)($field['id'] ?? 0);
      $key = $fieldId > 0 ? ('id:' . $fieldId) : ('row:' . count($out) . ':' . (string)($field['field_name'] ?? ''));
      if (isset($seen[$key])) {
        continue;
      }
      $seen[$key] = true;
      $out[] = $field;
    }
  }
  return $out;
}

function supplier_view_ozon_attribute_names_from_status(array $offer): array
{
  $texts = [];
  foreach ((array)($offer['status_ozon_messages'] ?? []) as $message) {
    $texts[] = (string)$message;
  }
  $texts[] = (string)($offer['status_ozon_title'] ?? '');

  $out = [];
  foreach ($texts as $text) {
    $text = trim($text);
    if ($text === '') {
      continue;
    }
    if (supplier_view_text_mentions_tnved($text)) {
      $out[supplier_view_norm_characteristic_name(supplier_view_ozon_tnved_attribute_name())] = supplier_view_ozon_tnved_attribute_name();
    }
    if (preg_match_all('~(?:ошибка\s+характеристики|нет)\s*:\s*([^;\n\r]+)~iu', $text, $matches)) {
      foreach ((array)($matches[1] ?? []) as $name) {
        $name = trim((string)$name);
        if ($name !== '' && !supplier_view_is_technical_characteristic_name($name) && !supplier_view_is_excluded_characteristic('ozon', $name)) {
          $out[supplier_view_norm_characteristic_name($name)] = $name;
        }
      }
    }
  }
  return $out;
}

function supplier_view_ozon_tnved_attribute_name(): string
{
  return 'ТН ВЭД коды ЕАЭС';
}

function supplier_view_text_mentions_tnved(string $text): bool
{
  $lower = function_exists('mb_strtolower') ? mb_strtolower($text, 'UTF-8') : strtolower($text);
  return str_contains($lower, 'тн вэд')
    || str_contains($lower, 'тнвэд')
    || str_contains($lower, 'tnved')
    || str_contains($lower, 'tn ved');
}

function supplier_view_is_technical_characteristic_name(string $name): bool
{
  $name = trim($name);
  if ($name === '') {
    return true;
  }
  $lower = function_exists('mb_strtolower') ? mb_strtolower($name, 'UTF-8') : strtolower($name);
  $norm = supplier_view_norm_characteristic_name($name);
  if (in_array($norm, [
    'attribute id',
    'attribute name',
    'attributeid',
    'attributename',
    'attribute complex id',
    'complex id',
    'dictionary id',
    'description category id',
    'type id',
    'id',
    'name',
    'title',
    'type',
    'key',
    'value',
    'texts',
    'message',
    'description',
    'error',
    'code',
  ], true)) {
    return true;
  }
  if (preg_match('~^[a-z][a-z0-9_]*(?:\.[a-z0-9_]+)*$~', $lower) && str_contains($lower, '_')) {
    return true;
  }
  return false;
}

function supplier_view_characteristic_error_names_from_text(string $text, string $source = ''): array
{
  $text = trim($text);
  if ($text === '') {
    return [];
  }

  $out = [];
  if ($source === 'ozon' && supplier_view_text_mentions_tnved($text)) {
    $name = supplier_view_ozon_tnved_attribute_name();
    $out[supplier_view_norm_characteristic_name($name)] = $name;
  }
  $patterns = [
    '~ошибка\s+характеристики\s*:\s*([^;\n\r]+)~iu',
    '~ошибка\s+значения\s+характеристики\s*:\s*([^;\n\r]+)~iu',
    '~некорректн[а-я\s]+характеристик[а-я\s]*:\s*([^;\n\r]+)~iu',
    '~(?:не\s+заполнена|нет)\s*:\s*([^;\n\r]+)~iu',
  ];
  foreach ($patterns as $pattern) {
    if (!preg_match_all($pattern, $text, $matches)) {
      continue;
    }
    foreach ((array)($matches[1] ?? []) as $name) {
      $name = trim(preg_replace('~\s+~u', ' ', (string)$name));
      $name = trim($name, " \t\n\r\0\x0B:.,;\"'«»");
      if ($name === '') {
        continue;
      }
      if (supplier_view_is_technical_characteristic_name($name)) {
        continue;
      }
      $lower = function_exists('mb_strtolower') ? mb_strtolower($name, 'UTF-8') : strtolower($name);
      if (in_array($lower, ['тип', 'type', 'название', 'name', 'title'], true)) {
        continue;
      }
      if ($source !== '' && supplier_view_is_excluded_characteristic($source, $name)) {
        continue;
      }
      $norm = supplier_view_norm_characteristic_name($name);
      if ($norm !== '') {
        $out[$norm] = $name;
      }
    }
  }
  return $out;
}

function supplier_view_characteristic_error_names_from_value($value, string $source = ''): array
{
  $out = [];
  if (is_array($value)) {
    $attributeNameKeys = ['attribute_name', 'attributeName', 'name', 'field_name', 'fieldName', 'charcName', 'characteristicName'];
    $hasCharacteristicError = false;
    foreach (['code', 'error', 'message', 'description', 'errorText', 'text'] as $key) {
      if (isset($value[$key]) && is_scalar($value[$key])) {
        $part = (string)$value[$key];
        if (preg_match('~характерист|characteristic|attribute|значен~iu', $part)) {
          $hasCharacteristicError = true;
        }
        foreach (supplier_view_characteristic_error_names_from_text($part, $source) as $norm => $name) {
          $out[$norm] = $name;
        }
      }
    }
    if (!$hasCharacteristicError) {
      foreach ($value as $child) {
        if (is_scalar($child) && preg_match('~характерист|characteristic|attribute|значен~iu', (string)$child)) {
          $hasCharacteristicError = true;
          break;
        }
      }
    }
    if ($hasCharacteristicError) {
      foreach ($attributeNameKeys as $key) {
        if (isset($value[$key]) && is_scalar($value[$key])) {
          $name = trim((string)$value[$key]);
          $norm = supplier_view_norm_characteristic_name($name);
          if ($name !== '' && $norm !== '' && !supplier_view_is_technical_characteristic_name($name) && !in_array($norm, ['тип', 'type', 'название', 'name', 'title'], true)) {
            if ($source === '' || !supplier_view_is_excluded_characteristic($source, $name)) {
              $out[$norm] = $name;
            }
          }
        }
      }
      if (isset($value['texts']) && is_array($value['texts'])) {
        foreach (['attribute_name', 'attributeName', 'name'] as $key) {
          if (isset($value['texts'][$key]) && is_scalar($value['texts'][$key])) {
            $name = trim((string)$value['texts'][$key]);
            $norm = supplier_view_norm_characteristic_name($name);
            if ($name !== '' && $norm !== '' && !supplier_view_is_technical_characteristic_name($name) && ($source === '' || !supplier_view_is_excluded_characteristic($source, $name))) {
              $out[$norm] = $name;
            }
          }
        }
      }
    }
    foreach ($value as $child) {
      foreach (supplier_view_characteristic_error_names_from_value($child, $source) as $norm => $name) {
        $out[$norm] = $name;
      }
    }
  } elseif (is_scalar($value)) {
    foreach (supplier_view_characteristic_error_names_from_text((string)$value, $source) as $norm => $name) {
      $out[$norm] = $name;
    }
  }
  return $out;
}

function supplier_view_marketplace_characteristic_error_names_from_row(array $row, string $source): array
{
  $out = [];
  foreach (['status_text', 'status_name', 'status_description'] as $key) {
    if (isset($row[$key])) {
      foreach (supplier_view_characteristic_error_names_from_text((string)$row[$key], $source) as $norm => $name) {
        $out[$norm] = $name;
      }
    }
  }
  $raw = trim((string)($row['raw_json'] ?? ''));
  if ($raw !== '') {
    $decoded = json_decode($raw, true);
    if (is_array($decoded)) {
      foreach (supplier_view_characteristic_error_names_from_value($decoded, $source) as $norm => $name) {
        $out[$norm] = $name;
      }
    }
  }
  return $out;
}

function supplier_view_marketplace_characteristic_error_norms(array $offer, string $source): array
{
  $key = $source === 'wb' ? 'status_wb_characteristic_error_names' : 'status_ozon_characteristic_error_names';
  $out = [];
  foreach ((array)($offer[$key] ?? []) as $norm => $name) {
    $norm = is_string($norm) ? supplier_view_norm_characteristic_name($norm) : supplier_view_norm_characteristic_name((string)$name);
    if ($norm !== '') {
      $out[$norm] = true;
    }
  }
  return $out;
}

function supplier_view_marketplace_badge_html(string $source): string
{
  $label = $source === 'wb' ? 'WB' : 'oz';
  return '<span class="supplier-field-kind supplier-field-kind--' . h($source) . '">' . h($label) . '</span>';
}

function supplier_view_marketplace_attr_name($attr): string
{
  return is_array($attr) ? trim((string)($attr['name'] ?? '')) : trim((string)$attr);
}

function supplier_view_marketplace_attr_allowed_values($attr): array
{
  if (!is_array($attr)) {
    return [];
  }
  $out = [];
  $seen = [];
  foreach ((array)($attr['allowed_values'] ?? []) as $value) {
    $value = trim((string)$value);
    $key = supplier_view_norm_characteristic_name($value);
    if ($value !== '' && $key !== '' && !isset($seen[$key])) {
      $seen[$key] = true;
      $out[] = $value;
    }
  }
  return array_slice($out, 0, 500);
}

function supplier_view_marketplace_attr_has_value_suggestions($attr): bool
{
  if (!is_array($attr)) {
    return false;
  }
  if (supplier_view_marketplace_attr_allowed_values($attr)) {
    return true;
  }
  if (!empty($attr['has_dictionary']) || (int)($attr['dictionary_id'] ?? 0) > 0) {
    return true;
  }
  $selectionMode = trim((string)($attr['selection_mode'] ?? ''));
  $valueSource = trim((string)($attr['value_source'] ?? ''));
  return ($selectionMode !== '' && $selectionMode !== 'free')
    || str_contains($valueSource, 'dictionary')
    || str_contains($valueSource, 'directory');
}

function supplier_view_marketplace_category_not_analyzed_html(string $source): string
{
  $label = $source === 'wb' ? 'WB' : 'Ozon';
  return '<div class="supplier-fields-empty supplier-fields-empty--not-analyzed">'
    . supplier_view_marketplace_badge_html($source)
    . '<span>категория ' . h($label) . ' не проанализирована</span>'
    . '</div>';
}

function supplier_view_marketplace_category_not_selected_html(string $source): string
{
  $label = $source === 'wb' ? 'WB' : 'Ozon';
  return '<div class="supplier-fields-empty supplier-fields-empty--not-analyzed supplier-fields-empty--not-selected">'
    . supplier_view_marketplace_badge_html($source)
    . '<span>выбрать категорию ' . h($label) . '</span>'
    . '</div>';
}

function supplier_view_characteristic_row_html(
  array $offer,
  string $kind,
  string $name,
  string $value,
  int $fieldId,
  string $source = '',
  bool $virtual = false,
  array $allowedValues = [],
  array $flags = []
): string {
  $productId = supplier_view_product_id($offer);
  $displayValue = trim($value) !== '' ? $value : '—';
  $allowedValues = supplier_view_marketplace_attr_allowed_values(['allowed_values' => $allowedValues]);
  $isTnved = $source !== '' && supplier_view_text_mentions_tnved($name);
  $hasValueSuggestions = $source !== '' && ($allowedValues || !empty($flags['has_dictionary']) || $isTnved);
  $isRequired = !empty($flags['required']);
  $hasMarketplaceError = !empty($flags['has_error']);
  $classes = 'supplier-field-row';
  if ($source !== '') {
    $classes .= ' supplier-field-row--marketplace';
  }
  if ($virtual) {
    $classes .= ' supplier-field-row--virtual';
  }
  if ($isRequired) {
    $classes .= ' supplier-field-row--required';
  }
  if ($hasMarketplaceError) {
    $classes .= ' supplier-field-row--has-marketplace-error';
  }
  if ($isTnved) {
    $classes .= ' supplier-field-row--tnved';
  }
  $rowStyle = $source !== '' ? ' style="display:block;width:100%;max-width:100%;min-width:0;overflow:visible;"' : '';
  $displayStyle = $source !== ''
    ? ' style="display:flex;align-items:flex-start;gap:5px;width:100%;max-width:100%;min-width:0;white-space:normal;overflow-wrap:break-word;word-break:normal;"'
    : '';
  $titleParts = [];
  if ($isRequired) {
    $titleParts[] = 'Обязательная характеристика маркетплейса';
  }
  if ($hasMarketplaceError) {
    $titleParts[] = 'Маркетплейс вернул ошибку по значению этой характеристики';
  }
  $titleAttr = $titleParts ? ' title="' . h(implode("\n", $titleParts)) . '"' : '';
  $html = '<div class="' . h($classes) . '" data-field-id="' . h((string)$fieldId) . '" data-kind="' . h($kind) . '" data-field-name="' . h($name) . '" data-field-label="' . h($name) . '"' . ($source !== '' ? ' data-market-source="' . h($source) . '"' : '') . ($hasValueSuggestions ? ' data-has-value-suggestions="1"' : '') . ($isTnved ? ' data-market-tnved="1" data-value-picker-mode="tnved"' : '') . ($virtual ? ' data-virtual-field="1"' : '') . ($isRequired ? ' data-market-required="1"' : '') . ($hasMarketplaceError ? ' data-market-value-error="1"' : '') . $titleAttr . $rowStyle . '>';
  $html .= '<span class="supplier-field-display" tabindex="0"' . $displayStyle . '>';
  if ($source !== '') {
    $html .= '<span class="supplier-field-kind supplier-field-kind--inline supplier-field-kind--' . h($source) . ($hasValueSuggestions ? ' supplier-field-kind--has-dict' : '') . '">' . h($source === 'wb' ? 'WB' : 'oz') . ($hasValueSuggestions ? '<span class="supplier-field-kind-dict">С</span>' : '') . '</span>';
  }
  $textStyle = $source !== '' ? ' style="display:block;min-width:0;white-space:normal;overflow-wrap:break-word;word-break:normal;"' : '';
  $html .= '<span class="supplier-field-text"' . $textStyle . '><b>' . h($name) . '</b>: ' . h($displayValue) . '</span></span>';
  if (!$virtual) {
    $deleteTitle = $source !== '' ? 'Очистить значение характеристики' : 'Удалить характеристику';
    $html .= '<button type="button" class="supplier-field-delete" title="' . h($deleteTitle) . '" aria-label="' . h($deleteTitle) . '">×</button>';
  }
  $html .= '<span class="supplier-field-name" contenteditable="' . ($virtual ? 'false' : 'true') . '" spellcheck="false" data-field-part="name">' . h($name) . '</span>';
  $valueHtml = '<span class="supplier-field-value" contenteditable="' . ($productId > 0 ? 'true' : 'false') . '" spellcheck="false" data-field-part="value">' . h($value) . '</span>';
  if ($source !== '') {
    $html .= '<span class="supplier-field-value-wrap">';
    $html .= $valueHtml;
    if ($hasValueSuggestions) {
      $html .= '<button type="button" class="supplier-field-values-toggle" data-field-values-toggle title="Выбрать допустимое значение" aria-label="Выбрать допустимое значение">▾</button>';
      $html .= '<span class="supplier-field-values-panel" data-field-values-panel></span>';
    }
    $html .= '</span>';
  } else {
    $html .= $valueHtml;
  }
  $html .= '<span class="supplier-edit-state" aria-live="polite"></span>';
  $html .= '</div>';
  return $html;
}

function supplier_view_render_unused_characteristic_fields(
  array $offer,
  string $kind,
  string $source,
  array $fieldsByNorm,
  array $usedFieldIds
): array {
  $html = '';
  $rendered = 0;
  foreach ($fieldsByNorm as $fields) {
    foreach ((array)$fields as $field) {
      if (!is_array($field)) {
        continue;
      }
      $fieldId = (int)($field['id'] ?? 0);
      if ($fieldId > 0 && isset($usedFieldIds[$fieldId])) {
        continue;
      }
      $name = trim((string)($field['field_name'] ?? ''));
      if ($name === '' || supplier_view_is_hashtags_field_name($name)) {
        continue;
      }
      $html .= supplier_view_characteristic_row_html(
        $offer,
        $kind,
        $name,
        (string)($field['field_value'] ?? ''),
        $fieldId,
        $source,
        false
      );
      $rendered++;
    }
  }
  return ['html' => $html, 'count' => $rendered];
}

function supplier_view_characteristics_editor(array $offer, array $marketplaceSets, string $section = 'all'): string
{
  $section = in_array($section, ['all', 'ozon', 'wb', 'other'], true) ? $section : 'all';
  $productId = supplier_view_product_id($offer);
  if ($productId <= 0) {
    if ($section !== 'all') {
      return '<span class="muted">—</span>';
    }
    return '<div style="white-space:pre-wrap;line-height:1.25;">' . h(implode("\n", (array)($offer['params_lines'] ?? []))) . '</div>';
  }

  $ozonCategory = trim((string)($offer['ozon_category'] ?? ''));
  if (preg_match('~^leaf:(\d+_\d+)$~', $ozonCategory, $m)) {
    $ozonCategory = (string)$m[1];
  }
  $wbCategory = trim((string)($offer['wb_category'] ?? ($offer['wb_subject_id'] ?? '')));
  if (preg_match('~^wb:(?:subject|parent):(\d+)$~', $wbCategory, $m)) {
    $wbCategory = (string)$m[1];
  }

  $ozonCategoryMissing = $ozonCategory === '';
  $wbCategoryMissing = $wbCategory === '';
  $categoryOzonAttrs = (array)(($marketplaceSets['ozon'] ?? [])[$ozonCategory] ?? []);
  $ozonAnalysis = (array)((($marketplaceSets['_analysis'] ?? [])['ozon'] ?? []));
  $ozonHasAnalysisKey = $ozonCategory !== '' && array_key_exists($ozonCategory, $ozonAnalysis);
  $ozonCategoryNotAnalyzed = !$ozonCategoryMissing && ($ozonHasAnalysisKey ? !(bool)$ozonAnalysis[$ozonCategory] : !$categoryOzonAttrs);
  $requiredOzon = $categoryOzonAttrs;
  foreach (supplier_view_ozon_attribute_names_from_status($offer) as $norm => $name) {
    if ($norm !== '' && !isset($requiredOzon[$norm])) {
      $requiredOzon[$norm] = supplier_view_norm_characteristic_name($name) === supplier_view_norm_characteristic_name(supplier_view_ozon_tnved_attribute_name())
        ? ['name' => $name, 'required' => true, 'allowed_values' => []]
        : $name;
    }
  }
  foreach ((array)($offer['status_ozon_characteristic_error_names'] ?? []) as $norm => $name) {
    $norm = is_string($norm) ? supplier_view_norm_characteristic_name($norm) : supplier_view_norm_characteristic_name((string)$name);
    $name = trim((string)$name);
    if ($norm !== '' && $name !== '' && !supplier_view_is_technical_characteristic_name($name) && !isset($requiredOzon[$norm])) {
      $requiredOzon[$norm] = $norm === supplier_view_norm_characteristic_name(supplier_view_ozon_tnved_attribute_name())
        ? ['name' => supplier_view_ozon_tnved_attribute_name(), 'required' => true, 'allowed_values' => []]
        : $name;
    }
  }
  $requiredOzon = supplier_view_sort_marketplace_characteristics($requiredOzon);
  $categoryWbAttrs = (array)(($marketplaceSets['wb'] ?? [])[$wbCategory] ?? []);
  $wbAnalysis = (array)((($marketplaceSets['_analysis'] ?? [])['wb'] ?? []));
  $wbHasAnalysisKey = $wbCategory !== '' && array_key_exists($wbCategory, $wbAnalysis);
  $wbCategoryNotAnalyzed = !$wbCategoryMissing && ($wbHasAnalysisKey ? !(bool)$wbAnalysis[$wbCategory] : !$categoryWbAttrs);
  $requiredWb = $categoryWbAttrs;
  foreach ((array)($offer['status_wb_characteristic_error_names'] ?? []) as $norm => $name) {
    $norm = is_string($norm) ? supplier_view_norm_characteristic_name($norm) : supplier_view_norm_characteristic_name((string)$name);
    $name = trim((string)$name);
    if ($norm !== '' && $name !== '' && !supplier_view_is_technical_characteristic_name($name) && !isset($requiredWb[$norm])) {
      $requiredWb[$norm] = $name;
    }
  }
  $requiredWb = supplier_view_sort_marketplace_characteristics($requiredWb);
  $paramByNorm = supplier_view_characteristic_fields_by_norm($offer, 'param');
  $wbParamByNorm = supplier_view_characteristic_fields_by_norm($offer, 'wb_param');
  $ozonErrorNorms = supplier_view_marketplace_characteristic_error_norms($offer, 'ozon');
  $wbErrorNorms = supplier_view_marketplace_characteristic_error_norms($offer, 'wb');

  $usedParamFieldIds = [];
  $usedWbFieldIds = [];
  $hasRenderedRows = false;
  $html = '<div class="supplier-fields-editor supplier-fields-editor--characteristics supplier-fields-editor--characteristics-' . h($section) . '" data-product-id="' . h($productId) . '" data-characteristics-section="' . h($section) . '">';
  $html .= '<div class="supplier-fields-list">';

  if (($section === 'all' || $section === 'ozon') && $ozonCategoryMissing) {
    $html .= supplier_view_marketplace_category_not_selected_html('ozon');
    $hasRenderedRows = true;
  } elseif (($section === 'all' || $section === 'ozon') && $ozonCategoryNotAnalyzed) {
    $html .= supplier_view_marketplace_category_not_analyzed_html('ozon');
    $hasRenderedRows = true;
  }
  if (($section === 'all' || $section === 'wb') && $wbCategoryMissing) {
    $html .= supplier_view_marketplace_category_not_selected_html('wb');
    $hasRenderedRows = true;
  } elseif (($section === 'all' || $section === 'wb') && $wbCategoryNotAnalyzed) {
    $html .= supplier_view_marketplace_category_not_analyzed_html('wb');
    $hasRenderedRows = true;
  }

  foreach ($requiredOzon as $norm => $attr) {
    $name = supplier_view_marketplace_attr_name($attr);
    $allowedValues = supplier_view_marketplace_attr_allowed_values($attr);
    if (supplier_view_is_hashtags_field_name((string)$name) || supplier_view_is_excluded_characteristic('ozon', (string)$name)) {
      continue;
    }
    $fields = supplier_view_characteristic_fields_for_market_name($paramByNorm, (string)$name);
    foreach ($fields as $field) {
      $usedParamFieldIds[(int)($field['id'] ?? 0)] = true;
    }
    $value = supplier_view_characteristic_value_from_fields($fields, $allowedValues, 'ozon', (string)$name);
    $fallbackWbFields = [];
    if ($value === '') {
      $fallbackWbFields = supplier_view_characteristic_fields_for_market_name($wbParamByNorm, (string)$name);
    }
    if ($value === '' && $fallbackWbFields) {
      $value = supplier_view_characteristic_value_from_fields($fallbackWbFields, $allowedValues, 'ozon', (string)$name);
      foreach ($fallbackWbFields as $field) {
        $usedWbFieldIds[(int)($field['id'] ?? 0)] = true;
      }
    }
    if ($section === 'all' || $section === 'ozon') {
      $error = false;
      foreach (supplier_view_characteristic_candidate_norms((string)$name) as $candidateNorm) {
        if (isset($ozonErrorNorms[$candidateNorm])) {
          $error = true;
          break;
        }
      }
      $html .= supplier_view_characteristic_row_html($offer, 'param', (string)$name, $value, (int)($fields[0]['id'] ?? 0), 'ozon', !$fields, $allowedValues, [
        'required' => supplier_view_marketplace_attr_is_required($attr),
        'has_error' => $error,
        'has_dictionary' => supplier_view_marketplace_attr_has_value_suggestions($attr),
      ]);
      $hasRenderedRows = true;
    }
  }

  foreach ($requiredWb as $norm => $attr) {
    $name = supplier_view_marketplace_attr_name($attr);
    $allowedValues = supplier_view_marketplace_attr_allowed_values($attr);
    if (supplier_view_is_hashtags_field_name((string)$name)) {
      continue;
    }
    $fields = supplier_view_characteristic_fields_for_market_name($wbParamByNorm, (string)$name);
    $kind = 'wb_param';
    $virtual = !$fields;
    $fallbackFromParam = false;
    if (!$fields) {
      $fields = supplier_view_characteristic_fields_for_market_name($paramByNorm, (string)$name);
      $fallbackFromParam = true;
    }
    foreach ($fields as $field) {
      $fieldId = (int)($field['id'] ?? 0);
      if (!$virtual && $kind === 'wb_param') {
        $usedWbFieldIds[$fieldId] = true;
      } elseif (!$virtual || $fallbackFromParam) {
        $usedParamFieldIds[$fieldId] = true;
      }
    }
    if ($section === 'all' || $section === 'wb') {
      $error = false;
      foreach (supplier_view_characteristic_candidate_norms((string)$name) as $candidateNorm) {
        if (isset($wbErrorNorms[$candidateNorm])) {
          $error = true;
          break;
        }
      }
      $html .= supplier_view_characteristic_row_html($offer, $kind, (string)$name, supplier_view_characteristic_value_from_fields($fields, $allowedValues, 'wildberries', (string)$name), $virtual ? 0 : (int)($fields[0]['id'] ?? 0), 'wb', $virtual, $allowedValues, [
        'required' => supplier_view_marketplace_attr_is_required($attr),
        'has_error' => $error,
        'has_dictionary' => supplier_view_marketplace_attr_has_value_suggestions($attr),
      ]);
      $hasRenderedRows = true;
    }
  }

  if ($section === 'ozon') {
    $unusedOzon = supplier_view_render_unused_characteristic_fields($offer, 'param', 'ozon', $paramByNorm, $usedParamFieldIds);
    if ((int)($unusedOzon['count'] ?? 0) > 0) {
      $html .= (string)($unusedOzon['html'] ?? '');
      $hasRenderedRows = true;
    }
  }

  if ($section === 'wb') {
    $unusedWb = supplier_view_render_unused_characteristic_fields($offer, 'wb_param', 'wb', $wbParamByNorm, $usedWbFieldIds);
    if ((int)($unusedWb['count'] ?? 0) > 0) {
      $html .= (string)($unusedWb['html'] ?? '');
      $hasRenderedRows = true;
    }
  }

  if ($section === 'all' || $section === 'other') {
    foreach (['param' => $paramByNorm, 'wb_param' => $wbParamByNorm] as $kind => $byNorm) {
      foreach ($byNorm as $norm => $fields) {
        foreach ((array)$fields as $field) {
          $fieldId = (int)($field['id'] ?? 0);
          if (($kind === 'param' && isset($usedParamFieldIds[$fieldId])) || ($kind === 'wb_param' && isset($usedWbFieldIds[$fieldId]))) {
            continue;
          }
          $name = trim((string)($field['field_name'] ?? ''));
          if ($name === '') {
            continue;
          }
          if (supplier_view_is_hashtags_field_name($name)) {
            continue;
          }
          if ($kind === 'param' && supplier_view_is_excluded_characteristic('ozon', $name)) {
            continue;
          }
          $html .= supplier_view_characteristic_row_html($offer, $kind, $name, (string)($field['field_value'] ?? ''), $fieldId, '');
          $hasRenderedRows = true;
        }
      }
    }
  }

  if (!$hasRenderedRows) {
    if ($section === 'ozon' && $ozonCategoryMissing) {
      $html .= supplier_view_marketplace_category_not_selected_html('ozon');
    } elseif ($section === 'ozon' && $ozonCategoryNotAnalyzed) {
      $html .= supplier_view_marketplace_category_not_analyzed_html('ozon');
    } elseif ($section === 'wb' && $wbCategoryMissing) {
      $html .= supplier_view_marketplace_category_not_selected_html('wb');
    } elseif ($section === 'wb' && $wbCategoryNotAnalyzed) {
      $html .= supplier_view_marketplace_category_not_analyzed_html('wb');
    } else {
      $html .= '<div class="supplier-fields-empty muted">—</div>';
    }
  }
  $html .= '</div>';
  $addKind = $section === 'wb' ? 'wb_param' : 'param';
  $html .= '<button type="button" class="supplier-field-add" data-kind="' . h($addKind) . '">+ характеристика</button>';
  $html .= '</div>';
  return $html;
}

function supplier_view_fields_editor(array $offer, array $kinds, string $addKind, string $addLabel, array $fallbackLines, bool $allowAdd = true, array $skipFieldNamesByKind = []): string
{
  $productId = supplier_view_product_id($offer);
  if ($productId <= 0) {
    return '<div style="white-space:pre-wrap;line-height:1.25;">' . h(implode("\n", $fallbackLines)) . '</div>';
  }

  $fields = supplier_view_fields_for_kinds($offer, $kinds);
  $html = '<div class="supplier-fields-editor" data-product-id="' . h($productId) . '">';
  $html .= '<div class="supplier-fields-list">';
  foreach ($fields as $field) {
    $kind = (string)($field['field_kind'] ?? $addKind);
    $fieldId = (int)($field['id'] ?? 0);
    if ($fieldId <= 0) {
      continue;
    }
    $name = (string)($field['field_name'] ?? '');
    $skipNames = (array)($skipFieldNamesByKind[$kind] ?? []);
    if ($skipNames && in_array($name, $skipNames, true)) {
      continue;
    }
    if ($kind === 'tag' && in_array($name, ['ozon_category', 'wb_category', 'wb_subject_id', 'categoryId', 'category', 'price_original', 'brand', 'vendor', 'weight', 'dimensions', 'count', 'stock', 'quantity', 'url', 'same_model'], true)) {
      continue;
    }
    $value = (string)($field['field_value'] ?? '');
    $isStandard = $kind === 'standard';
    $displayName = supplier_view_field_label($kind, $name);
    $displayValue = ($isStandard && trim($value) === '') ? '—' : $value;
    $kindLabel = $kind === 'wb_param' ? 'WB' : '';
    $html .= '<div class="supplier-field-row" data-field-id="' . h($fieldId) . '" data-kind="' . h($kind) . '" data-field-name="' . h($name) . '" data-field-label="' . h($displayName) . '">';
      if ($kindLabel !== '') {
        $html .= '<span class="supplier-field-kind supplier-field-kind--wb">' . h($kindLabel) . '</span>';
    }
    $html .= '<span class="supplier-field-display" tabindex="0"><b>' . h($displayName) . '</b>' . (trim($displayName) !== '' ? ': ' : '') . h($displayValue) . '</span>';
    if (!$isStandard) {
      $html .= '<button type="button" class="supplier-field-delete" title="Удалить характеристику" aria-label="Удалить характеристику">×</button>';
    }
    $html .= '<span class="supplier-field-name" contenteditable="' . ($isStandard ? 'false' : 'true') . '" spellcheck="false" data-field-part="name"></span>';
    $html .= '<span class="supplier-field-value" contenteditable="true" spellcheck="false" data-field-part="value"></span>';
    $html .= '<span class="supplier-edit-state" aria-live="polite"></span>';
    $html .= '</div>';
  }
  $html .= '</div>';
  if ($allowAdd) {
    $html .= '<button type="button" class="supplier-field-add" data-kind="' . h($addKind) . '">' . h($addLabel) . '</button>';
  }
  $html .= '</div>';
  return $html;
}

function supplier_view_features_editor(array $offer): string
{
  $productId = supplier_view_product_id($offer);
  $maxFeatures = defined('SUPPLIER_PRODUCTS_FEATURE_MAX') ? (int)SUPPLIER_PRODUCTS_FEATURE_MAX : 3;
  if ($productId <= 0) {
    $features = [];
    foreach ((array)(($offer['_supplier_fields'] ?? [])['feature'] ?? []) as $field) {
      $value = trim((string)($field['field_value'] ?? ''));
      if ($value !== '') {
        $features[] = $value;
      }
      if (count($features) >= $maxFeatures) {
        break;
      }
    }
    return $features
      ? '<div class="supplier-features-readonly">' . h(implode("\n", $features)) . '</div>'
      : '<span class="muted">—</span>';
  }

  $fields = supplier_view_fields_for_kinds($offer, ['feature']);
  $html = '<div class="supplier-fields-editor supplier-fields-editor--features" data-product-id="' . h($productId) . '" data-feature-max="' . h((string)$maxFeatures) . '">';
  $html .= '<div class="supplier-fields-list">';
  $rendered = 0;
  foreach ($fields as $field) {
    if ($rendered >= $maxFeatures) {
      break;
    }
    $fieldId = (int)($field['id'] ?? 0);
    if ($fieldId <= 0) {
      continue;
    }
    $name = trim((string)($field['field_name'] ?? ''));
    if ($name === '') {
      $name = 'feature_' . ($rendered + 1);
    }
    $value = (string)($field['field_value'] ?? '');
    $displayValue = trim($value) !== '' ? $value : '—';
    $html .= '<div class="supplier-field-row supplier-field-row--feature" data-field-id="' . h($fieldId) . '" data-kind="feature" data-field-name="' . h($name) . '" data-field-label="Фишка" data-display-label="0">';
    $html .= '<span class="supplier-field-display" tabindex="0">' . h($displayValue) . '</span>';
    $html .= '<button type="button" class="supplier-field-delete" title="Удалить фишку" aria-label="Удалить фишку">×</button>';
    $html .= '<span class="supplier-field-name" contenteditable="false" spellcheck="false" data-field-part="name"></span>';
    $html .= '<span class="supplier-field-value" contenteditable="true" spellcheck="false" data-field-part="value"></span>';
    $html .= '<span class="supplier-edit-state" aria-live="polite"></span>';
    $html .= '</div>';
    $rendered++;
  }
  $html .= '</div>';
  $html .= '<button type="button" class="supplier-field-add" data-kind="feature"' . ($rendered >= $maxFeatures ? ' disabled hidden' : '') . '>+ фишка</button>';
  $html .= '</div>';
  return $html;
}

function supplier_view_standard_value_editable(array $offer, string $fieldName, string $fallbackValue): string
{
  $productId = supplier_view_product_id($offer);
  $value = trim($fallbackValue);
  if ($productId <= 0) {
    return '<div class="supplier-offer-plain-cell">' . ($value !== '' ? h($value) : '<span class="muted">—</span>') . '</div>';
  }

  $field = null;
  foreach ((array)(($offer['_supplier_fields'] ?? [])['standard'] ?? []) as $candidate) {
    if (is_array($candidate) && (string)($candidate['field_name'] ?? '') === $fieldName) {
      $field = $candidate;
      break;
    }
  }

  $fieldId = (int)($field['id'] ?? 0);
  $fieldValue = is_array($field) ? (string)($field['field_value'] ?? '') : $fallbackValue;
  $label = supplier_view_field_label('standard', $fieldName);
  $displayValue = trim($fieldValue) !== '' ? $fieldValue : '—';

  return '<div class="supplier-fields-editor supplier-fields-editor--single" data-product-id="' . h($productId) . '">'
    . '<div class="supplier-fields-list">'
    . '<div class="supplier-field-row supplier-field-row--value-only" data-field-id="' . h($fieldId) . '" data-kind="standard" data-field-name="' . h($fieldName) . '" data-field-label="' . h($label) . '" data-display-label="0">'
    . '<span class="supplier-field-display" tabindex="0">' . h($displayValue) . '</span>'
    . '<span class="supplier-field-name" contenteditable="false" spellcheck="false" data-field-part="name"></span>'
    . '<span class="supplier-field-value" contenteditable="true" spellcheck="false" data-field-part="value"></span>'
    . '<span class="supplier-edit-state" aria-live="polite"></span>'
    . '</div>'
    . '</div>'
    . '</div>';
}

function supplier_view_brand_value_editable(array $offer, string $fieldName, string $fallbackValue, string $marketplace): string
{
  return '<div class="supplier-brand-editor" data-brand-editor data-brand-field-name="' . h($fieldName) . '" data-brand-marketplace="' . h($marketplace) . '">'
    . '<div class="supplier-brand-input-row">'
    . '<div class="supplier-brand-input-slot">' . supplier_view_standard_value_editable($offer, $fieldName, $fallbackValue) . '</div>'
    . '</div>'
    . '<div class="supplier-brand-suggest-panel ddpanel" data-brand-suggest-panel>'
    . '<div class="supplier-brand-suggest-results" data-brand-suggest-results></div>'
    . '</div>'
    . '</div>';
}

function supplier_view_standard_values(array $offer): array
{
  $out = [];
  foreach ((array)(($offer['_supplier_fields'] ?? [])['standard'] ?? []) as $field) {
    if (!is_array($field)) {
      continue;
    }
    $name = trim((string)($field['field_name'] ?? ''));
    if ($name === '') {
      continue;
    }
    $out[$name] = trim((string)($field['field_value'] ?? ''));
  }
  return $out;
}

function supplier_view_dimensions_cell(array $offer): string
{
  $productId = supplier_view_product_id($offer);
  if ($productId > 0) {
    $fieldsByName = [];
    foreach ((array)(($offer['_supplier_fields'] ?? [])['standard'] ?? []) as $field) {
      if (!is_array($field)) {
        continue;
      }
      $name = trim((string)($field['field_name'] ?? ''));
      if ($name !== '') {
        $fieldsByName[$name] = $field;
      }
    }

    $html = '<div class="supplier-fields-editor supplier-fields-editor--dimensions" data-product-id="' . h($productId) . '">';
    $html .= '<div class="supplier-fields-list">';
    $hasRows = false;
    foreach (['length', 'width', 'height', 'weight'] as $fieldName) {
      $field = $fieldsByName[$fieldName] ?? null;
      $fieldId = (int)($field['id'] ?? 0);
      if ($fieldId <= 0) {
        continue;
      }
      $label = supplier_view_field_label('standard', $fieldName);
      $value = (string)($field['field_value'] ?? '');
      $displayValue = trim($value) !== '' ? $value : '—';
      $html .= '<div class="supplier-field-row supplier-field-row--dimension" data-field-id="' . h($fieldId) . '" data-kind="standard" data-field-name="' . h($fieldName) . '" data-field-label="' . h($label) . '">';
      $html .= '<span class="supplier-field-display" tabindex="0"><b>' . h($label) . '</b>: ' . h($displayValue) . '</span>';
      $html .= '<span class="supplier-field-name" contenteditable="false" spellcheck="false" data-field-part="name"></span>';
      $html .= '<span class="supplier-field-value" contenteditable="true" spellcheck="false" data-field-part="value"></span>';
      $html .= '<span class="supplier-edit-state" aria-live="polite"></span>';
      $html .= '</div>';
      $hasRows = true;
    }
    $html .= '</div>';
    $html .= '</div>';
    if ($hasRows) {
      return $html;
    }
  }

  $standard = supplier_view_standard_values($offer);
  $length = trim((string)($standard['length'] ?? ''));
  $width = trim((string)($standard['width'] ?? ''));
  $height = trim((string)($standard['height'] ?? ''));
  $weight = trim((string)($standard['weight'] ?? ''));
  if ($weight === '' && isset($offer['weight']) && $offer['weight'] !== null && (string)$offer['weight'] !== '') {
    $weight = supplier_view_money_value($offer['weight']);
  }

  $lines = [];
  if ($length !== '' || $width !== '' || $height !== '') {
    $lines[] = 'Д: ' . ($length !== '' ? $length : '—');
    $lines[] = 'Ш: ' . ($width !== '' ? $width : '—');
    $lines[] = 'В: ' . ($height !== '' ? $height : '—');
  }
  if ($weight !== '') {
    $lines[] = 'Вес: ' . $weight;
  }
  if (!$lines) {
    return '<span class="muted">—</span>';
  }
  $html = '<div class="supplier-dimensions-cell">';
  foreach ($lines as $line) {
    $html .= '<div>' . h($line) . '</div>';
  }
  $html .= '</div>';
  return $html;
}

