function supplier_view_video_cover_field_norm(string $name): string
{
  if (function_exists('supplier_products_video_cover_field_norm')) {
    return supplier_products_video_cover_field_norm($name);
  }
  $name = function_exists('mb_strtolower') ? mb_strtolower(trim($name), 'UTF-8') : strtolower(trim($name));
  $name = preg_replace('~[^\p{L}\p{N}]+~u', ' ', $name) ?: '';
  return trim(preg_replace('~\s+~u', ' ', $name) ?: '');
}

function supplier_view_extract_video_urls(string $value): array
{
  if (function_exists('supplier_products_extract_video_urls')) {
    return supplier_products_extract_video_urls($value);
  }
  $out = [];
  $seen = [];
  $parts = preg_split('~[\s,;\r\n]+~u', trim($value), -1, PREG_SPLIT_NO_EMPTY) ?: [];
  foreach ($parts as $part) {
    $url = trim((string)$part, " \t\n\r\0\x0B\"'<>");
    if ($url === '' || !preg_match('~^https?://~i', $url)) {
      continue;
    }
    $key = function_exists('mb_strtolower') ? mb_strtolower($url, 'UTF-8') : strtolower($url);
    if (isset($seen[$key])) {
      continue;
    }
    $seen[$key] = true;
    $out[] = $url;
  }
  return $out;
}

function supplier_view_video_cover_field(array $offer): array
{
  $wanted = [];
  foreach (supplier_view_video_cover_field_names() as $name) {
    $norm = supplier_view_video_cover_field_norm((string)$name);
    if ($norm !== '') {
      $wanted[$norm] = true;
    }
  }
  foreach ((array)(($offer['_supplier_fields'] ?? [])['param'] ?? []) as $field) {
    if (!is_array($field)) {
      continue;
    }
    $nameNorm = supplier_view_video_cover_field_norm((string)($field['field_name'] ?? ''));
    $value = trim((string)($field['field_value'] ?? ''));
    if ($value !== '' && isset($wanted[$nameNorm])) {
      return [
        'id' => (int)($field['id'] ?? 0),
        'name' => (string)($field['field_name'] ?? ''),
        'value' => $value,
      ];
    }
  }
  return ['id' => 0, 'name' => '', 'value' => ''];
}

function supplier_view_video_fields(array $offer): array
{
  $videoWanted = [];
  foreach (supplier_view_video_field_names() as $name) {
    $norm = supplier_view_video_cover_field_norm((string)$name);
    if ($norm !== '') {
      $videoWanted[$norm] = true;
    }
  }
  $coverWanted = [];
  foreach (supplier_view_video_cover_field_names() as $name) {
    $norm = supplier_view_video_cover_field_norm((string)$name);
    if ($norm !== '') {
      $coverWanted[$norm] = true;
    }
  }

  $out = [];
  $seen = [];
  foreach (['tag', 'param', 'wb_param'] as $kind) {
    foreach ((array)(($offer['_supplier_fields'] ?? [])[$kind] ?? []) as $field) {
      if (!is_array($field)) {
        continue;
      }
      $name = (string)($field['field_name'] ?? '');
      $nameNorm = supplier_view_video_cover_field_norm($name);
      $isCoverLike = isset($coverWanted[$nameNorm])
        || str_contains($nameNorm, 'видеообложк')
        || str_contains($nameNorm, 'video cover')
        || str_contains($nameNorm, 'videocover');
      $isVideoLike = isset($videoWanted[$nameNorm])
        || str_contains($nameNorm, 'видео')
        || str_contains($nameNorm, 'video');
      if ($nameNorm === '' || $isCoverLike || !$isVideoLike) {
        continue;
      }
      $urls = supplier_view_extract_video_urls((string)($field['field_value'] ?? ''));
      if (!$urls) {
        continue;
      }
      foreach ($urls as $url) {
        $key = function_exists('mb_strtolower') ? mb_strtolower($url, 'UTF-8') : strtolower($url);
        if (isset($seen[$key])) {
          continue;
        }
        $seen[$key] = true;
        $out[] = [
          'id' => (int)($field['id'] ?? 0),
          'kind' => $kind,
          'name' => $name,
          'value' => $url,
        ];
      }
    }
  }
  return $out;
}

function supplier_view_video_urls(array $offer, bool $includeCover = true): array
{
  $out = [];
  $seen = [];
  if ($includeCover) {
    $coverUrl = trim((string)(supplier_view_video_cover_field($offer)['value'] ?? ''));
    foreach (supplier_view_extract_video_urls($coverUrl) ?: ($coverUrl !== '' ? [$coverUrl] : []) as $url) {
      $url = trim((string)$url);
      if ($url === '') {
        continue;
      }
      $key = function_exists('mb_strtolower') ? mb_strtolower($url, 'UTF-8') : strtolower($url);
      $seen[$key] = true;
      $out[] = $url;
    }
  }
  foreach (supplier_view_video_fields($offer) as $field) {
    $url = trim((string)($field['value'] ?? ''));
    if ($url === '') {
      continue;
    }
    $key = function_exists('mb_strtolower') ? mb_strtolower($url, 'UTF-8') : strtolower($url);
    if (isset($seen[$key])) {
      continue;
    }
    $seen[$key] = true;
    $out[] = $url;
  }
  return $out;
}

function supplier_view_pictures_editor(array $offer): string
{
  $productId = supplier_view_product_id($offer);
  $pictures = array_values(array_filter(array_map(static fn($v) => trim((string)$v), (array)($offer['pictures'] ?? [])), static fn($v) => $v !== ''));
  $videoCover = supplier_view_video_cover_field($offer);
  $videoCoverUrl = trim((string)($videoCover['value'] ?? ''));
  $videoFields = supplier_view_video_fields($offer);
  if ($productId <= 0) {
    if (!$pictures && $videoCoverUrl === '' && !$videoFields) {
      return '<span class="muted">—</span>';
    }
    $html = '<div class="supplier-pictures-editor supplier-pictures-editor--readonly">';
    if ($pictures) {
      $pic0 = $pictures[0];
      $html .= '<a href="' . h($pic0) . '" target="_blank" rel="noopener"><img src="' . h($pic0) . '" alt="" loading="lazy" referrerpolicy="no-referrer" class="supplier-picture-img"></a>';
    }
    if ($videoCoverUrl !== '') {
      $html .= '<a href="' . h($videoCoverUrl) . '" target="_blank" rel="noopener" class="supplier-video-cover-link">видео-обложка</a>';
    }
    foreach ($videoFields as $videoField) {
      $videoUrl = trim((string)($videoField['value'] ?? ''));
      if ($videoUrl !== '') {
        $html .= '<a href="' . h($videoUrl) . '" target="_blank" rel="noopener" class="supplier-video-cover-link">видео</a>';
      }
    }
    $html .= '</div>';
    return $html;
  }

  $html = '<div class="supplier-pictures-editor" data-product-id="' . h($productId) . '">';
  $html .= '<div class="supplier-picture-list">';
  if (!$pictures) {
    $html .= '<div class="supplier-pictures-empty muted">—</div>';
  } else {
    foreach ($pictures as $i => $picture) {
      $html .= '<div class="supplier-picture-item' . ($i > 0 ? ' is-extra' : '') . '" draggable="true" data-url="' . h($picture) . '">';
      $html .= '<button type="button" class="supplier-picture-remove" title="Удалить фото">×</button>';
      $html .= '<a href="' . h($picture) . '" target="_blank" rel="noopener" draggable="false">';
      $html .= '<img src="' . h($picture) . '" alt="" loading="lazy" referrerpolicy="no-referrer" class="supplier-picture-img" draggable="false">';
      $html .= '</a>';
      $html .= '</div>';
    }
  }
  $html .= '</div>';
  $extra = max(0, count($pictures) - 1);
  if ($extra > 0) {
    $html .= '<button type="button" class="supplier-picture-toggle">еще ' . h((string)$extra) . '</button>';
  }
  if ($videoCoverUrl !== '') {
    $html .= '<div class="supplier-video-cover-card" data-video-cover data-video-kind="cover" data-url="' . h($videoCoverUrl) . '" data-field-id="' . h((string)(int)($videoCover['id'] ?? 0)) . '">';
    $html .= '<button type="button" class="supplier-video-cover-remove" title="Удалить видео-обложку" aria-label="Удалить видео-обложку">×</button>';
    $html .= '<button type="button" class="supplier-video-cover-open" title="' . h($videoCoverUrl) . '">▶ видео-обложка</button>';
    $html .= '<a href="' . h($videoCoverUrl) . '" target="_blank" rel="noopener" class="supplier-video-cover-link" title="' . h($videoCoverUrl) . '">ссылка</a>';
    $html .= '</div>';
  }
  foreach ($videoFields as $videoField) {
    $videoUrl = trim((string)($videoField['value'] ?? ''));
    if ($videoUrl === '') {
      continue;
    }
    $fieldName = trim((string)($videoField['name'] ?? ''));
    $title = $fieldName !== '' ? $fieldName . ': ' . $videoUrl : $videoUrl;
    $html .= '<div class="supplier-video-cover-card supplier-video-card" data-video-cover data-video-kind="external" data-url="' . h($videoUrl) . '" data-field-id="' . h((string)(int)($videoField['id'] ?? 0)) . '">';
    $html .= '<button type="button" class="supplier-video-cover-open" title="' . h($title) . '">▶ видео</button>';
    $html .= '<a href="' . h($videoUrl) . '" target="_blank" rel="noopener" class="supplier-video-cover-link" title="' . h($videoUrl) . '">ссылка</a>';
    $html .= '</div>';
  }
  $html .= '<div class="supplier-picture-actions">';
  $html .= '<button type="button" class="supplier-picture-add" title="Добавить фото">+</button>';
  $html .= '<div class="supplier-picture-menu">';
  $html .= '<button type="button" class="supplier-picture-upload-btn">файл</button>';
  $html .= '<button type="button" class="supplier-picture-add-url">ссылка</button>';
  $html .= '</div>';
  $html .= '<input type="file" class="supplier-picture-file" accept="image/*" hidden>';
  $html .= '</div>';
  $html .= '<span class="supplier-picture-state" aria-live="polite"></span>';
  $html .= '</div>';
  return $html;
}

function supplier_view_category_picker(array $offer, string $source, string $value, string $label = ''): string
{
  $productId = supplier_view_product_id($offer);
  $value = trim($value);
  $label = trim($label);
  if ($label === '') {
    $label = $value;
  }
  if ($productId <= 0) {
    return $label !== '' ? h($label) : '<span class="muted">—</span>';
  }

  $sourceLabel = $source === 'ozon' ? 'Ozon' : 'WB';
  $placeholder = 'Выбрать ' . $sourceLabel;
  $cleanLabel = html_entity_decode($label, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
  $categoryCode = $value;
  if (preg_match('~\s*\(([^()]*)\)\s*$~u', $cleanLabel, $m)) {
    $categoryCode = trim((string)$m[1]);
    $cleanLabel = trim(preg_replace('~\s*\([^()]*\)\s*$~u', '', $cleanLabel) ?? $cleanLabel);
  }
  $pathParts = array_values(array_filter(array_map('trim', explode('>', $cleanLabel)), static fn($v) => $v !== ''));
  $leaf = $cleanLabel !== '' ? trim((string)end($pathParts)) : '';
  if ($leaf === '') {
    $leaf = $value !== '' ? $value : '—';
  }
  $parents = count($pathParts) > 1 ? array_slice($pathParts, 0, -1) : [];
  $hasDetails = ($parents || $categoryCode !== '');
  $buttonTitle = $label !== '' ? $label : $placeholder;
  $buttonClass = 'supplier-category-button' . (($value === '' && $label === '') ? ' supplier-category-button--empty' : '');
  $html = '<div class="supplier-category-picker" data-product-id="' . h($productId) . '" data-source="' . h($source) . '" data-value="' . h($value) . '">';
  if ($hasDetails) {
    $html .= '<button type="button" class="supplier-category-hierarchy-toggle" title="Показать иерархию и код" aria-expanded="false"><span class="supplier-category-toggle-dash">—</span><span class="supplier-category-toggle-arrow">▾</span></button>';
  }
  if ($parents) {
    $html .= '<div class="supplier-category-details">';
    foreach ($parents as $parent) {
      $html .= '<div class="supplier-category-parent-line">' . h($parent) . '</div>';
    }
    $html .= '</div>';
  }
  $html .= '<button type="button" class="' . h($buttonClass) . '" title="' . h($buttonTitle) . '"><span class="supplier-category-branch-icon">↳</span><span class="supplier-category-label">' . h($leaf) . '</span></button>';
  if ($categoryCode !== '') {
    $html .= '<div class="supplier-category-code">Код: ' . h($categoryCode) . '</div>';
  }
  $html .= '<div class="supplier-category-panel ddpanel">';
  $html .= '<input class="supplier-category-search ddsearch" type="text" placeholder="поиск категории...">';
  $html .= '<div class="supplier-category-results"></div>';
  $html .= '<div class="ddactions"><button type="button" class="supplier-category-clear">Очистить</button></div>';
  $html .= '</div></div>';
  return $html;
}

function supplier_view_taxonomy_labels(string $source, array $values): array
{
  $values = array_values(array_unique(array_filter(array_map(static fn($v) => trim((string)$v), $values), static fn($v) => $v !== '')));
  if (!$values) return [];

  $labels = [];
  $pdo = db();

  if ($source === 'ozon') {
    $pairs = [];
    foreach ($values as $value) {
      if (preg_match('~^(\d+)_(\d+)$~', $value, $m)) {
        $pairs[$value] = [$m[1], $m[2]];
      }
    }
    if (!$pairs) return [];

    foreach (array_chunk($pairs, 100, true) as $chunk) {
      $clauses = [];
      $args = ['ozon'];
      foreach ($chunk as $pair) {
        $clauses[] = '(ozon_parent_id = ? AND ozon_leaf_id = ?)';
        $args[] = $pair[0];
        $args[] = $pair[1];
      }
      $sql = "
        SELECT full_path, ozon_parent_id, ozon_leaf_id
        FROM feedtools_taxonomy_categories
        WHERE source = ? AND is_leaf = 1 AND (" . implode(' OR ', $clauses) . ")
      ";
      $st = $pdo->prepare($sql);
      $st->execute($args);
      while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
        $value = (string)($row['ozon_parent_id'] ?? '') . '_' . (string)($row['ozon_leaf_id'] ?? '');
        $label = trim((string)($row['full_path'] ?? ''));
        if ($value !== '' && $label !== '') {
          $labels[$value] = $label . ' (' . $value . ')';
        }
      }
    }
    return $labels;
  }

  if ($source === 'wildberries') {
    $valuesById = [];
    foreach ($values as $value) {
      $id = '';
      if (ctype_digit($value)) {
        $id = $value;
      } elseif (preg_match('~^wb:(?:subject|parent):(\d+)$~', $value, $m)) {
        $id = (string)$m[1];
      }
      if ($id === '') continue;
      if (!isset($valuesById[$id])) $valuesById[$id] = [];
      $valuesById[$id][$value] = true;
    }
    if (!$valuesById) return [];

    foreach (array_chunk(array_keys($valuesById), 200) as $idsChunk) {
      $externalIds = [];
      foreach ($idsChunk as $id) {
        $externalIds[] = 'wb:subject:' . $id;
        $externalIds[] = 'wb:parent:' . $id;
      }
      $placeholders = implode(',', array_fill(0, count($externalIds), '?'));
      $st = $pdo->prepare("
        SELECT full_path, external_id, name, is_leaf
        FROM feedtools_taxonomy_categories
        WHERE source = 'wildberries' AND external_id IN ({$placeholders})
      ");
      $st->execute($externalIds);
      while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
        $externalId = (string)($row['external_id'] ?? '');
        if (!preg_match('~^wb:(?:subject|parent):(\d+)$~', $externalId, $m)) continue;
        $id = (string)$m[1];
        $label = trim((string)($row['full_path'] ?? ''));
        if ($label === '') $label = trim((string)($row['name'] ?? ''));
        if ($id === '' || $label === '' || !isset($valuesById[$id])) continue;
        foreach (array_keys($valuesById[$id]) as $value) {
          if (!isset($labels[$value]) || (int)($row['is_leaf'] ?? 0) === 1) {
            $labels[$value] = $label . ' (' . $id . ')';
          }
        }
      }
    }
  }

  return $labels;
}


function sanitize_description_html(string $html): string
{
  $html = str_replace(['<![CDATA[', ']]>'], '', $html);
  $html = preg_replace('~<!--.*?-->~s', '', $html);
  $html = preg_replace('~<\s*(script|style|iframe|object|embed|svg|canvas|form|input|button|textarea|select|video|audio|source|picture|img)\b[^>]*>.*?<\s*/\s*\1\s*>~is', '', $html);
  $html = preg_replace('~<\s*(script|style|iframe|object|embed|svg|canvas|form|input|button|textarea|select|video|audio|source|picture|img)\b[^>]*\/?\s*>~is', '', (string)$html);

  $allowed = '<p><br><ul><ol><li><b><strong><i><em><span><div><h1><h2><h3><h4>';
  $html = strip_tags((string)$html, $allowed);

  // Оставляем только безопасные теги без любых inline-style/class/id/on*.
  $html = preg_replace_callback('~<\s*(/?)\s*(p|br|ul|ol|li|b|strong|i|em|span|div|h1|h2|h3|h4)\b[^>]*>~i', static function (array $m): string {
    $closing = ($m[1] ?? '') === '/';
    $tag = strtolower((string)$m[2]);
    if ($tag === 'br') return '<br>';
    return $closing ? "</{$tag}>" : "<{$tag}>";
  }, (string)$html);

  return trim((string)$html);
}

function supplier_view_description_plain_text(string $html): string
{
  $text = str_replace(["\0", "\xEF\xBB\xBF"], '', $html);
  if (trim($text) === '') {
    return '';
  }

  for ($i = 0; $i < 2; $i++) {
    $text = html_entity_decode($text, ENT_QUOTES | ENT_HTML5, 'UTF-8');
  }

  $text = str_replace(['<![CDATA[', ']]>'], '', $text);
  $text = preg_replace('~<!--.*?-->~su', ' ', $text);

  $embedded = 'script|style|iframe|object|embed|svg|canvas|form';
  $media = 'input|button|textarea|select|video|audio|source|picture|img';
  $text = preg_replace('~<\s*(?:' . $embedded . ')\b.*?(?:<\s*/\s*(?:' . $embedded . ')\s*>|/\s*(?:' . $embedded . ')\s*>)~isu', ' ', (string)$text);
  $text = preg_replace('~<\s*(?:' . $media . ')\b[^>]*\/?\s*>~isu', ' ', (string)$text);
  $text = preg_replace('~<\s*(?:' . $embedded . ')\b[^>]*\/?\s*>~isu', ' ', (string)$text);

  $text = preg_replace('~<\s*br\b[^>]*>~iu', "\n", (string)$text);
  $text = preg_replace('~(?<!<)\bbr\s*/?>~iu', "\n", (string)$text);
  $text = preg_replace('~<\s*li\b[^>]*>~iu', "\n- ", (string)$text);
  $text = preg_replace('~<\s*/\s*li\s*>~iu', "\n", (string)$text);
  $blockTags = 'p|div|section|article|header|footer|h[1-6]|table|thead|tbody|tfoot|tr|td|th|ul|ol|blockquote';
  $text = preg_replace('~<\s*/?\s*(?:' . $blockTags . ')\b[^>]*>~iu', "\n", (string)$text);
  $text = preg_replace('~<\s*/?\s*(?:a|b|strong|i|em|span|small|mark|font)\b[^>]*>~iu', '', (string)$text);
  $text = strip_tags((string)$text);

  $text = preg_replace('~\s(?:style|class|id|srcdoc|src|title|width|height|loading|allow|frameborder)="[^"]*"~iu', ' ', (string)$text);
  $text = preg_replace('~(?:^|\s)/?\s*(?:iframe|style|script|div|span|p|strong|em|b|i|ul|ol|li|br)\b[^<>\n]{0,140}>~iu', "\n", (string)$text);
  $text = preg_replace('~"[^"\n]{0,160}"\s*/?\s*(?:iframe|style|script|div|span|p)\s*>?~iu', "\n", (string)$text);

  $text = str_replace(["\xc2\xa0", "\xe2\x80\x8b", "\r\n", "\r"], [' ', '', "\n", "\n"], (string)$text);
  $lines = preg_split('~\n~u', $text);
  $clean = [];
  foreach ($lines ?: [] as $line) {
    $line = trim((string)$line);
    $line = preg_replace('~[ \t]+~u', ' ', $line);
    if ($line === null) {
      $line = '';
    }
    if ($line === '') {
      $clean[] = '';
      continue;
    }
    if (preg_match('~^[\'"]+$~u', $line)) {
      continue;
    }
    if (preg_match('~^/?(?:iframe|style|script|div|span|p|strong|em|b|i|ul|ol|li|br)\s*>?$~iu', $line)) {
      continue;
    }
    if (preg_match('~^(?:[a-z][a-z-]{2,}\s*:\s*[^;\n]+;\s*)+$~', $line)) {
      continue;
    }
    if (preg_match('~^(?:body|html|\.?[a-z0-9_-]+|#[a-z0-9_-]+|\*)\s*\{~i', $line)) {
      continue;
    }
    if (preg_match('~^[{};,]+$~', $line)) {
      continue;
    }
    $clean[] = $line;
  }

  $text = implode("\n", $clean);
  $text = preg_replace('~[ \t]+\n~u', "\n", $text);
  $text = preg_replace('~\n[ \t]+~u', "\n", (string)$text);
  $text = preg_replace('~\n{3,}~u', "\n\n", (string)$text);
  return trim(is_string($text) ? $text : '');
}

function supplier_view_offer_from_product_row(array $row, array $catMap = []): array
{
  $fieldsByKind = [
    'standard' => [],
    'attr' => [],
    'tag' => [],
    'param' => [],
    'wb_param' => [],
    'feature' => [],
  ];
  foreach ((array)($row['fields'] ?? []) as $kind => $fields) {
    if (!isset($fieldsByKind[$kind])) continue;
    foreach ((array)$fields as $field) {
      if (is_array($field)) $fieldsByKind[$kind][] = $field;
    }
  }

  $standard = [];
  foreach ($fieldsByKind['standard'] as $field) {
    $name = trim((string)($field['field_name'] ?? ''));
    if ($name !== '') $standard[$name] = (string)($field['field_value'] ?? '');
  }

  $details = [];
  $url = '';
  $hashtags = [];
  $sameModel = '';
  $sameModelFieldId = 0;
  foreach ($fieldsByKind['attr'] as $field) {
    $name = trim((string)($field['field_name'] ?? ''));
    if ($name === '') continue;
    $details[] = '@' . $name . ': ' . (string)($field['field_value'] ?? '');
  }
  foreach ($fieldsByKind['tag'] as $field) {
    $name = trim((string)($field['field_name'] ?? ''));
    $value = trim((string)($field['field_value'] ?? ''));
    if ($name === '') continue;
    if ($name === 'url') {
      $url = $value;
      continue;
    }
    if (supplier_view_is_hashtags_field_name($name)) {
      $hashtags = array_values(array_unique(array_merge($hashtags, supplier_view_hashtag_values_from_text($value))));
      if ($hashtags) $details[] = 'hashtags: ' . implode(' ', $hashtags);
      continue;
    }
    if ($name === 'same_model') {
      $sameModel = $value;
      $sameModelFieldId = (int)($field['id'] ?? 0);
      continue;
    }
    if (in_array($name, ['ozon_category', 'wb_category', 'wb_subject_id', 'categoryId', 'category', 'price_original', 'brand', 'vendor', 'weight', 'dimensions', 'count', 'stock', 'quantity'], true)) {
      continue;
    }
    $details[] = $name . ': ' . $value;
  }

  $paramsLines = [];
  $paramsKv = [];
  foreach ($fieldsByKind['param'] as $field) {
    $name = trim((string)($field['field_name'] ?? ''));
    $value = trim((string)($field['field_value'] ?? ''));
    if ($name === '') continue;
    if (supplier_view_is_hashtags_field_name($name)) {
      $hashtags = array_values(array_unique(array_merge($hashtags, supplier_view_hashtag_values_from_text($value))));
      continue;
    }
    $paramsLines[] = $name . ': ' . $value;
    $paramsKv[$name][] = $value;
  }
  foreach ($fieldsByKind['wb_param'] as $field) {
    $name = trim((string)($field['field_name'] ?? ''));
    $value = trim((string)($field['field_value'] ?? ''));
    if ($name === '') continue;
    if (supplier_view_is_hashtags_field_name($name)) {
      $hashtags = array_values(array_unique(array_merge($hashtags, supplier_view_hashtag_values_from_text($value))));
      continue;
    }
    $label = '[WB] ' . $name;
    $paramsLines[] = $label . ': ' . $value;
    $paramsKv[$label][] = $value;
  }

  $pictures = supplier_products_decode_json_array($row['pictures_json'] ?? null);
  $pictures = array_values(array_filter(array_map(static fn($v) => trim((string)$v), $pictures), static fn($v) => $v !== ''));

  $categoryId = trim((string)($row['category_id'] ?? ''));
  $categoryPath = trim((string)($row['category_path'] ?? ''));
  if ($categoryPath === '' && $categoryId !== '' && $catMap) {
    $categoryPath = supplier_products_build_category_path($categoryId, $catMap);
  }

  $brand = trim((string)($standard['brand'] ?? ''));
  if ($brand === '') $brand = trim((string)($row['brand'] ?? ''));
  $brandOzon = array_key_exists('brand_ozon', $standard) ? trim((string)$standard['brand_ozon']) : $brand;
  $brandWb = array_key_exists('brand_wb', $standard) ? trim((string)$standard['brand_wb']) : $brand;
  $purchasePrice = trim((string)($standard['purchase_price'] ?? ''));
  $priceOriginal = null;
  if ($purchasePrice !== '') {
    $num = str_replace(["\xc2\xa0", ' '], '', $purchasePrice);
    $num = str_replace(',', '.', $num);
    if (is_numeric($num)) $priceOriginal = (float)$num;
  } elseif (($row['price_original'] ?? null) !== null && (string)$row['price_original'] !== '') {
    $priceOriginal = (float)$row['price_original'];
  }

  $stockRaw = trim((string)($standard['stock'] ?? ''));
  $stock = $stockRaw !== '' ? (int)$stockRaw : (int)($row['stock_qty'] ?? 0);
  $count = (int)($row['count_qty'] ?? 0);
  $marketplaceEnabled = supplier_products_normalize_marketplace_enabled($row['marketplace_enabled'] ?? 1);
  $stockModifier = (int)($row['stock_modifier'] ?? 0);
  $priceModifier = supplier_products_normalize_price_modifier($row['price_modifier'] ?? '');
  $weightRaw = trim((string)($standard['weight'] ?? ''));
  $weight = null;
  if ($weightRaw !== '') {
    $num = str_replace(',', '.', str_replace(["\xc2\xa0", ' '], '', $weightRaw));
    if (is_numeric($num)) $weight = (float)$num;
  }
  $dimensions = '';
  $dimParts = [
    trim((string)($standard['length'] ?? '')),
    trim((string)($standard['width'] ?? '')),
    trim((string)($standard['height'] ?? '')),
  ];
  if (implode('', $dimParts) !== '') {
    $dimensions = implode('/', $dimParts);
  }

  return [
    'id' => (string)($row['offer_id'] ?? ''),
    'name' => (string)($row['name'] ?? ''),
    'same_model' => $sameModel,
    'same_model_field_id' => $sameModelFieldId,
    'category_id' => $categoryId,
    'category_path' => $categoryPath,
    'ozon_category' => (string)($row['ozon_category'] ?? ''),
    'wb_category' => (string)($row['wb_category'] ?? ''),
    'wb_subject_id' => (string)($row['wb_category'] ?? ''),
    'article' => (string)($row['vendor_code'] ?? ''),
    'vendorCode' => (string)($row['vendor_code'] ?? ''),
    'vendor_code' => (string)($row['vendor_code'] ?? ''),
    'brand_effective' => $brand,
    'brand_ozon_effective' => $brandOzon,
    'brand_wb_effective' => $brandWb,
    'details' => $details,
    'description_html' => (string)($row['description_html'] ?? ''),
    'params_lines' => $paramsLines,
    'params_kv' => $paramsKv,
    'url' => $url,
    'pictures' => $pictures,
    'count' => $count,
    'stock' => $stock,
    'price_original' => $priceOriginal,
    'marketplace_enabled' => $marketplaceEnabled,
    'stock_modifier' => $stockModifier,
    'price_modifier' => $priceModifier,
    'weight' => $weight,
    'dimensions' => $dimensions,
    'hashtags' => $hashtags,
    '_supplier_product_id' => (int)($row['id'] ?? 0),
    '_supplier_fields' => $fieldsByKind,
  ];
}

function supplier_view_supplier_product_rows_by_offer_ids(int $supplierId, array $offerIds, array $cfg = []): array
{
  supplier_products_tables_ensure($cfg);
  $offerIds = array_values(array_unique(array_values(array_filter(array_map(
    static fn($value): string => trim((string)$value),
    $offerIds
  ), static fn(string $value): bool => $value !== ''))));
  if ($supplierId <= 0 || !$offerIds) {
    return [];
  }

  $pdo = db();
  $placeholders = implode(',', array_fill(0, count($offerIds), '?'));
  $st = $pdo->prepare("
    SELECT *
    FROM feedtools_supplier_products
    WHERE supplier_id = ?
      AND offer_id IN ({$placeholders})
  ");
  $st->execute(array_merge([$supplierId], $offerIds));

  $rows = [];
  $productIds = [];
  while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
    $row['fields'] = [
      'standard' => [],
      'attr' => [],
      'tag' => [],
      'param' => [],
      'wb_param' => [],
      'feature' => [],
    ];
    $offerId = trim((string)($row['offer_id'] ?? ''));
    if ($offerId === '') {
      continue;
    }
    $rows[$offerId] = $row;
    $productIds[] = (int)($row['id'] ?? 0);
  }

  $productIds = array_values(array_filter(array_unique($productIds)));
  if (!$productIds) {
    return $rows;
  }

  $fieldPlaceholders = implode(',', array_fill(0, count($productIds), '?'));
  $fields = $pdo->prepare("
    SELECT *
    FROM feedtools_supplier_product_fields
    WHERE product_id IN ({$fieldPlaceholders})
    ORDER BY product_id ASC, sort_order ASC, id ASC
  ");
  $fields->execute($productIds);
  $byProductId = [];
  foreach ($rows as $offerId => $row) {
    $productId = (int)($row['id'] ?? 0);
    if ($productId > 0) {
      $byProductId[$productId] = $offerId;
    }
  }
  while ($field = $fields->fetch(PDO::FETCH_ASSOC)) {
    $productId = (int)($field['product_id'] ?? 0);
    $offerId = (string)($byProductId[$productId] ?? '');
    if ($offerId === '') {
      continue;
    }
    $kind = (string)($field['field_kind'] ?? 'tag');
    if (!isset($rows[$offerId]['fields'][$kind])) {
      $kind = 'tag';
    }
    $rows[$offerId]['fields'][$kind][] = $field;
  }

  return $rows;
}

function supplier_view_offer_raw_effective_stock(array $offer): int
{
  $base = max((int)($offer['stock'] ?? 0), (int)($offer['count'] ?? 0));
  return supplier_products_apply_stock_modifier(
    $base,
    (int)($offer['marketplace_enabled'] ?? 1),
    (int)($offer['stock_modifier'] ?? 0)
  );
}

function supplier_view_offer_effective_price(array $offer): ?float
{
  if (array_key_exists('_display_price_original', $offer) && $offer['_display_price_original'] !== null) {
    return (float)$offer['_display_price_original'];
  } elseif (isset($offer['price_original']) && $offer['price_original'] !== null) {
    return (float)$offer['price_original'];
  }
  return null;
}

function supplier_view_apply_bundle_ui_values(array &$offers, int $supplierId, array $catMap = [], array $cfg = []): void
{
  if (!$offers) {
    return;
  }

  $baseOfferIds = [];
  $offerIndexById = [];
  foreach ($offers as $idx => &$offer) {
    $offerId = trim((string)($offer['id'] ?? ''));
    $info = bundle_offer_parse($offerId);
    $offer['_is_bundle'] = !empty($info['is_bundle']);
    $offer['_bundle_qty'] = (int)($info['bundle_qty'] ?? 1);
    $offer['_bundle_base_offer_id'] = (string)($info['base_offer_id'] ?? '');
    if ($offerId !== '' && empty($info['is_bundle'])) {
      $offerIndexById[$offerId] = $idx;
    }
    if (!empty($info['is_bundle']) && (int)($info['bundle_qty'] ?? 1) > 1 && (string)($info['base_offer_id'] ?? '') !== '') {
      $baseOfferIds[(string)$info['base_offer_id']] = true;
    }
  }
  unset($offer);

  if (!$baseOfferIds) {
    return;
  }

  $baseOffers = [];
  foreach (array_keys($baseOfferIds) as $baseOfferId) {
    if (isset($offerIndexById[$baseOfferId]) && isset($offers[$offerIndexById[$baseOfferId]])) {
      $baseOffers[$baseOfferId] = $offers[$offerIndexById[$baseOfferId]];
    }
  }

  $missingBaseIds = array_values(array_diff(array_keys($baseOfferIds), array_keys($baseOffers)));
  if ($missingBaseIds) {
    foreach (supplier_view_supplier_product_rows_by_offer_ids($supplierId, $missingBaseIds, $cfg) as $baseOfferId => $row) {
      $baseOffers[$baseOfferId] = supplier_view_offer_from_product_row($row, $catMap);
    }
  }

  foreach ($offers as &$offer) {
    if (empty($offer['_is_bundle'])) {
      continue;
    }
    $qty = max(1, (int)($offer['_bundle_qty'] ?? 1));
    $baseOfferId = (string)($offer['_bundle_base_offer_id'] ?? '');
    $baseOffer = is_array($baseOffers[$baseOfferId] ?? null) ? $baseOffers[$baseOfferId] : [];

    if ($baseOffer) {
      $unitPrice = isset($baseOffer['price_original']) && $baseOffer['price_original'] !== null
        ? (float)$baseOffer['price_original']
        : null;
      $offer['_bundle_unit_price_original'] = $unitPrice;
      $offer['_display_price_original'] = $unitPrice !== null ? $unitPrice * $qty : null;

      $baseStock = supplier_view_offer_raw_effective_stock($baseOffer);
      $offer['_bundle_base_stock'] = $baseStock;
      $offer['_display_stock'] = bundle_offer_bundle_units_from_base($offer['id'] ?? '', $baseStock);
      continue;
    }

    $offer['_bundle_base_missing'] = true;
    if (isset($offer['price_original']) && $offer['price_original'] !== null) {
      $offer['_display_price_original'] = (float)$offer['price_original'];
    }
    $offer['_display_stock'] = supplier_view_offer_raw_effective_stock($offer);
  }
  unset($offer);
}

function supplier_view_bundle_ui_values_are_needed_for_candidate_filtering(
  string $offerSort,
  bool $filterInStock,
  ?float $filterPriceMin,
  ?float $filterPriceMax,
  ?int $filterStockMin,
  ?int $filterStockMax
): bool {
  return in_array($offerSort, ['price', 'stock'], true)
    || $filterInStock
    || $filterPriceMin !== null
    || $filterPriceMax !== null
    || $filterStockMin !== null
    || $filterStockMax !== null;
}

function supplier_view_apply_bundle_ui_values_for_visible_rows(array &$offers, int $supplierId, array $catMap = [], array $cfg = []): void
{
  if (!$offers || count($offers) > 1000) {
    return;
  }
  supplier_view_apply_bundle_ui_values($offers, $supplierId, $catMap, $cfg);
}

function supplier_view_supplier_product_facets(int $supplierId, array $catMap = [], array $cfg = [], bool $includeParams = true): array
{
  $facets = [
    'catpath' => [],
    'ozoncat' => [],
    'wbcat' => [],
    'brand' => [],
    'brand_ozon' => [],
    'brand_wb' => [],
    'model' => [],
    'brand_status_ozon' => [],
    'brand_status_wb' => [],
    'status_ozon' => [],
    'status_wb' => [],
    'hashtag' => [],
    'params' => [],
  ];
  if ($supplierId <= 0) {
    return $facets;
  }

  $pdo = db();
  $facetCat = [];
  $facetOzon = [];
  $facetWb = [];
  $facetBrand = [];
  $facetBrandOzon = [];
  $facetBrandWb = [];
  $facetModel = [];
  $facetBrandStatusOzon = [];
  $facetBrandStatusWb = [];
  $facetHashtag = [];
  $facetParams = [];

  $st = $pdo->prepare("
    SELECT
      p.category_id,
      p.category_path,
      p.ozon_category,
      p.wb_category,
      p.brand,
      fsm.field_value AS same_model,
      fbo.field_value AS brand_ozon,
      fbw.field_value AS brand_wb
    FROM feedtools_supplier_products p
    LEFT JOIN feedtools_supplier_product_fields fsm
      ON fsm.product_id = p.id
      AND fsm.supplier_id = p.supplier_id
      AND fsm.field_kind = 'tag'
      AND fsm.field_name = 'same_model'
    LEFT JOIN feedtools_supplier_product_fields fbo
      ON fbo.product_id = p.id
      AND fbo.supplier_id = p.supplier_id
      AND fbo.field_kind = 'standard'
      AND fbo.field_name = 'brand_ozon'
    LEFT JOIN feedtools_supplier_product_fields fbw
      ON fbw.product_id = p.id
      AND fbw.supplier_id = p.supplier_id
      AND fbw.field_kind = 'standard'
      AND fbw.field_name = 'brand_wb'
    WHERE p.supplier_id = ?
  ");
  $st->execute([$supplierId]);
  while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
    $categoryId = trim((string)($row['category_id'] ?? ''));
    $categoryPath = trim((string)($row['category_path'] ?? ''));
    if ($categoryPath === '' && $categoryId !== '' && $catMap) {
      $categoryPath = supplier_products_build_category_path($categoryId, $catMap);
    }
    $ozonCategory = trim((string)($row['ozon_category'] ?? ''));
    $wbCategory = trim((string)($row['wb_category'] ?? ''));
    $brand = trim((string)($row['brand'] ?? ''));
    $brandOzon = trim((string)($row['brand_ozon'] ?? ''));
    $brandWb = trim((string)($row['brand_wb'] ?? ''));
    $model = trim((string)($row['same_model'] ?? ''));
    if ($brandOzon === '') $brandOzon = $brand;
    if ($brandWb === '') $brandWb = $brand;

    $facetCat[$categoryPath === '' ? EMPTY_TOKEN : $categoryPath] = true;
    $facetOzon[$ozonCategory === '' ? EMPTY_TOKEN : $ozonCategory] = true;
    $facetWb[$wbCategory === '' ? EMPTY_TOKEN : $wbCategory] = true;
    $facetBrand[$brand === '' ? EMPTY_TOKEN : $brand] = true;
    $facetBrandOzon[$brandOzon === '' ? EMPTY_TOKEN : $brandOzon] = true;
    $facetBrandWb[$brandWb === '' ? EMPTY_TOKEN : $brandWb] = true;
    $facetModel[$model === '' ? EMPTY_TOKEN : $model] = true;
  }

  $hashtags = $pdo->prepare("
    SELECT DISTINCT field_value
    FROM feedtools_supplier_product_fields
    WHERE supplier_id = ?
      AND field_kind = 'tag'
      AND field_name = 'hashtags'
      AND field_value IS NOT NULL
      AND field_value <> ''
  ");
  $hashtags->execute([$supplierId]);
  while ($value = $hashtags->fetchColumn()) {
    $parts = preg_split('/[\s,;]+/u', trim((string)$value), -1, PREG_SPLIT_NO_EMPTY) ?: [];
    foreach ($parts as $part) {
      $part = trim((string)$part);
      if ($part === '') continue;
      if ($part[0] !== '#') $part = '#' . $part;
      $facetHashtag[$part] = true;
    }
  }

  if ($includeParams) {
    $params = $pdo->prepare("
      SELECT field_kind, field_name, field_value
      FROM feedtools_supplier_product_fields
      WHERE supplier_id = ?
        AND field_kind IN ('param', 'wb_param')
        AND field_name <> ''
      GROUP BY field_kind, field_name, field_value
    ");
    $params->execute([$supplierId]);
    while ($field = $params->fetch(PDO::FETCH_ASSOC)) {
      $kind = (string)($field['field_kind'] ?? '');
      $name = trim((string)($field['field_name'] ?? ''));
      $value = trim((string)($field['field_value'] ?? ''));
      if ($name === '' || !in_array($kind, ['param', 'wb_param'], true)) {
        continue;
      }
      $facetName = $kind === 'wb_param' ? '[WB] ' . $name : $name;
      if (!isset($facetParams[$facetName])) $facetParams[$facetName] = [];
      $facetParams[$facetName][$value === '' ? EMPTY_TOKEN : $value] = true;
    }
  }

  $cmp = function ($a, $b) {
    $la = ($a === EMPTY_TOKEN) ? '∅ (пусто)' : $a;
    $lb = ($b === EMPTY_TOKEN) ? '∅ (пусто)' : $b;
    return strcasecmp($la, $lb);
  };

  $facets['catpath'] = array_keys($facetCat);
  $facets['ozoncat'] = array_keys($facetOzon);
  $facets['wbcat'] = array_keys($facetWb);
  $facets['brand'] = array_keys($facetBrand);
  $facets['brand_ozon'] = array_keys($facetBrandOzon);
  $facets['brand_wb'] = array_keys($facetBrandWb);
  $facets['model'] = array_keys($facetModel);
  $facets['brand_status_ozon'] = supplier_view_default_brand_status_filter_tokens();
  $facets['brand_status_wb'] = supplier_view_default_brand_status_filter_tokens();
  $facets['hashtag'] = array_keys($facetHashtag);

  usort($facets['catpath'], $cmp);
  usort($facets['ozoncat'], $cmp);
  usort($facets['wbcat'], $cmp);
  usort($facets['brand'], $cmp);
  usort($facets['brand_ozon'], $cmp);
  usort($facets['brand_wb'], $cmp);
  usort($facets['model'], $cmp);
  usort($facets['hashtag'], $cmp);

  if ($includeParams) {
    foreach ($facetParams as $pname => $valsMap) {
      $vals = array_keys((array)$valsMap);
      usort($vals, $cmp);
      $facets['params'][$pname] = $vals;
    }
    uksort($facets['params'], static function ($a, $b) {
      return strcasecmp((string)$a, (string)$b);
    });
  }

  return $facets;
}

function url_with(array $extra): string
{
  $q = [];
  foreach (['id', 'supplier_id', 'limit', 'page', 'sort', 'dir'] as $key) {
    if (isset($_GET[$key]) && !is_array($_GET[$key])) {
      $q[$key] = (string)$_GET[$key];
    }
  }
  foreach ($extra as $key => $value) {
    if ($value === null || $value === '') {
      unset($q[$key]);
      continue;
    }
    $q[$key] = $value;
  }
  return '?' . http_build_query($q);
}

function supplier_view_offer_effective_stock(array $offer): int
{
  if (array_key_exists('_display_stock', $offer)) {
    return supplier_products_apply_stock_modifier(
      max(0, (int)$offer['_display_stock']),
      (int)($offer['marketplace_enabled'] ?? 1),
      (int)($offer['stock_modifier'] ?? 0)
    );
  }
  return supplier_view_offer_raw_effective_stock($offer);
}

function supplier_view_offer_controls_html(array $offer): string
{
  $productId = supplier_view_product_id($offer);
  $enabled = supplier_products_normalize_marketplace_enabled($offer['marketplace_enabled'] ?? 1);
  $stockModifier = (int)($offer['stock_modifier'] ?? 0);
  $priceModifier = supplier_products_normalize_price_modifier($offer['price_modifier'] ?? '');
  $disabled = $productId <= 0;
  $baseStock = max((int)($offer['stock'] ?? 0), (int)($offer['count'] ?? 0));
  $purchasePrice = isset($offer['price_original']) && $offer['price_original'] !== null ? supplier_view_money_value((float)$offer['price_original']) : '';
  $title = 'Ручное управление: выключенный товар всегда выгружается с остатком 0. Остаток: +5 или -2. Модификатор цены применяется к итоговой цене продажи: +100, -50, +5%, -7%, =999.';
  $html = '<div class="supplier-offer-controls ' . ($enabled ? 'is-enabled' : 'is-disabled') . '" data-offer-control data-product-id="' . h((string)$productId) . '" title="' . h($title) . '">';
  $html .= '<label class="supplier-offer-sale-switch">';
  $html .= '<input type="checkbox" data-offer-control-enabled ' . ($enabled ? 'checked' : '') . ($disabled ? ' disabled' : '') . '>';
  $html .= '<span class="supplier-offer-sale-slider" aria-hidden="true"></span>';
  $html .= '<span class="supplier-offer-sale-label">' . h($enabled ? 'в продаже' : 'снят') . '</span>';
  $html .= '</label>';
  $html .= '<label class="supplier-offer-control-field"><span>ост.</span><input type="text" inputmode="numeric" data-offer-control-stock value="' . h((string)$stockModifier) . '" placeholder="0" ' . ($disabled ? 'disabled' : '') . '></label>';
  $html .= '<label class="supplier-offer-control-field"><span>цена</span><input type="text" inputmode="decimal" data-offer-control-price value="' . h($priceModifier) . '" placeholder="+0" ' . ($disabled ? 'disabled' : '') . '></label>';
  $meta = [];
  $meta[] = 'база ост.: ' . $baseStock;
  if ($purchasePrice !== '') {
    $meta[] = 'закупка: ' . $purchasePrice;
  }
  $html .= '<div class="supplier-offer-control-meta">' . h(implode(' · ', $meta)) . '</div>';
  $html .= '<div class="supplier-offer-control-state" data-offer-control-state></div>';
  $html .= '</div>';
  return $html;
}

function supplier_view_offer_sort_value(array $offer, string $sort)
{
  switch ($sort) {
    case 'id':
      return (string)($offer['id'] ?? '');
    case 'name':
      return (string)($offer['name'] ?? '');
    case 'description':
      return trim(strip_tags((string)($offer['description_html'] ?? '')));
    case 'brand':
      return (string)($offer['brand_effective'] ?? '');
    case 'brand_ozon':
      return (string)($offer['brand_ozon_effective'] ?? ($offer['brand_effective'] ?? ''));
    case 'brand_wb':
      return (string)($offer['brand_wb_effective'] ?? ($offer['brand_effective'] ?? ''));
    case 'price':
      return supplier_view_offer_effective_price($offer);
    case 'stock':
      return supplier_view_offer_effective_stock($offer);
    case 'category_supplier':
      return (string)($offer['category_path'] ?? '');
    case 'category_ozon':
      return (string)($offer['ozon_category'] ?? '');
    case 'category_wb':
      return (string)($offer['wb_category'] ?? ($offer['wb_subject_id'] ?? ''));
  }
  return '';
}

function supplier_view_sort_url(string $sort, string $currentSort, string $currentDir): string
{
  $nextDir = ($currentSort === $sort && $currentDir === 'asc') ? 'desc' : 'asc';
  return url_with([
    'sort' => $sort,
    'dir' => $nextDir,
    'page' => 1,
  ]);
}

function supplier_view_sort_mark(string $sort, string $currentSort, string $currentDir): string
{
  if ($currentSort !== $sort) {
    return '↕';
  }
  return $currentDir === 'desc' ? '↓' : '↑';
}

function supplier_view_sort_icon_html(string $sort, string $currentSort, string $currentDir): string
{
  $active = $currentSort === $sort;
  if ($active) {
    $triangle = $currentDir === 'desc' ? '▼' : '▲';
    $dir = $currentDir === 'desc' ? 'desc' : 'asc';
    return '<span class="supplier-sort-icon supplier-sort-icon--active supplier-sort-icon--' . h($dir) . '" aria-hidden="true">'
      . '<span>' . h($triangle) . '</span>'
      . '</span>';
  }
  return '<span class="supplier-sort-icon" aria-hidden="true">'
    . '<span>▲</span><span>▼</span>'
    . '</span>';
}

function supplier_view_sort_link(string $sort, string $label, string $currentSort, string $currentDir): string
{
  $active = $currentSort === $sort;
  return '<a class="supplier-sort-link' . ($active ? ' is-active' : '') . '" href="' . h(supplier_view_sort_url($sort, $currentSort, $currentDir)) . '">'
    . '<span class="supplier-sort-label">' . h($label) . '</span>' . supplier_view_sort_icon_html($sort, $currentSort, $currentDir) . '</a>';
}

function supplier_view_money_value($value): string
{
  if ($value === null || $value === '') {
    return '';
  }
  $number = (float)$value;
  $formatted = number_format($number, 2, ',', ' ');
  $formatted = preg_replace('~,00$~', '', $formatted) ?? $formatted;
  return $formatted;
}

if (session_status() !== PHP_SESSION_ACTIVE) {
  $isHttps = (
    (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off')
    || ((string)($_SERVER['SERVER_PORT'] ?? '') === '443')
    || (strtolower((string)($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '')) === 'https')
  );

  session_set_cookie_params([
    'path' => '/',
    'httponly' => true,
    'secure' => $isHttps,
    'samesite' => 'Lax',
  ]);

  session_start();
}

function ft_close_session_if_active(): void
{
  if (session_status() === PHP_SESSION_ACTIVE && function_exists('session_write_close')) {
    @session_write_close();
  }
}

function ft_request_has_filter_payload(array $src): bool
{
  foreach (['filter_apply', 'content_filter', 'content_issue', 'f_catpath', 'f_ozoncat', 'f_wbcat', 'f_brand', 'f_brand_ozon', 'f_brand_wb', 'f_model', 'f_brand_status_ozon', 'f_brand_status_wb', 'f_status_ozon', 'f_status_wb', 'f_hashtag', 'f_param', 'f_ready', 'f_ready_mode', 'f_ready_ready', 'f_ready_missing', 'f_quality_hint', 'f_ozon_marking_error', 'q_name', 'f_instock', 'f_not_in_ozon', 'f_not_in_ozon_archive', 'f_not_in_wb', 'f_has_picture', 'f_not_bulky_ozon', 'f_selected_only', 'f_selected_ids', 'f_price_min', 'f_price_max', 'f_stock_min', 'f_stock_max', 'f_ozon_hits_min', 'f_ozon_hits_max', 'f_ozon_sales_min', 'f_ozon_sales_max', 'f_ozon_view_card_min', 'f_ozon_view_card_max', 'f_ozon_card_order_min', 'f_ozon_card_order_max'] as $key) {
    if (array_key_exists($key, $src)) return true;
  }
  return false;
}

function ft_request_wants_json(): bool
{
  return strtolower((string)($_SERVER['HTTP_X_REQUESTED_WITH'] ?? '')) === 'xmlhttprequest'
    || str_contains(strtolower((string)($_SERVER['HTTP_ACCEPT'] ?? '')), 'application/json');
}

function ft_parse_filter_float($value): ?float
{
  $value = trim((string)$value);
  if ($value === '') return null;
  $value = str_replace(["\xc2\xa0", ' '], '', $value);
  $value = str_replace(',', '.', $value);
  return is_numeric($value) ? (float)$value : null;
}

function ft_parse_filter_int($value): ?int
{
  $value = trim((string)$value);
  if ($value === '') return null;
  $value = str_replace(["\xc2\xa0", ' '], '', $value);
  return preg_match('/^-?\d+$/', $value) ? (int)$value : null;
}

function ft_parse_selected_offer_ids_filter($value): array
{
  if (is_string($value)) {
    $raw = trim($value);
    if ($raw === '') return [];
    $decoded = json_decode($raw, true);
    if (is_array($decoded)) {
      $value = $decoded;
    } else {
      $value = preg_split('/[\r\n,]+/u', $raw) ?: [];
    }
  } elseif (!is_array($value)) {
    $value = [$value];
  }

  $out = [];
  foreach ($value as $id) {
    if (is_array($id)) continue;
    $id = trim((string)$id);
    if ($id === '') continue;
    $out[$id] = true;
  }

  return array_keys($out);
}

function ft_content_filter_defs(): array
{
  return [
    'not_uploaded' => ['label' => 'Не загружено'],
    'not_uploaded_ozon' => ['label' => 'Не загружено Ozon'],
    'not_uploaded_wb' => ['label' => 'Не загружено WB'],
    'marketplace_errors' => ['label' => 'Ошибки и доработки'],
    'marketplace_errors_ozon' => ['label' => 'Ошибки и доработки Ozon'],
    'marketplace_errors_wb' => ['label' => 'Ошибки и доработки WB'],
    'not_sellable' => ['label' => 'Загружено, но не продается'],
    'not_sellable_ozon' => ['label' => 'Загружено, но не продается Ozon'],
    'not_sellable_wb' => ['label' => 'Загружено, но не продается WB'],
    'weak_quality' => ['label' => 'Качество ниже 70'],
    'weak_quality_ozon' => ['label' => 'Качество ниже 70 Ozon'],
    'weak_quality_wb' => ['label' => 'Качество ниже 70 WB'],
    'missing_core' => ['label' => 'Нет базовых данных'],
    'issue' => ['label' => 'Проблема контента'],
  ];
}

function ft_content_filter_normalize($value): string
{
  $value = trim((string)$value);
  return array_key_exists($value, ft_content_filter_defs()) ? $value : '';
}

function ft_content_issue_code($value): string
{
  $value = trim((string)$value);
  return preg_match('~^[a-z0-9_:-]{1,80}$~i', $value) ? $value : '';
}

function ft_content_issue_label(string $code): string
{
  $labels = [
    'not_uploaded_ozon' => 'Ozon: товар не загружен',
    'not_uploaded_wb' => 'WB: товар не загружен',
    'missing_ozon_category' => 'Нет категории Ozon',
    'missing_wb_category' => 'Нет категории WB',
    'missing_brand' => 'Нет бренда',
    'missing_title' => 'Нет названия',
    'weak_title' => 'Короткое название',
    'missing_description' => 'Нет описания',
    'weak_description' => 'Слабое описание',
    'missing_images' => 'Нет фото',
    'low_images_count' => 'Мало фото',
    'missing_price' => 'Нет цены',
    'ozon_error' => 'Ozon: ошибка карточки',
    'wb_error' => 'WB: ошибка карточки',
    'ozon_revision' => 'Ozon: доработка',
    'wb_revision' => 'WB: доработка',
  ];
  return (string)($labels[$code] ?? $code);
}

function ft_content_filter_label(string $filter, string $issueCode = ''): string
{
  $defs = ft_content_filter_defs();
  $label = (string)($defs[$filter]['label'] ?? $filter);
  if ($filter === 'issue' && $issueCode !== '') {
    $label .= ': ' . ft_content_issue_label($issueCode);
  }
  return $label;
}

function ft_content_filter_issue_like(string $code): string
{
  $code = str_replace(['\\', '%', '_'], ['\\\\', '\\%', '\\_'], $code);
  return '%"code":"' . $code . '"%';
}

function ft_content_filter_product_ids(int $supplierId, string $filter, string $issueCode = ''): array
{
  if ($supplierId <= 0 || $filter === '') {
    return [];
  }

  $where = [
    'a.supplier_id = ?',
    'GREATEST(COALESCE(p.stock_qty, 0), COALESCE(p.count_qty, 0)) > 0',
  ];
  $args = [$supplierId];
  $marketplace = '';
  foreach (['_ozon' => 'ozon', '_wb' => 'wb'] as $suffix => $mp) {
    if (str_ends_with($filter, $suffix)) {
      $marketplace = $mp;
      $filter = substr($filter, 0, -strlen($suffix));
      break;
    }
  }
  if ($marketplace !== '') {
    $where[] = 'a.marketplace = ?';
    $args[] = $marketplace;
  }

  if ($filter === 'not_uploaded') {
    $where[] = "a.normalized_status = 'not_uploaded'";
  } elseif ($filter === 'marketplace_errors') {
    $where[] = "a.normalized_status IN ('error', 'revision')";
  } elseif ($filter === 'not_sellable') {
    $where[] = "a.is_uploaded = 1 AND a.is_sellable = 0 AND a.normalized_status NOT IN ('error', 'revision')";
  } elseif ($filter === 'weak_quality') {
    $where[] = 'a.card_quality_score < 70';
  } elseif ($filter === 'missing_core') {
    $coreCodes = [
      'missing_title',
      'missing_brand',
      'missing_description',
      'missing_images',
      'missing_price',
      'missing_ozon_category',
      'missing_wb_category',
    ];
    $parts = [];
    foreach ($coreCodes as $code) {
      $parts[] = "a.issues_json LIKE ? ESCAPE '\\\\'";
      $args[] = ft_content_filter_issue_like($code);
    }
    $where[] = '(' . implode(' OR ', $parts) . ')';
  } elseif ($filter === 'issue' && $issueCode !== '') {
    $where[] = "a.issues_json LIKE ? ESCAPE '\\\\'";
    $args[] = ft_content_filter_issue_like($issueCode);
  } else {
    return [];
  }

  try {
    $st = db()->prepare("
      SELECT DISTINCT a.product_id
      FROM feedtools_supplier_content_assessments a
      JOIN feedtools_supplier_products p ON p.id = a.product_id
      WHERE " . implode("\n        AND ", $where) . "
    ");
    $st->execute($args);
    $ids = [];
    while ($id = $st->fetchColumn()) {
      $id = (int)$id;
      if ($id > 0) {
        $ids[] = $id;
      }
    }
    return $ids;
  } catch (Throwable) {
    return [];
  }
}

function ft_parse_dimensions_triplet(string $raw): array
{
  $raw = trim((string)$raw);
  if ($raw === '') return ['', '', ''];
  $parts = preg_split('~\s*[xх×*/]\s*~u', $raw) ?: [];
  $parts = array_map('trim', $parts);
  return [$parts[0] ?? '', $parts[1] ?? '', $parts[2] ?? ''];
}

function ft_detect_dimensions_unit(string $raw): string
{
  $lc = mb_strtolower(trim((string)$raw), 'UTF-8');
  if ($lc === '') return '';
  if (strpos($lc, 'мм') !== false || preg_match('/\bmm\b/u', $lc)) return 'mm';
  if (strpos($lc, 'см') !== false || preg_match('/\bcm\b/u', $lc)) return 'cm';
  return '';
}

function ft_dimensions_value_to_cm(string $value, bool $inputIsCm): ?float
{
  $value = trim(str_replace(',', '.', (string)$value));
  if ($value === '' || !is_numeric($value)) return null;
  $n = (float)$value;
  return $inputIsCm ? $n : ($n / 10.0);
}

function ft_offer_is_ozon_bulky(array $offer): bool
{
  $dimRaw = trim((string)($offer['dimensions'] ?? ''));
  if ($dimRaw === '') return false;

  [$lRaw, $wRaw, $hRaw] = ft_parse_dimensions_triplet($dimRaw);
  $unit = ft_detect_dimensions_unit($dimRaw);
  if ($unit === 'cm') {
    $dimInputIsCm = true;
  } elseif ($unit === 'mm') {
    $dimInputIsCm = false;
  } else {
    $nums = [];
    foreach ([$lRaw, $wRaw, $hRaw] as $v) {
      $v = trim(str_replace(',', '.', (string)$v));
      if ($v !== '' && is_numeric($v)) $nums[] = (float)$v;
    }
    $dimInputIsCm = ($nums && max($nums) < 50.0);
  }

  $dimsCm = [];
  foreach ([$lRaw, $wRaw, $hRaw] as $v) {
    $cm = ft_dimensions_value_to_cm($v, $dimInputIsCm);
    if ($cm !== null && $cm > 0) $dimsCm[] = $cm;
  }

  if (!$dimsCm) return false;

  $maxSide = max($dimsCm);
  if ($maxSide >= 200.0) return true;

  if (count($dimsCm) === 3) {
    $volumeLiters = ($dimsCm[0] * $dimsCm[1] * $dimsCm[2]) / 1000.0;
    if ($volumeLiters >= 500.0) return true;
  }

  $weightKg = isset($offer['weight']) && $offer['weight'] !== null ? (float)$offer['weight'] : null;
  if ($weightKg !== null && $weightKg >= 35.0 && $weightKg <= 125.0) return true;

  return false;
}

function ft_dataset_marketplace_connections_ensure(): void
{
  $pdo = db();
  ozon_products_table_add_column_if_missing(
    $pdo,
    'feedtools_datasets',
    'ozon_connection_id',
    "ALTER TABLE feedtools_datasets ADD COLUMN ozon_connection_id BIGINT UNSIGNED NULL DEFAULT NULL AFTER warnings_json"
  );
  ozon_products_table_add_column_if_missing(
    $pdo,
    'feedtools_datasets',
    'wb_connection_id',
    "ALTER TABLE feedtools_datasets ADD COLUMN wb_connection_id BIGINT UNSIGNED NULL DEFAULT NULL AFTER ozon_connection_id"
  );
  ozon_products_table_add_column_if_missing(
    $pdo,
    'feedtools_datasets',
    'yandex_connection_id',
    "ALTER TABLE feedtools_datasets ADD COLUMN yandex_connection_id BIGINT UNSIGNED NULL DEFAULT NULL AFTER wb_connection_id"
  );
}

function ft_connection_id_exists(array $connections, int $id): bool
{
  if ($id <= 0) return false;
  foreach ($connections as $connection) {
    if ((int)($connection['id'] ?? 0) === $id) return true;
  }
  return false;
}

function ft_first_connection_id(array $connections): int
{
  $first = reset($connections);
  return is_array($first) ? (int)($first['id'] ?? 0) : 0;
}

function supplier_view_ozon_products_last_sync(int $connectionId): string
{
  if ($connectionId <= 0) return '';
  try {
    $pdo = db();
    $keys = [
      'products_full_new_last_run_all',
      'products_full_new_last_run_archived',
      'products_daily_last_run_all',
      'products_daily_last_run_archived',
    ];
    $placeholders = implode(',', array_fill(0, count($keys), '?'));
    $st = $pdo->prepare("
      SELECT MAX(NULLIF(state_value, '')) AS last_sync
      FROM feedtools_ozon_sync_state
      WHERE connection_id = ?
        AND state_key IN ($placeholders)
    ");
    $st->execute(array_merge([$connectionId], $keys));
    $lastSync = trim((string)($st->fetchColumn() ?: ''));
    if ($lastSync !== '') {
      return $lastSync;
    }

    $st = $pdo->prepare("
      SELECT MAX(last_seen_at) AS last_sync
      FROM feedtools_ozon_products
      WHERE connection_id = ?
    ");
    $st->execute([$connectionId]);
    return trim((string)($st->fetchColumn() ?: ''));
  } catch (Throwable $e) {
    return '';
  }
}

function supplier_view_wb_products_last_sync(int $connectionId): string
{
  if ($connectionId <= 0) return '';
  try {
    $stats = wb_products_stats(db(), $connectionId);
    $lastSync = trim((string)($stats['last_success_at'] ?? ''));
    if ($lastSync !== '') {
      return $lastSync;
    }
    return trim((string)($stats['last_seen_at'] ?? ''));
  } catch (Throwable $e) {
    return '';
  }
}

function supplier_view_sync_datetime_html(string $value): string
{
  $value = trim($value);
  if ($value === '') {
    return 'нет данных';
  }
  return ft_local_datetime_html($value, ['show_seconds' => true]);
}

