function norm_filter_array($v): array
{
  if ($v === null) return [];
  if (!is_array($v)) $v = [$v];
  $out = [];
  foreach ($v as $x) {
    $s = trim((string)$x);
    if ($s === '') continue;
    if ($s === EMPTY_TOKEN) $s = ''; // empty marker
    $out[] = $s;
  }
  $out = array_values(array_unique($out));
  return $out;
}

