$filterStockMinRaw = trim((string)($requestFilterSource['f_stock_min'] ?? ''));
$filterStockMaxRaw = trim((string)($requestFilterSource['f_stock_max'] ?? ''));
$filterOzonHitsMinRaw = trim((string)($requestFilterSource['f_ozon_hits_min'] ?? ''));
$filterOzonHitsMaxRaw = trim((string)($requestFilterSource['f_ozon_hits_max'] ?? ''));
$filterOzonSalesMinRaw = trim((string)($requestFilterSource['f_ozon_sales_min'] ?? ''));
$filterOzonSalesMaxRaw = trim((string)($requestFilterSource['f_ozon_sales_max'] ?? ''));
$filterOzonViewCardMinRaw = trim((string)($requestFilterSource['f_ozon_view_card_min'] ?? ''));
$filterOzonViewCardMaxRaw = trim((string)($requestFilterSource['f_ozon_view_card_max'] ?? ''));
$filterOzonCardOrderMinRaw = trim((string)($requestFilterSource['f_ozon_card_order_min'] ?? ''));
$filterOzonCardOrderMaxRaw = trim((string)($requestFilterSource['f_ozon_card_order_max'] ?? ''));
$contentFilter = ft_content_filter_normalize($requestFilterSource['content_filter'] ?? '');
$contentIssueCode = ft_content_issue_code($requestFilterSource['content_issue'] ?? '');
if ($contentFilter !== 'issue') {
  $contentIssueCode = '';
}
if ($contentFilter === 'issue' && $contentIssueCode === '') {
  $contentFilter = '';
}

// Param filters: f_param[<param_name>] = <value>
// Param filters: f_param[<param_name>] = [values...]
$filterParams = []; // pname => array(values) ; value '' означает "пусто/нет значения"
$filterParamsRaw = $requestFilterSource['f_param'] ?? [];
if (is_array($filterParamsRaw)) {
  foreach ($filterParamsRaw as $k => $vv) {
    $pname = trim((string)$k);
    if ($pname === '') continue;

    $vals = norm_filter_array($vv); // умеет и строку, и массив; EMPTY_TOKEN -> ''
    if (empty($vals)) continue;

    $filterParams[$pname] = $vals;
  }
}

// Для UI: '' -> EMPTY_TOKEN (в каждом значении)
$filterParamsUi = [];
foreach ($filterParams as $k => $vals) {
  $out = [];
  foreach ($vals as $v) $out[] = ($v === '' ? EMPTY_TOKEN : $v);
  $filterParamsUi[$k] = $out;
}

$filterHashtagsUi = $filterHashtags; // они уже массив строк '#...'





$filterNameRaw = trim((string)($requestFilterSource['q_name'] ?? ''));
$filterNameRaw = preg_replace('/\s+/u', ' ', $filterNameRaw);

function ft_lc(string $s): string
{
  return function_exists('mb_strtolower') ? mb_strtolower($s, 'UTF-8') : strtolower($s);
}

function ft_query_matches_offer(string $offerId, string $name, array $tokens): bool
{
  // 1) если ВСЕ токены найдены в offer_id — матч (приоритет артикула)
  // 2) иначе если ВСЕ токены найдены в названии — матч
  // 3) иначе — не матч
  $oid = ft_lc($offerId);
  $n = ft_lc($name);

  $allInId = true;
  foreach ($tokens as $t) {
    $t = (string)$t;
    if ($t === '') continue;
    if (strpos($oid, $t) === false) {
      $allInId = false;
      break;
    }
  }
  if ($allInId) return true;

  foreach ($tokens as $t) {
    $t = (string)$t;
    if ($t === '') continue;
    if (strpos($n, $t) === false) return false;
  }
  return true;
}

function supplier_view_brand_status_product_ids_temp_table(PDO $pdo, int $supplierId, string $source, array $set): ?string
{
  $source = $source === 'wb' ? 'wb' : 'ozon';
  $wanted = [];
  foreach (array_keys($set) as $status) {
    $status = trim((string)$status);
    if ($status !== '') {
      $wanted[$status] = true;
    }
  }
  if ($supplierId <= 0 || !$wanted) {
    return null;
  }

  $tmp = 'tmp_supplier_brand_status_' . bin2hex(random_bytes(6));
  $pdo->exec("CREATE TEMPORARY TABLE {$tmp} (product_id BIGINT UNSIGNED NOT NULL PRIMARY KEY) ENGINE=Memory");
  $ins = $pdo->prepare("INSERT IGNORE INTO {$tmp} (product_id) VALUES (?)");
  $st = $pdo->prepare("
    SELECT
      p.id,
      p.brand,
      p.ozon_category,
      p.wb_category,
      (
        SELECT fbo.field_value
        FROM feedtools_supplier_product_fields fbo
        WHERE fbo.supplier_id = p.supplier_id
          AND fbo.product_id = p.id
          AND fbo.field_kind = 'standard'
          AND fbo.field_name = 'brand_ozon'
        ORDER BY fbo.sort_order ASC, fbo.id ASC
        LIMIT 1
      ) AS brand_ozon,
      (
        SELECT fbw.field_value
        FROM feedtools_supplier_product_fields fbw
        WHERE fbw.supplier_id = p.supplier_id
          AND fbw.product_id = p.id
          AND fbw.field_kind = 'standard'
          AND fbw.field_name = 'brand_wb'
        ORDER BY fbw.sort_order ASC, fbw.id ASC
        LIMIT 1
      ) AS brand_wb
    FROM feedtools_supplier_products p
    WHERE p.supplier_id = ?
    ORDER BY p.id ASC
  ");
  $st->execute([$supplierId]);

  $chunk = [];
  $flush = static function () use (&$chunk, $source, $wanted, $ins): void {
    if (!$chunk) {
      return;
    }
    $statuses = marketplace_brand_status_for_products($chunk);
    foreach ($chunk as $key => $product) {
      $status = trim((string)(($statuses[$key][$source] ?? [])['status'] ?? ''));
      if ($status !== '' && isset($wanted[$status])) {
        $ins->execute([(int)($product['_product_id'] ?? 0)]);
      }
    }
    $chunk = [];
  };

  while ($row = $st->fetch(PDO::FETCH_ASSOC)) {
    $productId = (int)($row['id'] ?? 0);
    if ($productId <= 0) {
      continue;
    }
    $brand = trim((string)($row['brand'] ?? ''));
    $hasBrandOzon = array_key_exists('brand_ozon', $row) && $row['brand_ozon'] !== null;
    $hasBrandWb = array_key_exists('brand_wb', $row) && $row['brand_wb'] !== null;
    $brandOzon = $hasBrandOzon ? trim((string)$row['brand_ozon']) : $brand;
    $brandWb = $hasBrandWb ? trim((string)$row['brand_wb']) : $brand;
    $chunk[$productId] = [
      '_product_id' => $productId,
      'brand' => $brand,
      'brand_ozon' => $brandOzon,
      'brand_wb' => $brandWb,
      'ozon_category' => (string)($row['ozon_category'] ?? ''),
      'wb_category' => (string)($row['wb_category'] ?? ''),
    ];
    if (count($chunk) >= 700) {
      $flush();
    }
  }
  $flush();

  return $tmp;
}

function supplier_view_build_fast_offer_filter_sql(
  int $supplierId,
  ?array $filterCatSet,
  ?array $filterOzonSet,
  ?array $filterWbSet,
  ?array $filterBrandSet,
  ?array $filterSelectedOfferIdSet,
  array $filterNameTokens,
  bool $filterHasPicture,
  bool $filterInStock,
  array $filterParams,
  ?int $filterStockMin = null,
  ?int $filterStockMax = null,
  ?array $filterReadySet = null,
  string $filterReadyMode = 'missing',
  ?array $filterQualityHintSet = null,
  int $ozonConnectionId = 0,
  int $wbConnectionId = 0,
  string $supplierCode = '',
  ?array $filterBrandOzonSet = null,
  ?array $filterBrandWbSet = null,
  ?array $filterModelSet = null,
  array $filterHashtags = [],
  ?float $filterPriceMin = null,
  ?float $filterPriceMax = null,
  ?array $filterStatusOzonSet = null,
  ?array $filterStatusWbSet = null,
  ?array $filterBrandStatusOzonSet = null,
  ?array $filterBrandStatusWbSet = null,
  bool $filterOzonMarkingError = false
): array {
  $where = ['p.supplier_id = ?'];
  $args = [$supplierId];

  $addInFilter = static function (string $column, ?array $set) use (&$where, &$args): void {
    if ($set === null) {
      return;
    }
    $values = array_keys($set);
    if (!$values) {
      return;
    }
    $where[] = $column . ' IN (' . implode(',', array_fill(0, count($values), '?')) . ')';
    foreach ($values as $value) {
      $args[] = (string)$value;
    }
  };

  $addInFilter('p.category_path', $filterCatSet);
  $addInFilter('p.ozon_category', $filterOzonSet);
  $addInFilter('p.wb_category', $filterWbSet);
  $addInFilter('p.brand', $filterBrandSet);

  $addEffectiveStandardFilter = static function (string $fieldName, ?array $set) use (&$where, &$args): void {
    if ($set === null) {
      return;
    }
    $values = array_keys($set);
    if (!$values) {
      return;
    }
    $fieldNameSql = str_replace("'", "''", $fieldName);
    $fieldExpr = "(SELECT TRIM(COALESCE(f_std.field_value, ''))
      FROM feedtools_supplier_product_fields f_std
      WHERE f_std.supplier_id = p.supplier_id
        AND f_std.product_id = p.id
        AND f_std.field_kind = 'standard'
        AND f_std.field_name = '{$fieldNameSql}'
      ORDER BY f_std.sort_order ASC, f_std.id ASC
      LIMIT 1)";
    $where[] = "COALESCE({$fieldExpr}, TRIM(COALESCE(p.brand, ''))) IN (" . implode(',', array_fill(0, count($values), '?')) . ")";
    foreach ($values as $value) {
      $args[] = (string)$value;
    }
  };

  $addTagFilter = static function (string $fieldName, ?array $set) use (&$where, &$args): void {
    if ($set === null) {
      return;
    }
    $wantEmpty = false;
    $values = [];
    foreach (array_keys($set) as $value) {
      $value = trim((string)$value);
      if ($value === '') {
        $wantEmpty = true;
      } else {
        $values[$value] = true;
      }
    }
    $fieldNameSql = str_replace("'", "''", $fieldName);
    $clauses = [];
    if ($values) {
      $realValues = array_keys($values);
      $clauses[] = "EXISTS (
        SELECT 1
        FROM feedtools_supplier_product_fields f_tag
        WHERE f_tag.supplier_id = p.supplier_id
          AND f_tag.product_id = p.id
          AND f_tag.field_kind = 'tag'
          AND f_tag.field_name = '{$fieldNameSql}'
          AND TRIM(COALESCE(f_tag.field_value, '')) IN (" . implode(',', array_fill(0, count($realValues), '?')) . ")
        LIMIT 1
      )";
      foreach ($realValues as $value) {
        $args[] = $value;
      }
    }
    if ($wantEmpty) {
      $clauses[] = "NOT EXISTS (
        SELECT 1
        FROM feedtools_supplier_product_fields f_tag_empty
        WHERE f_tag_empty.supplier_id = p.supplier_id
          AND f_tag_empty.product_id = p.id
          AND f_tag_empty.field_kind = 'tag'
          AND f_tag_empty.field_name = '{$fieldNameSql}'
          AND TRIM(COALESCE(f_tag_empty.field_value, '')) <> ''
        LIMIT 1
      )";
    }
    $where[] = $clauses ? '(' . implode(' OR ', $clauses) . ')' : '1 = 0';
  };

  $addEffectiveStandardFilter('brand_ozon', $filterBrandOzonSet);
  $addEffectiveStandardFilter('brand_wb', $filterBrandWbSet);
  $addTagFilter('same_model', $filterModelSet);

  if ($filterSelectedOfferIdSet !== null) {
    $selectedValues = array_keys($filterSelectedOfferIdSet);
    if ($selectedValues) {
      $where[] = 'p.offer_id IN (' . implode(',', array_fill(0, count($selectedValues), '?')) . ')';
      foreach ($selectedValues as $value) {
        $args[] = (string)$value;
      }
    } else {
      $where[] = '1 = 0';
    }
  }

  foreach ($filterNameTokens as $token) {
    $like = '%' . str_replace(['%', '_'], ['\\%', '\\_'], (string)$token) . '%';
    $where[] = "(p.offer_id LIKE ? ESCAPE '\\\\' OR p.name LIKE ? ESCAPE '\\\\')";
    $args[] = $like;
    $args[] = $like;
  }

  if ($filterHasPicture) {
    $where[] = "p.pictures_json IS NOT NULL AND TRIM(p.pictures_json) NOT IN ('', '[]', 'null')";
  }

  if ($filterHashtags) {
    $hashtagClauses = [];
    foreach ($filterHashtags as $wantHashtag) {
      $wantHashtag = trim((string)$wantHashtag);
      if ($wantHashtag === '') {
        continue;
      }
      $plainHashtag = ltrim($wantHashtag, '#');
      $likeValues = [];
      $likeValues[] = '%' . str_replace(['\\', '%', '_'], ['\\\\', '\\%', '\\_'], $wantHashtag) . '%';
      if ($plainHashtag !== '' && $plainHashtag !== $wantHashtag) {
        $likeValues[] = '%' . str_replace(['\\', '%', '_'], ['\\\\', '\\%', '\\_'], $plainHashtag) . '%';
      }
      $hashtagLikes = [];
      foreach (array_values(array_unique($likeValues)) as $likeValue) {
        $hashtagLikes[] = "f_hash.field_value LIKE ? ESCAPE '\\\\'";
        $args[] = $likeValue;
      }
      if ($hashtagLikes) {
        $hashtagClauses[] = "EXISTS (
          SELECT 1
          FROM feedtools_supplier_product_fields f_hash
          WHERE f_hash.supplier_id = p.supplier_id
            AND f_hash.product_id = p.id
            AND f_hash.field_kind = 'tag'
            AND f_hash.field_name IN ('hashtags', 'hashtag', 'хештеги', 'хэштеги')
            AND (" . implode(' OR ', $hashtagLikes) . ")
          LIMIT 1
        )";
      }
    }
    $where[] = $hashtagClauses ? '(' . implode(' OR ', $hashtagClauses) . ')' : '1 = 0';
  }

  foreach ($filterParams as $paramName => $paramValues) {
    $paramName = trim((string)$paramName);
    if ($paramName === '') {
      continue;
    }
    if (!is_array($paramValues)) {
      $paramValues = [$paramValues];
    }

    [$fieldKind, $fieldName] = supplier_view_parse_param_facet_display_name($paramName);
    if ($fieldName === '' || !in_array($fieldKind, ['param', 'wb_param'], true)) {
      continue;
    }

    $wantEmpty = false;
    $wantValues = [];
    foreach ($paramValues as $paramValue) {
      $paramValue = trim((string)$paramValue);
      if ($paramValue === '') {
        $wantEmpty = true;
        continue;
      }
      $wantValues[$paramValue] = true;
    }

    $paramClauses = [];
    if ($wantValues) {
      $values = array_keys($wantValues);
      $paramClauses[] = "EXISTS (
        SELECT 1
        FROM feedtools_supplier_product_fields f
        WHERE f.supplier_id = p.supplier_id
          AND f.product_id = p.id
          AND f.field_kind = ?
          AND f.field_name = ?
          AND TRIM(COALESCE(f.field_value, '')) IN (" . implode(',', array_fill(0, count($values), '?')) . ")
        LIMIT 1
      )";
      $args[] = $fieldKind;
      $args[] = $fieldName;
      foreach ($values as $value) {
        $args[] = $value;
      }
    }
    if ($wantEmpty) {
      $paramClauses[] = "NOT EXISTS (
        SELECT 1
        FROM feedtools_supplier_product_fields f
        WHERE f.supplier_id = p.supplier_id
          AND f.product_id = p.id
          AND f.field_kind = ?
          AND f.field_name = ?
        LIMIT 1
      )";
      $args[] = $fieldKind;
      $args[] = $fieldName;
      $paramClauses[] = "EXISTS (
        SELECT 1
        FROM feedtools_supplier_product_fields f
        WHERE f.supplier_id = p.supplier_id
          AND f.product_id = p.id
          AND f.field_kind = ?
          AND f.field_name = ?
          AND TRIM(COALESCE(f.field_value, '')) = ''
        LIMIT 1
      )";
      $args[] = $fieldKind;
      $args[] = $fieldName;
    }
    if ($paramClauses) {
      $where[] = '(' . implode(' OR ', $paramClauses) . ')';
    }
  }

  if ($filterPriceMin !== null || $filterPriceMax !== null) {
    if ($filterPriceMin !== null) {
      $where[] = 'p.price_original IS NOT NULL AND p.price_original >= ?';
      $args[] = $filterPriceMin;
    }
    if ($filterPriceMax !== null) {
      $where[] = 'p.price_original IS NOT NULL AND p.price_original <= ?';
      $args[] = $filterPriceMax;
    }
  }

  if ($filterInStock || $filterStockMin !== null || $filterStockMax !== null) {
    $stockExpr = "CASE
      WHEN COALESCE(p.marketplace_enabled, 1) <= 0 THEN 0
      ELSE GREATEST(0, GREATEST(COALESCE(p.stock_qty, 0), COALESCE(p.count_qty, 0)) + COALESCE(p.stock_modifier, 0))
    END";
    if ($filterInStock) {
      $where[] = "{$stockExpr} > 0";
    }
    if ($filterStockMin !== null) {
      $where[] = "{$stockExpr} >= ?";
      $args[] = $filterStockMin;
    }
    if ($filterStockMax !== null) {
      $where[] = "{$stockExpr} <= ?";
      $args[] = $filterStockMax;
    }
  }

  if ($filterReadySet !== null) {
    $readyMode = supplier_view_content_readiness_filter_mode($filterReadyMode);
    foreach ($filterReadySet as $readyKey => $readyState) {
      $isReady = ($readyState === 'ready') || ($readyState === true && $readyMode === 'ready');
      $readyClause = supplier_view_fast_readiness_sql_clause((string)$readyKey, $isReady);
      if ($readyClause !== null) {
        $where[] = $readyClause;
      }
    }
  }

  if ($filterQualityHintSet !== null) {
    $pdo = db();
    $hasOzonRecs = $ozonConnectionId > 0
      && (!function_exists('ozon_products_table_has_column') || ozon_products_table_has_column($pdo, 'feedtools_ozon_products', 'content_rating_recommendations_json'));
    $hasWbRecs = $wbConnectionId > 0
      && (!function_exists('wb_products_table_has_column') || wb_products_table_has_column($pdo, 'feedtools_wb_products', 'quality_recommendations_json'));

    $hintClauses = [];
    foreach (array_keys($filterQualityHintSet) as $qualityHintKey) {
      $fragments = supplier_view_quality_hint_sql_fragments((string)$qualityHintKey);
      if (!$fragments) {
        continue;
      }
      $codes = [];
      if ($hasOzonRecs) {
        foreach (supplier_view_quality_hint_marketplace_codes($pdo, 'ozon', $ozonConnectionId, $fragments) as $code) {
          $codes[$code] = true;
        }
      }
      if ($hasWbRecs) {
        foreach (supplier_view_quality_hint_marketplace_codes($pdo, 'wb', $wbConnectionId, $fragments) as $code) {
          $codes[$code] = true;
        }
      }
      $tmpTable = supplier_view_quality_hint_temp_table($pdo, array_keys($codes), $supplierCode);
      if ($tmpTable !== null) {
        $hintClauses[] = "EXISTS (
          SELECT 1
          FROM {$tmpTable} qh
          WHERE qh.code = p.offer_id
            OR (qh.code = p.vendor_code AND COALESCE(p.vendor_code, '') <> '')
          LIMIT 1
        )";
      }
    }
    $where[] = $hintClauses ? '(' . implode(' AND ', $hintClauses) . ')' : '1 = 0';
  }

  $addMarketplaceStatusFilter = static function (string $marketplace, ?array $set) use (&$where, $supplierId, $ozonConnectionId, $wbConnectionId, $supplierCode): void {
    if ($set === null) {
      return;
    }

    $states = [];
    $issues = [];
    foreach (array_keys($set) as $token) {
      $token = (string)$token;
      if (str_starts_with($token, 'state:')) {
        $state = trim(substr($token, 6));
        if ($state !== '') {
          $states[$state] = true;
        }
      } elseif (str_starts_with($token, 'issue:')) {
        $issue = trim(substr($token, 6));
        if ($issue !== '') {
          $issues[$issue] = true;
        }
      }
    }
    if (!$states && !$issues) {
      $where[] = '1 = 0';
      return;
    }

    $isWb = $marketplace === 'wb';
    $connectionId = $isWb ? $wbConnectionId : $ozonConnectionId;
    if ($connectionId <= 0) {
      $where[] = '1 = 0';
      return;
    }

    $pdo = db();
    $productTmpTable = supplier_view_marketplace_status_product_ids_temp_table($pdo, $supplierId, $marketplace, $connectionId, $states, $supplierCode, $issues);
    if ($productTmpTable === null) {
      $where[] = '1 = 0';
      return;
    }
    $where[] = "EXISTS (
      SELECT 1
      FROM {$productTmpTable} sf
      WHERE sf.product_id = p.id
      LIMIT 1
    )";
  };

  $addMarketplaceStatusFilter('ozon', $filterStatusOzonSet);
  $addMarketplaceStatusFilter('wb', $filterStatusWbSet);

  if ($filterOzonMarkingError) {
    $pdo = db();
    $markingCodes = supplier_view_ozon_marking_error_codes($pdo, $ozonConnectionId);
    $markingTmpTable = supplier_view_marketplace_code_temp_table(
      $pdo,
      $markingCodes,
      '',
      'tmp_ft_ozon_marking_error_codes',
      false
    );
    if ($markingTmpTable === null) {
      $where[] = '1 = 0';
    } else {
      $where[] = "EXISTS (
        SELECT 1
        FROM {$markingTmpTable} marking_error
        WHERE marking_error.code = p.offer_id
          OR (marking_error.code = p.vendor_code AND COALESCE(p.vendor_code, '') <> '')
        LIMIT 1
      )";
    }
  }

  $addBrandStatusFilter = static function (string $source, ?array $set) use (&$where, $supplierId): void {
    if ($set === null) {
      return;
    }
    $tmpTable = supplier_view_brand_status_product_ids_temp_table(db(), $supplierId, $source, $set);
    if ($tmpTable === null) {
      $where[] = '1 = 0';
      return;
    }
    $where[] = "EXISTS (
      SELECT 1
      FROM {$tmpTable} bsf
      WHERE bsf.product_id = p.id
      LIMIT 1
    )";
  };
  $addBrandStatusFilter('ozon', $filterBrandStatusOzonSet);
  $addBrandStatusFilter('wb', $filterBrandStatusWbSet);

  return [implode(' AND ', $where), $args];
}

function supplier_view_fast_readiness_sql_supported(?array $filterReadySet): bool
{
  if ($filterReadySet === null) {
    return true;
  }
  // Characteristics readiness depends on marketplace category schemas and fallback
  // field matching, so the rough SQL count below is only a prefilter and must not
  // be used as the final paginated result.
  if (isset($filterReadySet['params'])) {
    return false;
  }
  $supported = [
    'title' => true,
    'description' => true,
    'color' => true,
    'cover' => true,
    'video' => true,
    'extra_photos' => true,
    'features' => true,
    'model' => true,
    'hashtags' => true,
    'tnved' => true,
  ];
  foreach (array_keys($filterReadySet) as $key) {
    if (!isset($supported[(string)$key])) {
      return false;
    }
  }
  return true;
}

function supplier_view_fast_readiness_sql_clause(string $key, bool $ready): ?string
{
  $pictureLike = static function (array $fragments) use ($ready): string {
    $parts = [];
    foreach ($fragments as $fragment) {
      $fragment = str_replace("'", "''", (string)$fragment);
      $parts[] = "p.pictures_json LIKE '%{$fragment}%'";
    }
    $expr = '(' . implode(' OR ', $parts) . ')';
    return $ready
      ? "(p.pictures_json IS NOT NULL AND {$expr})"
      : "(p.pictures_json IS NULL OR NOT {$expr})";
  };

  if ($key === 'cover') {
    return $pictureLike(['gpt_cover']);
  }
  if ($key === 'extra_photos') {
    return $pictureLike(['gpt_photo_variant', 'photo_collage', 'product_specs_photo']);
  }
  if ($key === 'video') {
    $exists = "EXISTS (
      SELECT 1
      FROM feedtools_supplier_product_fields f_ready_video
      WHERE f_ready_video.supplier_id = p.supplier_id
        AND f_ready_video.product_id = p.id
        AND f_ready_video.field_kind IN ('tag', 'param', 'wb_param')
        AND (
          f_ready_video.field_name IN (
            'Видео',
            'Video',
            'Озон.Видео',
            'Озон.Видео: ссылка',
            'Ozon.Video',
            'Ozon.Video: link',
            'Озон.Видеообложка: ссылка',
            'Ozon.VideoCover: link',
            'Видеообложка',
            'Видео-обложка'
          )
          OR LOWER(f_ready_video.field_name) = 'video'
          OR LOWER(f_ready_video.field_name) LIKE '%ozon%video%'
          OR LOWER(f_ready_video.field_name) LIKE '%videocover%'
          OR LOWER(f_ready_video.field_name) LIKE '%video cover%'
          OR LOWER(f_ready_video.field_name) LIKE '%видео%'
          OR LOWER(f_ready_video.field_name) LIKE '%видеообложк%'
          OR LOWER(f_ready_video.field_name) LIKE '%видео обложк%'
        )
        AND TRIM(COALESCE(f_ready_video.field_value, '')) <> ''
      LIMIT 1
    )";
    return $ready ? $exists : "NOT {$exists}";
  }
  if ($key === 'title') {
    $ok = "(CHAR_LENGTH(TRIM(COALESCE(p.name, ''))) BETWEEN 16 AND 200
      AND COALESCE(p.name, '') REGEXP '[А-Яа-яЁё]{5}'
      AND COALESCE(p.name, '') NOT LIKE '%\\_\\_%' ESCAPE '\\\\'
      AND LOWER(COALESCE(p.name, '')) NOT LIKE '%(orig)%'
      AND LOWER(COALESCE(p.name, '')) NOT LIKE '% orig%'
      AND LOWER(COALESCE(p.name, '')) NOT LIKE 'orig%'
      AND LOWER(COALESCE(p.name, '')) NOT LIKE '%http://%'
      AND LOWER(COALESCE(p.name, '')) NOT LIKE '%https://%'
      AND COALESCE(p.name, '') NOT LIKE '%<%'
      AND COALESCE(p.name, '') NOT LIKE '%>%')";
    return $ready ? $ok : "NOT {$ok}";
  }
  if ($key === 'description') {
    $ok = "CHAR_LENGTH(TRIM(COALESCE(p.description_html, ''))) >= 180";
    return $ready ? $ok : "NOT ({$ok})";
  }
  if ($key === 'color') {
    $exists = "EXISTS (
      SELECT 1
      FROM feedtools_supplier_product_fields f_ready_color
      WHERE f_ready_color.supplier_id = p.supplier_id
        AND f_ready_color.product_id = p.id
        AND f_ready_color.field_kind IN ('param', 'wb_param')
        AND f_ready_color.field_name IN ('цвет', 'Цвет', 'цвет товара', 'Цвет товара', 'название цвета', 'Название цвета', 'основной цвет', 'Основной цвет')
        AND TRIM(COALESCE(f_ready_color.field_value, '')) <> ''
      LIMIT 1
    )";
    return $ready ? $exists : "NOT {$exists}";
  }
  if ($key === 'params') {
    $countSql = "(SELECT COUNT(DISTINCT CONCAT(f_ready_params.field_kind, ':', f_ready_params.field_name))
      FROM feedtools_supplier_product_fields f_ready_params
      WHERE f_ready_params.supplier_id = p.supplier_id
        AND f_ready_params.product_id = p.id
        AND f_ready_params.field_kind IN ('param', 'wb_param')
        AND TRIM(COALESCE(f_ready_params.field_name, '')) <> ''
        AND TRIM(COALESCE(f_ready_params.field_value, '')) <> ''
    )";
    return $ready ? "{$countSql} >= 5" : "{$countSql} < 5";
  }
  if ($key === 'features') {
    $target = defined('SUPPLIER_PRODUCTS_FEATURE_MAX') ? max(1, min(3, (int)SUPPLIER_PRODUCTS_FEATURE_MAX)) : 3;
    $countSql = "(SELECT COUNT(*)
      FROM feedtools_supplier_product_fields f_ready_features
      WHERE f_ready_features.supplier_id = p.supplier_id
        AND f_ready_features.product_id = p.id
        AND f_ready_features.field_kind = 'feature'
        AND TRIM(COALESCE(f_ready_features.field_value, '')) <> ''
    )";
    return $ready ? "{$countSql} >= {$target}" : "{$countSql} < {$target}";
  }
  if ($key === 'model') {
    $exists = "EXISTS (
      SELECT 1
      FROM feedtools_supplier_product_fields f_ready_model
      WHERE f_ready_model.supplier_id = p.supplier_id
        AND f_ready_model.product_id = p.id
        AND f_ready_model.field_kind = 'tag'
        AND f_ready_model.field_name = 'same_model'
        AND TRIM(COALESCE(f_ready_model.field_value, '')) <> ''
      LIMIT 1
    )";
    return $ready ? $exists : "NOT {$exists}";
  }
  if ($key === 'hashtags') {
    $exists = "EXISTS (
      SELECT 1
      FROM feedtools_supplier_product_fields f_ready_hashtags
      WHERE f_ready_hashtags.supplier_id = p.supplier_id
        AND f_ready_hashtags.product_id = p.id
        AND f_ready_hashtags.field_kind = 'tag'
        AND f_ready_hashtags.field_name IN ('hashtags', 'hashtag', 'хештеги', 'хэштеги')
        AND TRIM(COALESCE(f_ready_hashtags.field_value, '')) <> ''
      LIMIT 1
    )";
    return $ready ? $exists : "NOT {$exists}";
  }
  if ($key === 'tnved') {
    $exists = "EXISTS (
      SELECT 1
      FROM feedtools_supplier_product_fields f_ready_tnved
      WHERE f_ready_tnved.supplier_id = p.supplier_id
        AND f_ready_tnved.product_id = p.id
        AND (
          (
            f_ready_tnved.field_kind = 'standard'
            AND f_ready_tnved.field_name = 'tnved_code'
          )
          OR (
            f_ready_tnved.field_kind IN ('param', 'wb_param')
            AND (
              f_ready_tnved.field_name LIKE '%ТН%ВЭД%'
              OR f_ready_tnved.field_name LIKE '%ТН%ВЭЖ%'
              OR LOWER(f_ready_tnved.field_name) LIKE '%tnved%'
              OR LOWER(f_ready_tnved.field_name) LIKE '%tn ved%'
            )
          )
        )
        AND COALESCE(f_ready_tnved.field_value, '') REGEXP '[0-9]{4,10}'
      LIMIT 1
    )";
    return $ready ? $exists : "NOT {$exists}";
  }
  return null;
}

function ft_op_ui_label(string $key, array $def): string
{
  $title = trim((string)($def['title'] ?? $key));
  $ru = $title;

  if (preg_match('/^' . preg_quote($key, '/') . '\s*\((.+)\)\s*$/u', $title, $m)) {
    $ru = trim((string)$m[1]);
  }

  return $ru . ' (' . $key . ')';
}


