      $supplierImportRunResult = supplier_products_import_source_with_options($supplierId, $sourceData, [
        'mode' => $supplierImportSettings['mode'],
        'scope' => $supplierImportSettings['scope'],
        'selected_offer_ids' => $selectedIds,
        'replace_names' => $supplierImportSettings['replace_names'],
        'brand_mode' => $supplierImportSettings['brand_mode'],
        'model_mode' => $supplierImportSettings['model_mode'],
        'description_mode' => $supplierImportSettings['description_mode'],
        'update_supplier_category' => $supplierImportSettings['update_supplier_category'],
        'characteristics_mode' => $supplierImportSettings['characteristics_mode'],
        'photos_mode' => $supplierImportSettings['photos_mode'],
      ], $cfg, $sourceUrl);
      $supplierImportRunResult['operation_label'] = 'Импорт выполнен';
    }

    $supplierProductRowsBySort = [];
    $row = supplier_products_dataset_row((int)$row['id'], $cfg) ?: $row;
    $supplierProductContext = supplier_products_context_for_dataset($row, $cfg) ?: $supplierProductContext;
  } catch (Throwable $e) {
    $supplierImportRunError = $e->getMessage();
  } finally {
    foreach ($cleanupPaths as $pathToClean) {
      if (is_string($pathToClean) && $pathToClean !== '' && is_file($pathToClean)) {
        @unlink($pathToClean);
      }
    }
  }
}

