];
$supplierGroupContentActions = static function (array $actions) use ($supplierContentActionGroupDefs): array {
  $grouped = [];
  foreach ($actions as $action) {
    $groupKey = (string)($action['group'] ?? 'other');
    if (!isset($supplierContentActionGroupDefs[$groupKey])) {
      $groupKey = 'other';
    }
    if (!isset($grouped[$groupKey])) {
      $grouped[$groupKey] = [
        'key' => $groupKey,
        'title' => (string)($supplierContentActionGroupDefs[$groupKey]['title'] ?? $groupKey),
        'caption' => (string)($supplierContentActionGroupDefs[$groupKey]['caption'] ?? ''),
        'actions' => [],
      ];
    }
    $grouped[$groupKey]['actions'][] = $action;
  }
  $ordered = [];
  foreach (array_keys($supplierContentActionGroupDefs) as $groupKey) {
    if (isset($grouped[$groupKey]) && !empty($grouped[$groupKey]['actions'])) {
      $ordered[] = $grouped[$groupKey];
    }
  }
  return $ordered;
};
