        FROM feedtools_supplier_products p
        WHERE {$whereSql}
        ORDER BY p.sort_order ASC, p.id ASC
        LIMIT " . (int)($matchingOfferIdsMax + 1) . "
      ");
      $st->execute($args);
      $matchingOfferIds = [];
      while ($offerId = $st->fetchColumn()) {
        $offerId = trim((string)$offerId);
        if ($offerId !== '') {
          $matchingOfferIds[] = $offerId;
        }
      }
      $matchingOfferIdsTruncated = count($matchingOfferIds) > $matchingOfferIdsMax;
      if ($matchingOfferIdsTruncated) {
        $matchingOfferIds = array_slice($matchingOfferIds, 0, $matchingOfferIdsMax);
      }
      $totalOffers = $filtersActive ? $matchingOfferIdsCount : ($allOffersTotal > 0 ? $allOffersTotal : $matchingOfferIdsCount);
      $selectionOffersTotal = $filtersActive ? $matchingOfferIdsCount : ($allOffersTotal > 0 ? $allOffersTotal : $matchingOfferIdsCount);
    }
  }
  if ($contentFilter !== '') {
    $contentFilterProductIds = ft_content_filter_product_ids($supplierIdForView, $contentFilter, $contentIssueCode);
    $contentFilterProductIdsCount = count($contentFilterProductIds);
    $contentFilterProductIdSet = array_fill_keys(array_map('strval', $contentFilterProductIds), true);
  }
  $startMatch = 0;
  $endMatch = PHP_INT_MAX;
  if (!$showAll) {
    $startMatch = ($page - 1) * $limit;
    $endMatch = $startMatch + $limit;
  }

  $facetCat = [];
  $facetOzon = [];
  $facetWb = [];
  $facetBrand = [];
  $facetBrandOzon = [];
  $facetBrandWb = [];
  $facetModel = [];
  $facetBrandStatusOzon = [];
  $facetBrandStatusWb = [];
  $facetStatusOzon = [];
  $facetStatusWb = [];
  $facetParams = [];
  $facetHashtag = [];
  $filteredOffers = [];
  $buildOfferFacets = !$supplierOffersTablePartial && !$supplierOffersMatchingIdsAjax && !$filtersActive;
  $buildOfferParamFacets = false;
  if (!$supplierOffersTablePartial && !$supplierOffersMatchingIdsAjax && $filtersActive) {
    $facets = supplier_view_supplier_product_facets_cached($supplierIdForView, $catMap, $cfg, false);
    $statusFacets = supplier_view_supplier_product_status_facets_cached($supplierIdForView, $datasetOzonConnectionId, $datasetWbConnectionId, $supplierProductSupplierCode);
    $facets['status_ozon'] = $statusFacets['status_ozon'] ?? [];
    $facets['status_wb'] = $statusFacets['status_wb'] ?? [];
  }

  $catMap = supplier_products_category_map_from_json((string)($supplierProductContext['meta']['categories_json'] ?? ''));
  $needsFullOfferSort = in_array($offerSort, ['brand_ozon', 'brand_wb'], true);
  $canUseFastSqlOfferPage = $filtersActive
    && !$showAll
    && !$needsFullOfferSort
    && $contentFilter === ''
    && $fastStatusSqlSupported
    && $fastReadinessSqlSupported
    && !$filterNotInOzon
    && !$filterNotInOzonArchive
    && !$filterNotInWb
    && !$filterNotBulkyOzon
    && !$filterOzonAnalyticsActive;
  if ($supplierOffersMatchingIdsAjax && isset($selectionOffersTotal)) {
    // Fast matching-id path above already prepared the JSON payload.
  } elseif ($canUseFastSqlOfferPage) {
    [$fastWhereSql, $fastArgs] = supplier_view_build_fast_offer_filter_sql(
      $supplierIdForView,
      $filterCatSet,
      $filterOzonSet,
      $filterWbSet,
      $filterBrandSet,
      $filterSelectedOfferIdSet,
      $filterNameTokens,
      $filterHasPicture,
      $filterInStock,
      $filterParams,
      $filterStockMin,
      $filterStockMax,
      $filterReadySet,
      $filterReadyMode,
      $filterQualityHintSet,
      $datasetOzonConnectionId,
      $datasetWbConnectionId,
      $supplierProductSupplierCode,
      $filterBrandOzonSet,
      $filterBrandWbSet,
      $filterModelSet,
      $filterHashtags,
      $filterPriceMin,
      $filterPriceMax,
      $filterStatusOzonSet,
      $filterStatusWbSet,
      $filterBrandStatusOzonSet,
      $filterBrandStatusWbSet,
      $filterOzonMarkingError
    );

    $pdo = db();
    $countSt = $pdo->prepare("SELECT COUNT(*) FROM feedtools_supplier_products p WHERE {$fastWhereSql}");
    $countSt->execute($fastArgs);
    $filteredTotal = (int)$countSt->fetchColumn();
    $matchingOfferIdsCount = $filteredTotal;
    $totalOffers = $filteredTotal;
    $selectionOffersTotal = $filteredTotal;
    $scannedOffersTotal = $allOffersTotal > 0 ? $allOffersTotal : $filteredTotal;

    $orderSql = supplier_products_rows_for_view_order_sql($offerSort, $offerSortDir);
    $pageOfferIds = [];
    if ($filteredTotal > 0) {
      $pageSt = $pdo->prepare("
        SELECT p.offer_id
        FROM feedtools_supplier_products p
        WHERE {$fastWhereSql}
        {$orderSql}
        LIMIT " . (int)$limit . " OFFSET " . (int)$startMatch . "
      ");
      $pageSt->execute($fastArgs);
      while ($offerId = $pageSt->fetchColumn()) {
        $offerId = trim((string)$offerId);
        if ($offerId !== '') {
          $pageOfferIds[] = $offerId;
        }
      }
    }

    if (!$supplierOffersTablePartial) {
      $idsSt = $pdo->prepare("
        SELECT p.offer_id
        FROM feedtools_supplier_products p
        WHERE {$fastWhereSql}
        {$orderSql}
        LIMIT " . (int)($matchingOfferIdsMax + 1) . "
      ");
      $idsSt->execute($fastArgs);
      while ($offerId = $idsSt->fetchColumn()) {
        $offerId = trim((string)$offerId);
        if ($offerId !== '') {
          $matchingOfferIds[] = $offerId;
        }
      }
      $matchingOfferIdsTruncated = count($matchingOfferIds) > $matchingOfferIdsMax;
      if ($matchingOfferIdsTruncated) {
        $matchingOfferIds = array_slice($matchingOfferIds, 0, $matchingOfferIdsMax);
      }
    }

    $rowsByOfferId = supplier_view_supplier_product_rows_by_offer_ids($supplierIdForView, $pageOfferIds, $cfg);
    foreach ($pageOfferIds as $offerId) {
      $productRow = $rowsByOfferId[$offerId] ?? null;
      if (is_array($productRow)) {
        $offers[] = supplier_view_offer_from_product_row($productRow, $catMap);
      }
    }
    supplier_view_apply_bundle_ui_values($offers, $supplierIdForView, $catMap, $cfg);
  } elseif (!$filtersActive && !$showAll && !$needsFullOfferSort) {
    $supplierProductRowsBySort = supplier_products_rows_for_view($supplierIdForView, $cfg, $limit, $startMatch, $offerSort, $offerSortDir);
    foreach ($supplierProductRowsBySort as $productRow) {
      if (is_array($productRow)) {
        $offers[] = supplier_view_offer_from_product_row($productRow, $catMap);
      }
    }
    supplier_view_apply_bundle_ui_values($offers, $supplierIdForView, $catMap, $cfg);
    $allOffersTotal = $allOffersTotal > 0 ? $allOffersTotal : supplier_products_count($supplierIdForView, $cfg);
    $totalOffers = $allOffersTotal;
    $selectionOffersTotal = $allOffersTotal;
    $scannedOffersTotal = $allOffersTotal;
    if (!$supplierOffersTablePartial && !$supplierOffersMatchingIdsAjax) {
      $facets = supplier_view_supplier_product_facets_cached($supplierIdForView, $catMap, $cfg, false);
      $statusFacets = supplier_view_supplier_product_status_facets_cached($supplierIdForView, $datasetOzonConnectionId, $datasetWbConnectionId, $supplierProductSupplierCode);
      $facets['status_ozon'] = $statusFacets['status_ozon'] ?? [];
      $facets['status_wb'] = $statusFacets['status_wb'] ?? [];
    }
    if ($supplierOffersMatchingIdsAjax) {
      $idsInfo = supplier_products_offer_ids_for_view($supplierIdForView, $matchingOfferIdsMax, $cfg);
      $matchingOfferIds = (array)($idsInfo['ids'] ?? []);
      $matchingOfferIdsTruncated = !empty($idsInfo['truncated']);
      $matchingOfferIdsCount = (int)($idsInfo['count'] ?? count($matchingOfferIds));
    }
  } else {
    $supplierProductRowsBySort = supplier_products_rows_for_view($supplierIdForView, $cfg);

	  $candidateOffers = [];
	  foreach ($supplierProductRowsBySort as $productRow) {
	    if (!is_array($productRow)) continue;
	    $scannedOffersTotal++;
	    $candidateOffers[] = supplier_view_offer_from_product_row($productRow, $catMap);
	  }
	  $candidateBundleValuesApplied = supplier_view_bundle_ui_values_are_needed_for_candidate_filtering(
	    $offerSort,
	    $filterInStock,
	    $filterPriceMin,
	    $filterPriceMax,
	    $filterStockMin,
	    $filterStockMax
	  );
	  if ($candidateBundleValuesApplied) {
	    supplier_view_apply_bundle_ui_values($candidateOffers, $supplierIdForView, $catMap, $cfg);
	  }
	  $needsCandidateMarketplaceStatuses = $filterStatusOzonSet !== null || $filterStatusWbSet !== null || $filterQualityHintSet !== null || $filterOzonMarkingError;
  $needsCandidateBrandStatuses = $filterBrandStatusOzonSet !== null || $filterBrandStatusWbSet !== null;
  if ($needsCandidateMarketplaceStatuses) {
    supplier_view_apply_marketplace_statuses($candidateOffers, $datasetOzonConnectionId, $datasetWbConnectionId, $supplierProductSupplierCode);
  }
  if ($needsCandidateBrandStatuses) {
    supplier_view_apply_brand_statuses($candidateOffers);
  }
  if ($filterOzonAnalyticsActive) {
    supplier_view_apply_ozon_analytics($candidateOffers, $datasetOzonConnectionId, $supplierProductSupplierCode, $cfg);
    $offersHaveOzonAnalytics = true;
  }
  $candidateMarketplaceCharacteristicSets = $filterReadySet !== null
    ? supplier_view_marketplace_characteristic_sets($candidateOffers)
    : ['ozon' => [], 'wb' => [], '_analysis' => ['ozon' => [], 'wb' => []]];

  foreach ($candidateOffers as $o) {

    $vCat = (string)($o['category_path'] ?? '');
    $vOzon = (string)($o['ozon_category'] ?? '');
    $vWb = (string)($o['wb_category'] ?? ($o['wb_subject_id'] ?? ''));
    $vBrand = (string)($o['brand_effective'] ?? '');
    $vBrandOzon = (string)($o['brand_ozon_effective'] ?? $vBrand);
    $vBrandWb = (string)($o['brand_wb_effective'] ?? $vBrand);
    $vModel = trim((string)($o['same_model'] ?? ''));
    $vBrandStatusOzon = supplier_view_brand_status_value($o, 'ozon');
    $vBrandStatusWb = supplier_view_brand_status_value($o, 'wb');

    if ($buildOfferFacets) {
      $facetCat[$vCat === '' ? EMPTY_TOKEN : $vCat] = true;
      $facetOzon[$vOzon === '' ? EMPTY_TOKEN : $vOzon] = true;
      $facetWb[$vWb === '' ? EMPTY_TOKEN : $vWb] = true;
      $facetBrand[$vBrand === '' ? EMPTY_TOKEN : $vBrand] = true;
      $facetBrandOzon[$vBrandOzon === '' ? EMPTY_TOKEN : $vBrandOzon] = true;
      $facetBrandWb[$vBrandWb === '' ? EMPTY_TOKEN : $vBrandWb] = true;
      $facetModel[$vModel === '' ? EMPTY_TOKEN : $vModel] = true;
      if ($vBrandStatusOzon !== '') $facetBrandStatusOzon[$vBrandStatusOzon] = true;
      if ($vBrandStatusWb !== '') $facetBrandStatusWb[$vBrandStatusWb] = true;
      supplier_view_add_status_filter_facets($facetStatusOzon, (string)($o['status_ozon'] ?? ''), (array)($o['status_ozon_messages'] ?? []));
      supplier_view_add_status_filter_facets($facetStatusWb, (string)($o['status_wb'] ?? ''), (array)($o['status_wb_messages'] ?? []));

      foreach ((array)($o['hashtags'] ?? []) as $h) {
        $h = trim((string)$h);
        if ($h !== '') $facetHashtag[$h] = true;
      }

      if ($buildOfferParamFacets) {
        foreach ((array)($o['params_kv'] ?? []) as $pname => $vals) {
          $pname = trim((string)$pname);
          if ($pname === '') continue;
          if (!isset($facetParams[$pname])) $facetParams[$pname] = [];
          if (!is_array($vals)) $vals = [$vals];
          foreach ($vals as $pv) {
            $pv = trim((string)$pv);
            $facetParams[$pname][$pv === '' ? EMPTY_TOKEN : $pv] = true;
          }
        }
      }
    }

    $ok = true;
    if ($filterCatSet !== null) $ok = $ok && isset($filterCatSet[$vCat]);
    if ($filterOzonSet !== null) $ok = $ok && isset($filterOzonSet[$vOzon]);
    if ($filterWbSet !== null) $ok = $ok && isset($filterWbSet[$vWb]);
    if ($filterBrandSet !== null) $ok = $ok && isset($filterBrandSet[$vBrand]);
    if ($filterBrandOzonSet !== null) $ok = $ok && isset($filterBrandOzonSet[$vBrandOzon]);
    if ($filterBrandWbSet !== null) $ok = $ok && isset($filterBrandWbSet[$vBrandWb]);
    if ($filterModelSet !== null) $ok = $ok && isset($filterModelSet[$vModel]);
    if ($filterBrandStatusOzonSet !== null) $ok = $ok && isset($filterBrandStatusOzonSet[$vBrandStatusOzon]);
    if ($filterBrandStatusWbSet !== null) $ok = $ok && isset($filterBrandStatusWbSet[$vBrandStatusWb]);
    if ($filterStatusOzonSet !== null) $ok = $ok && supplier_view_status_filter_matches($o, 'ozon', $filterStatusOzonSet);
    if ($filterStatusWbSet !== null) $ok = $ok && supplier_view_status_filter_matches($o, 'wb', $filterStatusWbSet);
    if ($filterOzonMarkingError) $ok = $ok && supplier_view_offer_has_ozon_marking_error($o);
    if ($filterQualityHintSet !== null) $ok = $ok && supplier_view_quality_hint_filter_matches($o, $filterQualityHintSet);
    if ($filterSelectedOfferIdSet !== null) {
      $oidSelected = (string)($o['id'] ?? '');
      $ok = $ok && $oidSelected !== '' && isset($filterSelectedOfferIdSet[$oidSelected]);
    }
    if ($contentFilterProductIdSet !== null) {
      $productId = (int)($o['_supplier_product_id'] ?? 0);
      $ok = $ok && $productId > 0 && isset($contentFilterProductIdSet[(string)$productId]);
    }

    if ($ok && !empty($filterHashtags)) {
      $set = [];
      foreach ((array)($o['hashtags'] ?? []) as $h) {
        $h = trim((string)$h);
        if ($h !== '') $set[$h] = true;
      }
      $hit = false;
      foreach ($filterHashtags as $want) {
        $want = trim((string)$want);
        if ($want === '') continue;
        if ($want[0] !== '#') $want = '#' . $want;
        if (isset($set[$want])) { $hit = true; break; }
      }
      if (!$hit) $ok = false;
    }

    if (!empty($filterNameTokens)) {
      $ok = $ok && ft_query_matches_offer((string)($o['id'] ?? ''), (string)($o['name'] ?? ''), $filterNameTokens);
    }

    if ($ok && !empty($filterParams)) {
      $pmapOffer = (array)($o['params_kv'] ?? []);
      foreach ($filterParams as $fpName => $fpVals) {
        $fpName = (string)$fpName;
        if ($fpName === '') continue;
        if (!is_array($fpVals)) $fpVals = [$fpVals];
        $fpVals = array_values(array_unique($fpVals));

        $offerVals = [];
        if (isset($pmapOffer[$fpName])) {
          $ov = $pmapOffer[$fpName];
          if (!is_array($ov)) $ov = [$ov];
          foreach ($ov as $x) $offerVals[] = trim((string)$x);
        }

        $match = false;
        if (in_array('', $fpVals, true)) {
          if (!isset($pmapOffer[$fpName])) {
            $match = true;
          } else {
            foreach ($offerVals as $x) {
              if ($x === '') { $match = true; break; }
            }
          }
        }
        if (!$match) {
          $want = [];
          foreach ($fpVals as $v) {
            $v = (string)$v;
            if ($v !== '') $want[$v] = true;
          }
          if ($want) {
            foreach ($offerVals as $x) {
              if (isset($want[$x])) { $match = true; break; }
            }
          }
        }
        if (!$match) { $ok = false; break; }
      }
    }

    if ($filterInStock) {
      $ok = $ok && supplier_view_offer_effective_stock($o) > 0;
    }

    if ($ok && $filterHasPicture) {
      $hasPicture = false;
      foreach ((array)($o['pictures'] ?? []) as $pic) {
        if (trim((string)$pic) !== '') { $hasPicture = true; break; }
      }
      $ok = $ok && $hasPicture;
    }

    if ($ok && $filterNotBulkyOzon) {
      $ok = $ok && !ft_offer_is_ozon_bulky($o);
    }

    if ($ok && ($filterPriceMin !== null || $filterPriceMax !== null)) {
      $priceOriginal = supplier_view_offer_effective_price($o);
      if ($filterPriceMin !== null) $ok = $ok && ($priceOriginal !== null) && ($priceOriginal >= $filterPriceMin);
      if ($ok && $filterPriceMax !== null) $ok = $ok && ($priceOriginal !== null) && ($priceOriginal <= $filterPriceMax);
    }

    if ($ok && ($filterStockMin !== null || $filterStockMax !== null)) {
      $effectiveStock = supplier_view_offer_effective_stock($o);
      if ($filterStockMin !== null) $ok = $ok && ($effectiveStock >= $filterStockMin);
      if ($ok && $filterStockMax !== null) $ok = $ok && ($effectiveStock <= $filterStockMax);
    }

    if ($ok && $filterOzonAnalyticsActive) {
      $ok = $ok
        && supplier_view_analytics_filter_matches($o, 'hits_view', $filterOzonHitsMin !== null ? (float)$filterOzonHitsMin : null, $filterOzonHitsMax !== null ? (float)$filterOzonHitsMax : null)
        && supplier_view_analytics_filter_matches($o, 'ordered_units', $filterOzonSalesMin !== null ? (float)$filterOzonSalesMin : null, $filterOzonSalesMax !== null ? (float)$filterOzonSalesMax : null)
        && supplier_view_analytics_filter_matches($o, 'view_to_card_pct', $filterOzonViewCardMin, $filterOzonViewCardMax)
        && supplier_view_analytics_filter_matches($o, 'card_to_order_pct', $filterOzonCardOrderMin, $filterOzonCardOrderMax);
    }

    if ($ok && $filterReadySet !== null) {
      $ok = supplier_view_content_readiness_filter_matches_states($o, $candidateMarketplaceCharacteristicSets, $filterReadySet);
    }

    if ($filterNotInOzon && $ozonFilterError === '' && is_array($ozonPresentSet)) {
      $oid = trim((string)($o['id'] ?? ''));
      $ok = $ok && ($oid !== '') && !isset($ozonPresentSet[$oid]);
    }
    if ($filterNotInOzonArchive && $ozonFilterError === '' && is_array($ozonArchiveSet)) {
      $oid = trim((string)($o['id'] ?? ''));
      $ok = $ok && ($oid !== '') && !isset($ozonArchiveSet[$oid]);
    }
    if ($filterNotInWb && $wbFilterError === '' && is_array($wbPresentSet)) {
      $ok = $ok && !wb_products_offer_exists($o, $wbPresentSet);
    }

    if ($ok) {
      $oidAll = (string)($o['id'] ?? '');
      if ($supplierOffersMatchingIdsAjax && $oidAll !== '' && !$matchingOfferIdsTruncated) {
        if ($matchingOfferIdsCount < $matchingOfferIdsMax) {
          $matchingOfferIds[] = $oidAll;
          $matchingOfferIdsCount++;
        } else {
          $matchingOfferIdsTruncated = true;
        }
      }
      if (!$supplierOffersMatchingIdsAjax && ($offerSort !== '' || $showAll || ($filteredTotal >= $startMatch && $filteredTotal < $endMatch))) {
        $filteredOffers[] = $o;
      }
      $filteredTotal++;
    }
  }

  if ($allOffersTotal <= 0) {
    $allOffersTotal = $scannedOffersTotal;
	  }
	  $totalOffers = $filtersActive ? $filteredTotal : ($allOffersTotal > 0 ? $allOffersTotal : $filteredTotal);
	  $selectionOffersTotal = $filtersActive ? $totalOffers : ($allOffersTotal > 0 ? $allOffersTotal : $totalOffers);

	  if ($offerSort !== '') {
    usort($filteredOffers, static function (array $a, array $b) use ($offerSort, $offerSortDir): int {
      $va = supplier_view_offer_sort_value($a, $offerSort);
      $vb = supplier_view_offer_sort_value($b, $offerSort);
      $emptyA = ($va === null || (is_string($va) && trim($va) === ''));
      $emptyB = ($vb === null || (is_string($vb) && trim($vb) === ''));
      if ($emptyA && $emptyB) {
        return strnatcasecmp((string)($a['id'] ?? ''), (string)($b['id'] ?? ''));
      }
      if ($emptyA || $emptyB) {
        if ($offerSortDir === 'desc') {
          return $emptyA ? 1 : -1;
        }
        return $emptyA ? -1 : 1;
      }
      if (is_numeric($va) && is_numeric($vb)) {
        $cmp = ((float)$va <=> (float)$vb);
      } else {
        $cmp = strnatcasecmp((string)$va, (string)$vb);
      }
      if ($cmp === 0) {
        $cmp = strnatcasecmp((string)($a['id'] ?? ''), (string)($b['id'] ?? ''));
      }
      return $offerSortDir === 'desc' ? -$cmp : $cmp;
    });
  }

	  $offers = ($offerSort === '' && !$showAll) ? $filteredOffers : ($showAll ? $filteredOffers : array_slice($filteredOffers, $startMatch, $limit));
	  if (!$candidateBundleValuesApplied) {
	    supplier_view_apply_bundle_ui_values_for_visible_rows($offers, $supplierIdForView, $catMap, $cfg);
	  }
	  $offersHaveMarketplaceStatuses = $needsCandidateMarketplaceStatuses;

  if ($buildOfferFacets) {
    $cmp = function ($a, $b) {
      $la = ($a === EMPTY_TOKEN) ? '∅ (пусто)' : $a;
      $lb = ($b === EMPTY_TOKEN) ? '∅ (пусто)' : $b;
      return strcasecmp($la, $lb);
    };

    $facets['catpath'] = array_keys($facetCat);
    $facets['ozoncat'] = array_keys($facetOzon);
    $facets['wbcat'] = array_keys($facetWb);
    $facets['brand'] = array_keys($facetBrand);
    $facets['brand_ozon'] = array_keys($facetBrandOzon);
    $facets['brand_wb'] = array_keys($facetBrandWb);
    $facets['model'] = array_keys($facetModel);
    $facets['brand_status_ozon'] = supplier_view_default_brand_status_filter_tokens();
    $facets['brand_status_wb'] = supplier_view_default_brand_status_filter_tokens();
    $facets['status_ozon'] = $datasetOzonConnectionId > 0
      ? supplier_view_sort_status_filter_tokens(array_merge(supplier_view_default_status_filter_tokens(true), array_keys($facetStatusOzon)))
      : [];
    $facets['status_wb'] = $datasetWbConnectionId > 0
      ? supplier_view_sort_status_filter_tokens(array_merge(supplier_view_default_status_filter_tokens(false), array_keys($facetStatusWb)))
      : [];
    $facets['hashtag'] = array_keys($facetHashtag);

    usort($facets['catpath'], $cmp);
    usort($facets['ozoncat'], $cmp);
    usort($facets['wbcat'], $cmp);
    usort($facets['brand'], $cmp);
    usort($facets['brand_ozon'], $cmp);
    usort($facets['brand_wb'], $cmp);
    usort($facets['model'], $cmp);
    usort($facets['hashtag'], $cmp);

    $facets['params'] = [];
    foreach ($facetParams as $pname => $valsMap) {
      $pname = trim((string)$pname);
      if ($pname === '') continue;
      $vals = array_keys((array)$valsMap);
      usort($vals, $cmp);
      $facets['params'][$pname] = $vals;
    }
    uksort($facets['params'], function ($a, $b) {
      return strcasecmp((string)$a, (string)$b);
    });
  }
  }
}

if (!isset($selectionOffersTotal)) {
  $selectionOffersTotal = $allOffersTotal > 0 ? $allOffersTotal : $totalOffers;
}

if ($supplierOffersMatchingIdsAjax) {
  header('Content-Type: application/json; charset=utf-8');
  echo json_encode([
    'ok' => true,
    'ids' => array_values($matchingOfferIds),
    'truncated' => $matchingOfferIdsTruncated,
    'count' => $matchingOfferIdsCount,
    'selection_total' => $selectionOffersTotal,
  ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_INVALID_UTF8_SUBSTITUTE);
  exit;
}

if (!$offersHaveMarketplaceStatuses) {
  supplier_view_apply_marketplace_statuses($offers, $datasetOzonConnectionId, $datasetWbConnectionId, $supplierProductSupplierCode);
}
if (!$offersHaveOzonAnalytics) {
  supplier_view_apply_ozon_analytics($offers, $datasetOzonConnectionId, $supplierProductSupplierCode, $cfg);
}
supplier_view_apply_wb_analytics($offers, $datasetWbConnectionId, $supplierProductSupplierCode, $cfg);
supplier_view_apply_brand_statuses($offers);
$marketplaceCharacteristicSets = supplier_view_marketplace_characteristic_sets($offers);

