  1
);
$ozonAnalyticsFilterBounds['view_to_card_pct_max'] = max(
  (float)$ozonAnalyticsFilterBounds['view_to_card_pct_max'],
  (float)($filterOzonViewCardMin ?? 0),
  (float)($filterOzonViewCardMax ?? 0),
  100.0
);
$ozonAnalyticsFilterBounds['card_to_order_pct_max'] = max(
  (float)$ozonAnalyticsFilterBounds['card_to_order_pct_max'],
  (float)($filterOzonCardOrderMin ?? 0),
  (float)($filterOzonCardOrderMax ?? 0),
  100.0
);

$wbAnalyticsDatasetSummary = [
  'date_from' => '',
  'date_to' => '',
