if ($computeGlobalWbAnalyticsSummary && !$supplierOffersTablePartial) {
  $wbAnalyticsDatasetSummary = supplier_view_wb_analytics_dataset_summary(
    (int)($supplierProductContext['supplier_id'] ?? 0),
    $datasetWbConnectionId,
    $supplierProductSupplierCode,
    $cfg
  );
}

$totalPages = $showAll ? 1 : max(1, (int)ceil($totalOffers / $limit));

$taxonomyLazyLoading = true;
$ozonTaxonomyOptions = [];
$ozonTaxonomyLabelByValue = [];
$visibleOzonCategoryValues = [];
$visibleWbCategoryValues = [];
foreach ($offers as $visibleOffer) {
  $visibleOzonCategoryValues[] = (string)($visibleOffer['ozon_category'] ?? '');
  $visibleWbCategoryValues[] = (string)($visibleOffer['wb_category'] ?? ($visibleOffer['wb_subject_id'] ?? ''));
}
if (!$supplierOffersTablePartial) {
  foreach (($facets['ozoncat'] ?? []) as $facetValue) {
    $visibleOzonCategoryValues[] = (string)$facetValue;
  }
  foreach (($facets['wbcat'] ?? []) as $facetValue) {
    $visibleWbCategoryValues[] = (string)$facetValue;
  }
  foreach ($filterOzoncat as $filterValue) {
    $visibleOzonCategoryValues[] = (string)$filterValue;
  }
  foreach ($filterWbcat as $filterValue) {
    $visibleWbCategoryValues[] = (string)$filterValue;
  }
}
$ozonTaxonomyLabelByValue = supplier_view_taxonomy_labels('ozon', $visibleOzonCategoryValues);
$ozonFacetLabels = [];
if (!$supplierOffersTablePartial) {
  foreach (($facets['ozoncat'] ?? []) as $facetValue) {
    $facetValue = (string)$facetValue;
    if ($facetValue === '' || $facetValue === EMPTY_TOKEN) continue;
    if (isset($ozonTaxonomyLabelByValue[$facetValue])) {
      $ozonFacetLabels[$facetValue] = $ozonTaxonomyLabelByValue[$facetValue];
    }
  }
}

$wbTaxonomyOptions = [];
$wbTaxonomyLabelByValue = [];
$wbTaxonomyLabelByValue = supplier_view_taxonomy_labels('wildberries', $visibleWbCategoryValues);
$wbFacetLabels = [];
if (!$supplierOffersTablePartial) {
  foreach (($facets['wbcat'] ?? []) as $facetValue) {
