      gap: 6px;
      align-items: center;
      cursor: pointer;
      min-width: 0;
      font-weight: 900;
    }

    .supplier-offer-sale-switch input {
      position: absolute;
      opacity: 0;
      pointer-events: none;
    }

    .supplier-offer-sale-slider {
      position: relative;
      width: 31px;
      height: 18px;
      border-radius: 999px;
      background: #ef4444;
      box-shadow: inset 0 0 0 1px rgba(127, 29, 29, .15);
      transition: background .15s ease;
    }

    .supplier-offer-sale-slider::after {
      content: "";
      position: absolute;
      top: 3px;
      left: 3px;
      width: 12px;
      height: 12px;
      border-radius: 50%;
      background: #fff;
      box-shadow: 0 1px 3px rgba(15, 23, 42, .24);
      transition: transform .15s ease;
