    .dd {
      position: relative;
      display: inline-block;
    }

    .ddbtn {
      border: 1px solid var(--border);
      background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
      border-radius: 10px;
      padding: 6px 10px;
      font-size: 12px;
      cursor: pointer;
      display: inline-flex;
      align-items: center;
      gap: 8px;
      user-select: none;
      max-width: min(100%, 520px);
      min-height: 34px;
      color: #334155;
      font-weight: 500;
      transition: border-color .15s ease, box-shadow .15s ease, background .15s ease;
    }

    .ddbtn:hover {
      border-color: #93c5fd;
      background: var(--accent-soft);
    }

    .ddbtn.is-active {
      border-color: #22c55e;
      background: linear-gradient(180deg, #dcfce7 0%, #bbf7d0 100%);
      color: #14532d;
      box-shadow: 0 0 0 2px rgba(34, 197, 94, .18);
    }

    .ddbtn .pill {
      background: #dbeafe;
      color: #1d4ed8;
      border-radius: 999px;
      padding: 1px 8px;
      font-size: 12px;
    }

    .ddpanel {
      position: fixed;
      z-index: 5000;
      top: 0;
      left: 0;
      min-width: 280px;
      width: min(560px, calc(100vw - 24px));
      max-height: min(430px, calc(100vh - 24px));
      overflow: auto;
      overscroll-behavior: contain;
      border: 1px solid var(--border-strong);
      border-radius: 14px;
      background: #fff;
      box-shadow: 0 24px 70px rgba(15, 23, 42, .18);
      padding: 10px;
      display: none;
    }

    .ddpanel.open {
      display: block;
    }

    .toggleline {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-size: 12px;
      user-select: none;
      cursor: pointer;
      color: #111827;
      opacity: 0.85;
    }

    .toggleline:hover {
      opacity: 1;
    }

    .togglechev {
      display: inline-block;
      width: 14px;
      height: 14px;
      transition: transform .12s ease;
    }

    .togglechev.open {
      transform: rotate(90deg);
    }

    .dditem {
      display: flex;
      gap: 8px;
      align-items: flex-start;
      padding: 4px 2px;
      font-size: 12px;
      line-height: 1.2;
      word-break: break-word;
    }

    .dditem--status-parent {
      align-items: center;
      font-weight: 700;
      color: #0f172a;
    }

    .dditem--status-child {
      padding-left: 34px;
      color: #475569;
    }

    .ddstatus-caret,
    .ddstatus-caret-placeholder {
      width: 18px;
      height: 18px;
      flex: 0 0 18px;
      display: inline-flex;
      align-items: center;
      justify-content: center;
    }

    .ddstatus-caret {
      border: 0;
      background: transparent;
      color: #64748b;
      cursor: pointer;
      border-radius: 6px;
      padding: 0;
      transition: transform .12s ease, background .12s ease;
    }

    .ddstatus-caret:hover {
      background: #f1f5f9;
      color: #0f172a;
    }

    .ddstatus-caret.open {
      transform: rotate(90deg);
    }

    .ddstatus-count {
      margin-left: auto;
      border-radius: 999px;
      background: #f1f5f9;
      color: #64748b;
      font-size: 11px;
      line-height: 1;
      padding: 3px 7px;
    }

    .ddsearch {
      width: 100%;
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 6px 10px;
      font-size: 12px;
      margin-bottom: 8px;
      background: var(--surface-soft);
    }

    .ddactions {
      display: flex;
      gap: 8px;
      margin: 0 0 8px;
      flex-wrap: wrap;
    }

    .ddactions button {
      border: 1px solid var(--border);
      background: #fff;
      border-radius: 10px;
      padding: 4px 10px;
      font-size: 12px;
      cursor: pointer;
      color: #475569;
      font-weight: 600;
    }

    .ddactions button:disabled {
      cursor: default;
      opacity: .45;
    }

    button {
      border: 1px solid var(--border-strong);
      background: linear-gradient(180deg, #ffffff 0%, #f4f7fb 100%);
      border-radius: 10px;
      padding: 8px 12px;
      font-size: 12px;
      cursor: pointer;
      color: var(--text);
      font-weight: 600;
      transition: transform .12s ease, background .15s ease, border-color .15s ease, box-shadow .15s ease;
    }

    button:hover {
      background: #ffffff;
      border-color: #94a3b8;
      box-shadow: 0 8px 18px rgba(15, 23, 42, .08);
      transform: translateY(-1px);
    }

    button[type="submit"] {
      background: linear-gradient(135deg, #2563eb 0%, #0f766e 100%);
      border-color: transparent;
      color: #fff;
      font-weight: 700;
    }

    button[type="submit"]:hover {
      background: linear-gradient(135deg, #1d4ed8 0%, #0d6b63 100%);
      border-color: transparent;
      color: #fff;
    }

    button:disabled {
      opacity: 0.6;
      cursor: not-allowed;
    }

    .btn-primary {
      background: linear-gradient(135deg, #2563eb 0%, #0f766e 100%) !important;
      border-color: transparent !important;
      color: #fff !important;
      box-shadow: 0 10px 22px rgba(37, 99, 235, .18);
    }

    .btn-primary:hover {
      background: linear-gradient(135deg, #1d4ed8 0%, #0d6b63 100%) !important;
      border-color: transparent !important;
      color: #fff !important;
      box-shadow: 0 14px 26px rgba(37, 99, 235, .22);
    }

    .btn-secondary {
      background: linear-gradient(180deg, #ffffff 0%, #eef4fb 100%);
      border-color: #cbd5e1;
      color: #0f172a;
    }

    .btn-secondary:hover {
      border-color: #94a3b8;
      background: #ffffff;
    }

    .btn-neutral {
      background: #fff;
      border-color: #dbe3ee;
      color: #475569;
      box-shadow: none;
    }

    .btn-neutral:hover {
      background: #f8fafc;
      color: #334155;
      box-shadow: none;
    }

    .btn-danger {
      background: linear-gradient(180deg, #fff5f5 0%, #fee2e2 100%);
      border-color: #fecaca;
      color: #b91c1c;
    }

    .btn-danger:hover {
      background: #fff1f2;
      border-color: #fca5a5;
      color: #991b1b;
    }

    .btn-inline {
      padding-left: 10px;
      padding-right: 10px;
      font-size: 11px;
    }

    .fold-card {
      border: 1px solid var(--border);
      border-radius: 14px;
      background: #fff;
      margin-bottom: 16px;
      overflow: hidden;
    }

    .fold-card summary {
      list-style: none;
      cursor: pointer;
      padding: 14px 16px;
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      gap: 16px;
    }

    .fold-card summary::-webkit-details-marker {
      display: none;
    }

    .fold-label {
      display: flex;
      flex-direction: column;
      gap: 4px;
      min-width: 0;
    }

    .fold-title {
      font-size: 16px;
      font-weight: 700;
      color: var(--text);
    }

    .fold-meta {
      font-size: 12px;
      color: var(--muted);
      font-weight: 400;
      line-height: 1.45;
    }

    .fold-body {
      padding: 0 16px 16px;
      border-top: 1px solid #f3f4f6;
    }

    .dataset-meta-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
      gap: 12px;
      margin: 14px 0 0;
    }

    .dataset-meta-item {
      border: 1px solid var(--border);
      border-radius: 12px;
      background: var(--surface-soft);
      padding: 12px;
    }

    .dataset-meta-label {
      display: block;
      font-size: 12px;
      color: var(--muted);
      margin-bottom: 4px;
    }

    .dataset-meta-value {
      display: block;
      font-size: 14px;
      color: var(--text);
      font-weight: 600;
      line-height: 1.4;
      word-break: break-word;
    }

    .dataset-marketplace-card {
      margin-bottom: 14px;
      border: 1px solid #cfe0f7;
      border-radius: 18px;
      padding: 14px;
      background:
        radial-gradient(circle at top right, rgba(191, 219, 254, .38), transparent 34%),
        linear-gradient(180deg, #ffffff 0%, #f6faff 100%);
      box-shadow: 0 12px 28px rgba(24, 57, 90, .06);
    }

    .supplier-products-card-grid {
      display: grid;
      grid-template-columns: minmax(280px, .95fr) minmax(420px, 1.3fr);
      gap: 14px;
      align-items: stretch;
    }

    .supplier-products-source-panel {
      display: grid;
      gap: 8px;
      align-content: start;
      min-width: 0;
    }

    .supplier-products-source-head {
      gap: 12px;
    }

    .supplier-products-source-head .btn-primary {
      white-space: nowrap;
    }

    .supplier-marketplace-compact {
      display: grid;
      gap: 8px;
      margin: 0;
      padding-left: 14px;
      border-left: 1px solid #cfe0f7;
      min-width: 0;
    }

    .supplier-marketplace-title {
      color: #172033;
      font-size: 13px;
      font-weight: 800;
      line-height: 1.2;
    }

    .supplier-marketplace-compact-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 8px;
      align-items: start;
    }

    .supplier-marketplace-compact .dataset-marketplace-field {
      gap: 6px;
    }

    .supplier-marketplace-compact .field {
      gap: 4px;
    }

    .supplier-marketplace-compact .field > span {
      font-size: 11px;
      line-height: 1.2;
    }

    .supplier-marketplace-compact .control-select {
      min-height: 34px;
      padding: 7px 9px;
      font-size: 12px;
    }

    .supplier-marketplace-compact .dataset-marketplace-actions {
      gap: 6px;
    }

    .supplier-marketplace-compact .dataset-marketplace-actions button {
      min-height: 30px;
      padding: 0 9px;
      font-size: 11px;
    }

    .supplier-sync-meta {
      color: var(--muted);
      font-size: 10px;
      line-height: 1.25;
    }

    .supplier-marketplace-hint {
      margin-top: 0;
      font-size: 11px;
      line-height: 1.35;
    }

    .supplier-autosave-error {
      color: #b91c1c;
      font-size: 11px;
      line-height: 1.3;
    }

    .supplier-autosave-error[hidden] {
      display: none;
    }

    .dataset-marketplace-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 12px;
      align-items: end;
      margin-top: 12px;
    }

    .dataset-marketplace-field {
      display: grid;
      gap: 8px;
    }

    .dataset-marketplace-field label {
      min-width: 0;
    }

    .dataset-marketplace-actions {
      display: flex;
      gap: 8px;
      flex-wrap: wrap;
      align-items: center;
    }

    .dataset-marketplace-actions form {
      margin: 0;
    }

    .dataset-marketplace-actions button {
      min-height: 36px;
      padding: 0 12px;
      font-size: 12px;
    }

    .supplier-workspace {
      display: grid;
      gap: 14px;
      margin-bottom: 14px;
    }

    .supplier-workspace-tabs {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 12px;
    }

    .supplier-workspace-tab {
      min-height: 66px;
      border: 1px solid transparent;
      border-radius: 8px;
      padding: 14px 16px;
      cursor: pointer;
      text-align: left;
      font-size: 16px;
      font-weight: 800;
      color: #172033;
      box-shadow: 0 10px 24px rgba(15, 23, 42, .055);
    }

    .supplier-workspace-tab--import {
      border-color: #9bd7b2;
      background: linear-gradient(180deg, #ecfdf3 0%, #dff9ea 100%);
    }

    .supplier-workspace-tab--content {
      border-color: #fde68a;
      background: linear-gradient(180deg, #fffbeb 0%, #fef3c7 100%);
    }

    .supplier-workspace-tab--export {
      border-color: #bfdbfe;
      background: linear-gradient(180deg, #eff6ff 0%, #dbeafe 100%);
    }

    .supplier-workspace-tab.is-active {
      outline: 2px solid rgba(31, 111, 235, .38);
      outline-offset: 2px;
    }

    .supplier-workspace-panel[hidden] {
      display: none;
    }

    .supplier-workspace-panel > .card {
      margin-bottom: 0;
    }

    .supplier-workspace-panel--import > .card {
      min-height: 92px;
    }

    .supplier-workspace-panel--content > .card {
      display: flex;
      flex-direction: column;
    }

    .supplier-layout-note {
      display: flex;
      align-items: center;
      gap: 10px;
      flex-wrap: wrap;
      margin: 0 0 12px;
      padding: 10px 12px;
      border: 1px solid #d8e4ef;
      border-radius: 12px;
      background: #f8fbff;
      color: #334155;
      font-size: 13px;
      line-height: 1.35;
    }

    .supplier-layout-note strong {
      color: #0f172a;
    }

    .supplier-layout-note a {
      margin-left: auto;
      font-weight: 800;
    }

    .supplier-v2-actionbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      margin: 0 0 12px;
    }

    .supplier-v2-actionbar-main,
    .supplier-v2-actionbar-side {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      min-width: 0;
    }

    .supplier-v2-classic-link {
      display: inline-flex;
      align-items: center;
      min-height: 34px;
      padding: 0 12px;
      border: 1px solid #c7d9f1;
      border-radius: 10px;
      background: #fff;
      color: #2563eb;
      font-size: 12px;
      font-weight: 900;
      text-decoration: none;
      box-shadow: 0 8px 20px rgba(15, 23, 42, .06);
      white-space: nowrap;
    }

    .supplier-actions-toggle {
      position: fixed;
      left: 14px;
      top: 96px;
      z-index: 1200;
      display: inline-flex;
      align-items: center;
      gap: 8px;
      min-height: 42px;
      padding: 0 14px;
      border: 1px solid #bfd5ee;
      border-radius: 12px;
      background: #ffffff;
      color: #172033;
      font-weight: 900;
      box-shadow: 0 12px 28px rgba(15, 23, 42, .16);
      cursor: pointer;
    }

    .supplier-actions-toggle:hover {
      border-color: #93c5fd;
      background: #f8fbff;
    }

    .supplier-actions-toggle-icon {
      font-size: 18px;
      line-height: 1;
    }

    .supplier-actions-backdrop {
      position: fixed;
      inset: 0;
      z-index: 1290;
      background: rgba(15, 23, 42, .42);
      backdrop-filter: blur(2px);
    }

    .supplier-actions-backdrop[hidden] {
      display: none;
    }

    .supplier-actions-drawer {
      position: fixed;
      top: 0;
      left: 0;
      bottom: 0;
      z-index: 1300;
      width: min(560px, calc(100vw - 24px));
      overflow-y: auto;
      overscroll-behavior: contain;
      background: #f8fbff;
      border-right: 1px solid #cbdced;
      box-shadow: 24px 0 48px rgba(15, 23, 42, .24);
      transform: translateX(calc(-100% - 24px));
      transition: transform .22s ease;
    }

    body.supplier-products-v2-actions .supplier-actions-toggle {
      position: static;
      min-height: 34px;
      padding: 0 12px;
      border-radius: 10px;
      box-shadow: 0 8px 20px rgba(15, 23, 42, .08);
    }

    body.supplier-actions-open .supplier-actions-drawer {
      transform: translateX(0);
    }

    .supplier-actions-drawer-head {
      position: sticky;
      top: 0;
      z-index: 2;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 14px;
      padding: 16px 18px;
      border-bottom: 1px solid #d8e4ef;
      background: #ffffff;
      box-shadow: 0 8px 20px rgba(15, 23, 42, .05);
    }

    .supplier-actions-drawer-head span {
      display: block;
      color: #64748b;
      font-size: 11px;
      font-weight: 900;
      letter-spacing: .08em;
      text-transform: uppercase;
    }

    .supplier-actions-drawer-head strong {
      display: block;
      margin-top: 2px;
      color: #0f172a;
      font-size: 18px;
      line-height: 1.2;
    }

    .supplier-actions-close {
      width: 36px;
      height: 36px;
      display: grid;
      place-items: center;
      border: 1px solid #d8e4ef;
      border-radius: 10px;
      background: #fff;
      color: #334155;
      font-size: 22px;
      line-height: 1;
      cursor: pointer;
    }

    .supplier-actions-close:hover {
      border-color: #fca5a5;
      color: #b91c1c;
      background: #fff7f7;
    }

    body.supplier-products-v2-actions .supplier-workspace {
      gap: 12px;
      margin: 0;
      padding: 14px;
    }

    body.supplier-products-v2-actions .supplier-workspace-tabs {
      position: sticky;
      top: 70px;
      z-index: 1;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 8px;
