    .supplier-import-card {
      display: grid;
      gap: 14px;
    }

    .supplier-import-source-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 10px;
    }

    .supplier-import-source {
      display: grid;
      grid-template-columns: auto 1fr;
      gap: 8px;
      align-items: flex-start;
      border: 1px solid #d7e4f5;
      border-radius: 10px;
      padding: 10px;
      background: #fff;
      cursor: pointer;
    }

    .supplier-import-source input {
      margin-top: 3px;
    }

    .supplier-import-source-title {
      display: block;
      color: #172033;
      font-weight: 800;
      font-size: 13px;
      line-height: 1.25;
    }

    .supplier-import-source-meta {
      display: block;
      margin-top: 4px;
      color: var(--muted);
      font-size: 11px;
      line-height: 1.35;
      word-break: break-word;
    }

    .supplier-import-source:has(input:checked) {
      border-color: #60a5fa;
      background: #eff6ff;
      box-shadow: 0 0 0 2px rgba(96, 165, 250, .18);
    }

    .supplier-import-source-panel {
      display: none;
      gap: 8px;
    }

    .supplier-import-source-panel.is-active {
      display: grid;
    }

    .supplier-import-result {
      border: 1px solid #bbf7d0;
      border-radius: 12px;
      background: #f0fdf4;
      padding: 12px;
      display: grid;
      gap: 8px;
      color: #14532d;
      font-size: 13px;
    }

    .supplier-import-result--error {
      border-color: #fecaca;
      background: #fef2f2;
      color: #991b1b;
    }

    .supplier-import-result-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
      gap: 8px;
    }

    .supplier-import-result-item {
      display: grid;
      gap: 2px;
    }

    .supplier-import-result-item span {
      color: var(--muted);
      font-size: 11px;
    }

    .supplier-import-result-item b {
      color: inherit;
      font-size: 13px;
      word-break: break-word;
    }

    .supplier-import-settings {
      display: grid;
      gap: 14px;
      border: 1px solid #d7e4f5;
      border-radius: 12px;
      background: #fbfdff;
      padding: 14px;
    }

    .supplier-import-settings-title {
      margin: 0;
      color: #172033;
      font-size: 15px;
      font-weight: 800;
      line-height: 1.25;
    }

    .supplier-import-settings-layout {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 22px;
      align-items: start;
    }

    .supplier-import-settings-column {
      min-width: 0;
    }

    .supplier-import-settings-column--main,
    .supplier-import-dependent,
    .supplier-import-fields-group {
      display: grid;
      gap: 10px;
    }

    .supplier-import-settings-column--aside {
      min-height: 100%;
      border-left: 1px solid #e4edf8;
      padding-left: 18px;
    }

    .supplier-import-row {
      display: grid;
      grid-template-columns: 120px minmax(0, 1fr);
      gap: 12px;
      align-items: center;
      min-width: 0;
    }

    .supplier-import-row-label {
      color: #334155;
      font-size: 12px;
      font-weight: 800;
      line-height: 1.2;
    }

    .supplier-import-row-label--blank {
      visibility: hidden;
    }

    .supplier-import-row-label.selectedCountBadge {
      color: #64748b;
      white-space: nowrap;
    }

    .supplier-import-control {
      display: grid;
      min-width: 0;
      width: 100%;
    }

    .supplier-import-dependent.is-disabled {
      opacity: .48;
    }

    .supplier-import-fields-group {
      margin-top: 8px;
      padding-top: 18px;
      border-top: 2px solid #c8d8eb;
    }

    .supplier-import-segmented {
      --steps: 3;
      display: grid;
      grid-template-columns: repeat(var(--steps), minmax(0, 1fr));
      gap: 4px;
      width: 100%;
      min-height: 48px;
      border: 1px solid #d7e4f5;
      border-radius: 10px;
      background: #f8fafc;
      padding: 4px;
      box-shadow: 0 5px 14px rgba(15, 23, 42, .035);
    }

    .supplier-import-segmented-option {
      position: relative;
      display: grid;
      place-items: center;
      min-width: 0;
      border-radius: 8px;
      border: 1px solid transparent;
      padding: 7px 8px;
      color: #50627c;
      font-size: 12px;
      font-weight: 800;
      line-height: 1.15;
      text-align: center;
      cursor: pointer;
    }

    .supplier-import-segmented-option input {
      position: absolute;
      width: 1px;
      height: 1px;
      opacity: 0;
      pointer-events: none;
    }

    .supplier-import-segmented-option:has(input:checked) {
      color: #172033;
      background: #fff;
      box-shadow: 0 3px 10px rgba(15, 23, 42, .10);
    }

    .supplier-import-segmented-option:nth-child(1):has(input:checked) {
      color: #14532d;
      background: #dcfce7;
      border-color: #86efac;
      box-shadow: 0 4px 12px rgba(34, 197, 94, .16);
    }

    .supplier-import-segmented-option:nth-child(2):has(input:checked) {
      color: #713f12;
      background: #fef3c7;
      border-color: #fde68a;
      box-shadow: 0 4px 12px rgba(234, 179, 8, .16);
    }

    .supplier-import-segmented-option:nth-child(3):has(input:checked) {
      color: #7c2d12;
      background: #ffedd5;
      border-color: #fed7aa;
      box-shadow: 0 4px 12px rgba(249, 115, 22, .15);
    }

    .supplier-import-segmented-option:last-child:has(input:checked) {
      color: #7f1d1d;
      background: #fee2e2;
      border-color: #fecaca;
      box-shadow: 0 4px 12px rgba(239, 68, 68, .15);
    }

    .supplier-import-segmented--mode {
      border-color: #bfdbfe;
      background: #eaf2ff;
    }

    .supplier-import-segmented--scope {
      border-color: #bbf7d0;
      background: #ecfdf5;
    }

    .supplier-import-dependent.is-disabled .supplier-import-segmented-option {
      cursor: default;
    }

    .supplier-import-actions {
      display: flex;
      justify-content: center;
      padding-top: 8px;
    }

    .supplier-import-submit {
      min-width: 220px;
      min-height: 48px;
      border-radius: 12px;
      font-size: 15px;
    }

    .supplier-import-quick-actions {
      display: grid;
      gap: 16px;
      align-content: start;
    }

    .supplier-import-quick-scope {
      min-height: 40px;
    }

    .supplier-import-side-row {
      display: grid;
      grid-template-columns: minmax(0, 1fr) minmax(145px, .82fr);
      gap: 12px;
      align-items: center;
      min-width: 0;
    }

    .supplier-import-side-button {
      width: 100%;
      min-height: 40px;
      border-radius: 10px;
      padding: 0 12px;
      font-size: 12px;
      font-weight: 800;
      text-align: center;
    }

    .supplier-import-mini-toggle {
      display: flex;
      align-items: center;
      gap: 9px;
      color: #475569;
      font-size: 11px;
      font-weight: 700;
      line-height: 1.25;
      cursor: pointer;
      user-select: none;
      max-width: 160px;
    }

    .supplier-import-side-spacer {
      min-height: 1px;
    }

    .supplier-import-danger-zone {
      display: grid;
      gap: 12px;
      margin-top: 6px;
      padding-top: 16px;
      border-top: 1px solid #d7e4f5;
    }

    .supplier-import-danger-row {
      display: grid;
      grid-template-columns: 38px minmax(0, 1fr);
      gap: 10px;
      align-items: center;
      min-width: 0;
    }

    .supplier-import-arm {
      display: grid;
      place-items: center;
      cursor: pointer;
    }

    .supplier-import-arm input {
      position: absolute;
      width: 1px;
      height: 1px;
      opacity: 0;
      pointer-events: none;
    }

    .supplier-import-arm-track {
      position: relative;
      width: 34px;
      height: 20px;
      border: 1px solid #cbd5e1;
      border-radius: 999px;
      background: #f1f5f9;
      transition: background .16s ease, border-color .16s ease;
    }

    .supplier-import-arm-track::after {
      content: "";
      position: absolute;
      top: 2px;
      left: 2px;
      width: 14px;
      height: 14px;
      border-radius: 50%;
      background: #94a3b8;
      transition: transform .16s ease, background .16s ease;
    }

    .supplier-import-arm input:checked + .supplier-import-arm-track {
      border-color: #fecaca;
      background: #fee2e2;
    }

    .supplier-import-arm input:checked + .supplier-import-arm-track::after {
      transform: translateX(14px);
      background: #dc2626;
    }

    .supplier-import-side-button:disabled {
      cursor: not-allowed;
      opacity: .48;
      box-shadow: none;
    }

    .supplier-import-mini-toggle input {
      position: absolute;
      width: 1px;
      height: 1px;
      opacity: 0;
      pointer-events: none;
    }

    .supplier-import-mini-toggle-track {
      position: relative;
      flex: 0 0 34px;
      width: 34px;
      height: 20px;
      border: 1px solid #cbd5e1;
      border-radius: 999px;
      background: #f1f5f9;
      transition: background .16s ease, border-color .16s ease;
    }

    .supplier-import-mini-toggle-track::after {
      content: "";
      position: absolute;
      top: 2px;
      left: 2px;
      width: 14px;
      height: 14px;
      border-radius: 50%;
      background: #94a3b8;
      transition: transform .16s ease, background .16s ease;
    }

    .supplier-import-mini-toggle input:checked + .supplier-import-mini-toggle-track {
      border-color: #86efac;
      background: #dcfce7;
    }

    .supplier-import-mini-toggle input:checked + .supplier-import-mini-toggle-track::after {
      transform: translateX(14px);
      background: #16a34a;
    }

    .supplier-repair-modal[hidden] {
      display: none;
    }

    .supplier-repair-modal {
      position: fixed;
      inset: 0;
      z-index: 1000;
      display: grid;
      place-items: center;
      padding: 18px;
      background: rgba(15, 23, 42, .28);
    }

    .supplier-repair-modal-card {
      width: min(460px, 100%);
      border: 1px solid #d7e4f5;
      border-radius: 14px;
      background: #fff;
      box-shadow: 0 24px 60px rgba(15, 23, 42, .24);
      padding: 18px;
      display: grid;
      gap: 12px;
    }

    .supplier-repair-modal-card--wide {
      width: min(760px, 100%);
      max-height: min(92vh, 820px);
      overflow: auto;
    }

    .supplier-repair-modal-title {
      margin: 0;
      color: #172033;
      font-size: 17px;
      font-weight: 900;
    }

    .supplier-repair-modal-text {
      margin: 0;
      color: #475569;
      font-size: 13px;
      line-height: 1.45;
    }

    .supplier-brand-list-textarea {
      width: 100%;
      min-height: 220px;
      resize: vertical;
      border: 1px solid #cfe0f5;
      border-radius: 12px;
      padding: 12px;
      color: #172033;
      font: 700 14px/1.45 inherit;
      outline: none;
      background: #f8fbff;
    }

    .supplier-brand-list-textarea:focus {
      border-color: #60a5fa;
      box-shadow: 0 0 0 3px rgba(96, 165, 250, .18);
      background: #fff;
    }

    .supplier-brand-list-note {
      color: #64748b;
      font-size: 12px;
      line-height: 1.4;
    }

    .supplier-repair-progress {
      height: 12px;
      overflow: hidden;
      border: 1px solid #bfdbfe;
      border-radius: 999px;
      background: #eff6ff;
    }

    .supplier-repair-progress > span {
      display: block;
      width: 0%;
      height: 100%;
      border-radius: inherit;
      background: linear-gradient(90deg, #60a5fa, #16a34a);
      transition: width .18s ease;
    }

    .supplier-repair-modal-actions {
      display: flex;
      justify-content: flex-end;
      gap: 8px;
    }

    .supplier-bundle-form {
      display: grid;
      gap: 12px;
    }

    .supplier-bundle-form label {
      display: grid;
      gap: 5px;
      color: #334155;
      font-size: 12px;
      font-weight: 800;
    }

    .supplier-bundle-form .supplier-import-segmented-option {
      display: grid;
      place-items: center;
      gap: 0;
      font-size: 12px;
    }

    .supplier-bundle-form input:not([type="checkbox"]):not([type="radio"]) {
      min-width: 0;
      width: 100%;
      border: 1px solid #cfe0f6;
      border-radius: 10px;
      background: #fff;
      color: #172033;
      font: inherit;
      font-size: 14px;
      font-weight: 700;
      line-height: 1.2;
      padding: 10px 12px;
      outline: none;
    }

    .supplier-bundle-form input:not([type="checkbox"]):not([type="radio"]):focus {
      border-color: #60a5fa;
      box-shadow: 0 0 0 3px rgba(96, 165, 250, .18);
    }

    .supplier-bundle-checkbox {
      display: flex !important;
      grid-template-columns: none !important;
      align-items: center;
      gap: 8px !important;
      padding: 8px 10px;
      border: 1px solid #cfe0f6;
      border-radius: 10px;
      background: #f8fbff;
    }

    .supplier-bundle-checkbox input {
      width: 16px;
      height: 16px;
      flex: 0 0 auto;
      accent-color: #2563eb;
    }

    .supplier-bundle-size-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 8px;
    }

    .supplier-bundle-preview {
      border: 1px solid #fed7aa;
      border-radius: 10px;
      background: #fff7ed;
      color: #9a3412;
      font-size: 12px;
      font-weight: 800;
      line-height: 1.35;
      padding: 9px 10px;
      overflow-wrap: anywhere;
    }

    .supplier-bundle-error {
      color: #b91c1c;
      font-size: 12px;
      font-weight: 800;
      min-height: 16px;
    }

    .supplier-bundle-checkbox--compact {
      padding: 7px 9px;
    }

    .supplier-bulk-bundle-card {
      min-width: 0;
      display: grid;
      gap: 10px;
      padding: 14px;
      border: 1px solid #dbeafe;
      border-radius: 14px;
      background: #fff;
    }

    .supplier-bulk-bundle-head,
    .supplier-bulk-bundle-modal-head {
      display: grid;
      grid-template-columns: auto minmax(0, 1fr);
      align-items: center;
      gap: 10px;
    }

    .supplier-bulk-bundle-title,
    .supplier-bulk-bundle-section-title {
      color: #172033;
      font-size: 13px;
      font-weight: 900;
    }

    .supplier-bulk-bundle-caption {
      margin-top: 2px;
      color: #64748b;
      font-size: 12px;
      line-height: 1.35;
    }

    .supplier-bulk-bundle-open {
      justify-self: start;
    }

    .supplier-bulk-bundle-form {
      gap: 14px;
    }

    .supplier-bulk-bundle-section {
      display: grid;
      gap: 8px;
      padding: 10px;
      border: 1px solid #e4edf8;
      border-radius: 12px;
      background: #f8fbff;
    }

    .supplier-bulk-bundle-section--grid {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .supplier-bulk-bundle-section--grid > div {
      min-width: 0;
      display: grid;
      gap: 8px;
      align-content: start;
    }

    .supplier-bulk-bundle-radio {
      display: flex !important;
      grid-template-columns: none !important;
      align-items: center;
      gap: 7px !important;
      color: #334155;
      font-size: 12px;
      font-weight: 800;
    }

    .supplier-bulk-bundle-radio input {
      width: 14px;
      height: 14px;
      accent-color: #2563eb;
    }

    .supplier-confirm-list {
      margin: 0;
      padding-left: 18px;
      color: #334155;
      font-size: 13px;
      line-height: 1.45;
    }

    @media (max-width: 860px) {
      .supplier-import-settings-layout {
        grid-template-columns: 1fr;
      }

      .supplier-import-settings-column--aside {
        border-left: 0;
        border-top: 1px solid #e4edf8;
        padding-left: 0;
        padding-top: 14px;
      }

      .supplier-bulk-bundle-section--grid,
      .supplier-bulk-bundle-modal-head {
        grid-template-columns: 1fr;
      }

      .supplier-import-row {
        grid-template-columns: 1fr;
        gap: 6px;
      }

      .supplier-import-row-label--blank {
        display: none;
      }

      .supplier-content-runbar {
        align-items: stretch;
      }

      .supplier-content-scope {
        align-items: stretch;
        flex-direction: column;
      }

	      .supplier-bulk-category-block {
	        grid-template-columns: 1fr;
	      }

	      .supplier-edit-layout {
	        grid-template-columns: 1fr;
	      }

	      .supplier-bulk-replace-row {
	        grid-template-columns: 1fr;
	      }

	      .supplier-bulk-copy-grid,
	      .supplier-bulk-copy-head {
	        grid-template-columns: 1fr;
	      }

      .supplier-bulk-category-actions {
        align-items: stretch;
        flex-direction: column;
      }

      .supplier-bulk-category-button {
        width: 100%;
      }

      .supplier-content-layout {
        grid-template-columns: 1fr;
      }

      .supplier-content-panel--aside {
        border-left: 0;
        border-top: 1px solid #e4edf8;
        padding-left: 0;
        padding-top: 14px;
      }

      .supplier-content-action {
        align-items: stretch;
        flex-direction: column;
      }

      .supplier-content-action-form {
        flex-basis: auto;
        width: 100%;
      }
    }

    .dataset-marketplace-hint {
      margin-top: 8px;
      color: var(--muted);
      font-size: 12px;
    }

    .dataset-actions {
      display: flex;
      gap: 10px;
      align-items: center;
      flex-wrap: wrap;
      margin-top: 14px;
    }

    .dataset-actions a,
    .dataset-actions button {
      min-height: 36px;
    }

    .section-block {
      border: 1px solid var(--border);
      border-radius: 14px;
      background: var(--surface-soft);
      padding: 14px;
      margin-bottom: 12px;
    }

    .section-head {
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      gap: 12px;
      flex-wrap: wrap;
      margin-bottom: 12px;
    }

    .section-title {
      font-size: 15px;
      font-weight: 700;
      margin: 0;
      color: var(--text);
    }

    .section-subtitle {
      font-size: 12px;
      color: var(--muted);
      line-height: 1.45;
      margin: 4px 0 0;
    }

    .field {
      display: flex;
      flex-direction: column;
      gap: 6px;
      font-size: 12px;
      color: #334155;
      min-width: 0;
    }

    .control-input,
    .control-select {
      border: 1px solid var(--border-strong);
      border-radius: 10px;
      padding: 8px 10px;
      font-size: 12px;
      background: #fff;
      color: var(--text);
      min-width: 0;
      transition: border-color .15s ease, box-shadow .15s ease, background .15s ease;
    }

    .control-input:focus,
    .control-select:focus,
    .ddsearch:focus {
      outline: none;
      border-color: #60a5fa;
      box-shadow: 0 0 0 3px rgba(37, 99, 235, .12);
    }

    .control-input--sm {
      width: 110px;
    }

    .control-input--md {
      width: 200px;
    }

    .control-input--wide {
      width: 100%;
      min-width: 280px;
    }

    .count-chip {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 6px 10px;
      border-radius: 999px;
      background: #eef2ff;
      color: #1e3a8a;
      font-size: 12px;
      line-height: 1.2;
      white-space: nowrap;
    }

    .text-button {
      border: 0;
      background: transparent;
      color: #2563eb;
      padding: 0;
      font-size: 12px;
      font-weight: 600;
    }

    .text-button:hover {
      background: transparent;
      color: #1d4ed8;
    }

    .supplier-content-runbar {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 14px;
      flex-wrap: wrap;
      padding: 12px;
      margin-bottom: 14px;
      border: 1px solid #bfdbfe;
      border-radius: 14px;
      background: linear-gradient(180deg, #f8fbff 0%, #eff6ff 100%);
    }

    .supplier-content-scope {
      display: flex;
      align-items: center;
      gap: 10px;
      flex: 1 1 520px;
      min-width: 0;
    }

    .supplier-content-scope .count-chip {
      min-height: 38px;
      font-weight: 700;
    }

    .supplier-content-model {
      flex: 0 0 200px;
    }

	    .supplier-bulk-category-block {
	      display: grid;
	      gap: 12px;
	      align-items: start;
	      padding: 14px;
	      border: 1px solid #dbeafe;
	      border-radius: 14px;
	      background: #f8fbff;
	    }

	    .supplier-edit-layout {
	      display: grid;
	      grid-template-columns: repeat(2, minmax(0, 1fr));
	      gap: 18px;
	      align-items: start;
	    }

	    .supplier-edit-column {
	      min-width: 0;
	      display: grid;
	      gap: 12px;
	      align-content: start;
	    }

	    .supplier-edit-column--empty {
	      min-height: 1px;
	    }

	    .supplier-bulk-replace-card {
	      min-width: 0;
	      position: relative;
	      display: grid;
	      gap: 10px;
	      padding: 14px;
	      border: 1px solid #dbeafe;
	      border-radius: 14px;
	      background: #f8fbff;
	    }

	    .supplier-bulk-copy-card {
	      min-width: 0;
	      display: grid;
	      gap: 12px;
	      padding: 14px;
	      border: 1px solid #dbeafe;
	      border-radius: 14px;
	      background: #f8fbff;
	    }

	    .supplier-bulk-controls-card {
	      min-width: 0;
	      display: grid;
	      gap: 12px;
	      padding: 14px;
	      border: 1px solid #dbeafe;
	      border-radius: 14px;
	      background: #f8fbff;
	    }

	    .supplier-bulk-controls-head {
	      display: grid;
	      grid-template-columns: auto minmax(0, 1fr);
	      gap: 10px;
	      align-items: center;
	    }

	    .supplier-bulk-controls-title {
	      color: #172033;
	      font-size: 16px;
	      font-weight: 900;
	      line-height: 1.2;
	    }

	    .supplier-bulk-controls-caption {
	      margin-top: 2px;
	      color: #64748b;
	      font-size: 13px;
	      line-height: 1.3;
	    }

	    .supplier-bulk-controls-row {
	      display: grid;
	      grid-template-columns: minmax(0, 1fr) auto;
	      gap: 8px;
	      align-items: end;
	      min-width: 0;
	    }

	    .supplier-bulk-controls-field {
	      display: grid;
	      gap: 5px;
