      transform: translateY(10px) scale(.9);
	      pointer-events: none;
	      transition: opacity .18s ease, transform .18s ease;
	    }

	    .supplier-success-toast.is-busy {
	      background: #2563eb;
	      box-shadow: 0 18px 40px rgba(37, 99, 235, .28);
	      color: transparent;
	    }

	    .supplier-success-toast.is-busy::before {
	      content: "";
	      width: 34px;
	      height: 34px;
	      border: 5px solid rgba(255, 255, 255, .34);
	      border-top-color: #fff;
	      border-radius: 50%;
	      animation: supplierToastSpin .82s linear infinite;
	    }

	    .supplier-success-toast.is-visible {
	      opacity: 1;
	      transform: translateY(0) scale(1);
	    }

	    @keyframes supplierToastSpin {
	      to {
	        transform: rotate(360deg);
	      }
	    }

	    .supplier-content-layout {
	      display: grid;
	      grid-template-columns: repeat(2, minmax(0, 1fr));
	      gap: 22px;
	      align-items: start;
	    }

	    .supplier-auto-tools {
	      display: grid;
	      gap: 14px;
	    }

    .supplier-content-panel {
      min-width: 0;
      display: grid;
      gap: 12px;
      align-content: start;
    }

    .supplier-content-panel--aside {
      border-left: 1px solid #e4edf8;
      padding-left: 18px;
    }

    .supplier-content-panel-title {
      color: #172033;
      font-size: 13px;
      font-weight: 800;
      line-height: 1.25;
    }

    .supplier-content-actions-grid {
      display: grid;
      grid-template-columns: 1fr;
      gap: 12px;
      align-content: start;
      align-items: start;
    }

    .supplier-content-action-group {
      display: grid;
      gap: 8px;
      align-content: start;
      align-self: start;
      min-width: 0;
      border: 1px solid #dbe7f5;
      border-radius: 14px;
      background: rgba(248, 251, 255, .78);
      padding: 8px;
    }

    .supplier-content-action-group summary {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      cursor: pointer;
      list-style: none;
      min-width: 0;
      padding: 4px 4px 8px;
      color: #172033;
    }

    .supplier-content-action-group summary::-webkit-details-marker {
      display: none;
    }

    .supplier-content-action-group summary::before {
      content: "";
      flex: 0 0 auto;
      width: 0;
      height: 0;
      border-left: 4px solid transparent;
      border-right: 4px solid transparent;
      border-top: 6px solid #64748b;
      transition: transform .16s ease;
    }

    .supplier-content-action-group:not([open]) summary::before {
      transform: rotate(-90deg);
    }

    .supplier-content-action-group summary > span {
      display: grid;
      gap: 2px;
      min-width: 0;
      margin-right: auto;
    }

    .supplier-content-action-group-title {
      font-size: 13px;
      font-weight: 900;
      line-height: 1.18;
    }

    .supplier-content-action-group-caption {
      color: #64748b;
      font-size: 11px;
      font-weight: 700;
      line-height: 1.25;
    }

    .supplier-content-action-group summary b,
    .supplier-content-op-group-title b {
      display: inline-grid;
      place-items: center;
      min-width: 22px;
      height: 22px;
      border-radius: 999px;
      background: #eaf2ff;
      color: #1d4ed8;
      font-size: 11px;
      font-weight: 900;
    }

    .supplier-content-action-group-body {
      display: grid;
      gap: 8px;
    }

    .supplier-content-action {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 14px;
      min-height: 70px;
      padding: 12px;
      border: 1px solid var(--border);
      border-radius: 12px;
      background: #fff;
      box-shadow: 0 10px 24px rgba(15, 23, 42, .04);
    }

    .supplier-content-action-main {
      flex: 1 1 auto;
      min-width: 0;
    }

    .supplier-content-action-title-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 8px;
      min-width: 0;
    }

    .supplier-content-action--gpt {
      border-color: #bfdbfe;
      background: linear-gradient(180deg, #ffffff 0%, #eff6ff 100%);
    }

    .supplier-content-action--data {
      border-color: #bbf7d0;
      background: linear-gradient(180deg, #ffffff 0%, #f0fdf4 100%);
    }

    .supplier-content-action-title {
      display: block;
      font-size: 15px;
      font-weight: 700;
      color: var(--text);
      line-height: 1.2;
    }

    .supplier-content-action-caption {
      display: block;
      margin-top: 3px;
      color: var(--muted);
      font-size: 12px;
      line-height: 1.35;
    }

    .supplier-content-action-report-link {
      display: inline-flex;
      align-items: center;
      margin-top: 7px;
      color: #166534;
      font-size: 12px;
      font-weight: 800;
      text-decoration: underline;
      text-underline-offset: 2px;
    }

    .supplier-content-action-form {
      flex: 0 0 150px;
      display: grid;
      gap: 8px;
    }

    .supplier-content-action--photo-scope .supplier-content-action-form {
      flex-basis: 210px;
    }

    .supplier-content-action--tnved-overwrite .supplier-content-action-form {
      flex-basis: 230px;
    }

    .supplier-content-action-form button {
      width: 100%;
      min-height: 38px;
    }

    .supplier-content-overwrite-toggle {
      display: flex;
      align-items: center;
      gap: 8px;
      min-height: 34px;
      color: #475569;
      font-size: 11px;
      font-weight: 700;
      line-height: 1.25;
      cursor: pointer;
      user-select: none;
    }

    .supplier-content-overwrite-toggle input {
      position: absolute;
      width: 1px;
      height: 1px;
      opacity: 0;
      pointer-events: none;
    }

    .supplier-content-overwrite-toggle-track {
      position: relative;
      flex: 0 0 34px;
      width: 34px;
      height: 20px;
      border: 1px solid #cbd5e1;
      border-radius: 999px;
      background: #f1f5f9;
      transition: background .16s ease, border-color .16s ease;
    }

    .supplier-content-overwrite-toggle-track::after {
      content: "";
      position: absolute;
      top: 2px;
      left: 2px;
      width: 14px;
      height: 14px;
      border-radius: 50%;
      background: #94a3b8;
      transition: transform .16s ease, background .16s ease;
    }

    .supplier-content-overwrite-toggle input:checked + .supplier-content-overwrite-toggle-track {
      border-color: #86efac;
      background: #dcfce7;
    }

    .supplier-content-overwrite-toggle input:checked + .supplier-content-overwrite-toggle-track::after {
      transform: translateX(14px);
      background: #16a34a;
    }

    .supplier-content-photo-scope {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 4px;
      min-height: 34px;
      padding: 3px;
      border: 1px solid #bfdbfe;
      border-radius: 10px;
      background: rgba(255, 255, 255, .88);
    }

    .supplier-content-photo-scope label {
      position: relative;
      display: block;
      min-width: 0;
      cursor: pointer;
    }

    .supplier-content-photo-scope input {
      position: absolute;
      inset: 0;
      opacity: 0;
      pointer-events: none;
    }

    .supplier-content-photo-scope span {
      display: grid;
      place-items: center;
      min-height: 28px;
      padding: 4px 6px;
      border-radius: 8px;
      color: #64748b;
      font-size: 10px;
      font-weight: 800;
      line-height: 1.1;
      text-align: center;
      overflow-wrap: anywhere;
      transition: background .16s ease, color .16s ease, box-shadow .16s ease;
    }

    .supplier-content-photo-scope label:has(input:checked) span {
      background: #dcfce7;
      color: #166534;
      box-shadow: inset 0 0 0 1px #86efac;
    }

    .supplier-content-model-select {
      width: 112px;
      max-width: 112px;
      min-height: 28px;
      border-radius: 10px;
      border: 1px solid #bfdbfe;
      background: #fff;
      color: #172033;
      font-size: 11px;
      font-weight: 700;
      padding: 4px 24px 4px 8px;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .supplier-content-op-model {
      grid-column: 3;
      grid-row: 1;
      align-self: center;
      margin-top: 0;
    }

    .supplier-content-title-model {
      flex: 0 0 112px;
    }

    .supplier-brand-category-card {
      display: grid;
      gap: 10px;
      padding: 12px;
      border: 1px solid #dbeafe;
      border-radius: 12px;
      background: #f8fbff;
    }

    .supplier-brand-category-sync-grid {
      display: grid;
      gap: 10px;
    }

    .supplier-brand-category-form {
      display: grid;
      grid-template-columns: minmax(0, 1fr) 130px;
      gap: 8px;
      align-items: start;
    }

    .supplier-brand-category-picker {
      position: relative;
      min-width: 0;
    }

    .supplier-brand-category-picker .supplier-bulk-category-button {
      width: 100%;
      min-height: 38px;
      text-align: left;
      justify-content: flex-start;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .supplier-brand-category-form .btn-secondary {
      min-height: 38px;
    }

    .supplier-brand-category-actions {
      position: sticky;
      top: 0;
      z-index: 2;
      display: flex;
      gap: 8px;
      padding: 6px 0 10px;
      margin-bottom: 4px;
      border-bottom: 1px solid #e5e7eb;
      background: #fff;
    }

    .supplier-brand-category-action {
      padding: 7px 10px;
      border: 1px solid #bfdbfe;
      border-radius: 10px;
      background: #eff6ff;
      color: #1d4ed8;
      font-size: 12px;
      font-weight: 800;
    }

    .supplier-brand-category-action.secondary {
      background: #fff;
      color: var(--muted);
    }

    .supplier-brand-category-option {
      width: 100%;
      display: grid;
      grid-template-columns: 18px minmax(0, 1fr);
      gap: 8px;
      align-items: start;
      padding: 8px 10px;
      border: 0;
      border-radius: 10px;
      background: transparent;
      color: var(--text);
      text-align: left;
      cursor: pointer;
      font: inherit;
    }

    .supplier-brand-category-option:hover {
      background: #eef6ff;
    }

    .supplier-brand-category-option.is-selected {
      background: #ecfdf5;
      box-shadow: inset 0 0 0 1px #86efac;
    }

    .supplier-brand-category-option input {
      margin-top: 2px;
      width: 16px;
      height: 16px;
      accent-color: #16a34a;
    }

    .supplier-brand-category-option-title {
      display: block;
      font-size: 13px;
      font-weight: 700;
      line-height: 1.25;
    }

    .supplier-brand-category-option-meta {
      display: block;
      margin-top: 2px;
      color: var(--muted);
      font-size: 11px;
      line-height: 1.25;
    }

    .supplier-content-op-list {
      display: grid;
      gap: 8px;
    }

    .supplier-content-op-group-title {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 8px;
      margin-top: 6px;
      padding: 6px 2px 2px;
      color: #64748b;
      font-size: 11px;
      font-weight: 900;
      line-height: 1.2;
      text-transform: uppercase;
      letter-spacing: .06em;
    }

    .supplier-content-op-check--all + .supplier-content-op-group-title {
      margin-top: 0;
    }

    .supplier-content-op-check {
      display: grid;
      grid-template-columns: 20px minmax(0, 1fr) auto;
      gap: 8px;
      align-items: start;
      padding: 10px;
      border: 1px solid var(--border);
      border-radius: 12px;
      background: #fff;
      cursor: pointer;
    }

    .supplier-content-op-check:has(input[data-content-pipeline-op]:checked),
    .supplier-content-op-check--all:has(input[data-content-pipeline-select-all]:checked) {
      border-color: #60a5fa;
      background: #eff6ff;
      box-shadow: 0 0 0 2px rgba(96, 165, 250, .14);
    }

    .supplier-content-op-check input[data-content-pipeline-op],
    .supplier-content-op-check input[data-content-pipeline-select-all] {
      margin-top: 2px;
    }

    .supplier-content-op-choice {
      display: contents;
      cursor: pointer;
    }

    .supplier-content-op-check--all {
      border-style: dashed;
      background: #f8fafc;
    }

    .supplier-content-op-check--all .supplier-content-action-title {
      font-size: 14px;
    }

    .supplier-content-op-check--all {
      grid-template-columns: 20px minmax(0, 1fr);
    }

    .supplier-content-pipeline-photo-scope {
      grid-column: 2 / -1;
      justify-self: end;
      width: min(210px, 100%);
    }

    .supplier-content-pipeline-hint {
      min-height: 16px;
      color: #b91c1c;
      font-size: 11px;
    }

    .inline-toggle-card {
      border: 1px dashed var(--border-strong);
      border-radius: 12px;
      background: #fff;
      overflow: visible;
    }

    .inline-toggle-card summary {
      list-style: none;
      cursor: pointer;
      padding: 10px 12px;
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      gap: 12px;
    }

    .inline-toggle-card summary::-webkit-details-marker {
      display: none;
    }

    .inline-toggle-card[open] > .param-filters-host,
    .inline-toggle-card[open] > .inline-toggle-body {
      border-top: 1px solid #f3f4f6;
    }

    .offers-toolbar {
      display: grid;
      gap: 12px;
      margin: 8px 0 14px;
    }

    .toolbar-grid {
      display: grid;
      gap: 12px;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    }

    .toolbar-card {
      border: 1px solid var(--border);
      border-radius: 16px;
      background: linear-gradient(180deg, #fff 0%, #fbfdff 100%);
      padding: 16px;
      min-width: 0;
      box-shadow: 0 10px 24px rgba(15, 23, 42, .045);
    }

    .toolbar-card--wide {
      grid-column: 1 / -1;
    }

    .toolbar-card--action {
      border-color: #d6e4ff;
      background:
        radial-gradient(circle at top right, rgba(37, 99, 235, .08), transparent 28%),
        linear-gradient(180deg, #ffffff 0%, #f8fbff 100%);
    }

    .toolbar-card--filters {
      border-color: #d9e7de;
      background:
        radial-gradient(circle at top left, rgba(15, 118, 110, .07), transparent 24%),
        linear-gradient(180deg, #ffffff 0%, #fbfefd 100%);
    }

    .toolbar-card--export {
      border-color: #d7e2ff;
      background:
        radial-gradient(circle at top right, rgba(37, 99, 235, .10), transparent 26%),
        linear-gradient(180deg, #ffffff 0%, #f7faff 100%);
      box-shadow: 0 14px 32px rgba(37, 99, 235, .08);
    }

    .toolbar-header {
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      gap: 12px;
      flex-wrap: wrap;
      margin-bottom: 12px;
    }

    .toolbar-title {
      font-size: 14px;
      font-weight: 700;
      color: var(--text);
      margin: 0;
    }

    .toolbar-subtitle {
      font-size: 12px;
      color: var(--muted);
      line-height: 1.45;
      margin-top: 4px;
    }

    .toolbar-row {
      display: flex;
      gap: 10px;
      align-items: center;
      flex-wrap: wrap;
    }

    .toolbar-row--search {
      align-items: flex-end;
      display: grid;
      grid-template-columns: minmax(260px, 1fr) auto;
      width: 100%;
    }

    .toolbar-row--assign {
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto;
      align-items: center;
      width: 100%;
    }

    .toolbar-row + .toolbar-row {
      margin-top: 10px;
    }

    .marketplace-assign-grid {
      display: grid;
      gap: 12px;
      grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    }

    .marketplace-assign-panel {
      border: 1px solid var(--border);
      border-radius: 14px;
      background: #fff;
      padding: 14px;
      min-width: 0;
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, .8);
    }

    .marketplace-assign-panel:nth-child(1) {
      border-left: 4px solid var(--accent);
    }

    .marketplace-assign-panel:nth-child(2) {
      border-left: 4px solid var(--success);
    }

    .marketplace-assign-panel .toolbar-title {
      font-size: 13px;
    }

    .marketplace-assign-panel .toolbar-subtitle {
      margin-top: 2px;
      min-height: 34px;
    }

    .supplier-api-push-fields {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(132px, 1fr));
      gap: 8px;
      margin: 12px 0;
    }

    .supplier-api-push-field {
      display: flex;
      align-items: center;
      gap: 8px;
      min-height: 34px;
      padding: 7px 9px;
      border: 1px solid #dbeafe;
      border-radius: 10px;
      background: #f8fbff;
      color: #172033;
      font-size: 13px;
      font-weight: 700;
      cursor: pointer;
      user-select: none;
    }

    .supplier-api-push-field input {
      width: 16px;
      height: 16px;
      accent-color: var(--accent);
    }

    .supplier-api-push-panel[data-marketplace="wb"] .supplier-api-push-field input {
      accent-color: var(--success);
    }

    .supplier-api-push-note {
      color: var(--muted);
      font-size: 12px;
      line-height: 1.35;
      margin-top: 8px;
    }

    .supplier-api-push-selected {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 34px;
      margin: 0 0 12px;
      font-weight: 800;
    }

    .assign-picker {
      flex: 1 1 260px;
      min-width: 0;
    }

    .assign-picker .dd {
      display: block;
      width: 100%;
      min-width: 0;
    }

    .assign-picker .ddbtn {
      display: flex;
      width: 100%;
      max-width: none;
      min-width: 0;
      box-sizing: border-box;
    }

    .toolbar-row--assign .toolbar-actions {
      justify-content: flex-end;
      align-self: stretch;
    }

    .toolbar-actions {
      display: flex;
      gap: 8px;
      align-items: center;
      flex-wrap: wrap;
    }

    .toolbar-actions > button {
      min-height: 38px;
    }

    .toolbar-actions--right {
      margin-left: auto;
      justify-content: flex-end;
      min-width: max-content;
    }

    .filter-sync-status {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      width: 30px;
      height: 30px;
      border: 1px solid #dbe7f5;
      border-radius: 999px;
      padding: 0;
      font-size: 11px;
      font-weight: 800;
      line-height: 1;
      color: #64748b;
      background: #fff;
      white-space: nowrap;
    }

    .filter-sync-status [data-filter-status-text] {
      position: absolute;
      width: 1px;
      height: 1px;
      overflow: hidden;
      clip: rect(0 0 0 0);
      white-space: nowrap;
    }

    .filter-sync-dot {
      width: 9px;
      height: 9px;
      border-radius: 999px;
      background: #94a3b8;
      box-shadow: 0 0 0 2px rgba(148, 163, 184, 0.14);
    }

    .filter-sync-status.is-applied {
      color: #166534;
      border-color: #bbf7d0;
      background: #f0fdf4;
    }

    .filter-sync-status.is-applied .filter-sync-dot {
      background: #22c55e;
      box-shadow: 0 0 0 2px rgba(34, 197, 94, 0.18), 0 0 8px rgba(34, 197, 94, 0.45);
    }

    .filter-sync-status.is-pending {
      color: #92400e;
      border-color: #fde68a;
      background: #fffbeb;
    }

    .filter-sync-status.is-pending .filter-sync-dot {
      background: #f59e0b;
      box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.18);
    }

    .filter-sync-status.is-loading {
      color: #1d4ed8;
      border-color: #bfdbfe;
      background: #eff6ff;
    }

    .filter-sync-status.is-loading .filter-sync-dot {
      width: 10px;
      height: 10px;
      background: transparent;
      border: 2px solid #bfdbfe;
      border-top-color: #2563eb;
      box-shadow: none;
      animation: filterSyncSpin 0.7s linear infinite;
    }

    .filter-sync-status.is-error {
      color: #991b1b;
      border-color: #fecaca;
      background: #fef2f2;
    }

    .filter-sync-status.is-error .filter-sync-dot {
      background: #ef4444;
      box-shadow: 0 0 0 2px rgba(239, 68, 68, 0.16);
    }

    @keyframes filterSyncSpin {
      to { transform: rotate(360deg); }
    }

    .search-field {
      flex: 1 1 380px;
      width: 100%;
    }

    .search-field .control-input {
      width: 100%;
    }

    .range-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(330px, max-content));
      gap: 10px;
      width: auto;
      max-width: 100%;
      align-items: center;
    }

    .range-card {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 8px 10px;
      border: 1px solid var(--border);
      border-radius: 14px;
      background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
      min-width: 0;
    }

    .range-card.is-active {
      border-color: #22c55e;
      background: linear-gradient(180deg, #ecfdf5 0%, #dcfce7 100%);
      box-shadow: 0 0 0 2px rgba(34, 197, 94, .18);
    }

    .range-card-title {
      display: flex;
      gap: 6px;
      align-items: center;
      flex: 0 0 auto;
      min-width: 0;
      font-size: 11px;
      font-weight: 800;
      color: var(--muted);
      text-transform: uppercase;
      letter-spacing: .035em;
      line-height: 1.2;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .range-card-title code {
      display: inline-flex;
      max-width: 112px;
      padding: 1px 6px;
      border-radius: 6px;
      background: #e8eef7;
      color: #64748b;
      font-size: 11px;
      font-weight: 800;
      letter-spacing: .03em;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .range-fields {
      display: flex;
      align-items: center;
      gap: 8px;
      min-width: 0;
    }

    .range-fields .field {
      display: grid;
      grid-template-columns: 18px 112px;
      gap: 6px;
      align-items: center;
      min-width: 0;
      font-size: 11px;
      font-weight: 700;
      color: #475569;
    }

    .range-fields .control-input {
      width: 112px;
      min-width: 0;
      height: 30px;
      padding: 6px 8px;
      border-radius: 9px;
      font-size: 12px;
    }

    .analytics-slider-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(190px, 1fr));
      gap: 10px;
      width: 100%;
      max-width: 100%;
    }

    .analytics-slider-card {
      display: grid;
      gap: 10px;
      min-width: 0;
      padding: 11px 12px 12px;
      border: 1px solid var(--border);
      border-radius: 14px;
      background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
    }

    .analytics-slider-card.is-active {
      border-color: #22c55e;
      background: linear-gradient(180deg, #ecfdf5 0%, #dcfce7 100%);
      box-shadow: 0 0 0 2px rgba(34, 197, 94, .18);
    }

    .analytics-slider-title {
      display: flex;
      justify-content: space-between;
      gap: 8px;
      min-width: 0;
      font-size: 11px;
      font-weight: 900;
      color: var(--muted);
      text-transform: uppercase;
      letter-spacing: .035em;
      line-height: 1.2;
    }

    .analytics-slider-title span:first-child {
      min-width: 0;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .analytics-slider-value {
      flex: 0 0 auto;
      color: #0f172a;
      letter-spacing: 0;
      text-transform: none;
    }

    .analytics-slider-controls {
      display: grid;
      gap: 9px;
    }

    .analytics-slider-range {
      --range-min: 0%;
      --range-max: 100%;
      position: relative;
      height: 26px;
      min-width: 0;
    }

    .analytics-slider-range::before,
    .analytics-slider-range::after {
      content: "";
      position: absolute;
      left: 0;
      right: 0;
      top: 50%;
      height: 6px;
      border-radius: 999px;
      transform: translateY(-50%);
      pointer-events: none;
    }

    .analytics-slider-range::before {
      background: #e5edf7;
      border: 1px solid #cfdaea;
    }

    .analytics-slider-range::after {
      left: var(--range-min);
      right: calc(100% - var(--range-max));
      background: linear-gradient(90deg, #2563eb 0%, #0f8a83 100%);
      box-shadow: 0 1px 5px rgba(37, 99, 235, .18);
    }

    .analytics-slider-range input[type="range"] {
      position: absolute;
      inset: 0;
      width: 100%;
      height: 26px;
      margin: 0;
      background: transparent;
      pointer-events: none;
      appearance: none;
      -webkit-appearance: none;
    }

    .analytics-slider-range input[type="range"]::-webkit-slider-runnable-track {
      height: 6px;
      background: transparent;
      border: 0;
    }

    .analytics-slider-range input[type="range"]::-moz-range-track {
      height: 6px;
      background: transparent;
      border: 0;
    }

    .analytics-slider-range input[type="range"]::-webkit-slider-thumb {
      width: 18px;
      height: 18px;
      margin-top: -6px;
      border-radius: 999px;
      border: 2px solid #ffffff;
      background: #1f2937;
      box-shadow: 0 1px 4px rgba(15, 23, 42, .28), 0 0 0 1px rgba(15, 23, 42, .18);
      cursor: pointer;
      pointer-events: auto;
      appearance: none;
      -webkit-appearance: none;
    }

    .analytics-slider-range input[type="range"]::-moz-range-thumb {
      width: 18px;
      height: 18px;
      border-radius: 999px;
      border: 2px solid #ffffff;
      background: #1f2937;
      box-shadow: 0 1px 4px rgba(15, 23, 42, .28), 0 0 0 1px rgba(15, 23, 42, .18);
      cursor: pointer;
      pointer-events: auto;
    }

    .analytics-slider-inputs {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 8px;
    }

    .analytics-slider-inputs label {
      display: grid;
      grid-template-columns: 22px minmax(0, 1fr);
      gap: 6px;
      align-items: center;
      font-size: 11px;
      font-weight: 800;
      color: #64748b;
    }

    .analytics-slider-inputs input {
      width: 100%;
      min-width: 0;
      height: 30px;
      padding: 6px 8px;
      border: 1px solid #cfe0f7;
      border-radius: 9px;
      background: #fff;
      color: #0f172a;
      font-size: 12px;
      font-weight: 800;
      outline: none;
    }

    .analytics-slider-inputs input:focus {
      border-color: #60a5fa;
      box-shadow: 0 0 0 2px rgba(37, 99, 235, .14);
    }

    @media (max-width: 1200px) {
      .analytics-slider-grid {
        grid-template-columns: repeat(2, minmax(190px, 1fr));
      }
    }

    @media (max-width: 720px) {
      .analytics-slider-grid {
        grid-template-columns: 1fr;
      }
    }

    .checkbox-chip {
      display: inline-flex;
      align-items: flex-start;
      gap: 8px;
      border: 1px solid var(--border);
      border-radius: 12px;
      background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
      padding: 8px 10px;
      font-size: 12px;
      color: #334155;
      line-height: 1.35;
    }

    .checkbox-chip:has(input:checked),
    .checkbox-chip.is-active {
      border-color: #22c55e;
      background: linear-gradient(180deg, #ecfdf5 0%, #dcfce7 100%);
      color: #14532d;
      box-shadow: 0 0 0 2px rgba(34, 197, 94, .18);
    }

    .btn-filter-selected-only {
      min-height: 40px;
      white-space: nowrap;
    }

    .btn-filter-selected-only.is-active {
      border-color: #22c55e;
      background: linear-gradient(180deg, #ecfdf5 0%, #dcfce7 100%);
      color: #14532d;
      box-shadow: 0 0 0 2px rgba(34, 197, 94, .18);
    }

    .readiness-filter-card {
      display: grid;
      gap: 8px;
      width: 100%;
      border: 1px solid #d8e4ef;
      border-radius: 14px;
      background: linear-gradient(180deg, #ffffff 0%, #f8fbff 100%);
