      gap: 8px;
    }

    .readiness-filter-chip {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      cursor: pointer;
      border: 1px solid #dbe7f5;
      border-radius: 999px;
      background: #fff;
      padding: 7px 10px;
      color: #334155;
      font-size: 12px;
      font-weight: 800;
      line-height: 1;
      user-select: none;
    }

    .readiness-filter-chip input {
      position: absolute;
      opacity: 0;
      pointer-events: none;
    }

    .readiness-filter-chip:has(input:checked),
    .readiness-filter-chip.is-active {
      box-shadow: 0 0 0 2px rgba(37, 99, 235, .10);
    }

    .readiness-filter-chip.is-ready {
      border-color: #86efac;
