    .compact-table-bar {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 12px;
      flex-wrap: wrap;
      margin: 0 0 12px;
    }

    .compact-table-actions {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      margin-left: auto;
    }

    .compact-limit-form {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      margin: 0;
