    .supplier-column-settings {
      position: relative;
      display: inline-flex;
    }

    .supplier-column-settings summary {
      list-style: none;
      width: 34px;
      height: 34px;
      display: grid;
      place-items: center;
      border: 1px solid var(--border);
      border-radius: 10px;
      background: #fff;
      color: #334155;
      cursor: pointer;
      font-size: 18px;
      line-height: 1;
      box-shadow: 0 8px 18px rgba(15, 23, 42, .05);
    }

    .supplier-column-settings summary::-webkit-details-marker {
      display: none;
    }

    .supplier-column-settings[open] summary {
      border-color: #93c5fd;
      background: #eff6ff;
      color: #1d4ed8;
    }

    .supplier-column-settings-panel {
      position: absolute;
      top: calc(100% + 8px);
      right: 0;
      z-index: 120;
      width: 230px;
      max-height: 340px;
      overflow: auto;
      display: grid;
      gap: 3px;
      padding: 10px;
      border: 1px solid #dbe7f3;
      border-radius: 12px;
      background: #fff;
      box-shadow: 0 18px 42px rgba(15, 23, 42, .16);
    }

    .supplier-column-settings-item {
      display: flex;
      align-items: center;
      gap: 8px;
      min-width: 0;
      padding: 7px 8px;
      border-radius: 9px;
      color: #172033;
      font-size: 12px;
      line-height: 1.2;
      cursor: pointer;
    }

    .supplier-column-settings-item:hover {
      background: #f1f7ff;
    }

    .supplier-column-settings-item input {
      width: 14px;
      height: 14px;
      accent-color: #2563eb;
      flex: 0 0 auto;
    }

    .supplier-column-settings-item span {
      min-width: 0;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .collapsible-section {
      border: 1px solid var(--border);
      border-radius: 14px;
      background: #fff;
      overflow: visible;
    }

	    .offers-table-wrap {
	      position: relative;
	      overflow: auto;
	      border: 1px solid var(--border);
	      border-radius: 16px;
      background: #fff;
      max-height: clamp(360px, calc(100vh - 240px), 860px);
      min-height: 0;
      overscroll-behavior: contain;
      box-shadow: 0 12px 28px rgba(15, 23, 42, .055);
    }

    [data-offers-table-region] {
      transition: opacity .16s ease;
    }

    [data-offers-table-region].is-loading {
      opacity: .58;
      pointer-events: none;
    }

    .offer-description-preview {
      height: var(--supplier-description-height, auto);
      max-height: var(--supplier-description-max-height, 190px);
      box-sizing: border-box;
      overflow: auto;
      border: 1px solid #eef2f7;
      border-radius: 12px;
      padding: 8px;
      background: #fff;
      color: #1f2937;
      font-size: 8px;
      line-height: 1.35;
      isolation: isolate;
      contain: content;
    }

    .supplier-description-cell {
      height: 1px;
    }

    .supplier-description-cell .supplier-edit-wrap {
      min-height: 0;
      height: 100%;
    }

    .offer-description-preview,
    .offer-description-preview * {
      max-width: 100% !important;
      position: static !important;
      float: none !important;
      transform: none !important;
      animation: none !important;
      transition: none !important;
    }

    .offer-description-preview img,
    .offer-description-preview video,
    .offer-description-preview iframe,
    .offer-description-preview svg {
      display: none !important;
    }

    .offer-description-preview p,
    .offer-description-preview ul,
    .offer-description-preview ol {
      margin: 0 0 8px;
    }

    .offer-description-preview h1,
    .offer-description-preview h2,
    .offer-description-preview h3,
    .offer-description-preview h4 {
      margin: 0 0 8px;
      font-size: 9px;
      line-height: 1.3;
    }

    .supplier-edit-wrap {
      display: grid;
      grid-template-columns: minmax(0, 1fr);
      gap: 4px;
      align-items: start;
    }

    .supplier-same-model {
      display: flex;
      align-items: center;
      gap: 3px;
      margin-top: 4px;
      padding: 0 5px;
      color: #334155;
      font-size: 9px;
      line-height: 1.25;
      overflow-wrap: anywhere;
    }

    .supplier-same-model-delete {
      display: none;
      width: 18px;
      min-height: 20px;
      border: 0;
      border-radius: 7px;
      background: transparent;
      color: #dc2626;
      cursor: pointer;
      font-size: 16px;
      font-weight: 800;
      line-height: 1;
      place-items: center;
      padding: 0;
      flex: 0 0 auto;
    }

    .supplier-same-model.is-editing .supplier-same-model-delete {
      display: inline-grid;
    }

    .supplier-same-model-delete:hover,
    .supplier-same-model-delete:focus {
      background: #fee2e2;
      color: #b91c1c;
      outline: none;
    }

    .supplier-same-model-label {
      color: #334155;
      font-weight: 700;
      flex: 0 0 auto;
    }

    .supplier-same-model-value {
      display: inline;
      min-width: 20px;
      border: 1px solid transparent;
      border-radius: 6px;
      padding: 1px 3px;
      outline: none;
      cursor: text;
      flex: 1 1 auto;
    }

    .supplier-same-model-value:empty::before {
      content: "—";
      color: #94a3b8;
    }

    .supplier-inline-edit {
      min-height: 20px;
      width: 100%;
      box-sizing: border-box;
      white-space: pre-wrap;
      line-height: 1.25;
      border: 1px solid transparent;
      border-radius: 7px;
      padding: 4px 5px;
      background: #f8fafc;
      outline: none;
      cursor: text;
    }

    .supplier-inline-edit:focus,
    .supplier-field-name:focus,
    .supplier-field-value:focus,
    .supplier-same-model-value:focus {
      border-color: #93c5fd;
      background: #fff;
      box-shadow: 0 0 0 2px rgba(147, 197, 253, .24);
    }

    .supplier-inline-edit--rich {
      min-height: 72px;
      max-height: 132px;
      resize: none;
      overflow: auto;
      font-size: 8px;
    }

    .supplier-edit-wrap.is-rich-editing .supplier-inline-edit--rich {
      min-height: 150px;
      max-height: 560px;
      resize: both;
      max-width: calc(100vw - 80px);
      position: relative;
      z-index: 4;
    }

    .supplier-inline-edit--rich:empty::before {
      content: "—";
      color: var(--muted);
    }

    .supplier-field-add {
      border: 1px solid var(--border);
      background: #fff;
      color: #172033;
      border-radius: 7px;
      cursor: pointer;
      min-height: 22px;
      padding: 2px 6px;
      font: inherit;
    }

    .supplier-rich-toolbar {
      display: none;
      gap: 4px;
      align-items: center;
      flex-wrap: wrap;
      padding: 0 0 4px;
    }

    .supplier-edit-wrap.is-rich-editing .supplier-rich-toolbar {
      display: flex;
    }

    .supplier-rich-toolbar button {
      min-height: 24px;
      border: 1px solid var(--border);
      background: #fff;
      color: #172033;
      border-radius: 7px;
      cursor: pointer;
      padding: 2px 7px;
      font-size: 10px;
      line-height: 1.2;
    }

	    .supplier-fields-editor {
	      display: grid;
	      gap: 6px;
	      min-width: 0;
	      max-width: 100%;
	    }

    .supplier-fields-editor--single {
      gap: 0;
    }

	    .supplier-fields-list {
	      display: grid;
	      gap: 1px;
	      min-width: 0;
	      max-width: 100%;
	    }

	    .supplier-field-row {
	      display: grid;
	      grid-template-columns: minmax(0, 1fr);
	      gap: 2px;
	      align-items: start;
	      position: relative;
	      margin: 0;
	      min-width: 0;
	      max-width: 100%;
	      overflow: hidden;
	    }

    .supplier-field-row[data-kind="standard"] + .supplier-field-row:not([data-kind="standard"]) {
      margin-top: 3px;
      padding-top: 3px;
      border-top: 1px solid #e5edf7;
    }

    .supplier-field-row:has(> .supplier-field-kind) {
      grid-template-columns: 40px minmax(0, 1fr);
    }

	    .supplier-field-row.is-editing {
	      grid-template-columns: 18px minmax(0, .9fr) minmax(0, 1.2fr);
	      gap: 4px;
	    }

	    .supplier-field-row.is-editing[data-kind="standard"] {
	      grid-template-columns: minmax(0, .9fr) minmax(0, 1.1fr);
	    }

    .supplier-field-row.is-editing[data-kind="standard"][data-display-label="0"] {
      grid-template-columns: minmax(0, 1fr);
    }

    .supplier-field-row.is-editing[data-kind="feature"][data-display-label="0"] {
      grid-template-columns: 18px minmax(0, 1fr);
    }

	    .supplier-field-row.is-editing:has(> .supplier-field-kind) {
	      grid-template-columns: 40px 18px minmax(0, .8fr) minmax(0, 1.2fr);
	    }

    .supplier-field-row.is-editing.supplier-field-row--virtual:has(> .supplier-field-kind) {
      grid-template-columns: 40px minmax(0, 1fr);
    }

    .supplier-fields-editor--characteristics .supplier-field-row--virtual.is-editing {
      grid-template-columns: minmax(0, 1fr);
    }

    .supplier-field-kind {
      position: relative;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      box-sizing: border-box;
      width: 24px;
      min-width: 24px;
      height: 18px;
      min-height: 18px;
      flex: 0 0 24px;
      padding: 0;
      line-height: 1;
      border-radius: 7px;
      background: #edf6ff;
      color: #1d4ed8;
      text-align: center;
      font-weight: 700;
      font-size: 9px;
      border: 1px solid #dbeafe;
      white-space: nowrap;
      word-break: normal;
      overflow-wrap: normal;
      letter-spacing: 0;
    }

    .supplier-field-kind--ozon {
      background: #eff6ff;
      color: #1d4ed8;
      border-color: #bfdbfe;
    }

    .supplier-field-kind--wb {
      background: #f5f3ff;
