    .supplier-fields-editor--characteristics .supplier-field-row--has-marketplace-error.is-editing .supplier-field-value,
    .supplier-fields-editor--characteristics .supplier-field-row--has-marketplace-error.is-editing .supplier-field-value-wrap {
      border-color: #f87171;
    }

    .supplier-fields-editor--characteristics {
      max-height: 320px;
      overflow-y: auto;
      overflow-x: hidden;
      padding-right: 4px;
      scrollbar-width: thin;
    }

    .supplier-characteristics-cell {
      word-wrap: normal;
      overflow-wrap: normal;
      word-break: normal;
      min-width: 180px;
      max-width: 260px;
    }

    .supplier-fields-editor--characteristics .supplier-fields-list {
      gap: 5px;
    }

    .supplier-fields-editor--features .supplier-fields-list {
      gap: 4px;
