    .supplier-fields-editor--features .supplier-field-add[hidden] {
      display: none;
    }

    .supplier-fields-editor--features .supplier-field-row.is-editing .supplier-field-value {
      grid-column: auto;
    }

    .supplier-features-readonly {
      white-space: pre-wrap;
      line-height: 1.2;
      font-weight: 700;
      color: #172033;
    }

    .supplier-fields-empty--not-analyzed {
      display: flex;
      align-items: flex-start;
      gap: 6px;
      padding: 6px 7px;
      border: 1px solid #fde68a;
      border-radius: 8px;
      background: #fffbeb;
      color: #92400e;
      font-weight: 700;
      line-height: 1.2;
    }

    .supplier-fields-empty--not-analyzed .supplier-field-kind {
      flex: 0 0 auto;
    }

    .supplier-fields-editor--characteristics .supplier-field-row {
      display: block;
      width: 100%;
      overflow: visible;
    }

    .supplier-fields-editor--characteristics .supplier-field-row.is-editing {
      display: grid;
      grid-template-columns: 18px minmax(0, .9fr) minmax(0, 1.2fr);
      gap: 4px;
    }

    .supplier-fields-editor--characteristics .supplier-field-row--virtual.is-editing,
    .supplier-fields-editor--characteristics .supplier-field-row--marketplace.supplier-field-row--virtual.is-editing {
      grid-template-columns: minmax(0, 1fr);
