    }

    .supplier-field-value-wrap {
      display: none;
      position: relative;
      min-width: 0;
      max-width: 100%;
    }

		    .supplier-field-name,
		    .supplier-field-value {
		      display: none;
		      box-sizing: border-box;
	      min-width: 0;
	      max-width: 100%;
	      min-height: 22px;
	      white-space: pre-wrap;
	      overflow-wrap: anywhere;
	      overflow: hidden;
	      border: 1px solid transparent;
	      border-radius: 7px;
	      padding: 3px 5px;
	      background: #f8fafc;
	      outline: none;
	      cursor: text;
