	    .supplier-fields-editor--characteristics .supplier-field-row--virtual.is-editing .supplier-field-value,
    .supplier-fields-editor--characteristics .supplier-field-row--virtual.is-editing .supplier-field-value-wrap {
	      grid-column: 1 / -1;
	    }

    .supplier-field-values-toggle {
      position: absolute;
      top: 3px;
      right: 3px;
      width: 22px;
      min-height: 20px;
      border: 0;
      border-left: 1px solid #dbeafe;
      border-radius: 6px;
      background: #f8fbff;
      color: #2563eb;
      cursor: pointer;
      font-size: 11px;
      font-weight: 900;
      line-height: 1;
      padding: 0;
    }

    .supplier-field-values-toggle:hover {
      background: #eff6ff;
      color: #1d4ed8;
    }

    .supplier-field-values-panel {
      display: none;
      position: fixed;
      top: 0;
      left: 0;
      z-index: 30000;
      min-width: 190px;
      width: min(340px, calc(100vw - 24px));
      max-height: min(320px, calc(100vh - 24px));
      padding: 5px;
      overflow: auto;
      overscroll-behavior: contain;
      border: 1px solid var(--border-strong);
      border-radius: 9px;
      background: #fff;
      box-shadow: 0 18px 44px rgba(15, 23, 42, .16);
    }

    .supplier-field-values-panel--tnved {
      padding: 8px;
    }

    .supplier-field-values-panel.is-open {
      display: block;
    }

    .supplier-field-values-search {
      position: sticky;
      top: 0;
      z-index: 1;
      display: grid;
      gap: 5px;
      padding: 2px 2px 7px;
      background: #fff;
      border-bottom: 1px solid #e2e8f0;
      margin-bottom: 5px;
    }

    .supplier-field-values-search input {
      width: 100%;
      min-height: 30px;
      border: 1px solid #bfdbfe;
      border-radius: 8px;
      background: #f8fbff;
      color: #172033;
      outline: none;
      padding: 5px 8px;
      font: inherit;
      font-size: 12px;
      line-height: 1.2;
    }

    .supplier-field-values-search input:focus {
      border-color: #60a5fa;
