    }

    .supplier-field-values-hint {
      color: #64748b;
      font-size: 10px;
      line-height: 1.25;
    }

    .supplier-field-values-results {
      display: grid;
      gap: 3px;
    }

    .supplier-field-value-option {
      width: 100%;
      min-height: 23px;
      border: 1px solid transparent;
      border-radius: 6px;
      background: #fff;
      color: #172033;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: flex-start;
      gap: 6px;
      padding: 4px 6px;
      text-align: left;
      font: inherit;
      font-size: 10px;
    }

    .supplier-field-value-option--tnved {
      display: grid;
      grid-template-columns: minmax(74px, max-content) 1fr;
      align-items: start;
      gap: 8px;
