      min-width: 0;
      color: #334155;
      overflow-wrap: anywhere;
    }

    .supplier-field-value-option:hover {
      border-color: #bfdbfe;
      background: #eff6ff;
    }

    .supplier-field-name {
      font-weight: 700;
      color: #334155;
    }

	    .supplier-field-row[data-kind="standard"] .supplier-field-name {
	      cursor: default;
	      background: transparent;
	      border-color: transparent;
	      padding-left: 0;
	    }

	    .supplier-fields-editor--dimensions .supplier-field-row.is-editing .supplier-field-name {
	      white-space: nowrap;
	      text-overflow: ellipsis;
	    }

    .supplier-field-row[data-display-label="0"] .supplier-field-name {
      display: none !important;
    }

    .supplier-field-display {
      display: block;
      width: 100%;
      max-width: 100%;
      box-sizing: border-box;
      min-height: 15px;
      line-height: 1.12;
      padding: 0;
      white-space: pre-wrap;
      overflow-wrap: break-word;
      word-break: normal;
      hyphens: none;
      cursor: text;
      color: #172033;
    }

    .supplier-fields-editor--characteristics .supplier-field-display {
      overflow-wrap: break-word;
      word-break: normal;
