        word-break: normal !important;
      }

      .supplier-fields-editor--characteristics {
        max-height: 180px;
        overflow-y: auto;
        overflow-x: hidden;
      }

      .supplier-fields-editor--characteristics .supplier-field-row {
        max-width: 100%;
        min-width: 0;
      }

      .supplier-fields-editor--characteristics .supplier-field-display {
        display: block !important;
        min-width: 0 !important;
        max-width: 100% !important;
        white-space: nowrap !important;
        overflow: hidden !important;
        text-overflow: ellipsis;
        overflow-wrap: normal !important;
        word-break: normal !important;
      }

      .supplier-fields-editor--characteristics .supplier-field-row--marketplace .supplier-field-display {
        display: grid !important;
