	                    echo $renderBulkReplaceControls($bulkReplaceRows, 'supplier_bulk_replace_scope_main', true, $bulkReplaceDimensionRows);
	                  ?>
	                </div>
	                <div class="supplier-bulk-replace-widget" data-bulk-replace-widget hidden>
	                  <div class="supplier-bulk-replace-widget-head" data-bulk-replace-widget-handle>
	                    <div class="supplier-bulk-replace-widget-title">
	                      <span>Замена текстов</span>
	                    </div>
	                    <button type="button" class="supplier-bulk-replace-widget-close" data-bulk-replace-widget-close title="Закрыть" aria-label="Закрыть">×</button>
	                  </div>
	                  <div class="supplier-bulk-replace-widget-body">
	                    <div class="supplier-bulk-replace-widget-card" data-bulk-replace-card>
	                      <?= $renderBulkReplaceControls($bulkReplaceRows, 'supplier_bulk_replace_scope_widget', false) ?>
	                    </div>
	                  </div>
	                </div>
	              </div>
	            </div>
	          </div>
	        </details>
	      </div>

	      <script>
	        (function() {
	          const defaultModel = <?= json_encode($llmModelDefault, JSON_UNESCAPED_UNICODE) ?>;
	          const controls = document.querySelector('[data-content-controls]');
	          if (!controls) return;
	          const modelInput = controls.querySelector('[data-content-model-input]');
	          const scopeInputs = Array.from(document.querySelectorAll('input[name="supplier_content_scope"]'));
	          const selectedIdsInput = document.getElementById('offerIdsJson');
	          const pipelineForms = Array.from(document.querySelectorAll('[data-content-pipeline-form]'));
	          const modelStorageKey = 'feedtools.llm_model';
	          const opModelStorageKey = 'feedtools.llm_model_by_op';
	          const opImageModelStorageKey = 'feedtools.image_model_by_op';

	          const modelExists = function(value, select) {
	            if (!select || value === '') return false;
	            return Array.from(select.options).some(function(option) {
	              return String(option.value || '') === value;
	            });
	          };

	          const operationModelSelects = function() {
	            return Array.from(document.querySelectorAll('[data-content-op-model-select], [data-content-single-model-select]'));
	          };

	          const operationImageModelSelects = function() {
	            return Array.from(document.querySelectorAll('[data-content-op-image-model-select], [data-content-image-model-select]'));
	          };

	          const readOpModelMap = function() {
	            try {
	              const raw = String(localStorage.getItem(opModelStorageKey) || '').trim();
	              const parsed = raw ? JSON.parse(raw) : {};
	              return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
	            } catch (e) {
	              return {};
	            }
	          };

	          const writeOpModelMap = function(map) {
	            try {
	              localStorage.setItem(opModelStorageKey, JSON.stringify(map || {}));
	            } catch (e) {}
	          };

	          const readOpImageModelMap = function() {
	            try {
	              const raw = String(localStorage.getItem(opImageModelStorageKey) || '').trim();
	              const parsed = raw ? JSON.parse(raw) : {};
	              return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
	            } catch (e) {
	              return {};
	            }
	          };

	          const writeOpImageModelMap = function(map) {
	            try {
	              localStorage.setItem(opImageModelStorageKey, JSON.stringify(map || {}));
	            } catch (e) {}
	          };

	          const syncGlobalModelFields = function() {
	            const model = modelInput ? String(modelInput.value || '').trim() : '';
	            document.querySelectorAll('[data-content-global-model-field]').forEach(function(input) {
	              input.value = model || defaultModel;
	            });
	          };

	          const setOperationModel = function(opType, model, persist) {
	            opType = String(opType || '').trim();
	            model = String(model || '').trim();
	            if (opType === '' || model === '') return;
	            operationModelSelects().forEach(function(select) {
	              if (String(select.dataset.opType || '') === opType && modelExists(model, select)) {
	                select.value = model;
	              }
	            });
	            if (persist) {
	              const map = readOpModelMap();
	              map[opType] = model;
	              writeOpModelMap(map);
	            }
	          };

	          const setOperationImageModel = function(opType, model, persist) {
	            opType = String(opType || '').trim();
	            model = String(model || '').trim();
	            if (opType === '' || model === '') return;
	            operationImageModelSelects().forEach(function(select) {
	              if (String(select.dataset.opType || '') === opType && modelExists(model, select)) {
	                select.value = model;
	              }
	            });
	            if (persist) {
	              const map = readOpImageModelMap();
	              map[opType] = model;
	              writeOpImageModelMap(map);
	            }
	          };

	          const setAllOperationModels = function(model, persist) {
	            model = String(model || '').trim() || defaultModel;
	            const map = persist ? {} : readOpModelMap();
	            operationModelSelects().forEach(function(select) {
	              const opType = String(select.dataset.opType || '').trim();
	              if (modelExists(model, select)) {
	                select.value = model;
	              }
	              if (persist && opType !== '') {
	                map[opType] = model;
	              }
	            });
	            if (persist) {
	              writeOpModelMap(map);
	            }
	          };

	          const initOperationModels = function() {
	            const globalModel = modelInput ? String(modelInput.value || '').trim() : defaultModel;
	            const map = readOpModelMap();
	            operationModelSelects().forEach(function(select) {
	              const opType = String(select.dataset.opType || '').trim();
	              const opDefault = String(select.dataset.defaultModel || '').trim();
	              const saved = opType !== '' ? String(map[opType] || '').trim() : '';
	              if (saved !== '' && modelExists(saved, select)) {
	                select.value = saved;
	              } else if (opDefault !== '' && modelExists(opDefault, select)) {
	                select.value = opDefault;
	              } else if (modelExists(globalModel, select)) {
	                select.value = globalModel;
	              } else if (modelExists(defaultModel, select)) {
	                select.value = defaultModel;
	              }
	            });
	          };

	          const initOperationImageModels = function() {
	            const map = readOpImageModelMap();
	            operationImageModelSelects().forEach(function(select) {
	              const opType = String(select.dataset.opType || '').trim();
	              const opDefault = String(select.dataset.defaultModel || '').trim();
	              const saved = opType !== '' ? String(map[opType] || '').trim() : '';
	              if (saved !== '' && modelExists(saved, select)) {
	                select.value = saved;
	              } else if (opDefault !== '' && modelExists(opDefault, select)) {
	                select.value = opDefault;
	              }
	            });
	          };

	          if (modelInput) {
	            try {
	              const savedModel = String(localStorage.getItem(modelStorageKey) || '').trim();
	              if (modelExists(savedModel, modelInput)) {
	                modelInput.value = savedModel;
	              }
	            } catch (e) {}
	            syncGlobalModelFields();
	            initOperationModels();
	            initOperationImageModels();
	            modelInput.addEventListener('change', function() {
	              try {
	                localStorage.setItem(modelStorageKey, String(modelInput.value || ''));
	              } catch (e) {}
	              syncGlobalModelFields();
	              setAllOperationModels(String(modelInput.value || ''), true);
	            });
	          } else {
	            initOperationModels();
	            initOperationImageModels();
	          }

	          operationModelSelects().forEach(function(select) {
	            select.addEventListener('mousedown', function(event) {
	              event.stopPropagation();
	            });
	            select.addEventListener('click', function(event) {
	              event.stopPropagation();
	            });
	            select.addEventListener('change', function() {
	              setOperationModel(String(select.dataset.opType || ''), String(select.value || ''), true);
	            });
	          });

	          operationImageModelSelects().forEach(function(select) {
	            select.addEventListener('mousedown', function(event) {
	              event.stopPropagation();
	            });
	            select.addEventListener('click', function(event) {
	              event.stopPropagation();
	            });
	            select.addEventListener('change', function() {
	              setOperationImageModel(String(select.dataset.opType || ''), String(select.value || ''), true);
	            });
	          });

	          const currentScope = function() {
	            const checked = scopeInputs.find(input => input.checked);
	            return checked ? String(checked.value || 'selected') : 'selected';
	          };
	          const selectedIdsValue = function() {
	            return selectedIdsInput ? String(selectedIdsInput.value || '').trim() : '';
	          };

	          const brandListModal = document.querySelector('[data-brand-list-modal]');
	          const brandListTextarea = brandListModal ? brandListModal.querySelector('[data-brand-list-textarea]') : null;
	          const brandListRun = brandListModal ? brandListModal.querySelector('[data-brand-list-run]') : null;
	          const brandListCancel = brandListModal ? brandListModal.querySelector('[data-brand-list-cancel]') : null;
	          let pendingBrandListForm = null;

	          const formNeedsBrandListPrompt = function(form, pipelineOps) {
	            if (form && form.dataset.brandListPrompt === '1') {
	              return true;
	            }
	            if (Array.isArray(pipelineOps)) {
	              return pipelineOps.indexOf('detect_brand_from_title') !== -1;
	            }
	            return false;
	          };

	          const closeBrandListModal = function() {
	            if (brandListModal) {
	              brandListModal.hidden = true;
	            }
	            pendingBrandListForm = null;
	          };

	          const openBrandListModal = function(form) {
	            if (!brandListModal || !brandListTextarea) {
	              const raw = window.prompt('Введи список брендов поставщика, по одному в строке.', '') || '';
	              form.querySelectorAll('[data-brand-list-input]').forEach(function(input) {
	                input.value = raw;
	              });
	              form.dataset.brandListConfirmed = '1';
	              if (typeof form.requestSubmit === 'function') form.requestSubmit();
	              else form.submit();
	              return;
	            }
	            pendingBrandListForm = form;
	            const current = form.querySelector('[data-brand-list-input]');
	            brandListTextarea.value = current ? String(current.value || '') : '';
	            brandListModal.hidden = false;
	            setTimeout(function() {
	              try { brandListTextarea.focus(); } catch (e) {}
	            }, 0);
	          };

	          if (brandListCancel) {
	            brandListCancel.addEventListener('click', closeBrandListModal);
	          }
	          if (brandListModal) {
	            brandListModal.addEventListener('click', function(event) {
	              if (event.target === brandListModal) {
	                closeBrandListModal();
	              }
	            });
	          }
	          document.addEventListener('keydown', function(event) {
	            if (event.key === 'Escape' && brandListModal && !brandListModal.hidden) {
	              closeBrandListModal();
	            }
	          });
	          if (brandListRun) {
	            brandListRun.addEventListener('click', function() {
	              const form = pendingBrandListForm;
	              if (!form) {
	                closeBrandListModal();
	                return;
	              }
	              const value = brandListTextarea ? String(brandListTextarea.value || '') : '';
	              form.querySelectorAll('[data-brand-list-input]').forEach(function(input) {
	                input.value = value;
	              });
	              closeBrandListModal();
	              form.dataset.brandListConfirmed = '1';
	              if (typeof form.requestSubmit === 'function') form.requestSubmit();
	              else form.submit();
	            });
	          }

	          const updatePipelineSelectAll = function(form) {
	            const selectAll = form.querySelector('[data-content-pipeline-select-all]');
	            if (!selectAll) return;
	            const opInputs = Array.from(form.querySelectorAll('[data-content-pipeline-op]'));
	            const checkedCount = opInputs.filter(input => input.checked).length;
	            selectAll.checked = opInputs.length > 0 && checkedCount === opInputs.length;
	            selectAll.indeterminate = checkedCount > 0 && checkedCount < opInputs.length;
	          };

	          pipelineForms.forEach(function(form) {
	            const selectAll = form.querySelector('[data-content-pipeline-select-all]');
	            if (selectAll) {
	              selectAll.addEventListener('change', function() {
	                form.querySelectorAll('[data-content-pipeline-op]').forEach(function(input) {
	                  input.checked = selectAll.checked;
	                });
	                selectAll.indeterminate = false;
	              });
	            }
	            form.querySelectorAll('[data-content-pipeline-op]').forEach(function(input) {
	              input.addEventListener('change', function() {
	                updatePipelineSelectAll(form);
	              });
	            });
	            updatePipelineSelectAll(form);
	          });

	          const operationTypeForForm = function(form) {
	            const input = form ? form.querySelector('input[name="op_type"]') : null;
	            return input ? String(input.value || '').trim() : '';
	          };

	          const ensureHiddenInput = function(form, name) {
	            let input = form.querySelector('input[name="' + name + '"]');
	            if (!input) {
	              input = document.createElement('input');
	              input.type = 'hidden';
	              input.name = name;
	              form.appendChild(input);
	            }
	            return input;
	          };

	          const coverPreflightMessage = function(data) {
	            let message = String((data && (data.message || data.error)) || 'Не удалось проверить готовность товаров к генерации обложек.');
	            const examples = Array.isArray(data && data.missing_examples) ? data.missing_examples.slice(0, 5) : [];
	            if (examples.length) {
	              message += '\n\nПримеры проблемных товаров:\n' + examples.map(function(item) {
	                const offer = String(item.offer_id || '').trim();
	                const name = String(item.name || '').trim();
	                const reason = String(item.missing_reason || '').split(',').map(function(value) {
	                  value = String(value || '').trim();
	                  if (value === 'no_features') return 'нет фишек';
	                  if (value === 'no_cover_design') return 'нет дизайна обложки категории';
	                  return value;
	                }).filter(Boolean).join(', ');
	                return '- ' + (offer || ('#' + String(item.product_id || ''))) + (name ? ': ' + name : '') + (reason ? ' (' + reason + ')' : '');
	              }).join('\n');
	            }
	            return message;
	          };

	          const runCoverPreflight = async function(form, offerIds, model) {
	            const data = new FormData(form);
	            data.set('offer_ids_json', offerIds);
	            data.set('model', model || defaultModel);
	            const response = await fetch('supplier_products_operation_preflight.php', {
	              method: 'POST',
	              body: data,
	              credentials: 'same-origin',
	              headers: { 'Accept': 'application/json' }
	            });
	            const result = await response.json().catch(function() {
	              return { ok: false, error: 'Некорректный ответ preflight.' };
	            });
	            if (!response.ok || !result.ok) {
	              throw new Error(String(result.error || 'Не удалось проверить товары перед запуском.'));
	            }
	            return result;
	          };

	          document.querySelectorAll('[data-content-action-form]').forEach(function(form) {
	            form.addEventListener('submit', async function(event) {
	              const model = modelInput ? String(modelInput.value || '').trim() : '';
	              const scope = currentScope();
	              const offerIds = scope === 'selected' ? selectedIdsValue() : '';
	              const pipelineHint = form.querySelector('[data-content-pipeline-hint]');
	              const setPipelineHint = function(message) {
	                if (pipelineHint) {
	                  pipelineHint.textContent = message || '';
	                }
	              };
	              if (scope === 'selected' && offerIds === '') {
	                event.preventDefault();
	                event.stopImmediatePropagation();
	                setPipelineHint('Сейчас выбрано 0 товаров. Выбери товары в таблице или переключи сверху на «Все товары».');
	                window.alert('Для запуска по выбранным товарам сначала выбери товары в таблице или переключи режим на все товары.');
	                return;
	              }
	              const pipelineOpsInput = form.querySelector('[data-content-ops-json]');
	              let pipelineOps = null;
	              if (pipelineOpsInput) {
	                pipelineOps = Array.from(form.querySelectorAll('[data-content-pipeline-op]'))
	                  .filter(input => input.checked)
	                  .map(input => String(input.value || '').trim())
	                  .filter(Boolean);
	                if (!pipelineOps.length) {
	                  event.preventDefault();
	                  event.stopImmediatePropagation();
	                  setPipelineHint('Выбери хотя бы одну операцию.');
	                  return;
	                }
	                updatePipelineSelectAll(form);
	                pipelineOpsInput.value = JSON.stringify(pipelineOps);
	                const opModelsInput = form.querySelector('[data-content-op-models-json]');
	                if (opModelsInput) {
	                  const modelsByOp = {};
	                  const modelSelects = Array.from(form.querySelectorAll('[data-content-op-model-select]'));
	                  pipelineOps.forEach(function(opType) {
	                    const select = modelSelects.find(function(candidate) {
	                      return String(candidate.dataset.opType || '') === opType;
	                    });
	                    const opModel = select ? String(select.value || '').trim() : '';
	                    if (opModel !== '') {
	                      modelsByOp[opType] = opModel;
	                    }
	                  });
	                  opModelsInput.value = JSON.stringify(modelsByOp);
	                }
	                const opImageModelsInput = form.querySelector('[data-content-op-image-models-json]');
	                if (opImageModelsInput) {
	                  const modelsByOp = {};
	                  const modelSelects = Array.from(form.querySelectorAll('[data-content-op-image-model-select]'));
	                  pipelineOps.forEach(function(opType) {
	                    const select = modelSelects.find(function(candidate) {
	                      return String(candidate.dataset.opType || '') === opType;
	                    });
	                    const opModel = select ? String(select.value || '').trim() : '';
	                    if (opModel !== '') {
	                      modelsByOp[opType] = opModel;
	                    }
	                  });
	                  opImageModelsInput.value = JSON.stringify(modelsByOp);
	                }
	                const opParamsInput = form.querySelector('[data-content-op-params-json]');
	                if (opParamsInput) {
	                  const paramsByOp = {};
	                  Array.from(form.querySelectorAll('[data-content-pipeline-param]')).forEach(function(control) {
	                    const opType = String(control.dataset.opType || '').trim();
	                    const paramName = String(control.dataset.paramName || '').trim();
	                    if (opType === '' || paramName === '' || pipelineOps.indexOf(opType) === -1) return;
	                    if ((control.type === 'radio' || control.type === 'checkbox') && !control.checked) return;
	                    if (!paramsByOp[opType]) paramsByOp[opType] = {};
	                    paramsByOp[opType][paramName] = String(control.value || '');
	                  });
	                  opParamsInput.value = JSON.stringify(paramsByOp);
	                }
	                setPipelineHint('');
	              }
	              form.querySelectorAll('[data-offer-ids-json]').forEach(function(input) {
	                input.value = offerIds;
	              });
	              form.querySelectorAll('[data-content-global-model-field]').forEach(function(input) {
	                input.value = model || defaultModel;
	              });
	              const opType = operationTypeForForm(form);
	              if (opType === 'gpt_generate_cover_image' && form.dataset.coverPreflightConfirmed !== '1') {
	                event.preventDefault();
	                event.stopImmediatePropagation();
	                try {
	                  const preflight = await runCoverPreflight(form, offerIds, model || defaultModel);
	                  const message = coverPreflightMessage(preflight);
	                  if (preflight.blocked) {
	                    window.alert(message);
	                    return;
	                  }
	                  if (preflight.warning && !window.confirm(message + '\n\nПродолжить генерацию только для готовых товаров?')) {
	                    return;
	                  }
	                  form.dataset.coverPreflightConfirmed = '1';
	                  ensureHiddenInput(form, 'cover_preflight_confirmed').value = '1';
	                  if (typeof form.requestSubmit === 'function') form.requestSubmit();
	                  else form.submit();
	                } catch (error) {
	                  window.alert(error && error.message ? error.message : 'Не удалось проверить товары перед запуском.');
	                }
	                return;
	              }
	              if (form.dataset.coverPreflightConfirmed === '1') {
	                delete form.dataset.coverPreflightConfirmed;
	                ensureHiddenInput(form, 'cover_preflight_confirmed').value = '1';
	              }
	              if (formNeedsBrandListPrompt(form, pipelineOps) && form.dataset.brandListConfirmed !== '1') {
	                event.preventDefault();
	                event.stopImmediatePropagation();
	                openBrandListModal(form);
	                return;
	              }
	              if (form.dataset.brandListConfirmed === '1') {
	                delete form.dataset.brandListConfirmed;
	              }
	            });
	          });
	        })();
	      </script>
	    </section>

