      <script>
        (function() {
          const forms = [
            {
              form: document.getElementById('formExportTplXlsx'),
              file: document.getElementById('tplXlsxFile'),
              idsOut: document.getElementById('tplOfferIdsJson'),
              label: 'Ozon'
            },
            {
              form: document.getElementById('formExportWbTplXlsx'),
              file: document.getElementById('wbTplXlsxFile'),
              idsOut: document.getElementById('wbTplOfferIdsJson'),
              label: 'WB'
            }
          ];
          const selectedIdsHidden = document.getElementById('offerIdsJson'); // уже есть в странице

          if (!selectedIdsHidden) return;

          forms.forEach(function(item) {
            if (!item.form || !item.file || !item.idsOut) return;
            const submitBtn = item.form.querySelector('button[type="submit"]');
            const defaultButtonText = submitBtn ? submitBtn.textContent : '';
            const resetSubmitState = function() {
              item.form.dataset.submitting = '';
              if (submitBtn) {
                submitBtn.disabled = false;
                submitBtn.textContent = defaultButtonText || ('Скачать ' + item.label + ' XLSX');
              }
            };
            item.form.addEventListener('submit', function(e) {
              if (!item.file.files || !item.file.files[0]) {
                e.preventDefault();
                alert('Выбери файл шаблона ' + item.label + ' .xlsx');
                return;
              }
              if (item.form.dataset.submitting === '1') {
                e.preventDefault();
                return;
              }
              item.form.dataset.submitting = '1';
              if (submitBtn) {
                submitBtn.disabled = true;
                submitBtn.textContent = 'Готовим ' + item.label + ' XLSX...';
              }
              // пусто = весь датасет
              item.idsOut.value = String(selectedIdsHidden.value || '').trim();
              window.setTimeout(resetSubmitState, 3000);
            });
            item.file.addEventListener('change', resetSubmitState);
            window.addEventListener('pageshow', resetSubmitState);
          });

          const apiForms = Array.from(document.querySelectorAll('[data-api-push-form]'));
          function selectedOfferIdsForApi() {
            const raw = String(selectedIdsHidden.value || '').trim();
            if (!raw) return [];
            try {
              const decoded = JSON.parse(raw);
              return Array.isArray(decoded) ? decoded.map(String).filter(Boolean) : [];
            } catch (err) {
              return [];
            }
          }

          function updateApiConnectionState(form) {
            const connectionInput = form.querySelector('[data-api-push-connection-id]');
            const button = form.querySelector('button[type="submit"]');
            if (!connectionInput) return;
            const selectId = connectionInput.getAttribute('data-api-push-connection-from') || '';
            const select = selectId ? document.getElementById(selectId) : null;
            if (select) {
              connectionInput.value = String(select.value || '0');
            }
            const hasConnection = parseInt(String(connectionInput.value || '0'), 10) > 0;
            if (button) button.disabled = !hasConnection;
          }

          apiForms.forEach(function(form) {
            updateApiConnectionState(form);
            const connectionInput = form.querySelector('[data-api-push-connection-id]');
            const selectId = connectionInput ? (connectionInput.getAttribute('data-api-push-connection-from') || '') : '';
            const select = selectId ? document.getElementById(selectId) : null;
            if (select) {
              select.addEventListener('change', function() {
                updateApiConnectionState(form);
              });
            }

            form.addEventListener('submit', function(e) {
              updateApiConnectionState(form);
              const button = form.querySelector('button[type="submit"]');
              const connectionInput = form.querySelector('[data-api-push-connection-id]');
              const offerIdsInput = form.querySelector('[data-api-push-offer-ids]');
              const fieldsInput = form.querySelector('[data-api-push-fields-json]');
              const marketplace = form.getAttribute('data-marketplace') === 'wb' ? 'WB' : 'Ozon';
              const connectionId = parseInt(String((connectionInput && connectionInput.value) || '0'), 10);
              const offerIds = selectedOfferIdsForApi();
              const fields = Array.from(form.querySelectorAll('[data-api-push-field]:checked')).map(function(input) {
                return String(input.value || '').trim();
              }).filter(Boolean);
              const fieldLabels = Array.from(form.querySelectorAll('[data-api-push-field]:checked')).map(function(input) {
                const label = input.closest('label');
                return label ? String(label.textContent || '').trim() : String(input.value || '').trim();
              }).filter(Boolean);

              if (connectionId <= 0) {
                e.preventDefault();
                alert('Выбери подключение ' + marketplace + ' в блоке подключений.');
                return;
              }
              if (!offerIds.length) {
                e.preventDefault();
                alert('Выбери товары в таблице перед отправкой по API.');
                return;
              }
              if (!fields.length) {
                e.preventDefault();
                alert('Выбери хотя бы один тип данных для отправки.');
                return;
              }
              if (form.dataset.submitting === '1') {
                e.preventDefault();
                return;
              }
              const message = [
                'Отправить данные в ' + marketplace + '?',
                '',
                'Товаров: ' + offerIds.length,
                'Данные: ' + fieldLabels.join(', ')
              ].join('\n');
              if (!confirm(message)) {
                e.preventDefault();
                return;
              }
              form.dataset.submitting = '1';
              if (offerIdsInput) offerIdsInput.value = JSON.stringify(offerIds);
              if (fieldsInput) fieldsInput.value = JSON.stringify(fields);
              if (button) {
                button.disabled = true;
                button.textContent = 'Отправляем...';
              }
            });
          });
        })();
      </script>

	    </div>
		    </section>
		  </div>

      <?php if ($supplierProductsViewSidebarActions): ?>
        </aside>
      <?php endif; ?>

		  <script>
	    document.addEventListener('DOMContentLoaded', function() {
	      const workspace = document.querySelector('[data-supplier-workspace]');
	      if (!workspace) return;

		      const tabs = Array.from(workspace.querySelectorAll('[data-supplier-tab]'));
		      const panels = Array.from(workspace.querySelectorAll('[data-supplier-panel]'));
		      const workspaceStorageKey = 'feedtools.supplier_products.workspace.<?= h((string)(int)$row['id']) ?>';

		      let activePanel = '';

		      function openPanel(name) {
		        const nextName = activePanel === name ? '' : name;
	        activePanel = nextName;
	        tabs.forEach(function(tab) {
	          const isActive = tab.dataset.supplierTab === nextName;
	          tab.classList.toggle('is-active', isActive);
	          tab.setAttribute('aria-selected', isActive ? 'true' : 'false');
	        });
		        panels.forEach(function(panel) {
		          const isActive = panel.dataset.supplierPanel === nextName;
		          panel.hidden = !isActive;
		          panel.classList.toggle('is-active', isActive);
		        });
		        try {
		          localStorage.setItem(workspaceStorageKey, nextName);
		        } catch (e) {}
		      }

	      tabs.forEach(function(tab) {
	        tab.addEventListener('click', function() {
	          openPanel(tab.dataset.supplierTab || 'content');
	        });
	      });

		      let initialPanel = '<?= $supplierImportSubmitted ? 'import' : 'content' ?>';
		      if (!<?= $supplierImportSubmitted ? 'true' : 'false' ?>) {
		        try {
		          const savedPanel = String(localStorage.getItem(workspaceStorageKey) || '');
		          if (savedPanel === '' || tabs.some(function(tab) { return tab.dataset.supplierTab === savedPanel; })) {
		            initialPanel = savedPanel;
		          }
		        } catch (e) {}
		      }
		      openPanel(initialPanel);

		      const detailsStoragePrefix = 'feedtools.supplier_products.details.<?= h((string)(int)$row['id']) ?>.';
		      document.querySelectorAll('details[data-persist-open]').forEach(function(details) {
		        const key = detailsStoragePrefix + String(details.dataset.persistOpen || '').trim();
		        if (key === detailsStoragePrefix) return;
		        try {
		          const saved = localStorage.getItem(key);
		          if (saved === '1') {
		            details.open = true;
		          } else if (saved === '0') {
		            details.open = false;
		          }
		        } catch (e) {}
		        details.addEventListener('toggle', function() {
		          try {
		            localStorage.setItem(key, details.open ? '1' : '0');
		          } catch (e) {}
		        });
		      });

		      const importForm = document.querySelector('[data-supplier-import-form]');
	      if (importForm) {
	        const sourceInputs = Array.from(importForm.querySelectorAll('input[name="supplier_import_source"]'));
	        const sourcePanels = Array.from(importForm.querySelectorAll('[data-import-source-panel]'));
	        const urlInput = importForm.querySelector('input[name="supplier_import_feed_url"]');
	        const fileInput = importForm.querySelector('input[name="supplier_import_file"]');
	        const importModeInputs = Array.from(importForm.querySelectorAll('input[name="supplier_import_mode"]'));
	        const importDependent = importForm.querySelector('[data-import-dependent]');
	        const importActionInput = importForm.querySelector('[data-supplier-import-action]');
	        const importSelectedIdsInput = importForm.querySelector('[data-supplier-import-selected-ids]');
	        const importSubmitButtons = Array.from(importForm.querySelectorAll('[data-supplier-import-submit]'));
	        const dangerToggles = Array.from(importForm.querySelectorAll('[data-supplier-danger-toggle]'));
	        const repairPhotosButton = document.querySelector('[data-supplier-repair-photos]');
	        const repairAddPhotosInput = document.querySelector('[data-supplier-repair-add-photos]');
	        const repairScopeInputs = Array.from(importForm.querySelectorAll('input[name="supplier_import_quick_scope"]'));
	        const confirmModal = document.querySelector('[data-supplier-confirm-modal]');
	        const confirmTitle = confirmModal ? confirmModal.querySelector('[data-supplier-confirm-title]') : null;
	        const confirmText = confirmModal ? confirmModal.querySelector('[data-supplier-confirm-text]') : null;
	        const confirmList = confirmModal ? confirmModal.querySelector('[data-supplier-confirm-list]') : null;
	        const confirmCancel = confirmModal ? confirmModal.querySelector('[data-supplier-confirm-cancel]') : null;
	        const confirmRun = confirmModal ? confirmModal.querySelector('[data-supplier-confirm-run]') : null;
	        const importProgressModal = document.querySelector('[data-supplier-import-progress-modal]');
	        const importProgressTitle = importProgressModal ? importProgressModal.querySelector('[data-supplier-import-progress-title]') : null;
	        const importProgressStatus = importProgressModal ? importProgressModal.querySelector('[data-supplier-import-progress-status]') : null;
	        const importProgressBar = importProgressModal ? importProgressModal.querySelector('[data-supplier-import-progress-bar]') : null;
	        const importProgressStats = importProgressModal ? importProgressModal.querySelector('[data-supplier-import-progress-stats]') : null;
	        const importProgressLink = importProgressModal ? importProgressModal.querySelector('[data-supplier-import-progress-link]') : null;
	        const importProgressClose = importProgressModal ? importProgressModal.querySelector('[data-supplier-import-progress-close]') : null;
	        const importProgressRefresh = importProgressModal ? importProgressModal.querySelector('[data-supplier-import-progress-refresh]') : null;
	        const repairModal = document.querySelector('[data-supplier-repair-modal]');
	        const repairStatus = repairModal ? repairModal.querySelector('[data-supplier-repair-status]') : null;
	        const repairProgress = repairModal ? repairModal.querySelector('[data-supplier-repair-progress]') : null;
	        const repairStats = repairModal ? repairModal.querySelector('[data-supplier-repair-stats]') : null;
	        const repairClose = repairModal ? repairModal.querySelector('[data-supplier-repair-close]') : null;
	        const checkResult = document.querySelector('[data-import-check-result]');
	        let submitTimer = 0;
	        let lastSubmittedUrl = <?= json_encode($supplierImportSelectedSource === 'url' && is_array($supplierImportCheckResult) ? $supplierImportFeedUrl : '', JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?>;
	        const repairHasSupplierFeed = <?= trim((string)($supplierProductSupplier['feed_url'] ?? '')) !== '' ? 'true' : 'false' ?>;
	        const syncImportPanels = function() {
	          const current = (sourceInputs.find(function(input) { return input.checked; }) || {}).value || '';
	          sourcePanels.forEach(function(panel) {
	            panel.classList.toggle('is-active', panel.dataset.importSourcePanel === current);
	          });
	          if (checkResult && (current === '' || current === 'supplier_feed')) {
	            checkResult.hidden = true;
	          }
	        };
	        const currentSource = function() {
	          return (sourceInputs.find(function(input) { return input.checked; }) || {}).value || '';
	        };
	        const selectImportSource = function(source) {
	          source = String(source || '').trim();
	          if (!source) return false;
	          const input = sourceInputs.find(function(item) { return item.value === source; });
	          if (!input) return false;
	          input.checked = true;
	          syncImportPanels();
	          return true;
	        };
	        const ensureRepairSource = function() {
	          if (currentSource()) return true;
	          const storedFileInput = importForm.querySelector('input[name="supplier_import_stored_file"]');
	          const storedFile = storedFileInput ? String(storedFileInput.value || '').trim() : '';
	          if (repairHasSupplierFeed && selectImportSource('supplier_feed')) return true;
	          if (urlInput && String(urlInput.value || '').trim() !== '' && selectImportSource('url')) return true;
	          if (storedFile !== '' && selectImportSource('upload')) return true;
	          if (repairModal) {
	            repairModal.hidden = false;
	            if (repairProgress) repairProgress.style.width = '100%';
	            if (repairStatus) repairStatus.textContent = 'Выбери источник импорта для исправления фото.';
	            if (repairStats) repairStats.textContent = '';
	            if (repairClose) {
	              repairClose.hidden = false;
	              repairClose.textContent = 'Закрыть';
	            }
	          } else {
	            window.alert('Выбери источник импорта для исправления фото.');
	          }
	          return false;
	        };
	        const syncImportConnectionInputs = function() {
	          const ozonSelect = document.getElementById('datasetOzonConnectionSelect');
	          const wbSelect = document.getElementById('datasetWbConnectionSelect');
	          const ozonInput = importForm.querySelector('input[name="ozon_connection_id"]');
	          const wbInput = importForm.querySelector('input[name="wb_connection_id"]');
	          if (ozonSelect && ozonInput) ozonInput.value = ozonSelect.value || '0';
	          if (wbSelect && wbInput) wbInput.value = wbSelect.value || '0';
	        };
	        const syncImportOptions = function() {
	          if (!importDependent) return;
	          const currentMode = (importModeInputs.find(function(input) { return input.checked; }) || {}).value || 'add_update';
	          const isAddOnly = currentMode === 'add_only';
	          importDependent.classList.toggle('is-disabled', isAddOnly);
	          importDependent.querySelectorAll('input, select, textarea, button').forEach(function(input) {
	            input.disabled = isAddOnly;
	          });
	        };
	        const looksLikeHttpUrl = function(value) {
	          try {
	            const parsed = new URL(value);
	            return (parsed.protocol === 'http:' || parsed.protocol === 'https:') && !!parsed.host;
	          } catch (e) {
	            return false;
	          }
	        };
	        const submitImportForm = function() {
	          if (importForm.dataset.submitting === '1') return;
	          if (currentSource() === '' || currentSource() === 'supplier_feed') return;
	          if (importActionInput) importActionInput.value = 'choose_source';
	          importForm.dataset.submitting = '1';
	          importForm.submit();
	        };
	        const submitUrlIfReady = function(delay) {
	          if (!urlInput || currentSource() !== 'url') return;
	          const value = String(urlInput.value || '').trim();
	          if (value === '' || value === lastSubmittedUrl || !looksLikeHttpUrl(value)) return;
	          window.clearTimeout(submitTimer);
	          submitTimer = window.setTimeout(function() {
	            lastSubmittedUrl = value;
	            submitImportForm();
	          }, delay);
	        };
	        sourceInputs.forEach(function(input) {
	          input.addEventListener('change', function() {
	            syncImportPanels();
	            if (currentSource() === 'url') {
	              if (urlInput) urlInput.focus();
	              submitUrlIfReady(0);
	            }
	          });
	        });
	        if (urlInput) {
	          urlInput.addEventListener('change', function() { submitUrlIfReady(0); });
	          urlInput.addEventListener('blur', function() { submitUrlIfReady(0); });
	          urlInput.addEventListener('keydown', function(event) {
	            if (event.key !== 'Enter') return;
	            event.preventDefault();
	            submitUrlIfReady(0);
	          });
	        }
	        if (fileInput) {
	          fileInput.addEventListener('change', function() {
	            if (!fileInput.files || fileInput.files.length < 1) return;
	            const uploadInput = sourceInputs.find(function(input) { return input.value === 'upload'; });
	            if (uploadInput) uploadInput.checked = true;
	            syncImportPanels();
	            submitImportForm();
	          });
	        }
	        importModeInputs.forEach(function(input) {
	          input.addEventListener('change', syncImportOptions);
	        });
	        const selectedOfferIds = function() {
	          const selectedIdsHidden = document.getElementById('offerIdsJson');
	          const raw = selectedIdsHidden ? String(selectedIdsHidden.value || '').trim() : '';
	          if (!raw) return [];
	          try {
	            const parsed = JSON.parse(raw);
	            return Array.isArray(parsed) ? parsed.map(String).filter(Boolean) : [];
	          } catch (e) {
	            return [];
	          }
	        };
	        const selectedCount = function() {
	          return selectedOfferIds().length;
	        };
	        const selectedCountText = function() {
	          return 'выбрано ' + selectedCount() + ' из <?= h((string)$selectionOffersTotal) ?>';
	        };
	        const setSelectedIdsForSubmit = function() {
	          syncImportConnectionInputs();
	          if (!importSelectedIdsInput) return;
	          const selectedIdsHidden = document.getElementById('offerIdsJson');
	          importSelectedIdsInput.value = selectedIdsHidden ? String(selectedIdsHidden.value || '') : '';
	        };
	        const numericHidden = function(selector) {
	          const el = importForm.querySelector(selector);
	          const raw = el ? String(el.value || '').trim() : '';
	          if (raw === '') return null;
	          const n = Number(raw);
	          return Number.isFinite(n) ? n : null;
	        };
	        const formatCount = function(n, fallback) {
	          if (n === null || n === undefined || n === '') return fallback || 'определяется...';
	          const num = Number(n);
	          return Number.isFinite(num) ? String(num) : (fallback || 'определяется...');
	        };
	        const importModeLabel = function(mode) {
	          if (mode === 'add_only') return 'только добавить товары';
	          if (mode === 'update_only') return 'только обновить существующие товары';
	          return 'добавить новые и обновить существующие товары';
	        };
	        const radioValue = function(name, fallback) {
	          const input = importForm.querySelector('input[name="' + name + '"]:checked');
	          return input ? String(input.value || fallback || '') : (fallback || '');
	        };
	        const enabledImportChanges = function(mode) {
	          const changes = [];
	          if (mode === 'add_only' || mode === 'add_update') {
	            changes.push('Будут добавлены новые товары из источника');
	          }
	          if (mode === 'add_only') return changes;
	          if (radioValue('supplier_import_replace_names', '0') === '1') {
	            changes.push('Будут обновлены наименования товаров');
	          }
	          const brandMode = radioValue('supplier_import_brand_mode', 'no_update');
	          if (brandMode === 'add_only') {
	            changes.push('Будет заполнен бренд у товаров, где он пустой');
	          } else if (brandMode === 'replace') {
	            changes.push('Будет обновлен бренд');
	          }
	          if (radioValue('supplier_import_model_mode', 'no_update') === 'update') {
	            changes.push('Будет обновлена модель');
	          }
	          const descriptionMode = radioValue('supplier_import_description_mode', 'no_update');
	          if (descriptionMode === 'fill_empty') {
	            changes.push('Будут заполнены пустые описания');
	          } else if (descriptionMode === 'replace') {
	            changes.push('Будут обновлены описания');
	          }
	          if (radioValue('supplier_import_update_supplier_category', '0') === '1') {
	            changes.push('Будет обновлена категория поставщика');
	          }
	          const characteristicsMode = radioValue('supplier_import_characteristics_mode', 'no_update');
	          if (characteristicsMode === 'add_only') {
	            changes.push('Будут добавлены новые обычные и WB-характеристики');
	          } else if (characteristicsMode === 'add_replace') {
	            changes.push('Будут добавлены новые и обновлены совпадающие обычные и WB-характеристики');
	          } else if (characteristicsMode === 'replace_all') {
	            changes.push('Будет заменен весь список обычных и WB-характеристик');
	          }
	          const photosMode = radioValue('supplier_import_photos_mode', 'no_replace');
	          if (photosMode === 'add_only') {
	            changes.push('Будут добавлены новые фото из источника');
	          } else if (photosMode === 'replace_keep_generated') {
	            changes.push('Будут заменены обычные фото, сгенерированные обложка и фото характеристик сохранятся');
	          } else if (photosMode === 'replace_all') {
	            changes.push('Будут заменены все фото');
	          }
	          return changes;
	        };
	        const sourceLabel = function() {
	          const source = currentSource();
	          if (source === '') return 'источник не выбран';
	          if (source === 'supplier_feed') return 'фид поставщика';
	          if (source === 'url') return 'ссылка на фид';
	          if (source === 'ozon_account') return 'личный кабинет Ozon';
	          if (source === 'wb_account') return 'личный кабинет WB';
	          return 'загруженный файл';
	        };
	        const loadSourceInfo = async function() {
	          syncImportConnectionInputs();
	          const source = currentSource();
	          if (!source) {
	            throw new Error('Выбери источник импорта.');
	          }
	          const formData = new FormData(importForm);
	          const response = await fetch('supplier_products_source_info.php', {
	            method: 'POST',
	            credentials: 'same-origin',
	            headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
	            body: JSON.stringify({
	              id: Number(formData.get('id') || 0),
	              source: source,
	              feed_url: String(formData.get('supplier_import_feed_url') || ''),
	              stored_file: String(formData.get('supplier_import_stored_file') || ''),
	              stored_file_name: String(formData.get('supplier_import_stored_file_name') || ''),
	              ozon_connection_id: Number(formData.get('ozon_connection_id') || 0),
	              wb_connection_id: Number(formData.get('wb_connection_id') || 0),
	              mode: radioValue('supplier_import_mode', 'add_update'),
	              scope: radioValue('supplier_import_scope', 'all'),
	              selected_offer_ids: selectedOfferIds()
	            })
	          });
	          const data = await response.json().catch(function() { return null; });
	          if (!response.ok || !data || !data.ok) {
	            throw new Error((data && data.error) ? data.error : 'Не удалось определить количество товаров в источнике.');
	          }
	          const count = Number(data.items_count);
	          if (!Number.isFinite(count)) {
	            throw new Error('Не удалось определить количество товаров в источнике.');
	          }
	          const input = importForm.querySelector('[data-supplier-source-count]');
	          if (input) input.value = String(count);
	          return data;
	        };
	        const sourceInfoCount = function(sourceInfo) {
	          if (sourceInfo && Object.prototype.hasOwnProperty.call(sourceInfo, 'items_count')) {
	            const n = Number(sourceInfo.items_count);
	            return Number.isFinite(n) ? n : null;
	          }
	          return numericHidden('[data-supplier-source-count]');
	        };
	        const buildConfirmInfo = function(action, sourceInfoOverride) {
	          const currentTotal = numericHidden('[data-supplier-current-total]');
	          const sourceInfo = sourceInfoOverride && typeof sourceInfoOverride === 'object' ? sourceInfoOverride : null;
	          const preview = sourceInfo && sourceInfo.preview && typeof sourceInfo.preview === 'object' ? sourceInfo.preview : null;
	          const sourceCount = sourceInfo ? sourceInfoCount(sourceInfo) : numericHidden('[data-supplier-source-count]');
	          const selected = selectedCount();
	          const mode = (importModeInputs.find(function(input) { return input.checked; }) || {}).value || 'add_update';
	          const importScope = (importForm.querySelector('input[name="supplier_import_scope"]:checked') || {}).value || 'all';
	          const quickScope = (importForm.querySelector('input[name="supplier_import_quick_scope"]:checked') || {}).value || 'all';

	          if (action === 'replace_catalog') {
	            return {
	              title: 'Полностью заменить каталог товаров?',
	              text: 'Операция удалит текущие товары этого DB-датасета поставщика и заново загрузит каталог из выбранного источника.',
	              items: [
	                'Источник: ' + sourceLabel() + '.',
	                'Будет удалено текущих товаров: ' + formatCount(currentTotal, '0') + '.',
	                'Будет загружено товаров из источника: ' + formatCount(sourceCount) + '.',
	                'Будут пересозданы товары, характеристики, описания, категории и ссылки на фото из источника.'
	              ]
	            };
	          }

	          if (action === 'delete_stale') {
	            return {
	              title: 'Удалить неактуальные товары?',
	              text: 'Операция сравнит текущий каталог с выбранным источником и удалит товары, которых больше нет в источнике.',
	              items: [
	                'Источник: ' + sourceLabel() + '.',
	                'Будет проверено текущих товаров: ' + formatCount(currentTotal, '0') + '.',
	                'Товаров в источнике для сравнения: ' + formatCount(sourceCount) + '.',
	                preview ? ('Будет удалено неактуальных товаров: ' + formatCount(preview.stale_products, '0') + '.') : '',
	                'Удалятся только товары, offer id которых не найден в источнике.'
	              ].filter(Boolean)
	            };
	          }

	          const targetCount = (mode !== 'add_only' && importScope === 'selected') ? selected : currentTotal;
	          const items = [
	            'Источник: ' + sourceLabel() + '.',
	            'Режим: ' + importModeLabel(mode) + '.',
	            'Область: ' + ((mode !== 'add_only' && importScope === 'selected') ? ('только выбранные товары, ' + selectedCountText()) : 'все товары') + '.',
	            'Товаров в источнике: ' + formatCount(sourceCount) + '.'
	          ];
	          if (preview) {
	            if (mode === 'add_only' || mode === 'add_update') {
	              items.push('Будет добавлено новых товаров: ' + formatCount(preview.add_candidates, '0') + '.');
	            }
	            if (mode !== 'add_only') {
	              items.push('Будет обновлено существующих товаров: ' + formatCount(preview.update_candidates, '0') + '.');
	            }
	          } else {
	            items.push('Текущих товаров, на которые может действовать обновление: ' + formatCount(targetCount, '0') + '.');
	          }
	          enabledImportChanges(mode).forEach(function(change) {
	            items.push(change + '.');
	          });
	          return {
	            title: 'Запустить импорт?',
	            text: 'Операция применит выбранные правила импорта к каталогу поставщика.',
	            items: items
	          };
	        };
	        let pendingConfirmButton = null;
	        const renderConfirm = function(button, sourceInfo) {
	          const action = button.value || 'import';
	          const info = buildConfirmInfo(action, sourceInfo);
	          confirmTitle.textContent = info.title;
	          confirmText.textContent = info.text;
	          confirmList.innerHTML = '';
	          (info.items || []).forEach(function(item) {
	            const li = document.createElement('li');
	            li.textContent = item;
	            confirmList.appendChild(li);
	          });
	          confirmRun.textContent = action === 'import' ? 'Импортировать' : 'Запустить';
	        };
	        const openConfirm = async function(button) {
	          if (!currentSource()) {
	            window.alert('Выбери источник импорта.');
	            return false;
	          }
	          if (!confirmModal || !confirmTitle || !confirmText || !confirmList || !confirmRun) {
	            return false;
	          }
	          pendingConfirmButton = button;
	          renderConfirm(button, null);
	          confirmRun.disabled = true;
	          confirmList.innerHTML = '';
	          ['Источник: ' + sourceLabel() + '.', 'Определяю количество товаров в источнике...'].forEach(function(item) {
	            const li = document.createElement('li');
	            li.textContent = item;
	            confirmList.appendChild(li);
	          });
	          confirmModal.hidden = false;
	          try {
	            const sourceInfo = await loadSourceInfo();
	            if (pendingConfirmButton !== button) return false;
	            renderConfirm(button, sourceInfo);
	            confirmRun.disabled = false;
	            confirmRun.focus();
	          } catch (e) {
	            confirmTitle.textContent = 'Не удалось подготовить подтверждение';
	            confirmText.textContent = e.message || 'Не удалось определить количество товаров в источнике.';
	            confirmList.innerHTML = '';
	            confirmRun.disabled = true;
	          }
	          return true;
	        };
	        const setImportButtonsDisabled = function(disabled) {
	          importSubmitButtons.forEach(function(button) {
	            const dangerRow = button.closest('.supplier-import-danger-row');
	            const dangerToggle = dangerRow ? dangerRow.querySelector('[data-supplier-danger-toggle]') : null;
	            button.disabled = !!disabled || (button.hasAttribute('data-supplier-danger-button') && !(dangerToggle && dangerToggle.checked));
	          });
	        };
	        const setImportProgress = function(percent, status, stats) {
	          const safePercent = Math.max(0, Math.min(100, Number(percent) || 0));
	          if (importProgressBar) importProgressBar.style.width = safePercent + '%';
	          if (importProgressStatus) importProgressStatus.textContent = status || 'Импорт выполняется...';
	          if (importProgressStats) importProgressStats.textContent = stats || '';
	        };
	        const showImportProgress = function(title) {
	          if (!importProgressModal) return;
	          if (importProgressTitle) importProgressTitle.textContent = title || 'Импорт';
	          if (importProgressLink) importProgressLink.hidden = true;
	          if (importProgressClose) importProgressClose.hidden = true;
	          if (importProgressRefresh) importProgressRefresh.hidden = true;
	          setImportProgress(0, 'Запускаю операцию...', '');
	          importProgressModal.hidden = false;
	        };
	        const importOperationTitle = function(action) {
	          if (action === 'import') return 'Импорт';
	          if (action === 'remap_offer_ids') return 'Замена артикулов';
	          if (action === 'remap_wb_vendor_codes') return 'Замена артикулов WB';
	          return 'Операция импорта';
	        };
	        const pollImportOperation = async function(opId, opUrl) {
	          const pollUrl = 'op_poll.php?id=' + encodeURIComponent(String(opId));
	          if (importProgressLink) {
	            importProgressLink.href = opUrl || ('op.php?id=' + encodeURIComponent(String(opId)));
	            importProgressLink.hidden = false;
	          }
	          let keepPolling = true;
	          while (keepPolling) {
	            const response = await fetch(pollUrl, { credentials: 'same-origin', headers: { 'Accept': 'application/json' } });
	            const data = await response.json().catch(function() { return null; });
	            if (!response.ok || !data) {
	              throw new Error('Не удалось получить прогресс операции.');
	            }
	            const status = String(data.status || '');
	            const done = Number(data.done || 0);
	            const total = Number(data.total || 0);
	            const percent = data.percent !== null && data.percent !== undefined
	              ? Number(data.percent)
	              : (total > 0 ? (done / total) * 100 : 0);
	            const msg = String(data.msg || data.stage || '');
	            const queue = status === 'queued' && Number(data.queue_ahead_count || 0) > 0
	              ? (' · перед ней в очереди: ' + Number(data.queue_ahead_count || 0))
	              : '';
	            setImportProgress(
	              percent,
	              status === 'queued' ? ('Операция ждёт очередь' + queue) : (msg || 'Импорт выполняется...'),
	              'Прогресс: ' + Math.round(percent) + '% · ' + done + ' из ' + total
	            );
	            if (status === 'done') {
	              keepPolling = false;
	              setImportProgress(100, 'Импорт завершён.', 'Можно обновить страницу, чтобы увидеть новые данные в таблице.');
	              if (importProgressRefresh) importProgressRefresh.hidden = false;
	              if (importProgressClose) importProgressClose.hidden = false;
	              break;
	            }
	            if (status === 'error' || status === 'cancelled') {
	              keepPolling = false;
	              const errorText = String(data.error_text || data.msg || (status === 'cancelled' ? 'Операция отменена.' : 'Импорт завершился ошибкой.'));
	              setImportProgress(percent, errorText, '');
	              if (importProgressClose) importProgressClose.hidden = false;
	              break;
	            }
	            await new Promise(function(resolve) { window.setTimeout(resolve, 1000); });
	          }
	        };
	        const startImportOperation = async function(button) {
	          const action = button ? (button.value || 'import') : 'import';
	          syncImportConnectionInputs();
	          if (!currentSource()) {
	            window.alert('Выбери источник импорта.');
	            return;
	          }
	          if (['remap_offer_ids', 'remap_wb_vendor_codes'].includes(action)) {
	            const uploadInput = importForm.querySelector('input[name="supplier_import_file"]');
	            const hasFile = !!(uploadInput && uploadInput.files && uploadInput.files.length > 0);
	            const storedFile = String((importForm.querySelector('input[name="supplier_import_stored_file"]') || {}).value || '');
	            if (currentSource() !== 'upload') {
	              window.alert('Для замены артикулов выбери источник «Загрузить файл» и CSV-карту.');
	              return;
	            }
	            if (!hasFile && !storedFile) {
	              window.alert('Загрузи CSV-файл с колонками: старый артикул; новый артикул.');
	              return;
	            }
	          }
	          if (action === 'remap_wb_vendor_codes') {
	            const wbInput = importForm.querySelector('input[name="wb_connection_id"]');
	            const wbConnectionId = Number(wbInput ? wbInput.value : 0);
	            if (!Number.isFinite(wbConnectionId) || wbConnectionId <= 0) {
	              window.alert('Выбери подключение Wildberries.');
	              return;
	            }
	          }
	          if (importActionInput) importActionInput.value = action;
	          setSelectedIdsForSubmit();
	          if (action === 'import'
	            && radioValue('supplier_import_mode', 'add_update') !== 'add_only'
	            && radioValue('supplier_import_scope', 'all') === 'selected'
	            && selectedCount() < 1) {
	            window.alert('Для импорта только выбранных товаров сначала выбери товары в таблице.');
	            return;
	          }
	          if (['quick_prices_stock', 'quick_dimensions'].includes(action)
	            && radioValue('supplier_import_quick_scope', 'all') === 'selected'
	            && selectedCount() < 1) {
	            window.alert('Для операции только по выбранным товарам сначала выбери товары в таблице.');
	            return;
	          }
	          showImportProgress(importOperationTitle(action));
	          setImportButtonsDisabled(true);
	          importForm.dataset.submitting = '1';
	          try {
	            const formData = new FormData(importForm);
	            const response = await fetch('supplier_products_import_start.php', {
	              method: 'POST',
	              credentials: 'same-origin',
	              headers: { 'Accept': 'application/json' },
	              body: formData
	            });
	            const data = await response.json().catch(function() { return null; });
	            if (!response.ok || !data || !data.ok) {
	              throw new Error((data && data.error) ? data.error : 'Не удалось запустить импорт.');
	            }
	            await pollImportOperation(Number(data.op_id || 0), String(data.op_url || ''));
	          } catch (e) {
	            setImportProgress(100, e.message || 'Не удалось запустить импорт.', '');
	            if (importProgressClose) importProgressClose.hidden = false;
	          } finally {
	            importForm.dataset.submitting = '0';
	            setImportButtonsDisabled(false);
	            dangerToggles.forEach(function(toggle) {
	              const key = toggle.dataset.supplierDangerToggle || '';
	              const dangerButton = importForm.querySelector('[data-supplier-danger-button="' + key + '"]');
	              if (dangerButton) dangerButton.disabled = !toggle.checked;
	            });
	          }
	        };
	        dangerToggles.forEach(function(toggle) {
	          const key = toggle.dataset.supplierDangerToggle || '';
	          const button = importForm.querySelector('[data-supplier-danger-button="' + key + '"]');
	          if (!button) return;
	          const syncDanger = function() {
	            button.disabled = !toggle.checked;
	          };
	          toggle.addEventListener('change', syncDanger);
	          syncDanger();
	        });
	        importSubmitButtons.forEach(function(button) {
	          button.addEventListener('click', function(event) {
	            const action = button.value || 'import';
	            event.preventDefault();
	            if (importActionInput) importActionInput.value = action;
	            setSelectedIdsForSubmit();
	            if (['import', 'replace_catalog', 'delete_stale'].includes(action)) {
	              if (action === 'import'
	                && radioValue('supplier_import_mode', 'add_update') !== 'add_only'
	                && radioValue('supplier_import_scope', 'all') === 'selected'
	                && selectedCount() < 1) {
	                window.alert('Для импорта только выбранных товаров сначала выбери товары в таблице.');
	                return;
	              }
	              openConfirm(button);
	              return;
	            }
	            startImportOperation(button);
	          });
	        });
	        if (confirmCancel) {
	          confirmCancel.addEventListener('click', function() {
	            pendingConfirmButton = null;
	            if (confirmModal) confirmModal.hidden = true;
	          });
	        }
	        if (confirmRun) {
	          confirmRun.addEventListener('click', function() {
	            if (!pendingConfirmButton) return;
	            const buttonToRun = pendingConfirmButton;
	            const action = buttonToRun.value || 'import';
	            if (importActionInput) importActionInput.value = action;
	            setSelectedIdsForSubmit();
	            if (confirmModal) confirmModal.hidden = true;
	            pendingConfirmButton = null;
	            startImportOperation(buttonToRun);
	          });
	        }
	        if (importProgressClose) {
	          importProgressClose.addEventListener('click', function() {
	            if (importProgressModal) importProgressModal.hidden = true;
	          });
	        }
	        if (importProgressRefresh) {
	          importProgressRefresh.addEventListener('click', function() {
	            window.location.reload();
	          });
	        }
	        const setRepairProgress = function(done, total, stats, title) {
	          const percent = total > 0 ? Math.max(0, Math.min(100, Math.round((done / total) * 100))) : 100;
	          if (repairProgress) repairProgress.style.width = percent + '%';
	          if (repairStatus) repairStatus.textContent = title || (total > 0 ? ('Проверено ' + done + ' из ' + total) : 'Нет товаров для проверки.');
	          if (repairStats) {
	            const s = stats || {};
	            repairStats.textContent = 'Нерабочих ссылок: ' + Number(s.broken_links || 0)
	              + ' · синхронизировано с источником: ' + Number(s.synced_from_source || 0)
	              + ' · заменено: ' + Number(s.replaced_links || 0)
	              + ' · удалено: ' + Number(s.removed_links || 0)
	              + ' · добавлено: ' + Number(s.added_links || 0)
	              + ' · товаров обновлено: ' + Number(s.products_updated || 0);
	          }
	        };
	        const postRepairJson = async function(payload) {
	          const response = await fetch('supplier_products_repair_photos.php', {
	            method: 'POST',
	            credentials: 'same-origin',
	            headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
	            body: JSON.stringify(payload)
	          });
	          const data = await response.json().catch(function() { return null; });
	          if (!response.ok || !data || !data.ok) {
	            throw new Error((data && data.error) ? data.error : 'Не удалось выполнить исправление фото.');
	          }
	          return data;
	        };
	        const runRepairPhotos = async function() {
	          if (!repairPhotosButton || !repairModal) return;
	          if (!ensureRepairSource()) return;
	          syncImportConnectionInputs();
	          const formData = new FormData(importForm);
	          const repairScope = (repairScopeInputs.find(function(input) { return input.checked; }) || {}).value || 'selected';
	          const scope = repairScope === 'selected' ? 'selected' : 'all';
	          const selectedIds = selectedOfferIds();
	          if (scope === 'selected' && selectedIds.length < 1) {
	            window.alert('Для исправления только выбранных товаров сначала выбери товары в таблице.');
	            return;
	          }
	          if (String(formData.get('supplier_import_source') || '') === 'upload' && String(formData.get('supplier_import_stored_file') || '').trim() === '') {
	            window.alert('Сначала загрузи файл источника.');
	            return;
	          }
	          repairModal.hidden = false;
	          if (repairClose) repairClose.hidden = true;
	          repairPhotosButton.disabled = true;
	          setRepairProgress(0, 1, {}, 'Подготавливаю источник...');
	          try {
	              const start = await postRepairJson({
	              action: 'start',
	              id: Number(formData.get('id') || 0),
	              source: String(formData.get('supplier_import_source') || ''),
	              feed_url: String(formData.get('supplier_import_feed_url') || ''),
	              stored_file: String(formData.get('supplier_import_stored_file') || ''),
	              stored_file_name: String(formData.get('supplier_import_stored_file_name') || ''),
	              ozon_connection_id: Number(formData.get('ozon_connection_id') || 0),
	              wb_connection_id: Number(formData.get('wb_connection_id') || 0),
	              scope: scope,
	              selected_offer_ids: selectedIds,
	              add_photos: !!(repairAddPhotosInput && repairAddPhotosInput.checked),
	              sync_source: true
	            });
	            let token = String(start.token || '');
	            let total = Number(start.total || 0);
	            setRepairProgress(0, total, start.stats || {}, total > 0 ? ('Подготовлено товаров: ' + total) : 'Нет товаров для проверки.');
	            let result = start;
	            while (token && total > 0) {
	              result = await postRepairJson({ action: 'batch', token: token, limit: 20 });
	              const offset = Number(result.offset || 0);
	              total = Number(result.total || total || 0);
	              setRepairProgress(offset, total, result.stats || {});
	              if (result.done) break;
	              await new Promise(function(resolve) { window.setTimeout(resolve, 120); });
	            }
	            setRepairProgress(Number((result && result.offset) || total || 0), Number((result && result.total) || total || 0), (result && result.stats) || start.stats || {}, 'Исправление фото завершено.');
	            if (repairClose) {
	              repairClose.hidden = false;
	              repairClose.textContent = Number(((result && result.stats) || {}).products_updated || 0) > 0 ? 'Обновить страницу' : 'Закрыть';
	            }
	          } catch (e) {
	            if (repairProgress) repairProgress.style.width = '100%';
	            if (repairStatus) repairStatus.textContent = e.message || 'Исправление фото не выполнено.';
	            if (repairStats) repairStats.textContent = '';
	            if (repairClose) {
	              repairClose.hidden = false;
	              repairClose.textContent = 'Закрыть';
	            }
	          } finally {
	            repairPhotosButton.disabled = false;
	          }
	        };
	        if (repairPhotosButton) {
	          repairPhotosButton.addEventListener('click', runRepairPhotos);
	        }
	        if (repairClose) {
	          repairClose.addEventListener('click', function() {
	            if (repairClose.textContent === 'Обновить страницу') {
	              window.location.reload();
	              return;
	            }
	            if (repairModal) repairModal.hidden = true;
	          });
	        }
	        try {
	          const nav = performance.getEntriesByType('navigation')[0];
	          if (nav && nav.type === 'reload' && checkResult && !currentSource()) {
	            checkResult.hidden = true;
	          }
	        } catch (e) {}
	        syncImportPanels();
	        syncImportConnectionInputs();
	        syncImportOptions();
	      }
		    });
		  </script>

      <?php if ($supplierProductsViewSidebarActions): ?>
        <script>
          document.addEventListener('DOMContentLoaded', function() {
            const body = document.body;
            const drawer = document.querySelector('[data-supplier-actions-drawer]');
            const openButton = document.querySelector('[data-supplier-actions-open]');
            const closeButtons = Array.from(document.querySelectorAll('[data-supplier-actions-close]'));
            if (!drawer || !openButton) return;

            const openDrawer = function() {
              body.classList.add('supplier-actions-open');
              drawer.setAttribute('aria-hidden', 'false');
              drawer.removeAttribute('inert');
              openButton.setAttribute('aria-expanded', 'true');
              closeButtons.forEach(function(button) {
                if (button.classList.contains('supplier-actions-backdrop')) button.hidden = false;
              });
              const activeTab = drawer.querySelector('[data-supplier-tab].is-active');
              const closeButton = drawer.querySelector('.supplier-actions-close');
              window.setTimeout(function() {
                (activeTab || closeButton || drawer).focus({ preventScroll: true });
              }, 40);
            };

            const closeDrawer = function() {
              body.classList.remove('supplier-actions-open');
              drawer.setAttribute('aria-hidden', 'true');
              drawer.setAttribute('inert', '');
              openButton.setAttribute('aria-expanded', 'false');
              closeButtons.forEach(function(button) {
                if (button.classList.contains('supplier-actions-backdrop')) button.hidden = true;
              });
              openButton.focus({ preventScroll: true });
            };

            openButton.addEventListener('click', openDrawer);
            closeButtons.forEach(function(button) {
              button.addEventListener('click', closeDrawer);
            });
            document.addEventListener('keydown', function(event) {
              if (event.key === 'Escape' && body.classList.contains('supplier-actions-open')) {
                closeDrawer();
              }
            });

            <?php if ($supplierImportSubmitted): ?>
              openDrawer();
            <?php endif; ?>
          });
        </script>
      <?php endif; ?>



