                <input type="text" data-bulk-bundle-size-factor value="2" placeholder="коэффициент">
              </div>
            </div>
            <div class="supplier-bundle-preview" data-bulk-bundle-preview></div>
            <div class="supplier-bundle-error" data-bulk-bundle-error></div>
            <div class="supplier-repair-modal-actions">
              <button type="button" class="btn-secondary" data-bulk-bundle-cancel>Отмена</button>
              <button type="submit" class="btn-primary" data-bulk-bundle-submit>Создать комплекты</button>
            </div>
          </form>
        </div>
      </div>

      <script>
        (function() {
          if (window.__ftSupplierOffersAjaxSortInit) return;
          window.__ftSupplierOffersAjaxSortInit = true;

          function sortLinkFromTarget(target) {
            if (!target || !target.closest) return null;
            const link = target.closest('.supplier-sort-link, .supplier-sort-menu-panel a');
            if (!link) return null;
            return link.closest('[data-offers-table-region]') ? link : null;
          }

          function updateFilterSortState(url) {
            try {
              const parsed = new URL(url, window.location.href);
              if (window.ftOffersFiltersConfig && typeof window.ftOffersFiltersConfig === 'object') {
                window.ftOffersFiltersConfig.sort = parsed.searchParams.get('sort') || '';
                window.ftOffersFiltersConfig.dir = parsed.searchParams.get('dir') || 'asc';
              }
            } catch (e) {}
          }

          let tableFetchController = null;
          let tableFetchSeq = 0;

          async function loadSortedTable(url) {
            const region = document.querySelector('[data-offers-table-region]');
            if (!region) {
              window.location.href = url;
              return;
            }
            const requestSeq = ++tableFetchSeq;
            if (tableFetchController) {
              try { tableFetchController.abort(); } catch (e) {}
            }
            const controller = window.AbortController ? new AbortController() : null;
            tableFetchController = controller;
            const tableWrap = region.querySelector('.offers-table-wrap');
            const scrollLeft = tableWrap ? tableWrap.scrollLeft : 0;
            region.classList.add('is-loading');
            try {
              const requestOptions = {
                method: 'GET',
                credentials: 'same-origin',
                headers: {
                  'Accept': 'text/html',
                  'X-Requested-With': 'XMLHttpRequest'
                }
              };
              if (controller) requestOptions.signal = controller.signal;
              const response = await fetch(url, requestOptions);
              if (requestSeq !== tableFetchSeq) return;
              if (!response.ok) {
                throw new Error('HTTP ' + response.status);
              }
              const html = await response.text();
              if (requestSeq !== tableFetchSeq) return;
              const doc = new DOMParser().parseFromString(html, 'text/html');
              const nextRegion = doc.querySelector('[data-offers-table-region]');
              if (!nextRegion) {
                throw new Error('Таблица не найдена в ответе.');
              }
              Array.from(nextRegion.attributes || []).forEach((attr) => {
                if (attr && String(attr.name || '').indexOf('data-') === 0) {
                  region.setAttribute(attr.name, attr.value);
                }
              });
              const filterCountChip = document.querySelector('.toolbar-card--filters > summary .count-chip');
              if (filterCountChip && nextRegion.dataset) {
                const filteredTotal = nextRegion.dataset.filteredTotal || '';
                const offersTotal = nextRegion.dataset.offersTotal || '';
                if (filteredTotal && offersTotal) {
                  filterCountChip.textContent = 'Показано: ' + filteredTotal + ' из ' + offersTotal;
                }
              }
              region.innerHTML = nextRegion.innerHTML;
              const nextWrap = region.querySelector('.offers-table-wrap');
              if (nextWrap) nextWrap.scrollLeft = scrollLeft;
              window.history.pushState({ supplierOffersTable: true }, '', url);
              updateFilterSortState(url);
              document.dispatchEvent(new CustomEvent('supplier-offers-table-replaced'));
            } catch (e) {
              if (e && e.name === 'AbortError') return;
              if (requestSeq !== tableFetchSeq) return;
              window.location.href = url;
            } finally {
              if (requestSeq === tableFetchSeq) {
                if (tableFetchController === controller) tableFetchController = null;
                region.classList.remove('is-loading');
              }
            }
          }

	          document.addEventListener('click', function(event) {
	            const link = sortLinkFromTarget(event.target);
	            if (!link) return;
            const href = link.getAttribute('href') || '';
            if (!href || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
	            event.preventDefault();
	            loadSortedTable(href);
	          });
	          window.ftSupplierOffersLoad = loadSortedTable;
	          window.ftSupplierOffersReload = function() {
	            return loadSortedTable(window.location.href);
	          };
	        })();
	      </script>

      <script>
        (function() {
          if (window.__ftSupplierOffersColumnResizeInit) return;
          window.__ftSupplierOffersColumnResizeInit = true;

	          const storageKey = 'ftSupplierOffersColumnWidths:v4:' +
            <?= json_encode((string)(function_exists('ft_current_user') ? (ft_current_user() ?? 'anonymous') : 'anonymous'), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?> +
            ':supplier-products-offers';
          let activeResize = null;
          let dragCandidate = null;
          let activeDrag = null;
          let suppressHeaderClickUntil = 0;

          function readColumnPrefs() {
            try {
              const raw = localStorage.getItem(storageKey);
              const parsed = raw ? JSON.parse(raw) : {};
              if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
                return { widths: {}, hidden: [], order: [] };
              }
              if (parsed.widths || parsed.hidden || parsed.order) {
                return {
                  widths: parsed.widths && typeof parsed.widths === 'object' && !Array.isArray(parsed.widths) ? parsed.widths : {},
                  hidden: Array.isArray(parsed.hidden) ? parsed.hidden.map(String) : [],
                  order: Array.isArray(parsed.order) ? parsed.order.map(String) : []
                };
              }
              return { widths: parsed, hidden: [], order: [] };
            } catch (e) {
              return { widths: {}, hidden: [], order: [] };
            }
          }

          function saveColumnPrefs(state) {
            try {
              localStorage.setItem(storageKey, JSON.stringify({
                widths: snapshotWidths(state),
                hidden: state ? Array.from(state.hidden || []) : [],
                order: state ? state.keys.slice() : []
              }));
            } catch (e) {}
          }

          function getMinWidth(th) {
            const raw = Number(th.getAttribute('data-col-min') || '60');
            return Number.isFinite(raw) && raw > 0 ? raw : 60;
          }

          function tableState(table) {
            return table && table.__supplierColumnResizeState ? table.__supplierColumnResizeState : null;
          }

          function isColumnHidden(state, key) {
            return !!(state && state.hidden && state.hidden.has(key) && key !== 'select');
          }

          function setCellHidden(cell, hidden) {
            if (!cell) return;
            if (hidden) {
              cell.setAttribute('data-col-hidden', '1');
            } else {
              cell.removeAttribute('data-col-hidden');
            }
          }

          function setCellWidth(cell, hidden, width, minWidth) {
            if (!cell) return;
            setCellHidden(cell, hidden);
            if (hidden) {
              cell.style.width = '';
              cell.style.minWidth = '';
              cell.style.maxWidth = '';
              return;
            }
            cell.style.width = width + 'px';
            cell.style.minWidth = minWidth + 'px';
            cell.style.maxWidth = '';
          }

          function normalizedColumnOrder(savedOrder, currentKeys) {
            const all = currentKeys.map(String).filter(Boolean);
            const set = new Set(all);
            const out = [];
            if (set.has('select')) out.push('select');
            (Array.isArray(savedOrder) ? savedOrder : []).map(String).forEach(key => {
              if (key && key !== 'select' && set.has(key) && !out.includes(key)) out.push(key);
            });
            all.forEach(key => {
              if (key && key !== 'select' && !out.includes(key)) out.push(key);
            });
            return out;
          }

          function applyColumnOrderToTable(table, order) {
            if (!table || !table.tHead || !table.tHead.rows.length || !order || !order.length) return;
            const currentHeaders = Array.from(table.tHead.rows[0].cells);
            const currentKeys = currentHeaders.map((th, index) => th.getAttribute('data-col-key') || String(index));
            const targetOrder = normalizedColumnOrder(order, currentKeys);
            const rows = [
              ...Array.from(table.tHead ? table.tHead.rows : []),
              ...Array.from(table.tBodies || []).flatMap(tbody => Array.from(tbody.rows || []))
            ];
            rows.forEach(row => {
              const cells = Array.from(row.cells || []);
              const byKey = new Map();
              currentKeys.forEach((key, index) => {
                if (cells[index]) byKey.set(key, cells[index]);
              });
              targetOrder.forEach(key => {
                const cell = byKey.get(key);
                if (cell) row.appendChild(cell);
              });
            });
          }

          function applyColumnWidths(state) {
            if (!state || !state.table) return;
            let total = 0;
            const rows = Array.from(state.table.querySelectorAll('tbody tr'));
            state.headers.forEach((th, index) => {
              const key = state.keys[index];
              const hidden = isColumnHidden(state, key);
              const minWidth = getMinWidth(th);
              const width = Math.max(minWidth, Math.round(Number(state.widths[key] || minWidth)));
              if (!hidden) total += width;
              th.dataset.colKey = key;
              setCellWidth(th, hidden, width, minWidth);
              rows.forEach(row => {
                const cell = row.children[index];
                if (cell) cell.dataset.colKey = key;
                setCellWidth(cell, hidden, width, minWidth);
              });
            });
            state.table.style.width = total + 'px';
            state.table.style.minWidth = total + 'px';
          }

          function snapshotWidths(state) {
            const saved = {};
            if (!state) return saved;
            state.keys.forEach(key => {
              saved[key] = Math.round(Number(state.widths[key] || 0));
            });
            return saved;
          }

          function columnLabel(th, key) {
            const label = String(th.getAttribute('data-col-title') || '').trim();
            if (label) return label;
            return String(th.textContent || key).trim() || key;
          }

          function renderColumnSettings(state) {
            const panel = document.querySelector('[data-column-settings-panel]');
            if (!panel || !state) return;
            panel.innerHTML = '';
            state.headers.forEach((th, index) => {
              const key = state.keys[index];
              if (!key || key === 'select') return;
              const label = document.createElement('label');
              label.className = 'supplier-column-settings-item';
              const input = document.createElement('input');
              input.type = 'checkbox';
              input.checked = !isColumnHidden(state, key);
              input.dataset.colKey = key;
              const text = document.createElement('span');
              text.textContent = columnLabel(th, key);
              input.addEventListener('change', function() {
                if (input.checked) {
                  state.hidden.delete(key);
                } else {
                  state.hidden.add(key);
                }
                applyColumnWidths(state);
                saveColumnPrefs(state);
              });
              label.appendChild(input);
              label.appendChild(text);
              panel.appendChild(label);
            });
          }

          function clearColumnDropMarkers(table) {
            if (!table) return;
            table.querySelectorAll('.supplier-column-drop-before, .supplier-column-drop-after, .supplier-column-dragging').forEach(node => {
              node.classList.remove('supplier-column-drop-before', 'supplier-column-drop-after', 'supplier-column-dragging');
            });
          }

          function initResizableOffersTable(force) {
            const table = document.getElementById('offersTable');
            if (!table || !table.tHead || !table.tHead.rows.length) return;
            if (force) {
              table.dataset.supplierResizeReady = '';
              table.querySelectorAll('.supplier-col-resizer').forEach(node => node.remove());
              table.querySelectorAll('th').forEach(th => {
                th.classList.remove('supplier-resizable-th', 'supplier-column-draggable', 'supplier-column-drop-before', 'supplier-column-drop-after', 'supplier-column-dragging');
              });
            }
            let headers = Array.from(table.tHead.rows[0].cells);
            if (!headers.length || table.dataset.supplierResizeReady === '1') return;

            const prefs = readColumnPrefs();
            const nativeKeys = headers.map((th, index) => th.getAttribute('data-col-key') || String(index));
            applyColumnOrderToTable(table, normalizedColumnOrder(prefs.order || [], nativeKeys));
            headers = Array.from(table.tHead.rows[0].cells);
            const saved = prefs.widths || {};
            const currentWidths = headers.map(th => Math.max(getMinWidth(th), Math.round(th.getBoundingClientRect().width || 0)));
            const keys = headers.map((th, index) => th.getAttribute('data-col-key') || String(index));
            table.querySelectorAll('colgroup[data-supplier-resize-colgroup="1"]').forEach(node => node.remove());
            const widths = {};
            const hidden = new Set((prefs.hidden || []).map(String).filter(key => key !== 'select'));

            headers.forEach((th, index) => {
              const key = keys[index];
              const savedWidth = Number(saved[key] || 0);
              const minWidth = getMinWidth(th);
              widths[key] = Number.isFinite(savedWidth) && savedWidth > 0
                ? Math.max(minWidth, Math.round(savedWidth))
                : Math.max(minWidth, currentWidths[index] || minWidth);
              th.classList.add('supplier-resizable-th');
              if (key !== 'select') {
                th.classList.add('supplier-column-draggable');
                th.title = th.title || 'Перетащить колонку';
              }
              th.querySelectorAll(':scope > .supplier-col-resizer').forEach(node => node.remove());
            });

            const state = { table, headers, keys, widths, hidden };
            table.__supplierColumnResizeState = state;
            table.dataset.supplierResizeReady = '1';
            applyColumnWidths(state);
            renderColumnSettings(state);

            headers.forEach((th, index) => {
              if (th.getAttribute('data-col-resizable') === '0') return;
              const handle = document.createElement('span');
              handle.className = 'supplier-col-resizer';
              handle.setAttribute('role', 'separator');
              handle.setAttribute('aria-orientation', 'vertical');
              handle.title = 'Изменить ширину колонки';
              handle.addEventListener('click', event => {
                event.preventDefault();
                event.stopPropagation();
              });
              handle.addEventListener('pointerdown', event => {
                if (event.button !== 0 && event.pointerType !== 'touch') return;
                event.preventDefault();
                event.stopPropagation();
                const freshState = tableState(table);
                if (!freshState) return;
                const key = freshState.keys[index];
                activeResize = {
                  state: freshState,
                  index,
                  key,
                  handle,
                  startX: event.clientX,
                  startWidth: Number(freshState.widths[key] || th.getBoundingClientRect().width || getMinWidth(th)),
                };
                handle.classList.add('is-active');
                table.classList.add('is-resizing-columns');
                document.body.classList.add('is-resizing-offers-col');
                try {
                  handle.setPointerCapture(event.pointerId);
                } catch (e) {}
              });
              th.appendChild(handle);
            });
          }

          function finishResize() {
            if (!activeResize) return;
            const { state, handle } = activeResize;
            handle.classList.remove('is-active');
            if (state && state.table) state.table.classList.remove('is-resizing-columns');
            document.body.classList.remove('is-resizing-offers-col');
            saveColumnPrefs(state);
            activeResize = null;
          }

          document.addEventListener('pointermove', event => {
            if (!activeResize) return;
            const { state, key, startX, startWidth } = activeResize;
            if (!state) return;
            const th = state.headers[activeResize.index];
            const minWidth = th ? getMinWidth(th) : 60;
            state.widths[key] = Math.max(minWidth, Math.round(startWidth + (event.clientX - startX)));
            applyColumnWidths(state);
          });

          function headerFromPoint(event, state) {
            if (!state || !state.table) return null;
            const node = document.elementFromPoint(event.clientX, event.clientY);
            const th = node && node.closest ? node.closest('#offersTable th[data-col-key]') : null;
            if (!th || !state.table.contains(th)) return null;
            const key = th.getAttribute('data-col-key') || '';
            if (!key || key === 'select') return null;
            const index = state.headers.indexOf(th);
            if (index < 0) return null;
            const rect = th.getBoundingClientRect();
            return {
              th,
              index,
              key,
              placement: event.clientX < rect.left + rect.width / 2 ? 'before' : 'after'
            };
          }

          function startColumnDrag(event) {
            if (!dragCandidate || dragCandidate.started) return;
            const { state, th } = dragCandidate;
            dragCandidate.started = true;
            activeDrag = dragCandidate;
            th.classList.add('supplier-column-dragging');
            state.table.classList.add('is-dragging-columns');
            document.body.classList.add('is-dragging-offers-col');
            try {
              th.setPointerCapture(event.pointerId);
            } catch (e) {}
          }

          function updateColumnDragTarget(event) {
            if (!activeDrag) return;
            clearColumnDropMarkers(activeDrag.state.table);
            activeDrag.th.classList.add('supplier-column-dragging');
            const target = headerFromPoint(event, activeDrag.state);
            if (!target || target.key === activeDrag.key) {
              activeDrag.target = null;
              return;
            }
            activeDrag.target = target;
            target.th.classList.add(target.placement === 'after' ? 'supplier-column-drop-after' : 'supplier-column-drop-before');
          }

          function moveColumn(state, fromKey, targetKey, placement) {
            if (!state || !state.table || !fromKey || !targetKey || fromKey === 'select' || targetKey === 'select' || fromKey === targetKey) return;
            const order = state.keys.slice();
            const fromIndex = order.indexOf(fromKey);
            if (fromIndex < 0) return;
            order.splice(fromIndex, 1);
            let targetIndex = order.indexOf(targetKey);
            if (targetIndex < 0) return;
            if (placement === 'after') targetIndex += 1;
            order.splice(targetIndex, 0, fromKey);
            const nextOrder = normalizedColumnOrder(order, state.keys);
            state.keys = nextOrder;
            applyColumnOrderToTable(state.table, nextOrder);
            saveColumnPrefs(state);
            initResizableOffersTable(true);
          }

          document.addEventListener('pointerdown', event => {
            const th = event.target && event.target.closest ? event.target.closest('#offersTable th[data-col-key]') : null;
            if (!th || th.getAttribute('data-col-key') === 'select') return;
            if (event.button !== 0 && event.pointerType !== 'touch') return;
            if (event.target.closest('.supplier-col-resizer, input, button, select, textarea, summary, details')) return;
            const table = th.closest('#offersTable');
            const state = tableState(table);
            if (!state || table.classList.contains('is-resizing-columns')) return;
            const index = state.headers.indexOf(th);
            if (index < 0) return;
            dragCandidate = {
              state,
              th,
              index,
              key: state.keys[index],
              startX: event.clientX,
              startY: event.clientY,
              pointerId: event.pointerId,
              started: false,
              target: null
            };
          });

          document.addEventListener('pointermove', event => {
            if (!dragCandidate || activeResize) return;
            const dx = Math.abs(event.clientX - dragCandidate.startX);
            const dy = Math.abs(event.clientY - dragCandidate.startY);
            if (!dragCandidate.started && (dx > 6 || dy > 6)) {
              startColumnDrag(event);
            }
            if (activeDrag) {
              event.preventDefault();
              updateColumnDragTarget(event);
            }
          });

          function finishColumnDrag() {
            if (!dragCandidate && !activeDrag) return;
            const finished = activeDrag;
            if (finished) {
              if (finished.target) {
                moveColumn(finished.state, finished.key, finished.target.key, finished.target.placement);
              }
              clearColumnDropMarkers(finished.state.table);
              finished.state.table.classList.remove('is-dragging-columns');
              document.body.classList.remove('is-dragging-offers-col');
              suppressHeaderClickUntil = Date.now() + 450;
            }
            dragCandidate = null;
            activeDrag = null;
          }

          document.addEventListener('pointerup', finishResize);
          document.addEventListener('pointercancel', finishResize);
          document.addEventListener('pointerup', finishColumnDrag);
          document.addEventListener('pointercancel', finishColumnDrag);
          document.addEventListener('click', event => {
            if (suppressHeaderClickUntil && Date.now() < suppressHeaderClickUntil && event.target && event.target.closest && event.target.closest('#offersTable th')) {
              event.preventDefault();
              event.stopImmediatePropagation();
            }
          }, true);
          document.addEventListener('supplier-offers-table-replaced', initResizableOffersTable);
          window.addEventListener('load', initResizableOffersTable);
          initResizableOffersTable();
        })();
      </script>

