  <script>
    (function() {
      const endpoint = 'supplier_product_update.php';

      function closestEditable(target) {
        if (!target || !target.closest) return null;
        return target.closest('.supplier-inline-edit--basic');
      }

      function editableValue(el) {
        if (!el) return '';
        if (el.dataset.rich === '1') {
          return (el.innerText || el.textContent || '').trim();
        }
        return el.textContent.trim();
      }

      function setState(container, message, isError) {
        if (!container) return;
        container.classList.toggle('is-error', !!isError);
        const state = container.querySelector('.supplier-edit-state');
        if (state) state.textContent = isError ? (message || '') : '';
      }

      async function postJson(payload) {
        const res = await fetch(endpoint, {
          method: 'POST',
          credentials: 'same-origin',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify(payload)
        });
        const data = await res.json().catch(function() {
          return null;
        });
        if (!res.ok || !data || !data.ok) {
          throw new Error((data && data.error) ? data.error : 'Не удалось сохранить изменения.');
        }
        return data;
      }

      function showSupplierRowSuccessToast() {
        let toast = document.querySelector('.supplier-success-toast');
        if (!toast) {
          toast = document.createElement('div');
          toast.className = 'supplier-success-toast';
          toast.setAttribute('aria-hidden', 'true');
          document.body.appendChild(toast);
        }
        if (toast._hideTimer) window.clearTimeout(toast._hideTimer);
        toast.classList.remove('is-busy');
        toast.textContent = '✓';
        toast.classList.add('is-visible');
        toast._hideTimer = window.setTimeout(function() {
          toast.classList.remove('is-visible');
        }, 3800);
      }

      const bundleModal = document.querySelector('[data-bundle-modal]');
      const bundleForm = bundleModal ? bundleModal.querySelector('[data-bundle-form]') : null;
      const bundleFields = bundleModal ? {
        productId: bundleModal.querySelector('[data-bundle-product-id]'),
        offerId: bundleModal.querySelector('[data-bundle-offer-id]'),
        qty: bundleModal.querySelector('[data-bundle-qty]'),
        name: bundleModal.querySelector('[data-bundle-name]'),
        length: bundleModal.querySelector('[data-bundle-length]'),
        width: bundleModal.querySelector('[data-bundle-width]'),
        height: bundleModal.querySelector('[data-bundle-height]'),
        weight: bundleModal.querySelector('[data-bundle-weight]'),
        preview: bundleModal.querySelector('[data-bundle-preview]'),
        error: bundleModal.querySelector('[data-bundle-error]'),
        submit: bundleModal.querySelector('[data-bundle-submit]')
      } : {};

      function bundleCreateQty() {
        const qty = parseInt(String(bundleFields.qty ? bundleFields.qty.value : '0'), 10);
        return Number.isFinite(qty) ? qty : 0;
      }

      function updateBundlePreview() {
        if (!bundleFields.preview) return;
        const baseOfferId = String(bundleFields.offerId ? bundleFields.offerId.value : '').trim();
        const qty = bundleCreateQty();
        if (!baseOfferId || qty < 2) {
          bundleFields.preview.textContent = 'Укажи количество больше 1.';
          return;
        }
        bundleFields.preview.textContent = 'Будет создан артикул: ' + qty + '##' + baseOfferId + '. Характеристика количества в единице товара будет равна ' + qty + '. Фото будет скопировано без изменений.';
      }

      function closeBundleModal() {
        if (!bundleModal) return;
        bundleModal.hidden = true;
        if (bundleFields.error) bundleFields.error.textContent = '';
      }

      function openBundleModal(button) {
        if (!bundleModal || !bundleForm || !button || button.disabled) return;
        if (bundleFields.productId) bundleFields.productId.value = String(button.dataset.productId || '').trim();
        if (bundleFields.offerId) bundleFields.offerId.value = String(button.dataset.offerId || '').trim();
        if (bundleFields.qty) bundleFields.qty.value = '2';
        if (bundleFields.name) bundleFields.name.value = String(button.dataset.name || '').trim();
        if (bundleFields.length) bundleFields.length.value = String(button.dataset.length || '').trim();
        if (bundleFields.width) bundleFields.width.value = String(button.dataset.width || '').trim();
        if (bundleFields.height) bundleFields.height.value = String(button.dataset.height || '').trim();
        if (bundleFields.weight) bundleFields.weight.value = String(button.dataset.weight || '').trim();
        if (bundleFields.error) bundleFields.error.textContent = '';
        updateBundlePreview();
        bundleModal.hidden = false;
        window.setTimeout(function() {
          if (bundleFields.qty) bundleFields.qty.focus();
        }, 0);
      }

      if (bundleFields.qty) {
        bundleFields.qty.addEventListener('input', updateBundlePreview);
      }
      if (bundleModal) {
        bundleModal.addEventListener('click', function(event) {
          if (event.target === bundleModal || (event.target && event.target.closest && event.target.closest('[data-bundle-cancel]'))) {
            event.preventDefault();
            closeBundleModal();
          }
        });
      }
      if (bundleForm) {
        bundleForm.addEventListener('submit', async function(event) {
          event.preventDefault();
          const productId = parseInt(String(bundleFields.productId ? bundleFields.productId.value : '0'), 10) || 0;
          const qty = bundleCreateQty();
          const name = String(bundleFields.name ? bundleFields.name.value : '').trim();
          if (!productId || qty < 2 || !name) {
            if (bundleFields.error) bundleFields.error.textContent = 'Заполни товар, количество и название комплекта.';
            return;
          }
          const submit = bundleFields.submit;
          const oldText = submit ? submit.textContent : '';
          if (submit) {
            submit.disabled = true;
            submit.textContent = 'Создаю...';
          }
          if (bundleFields.error) bundleFields.error.textContent = '';
          try {
            await postJson({
              action: 'bundle_create',
              product_id: productId,
              qty: qty,
              name: name,
              length: bundleFields.length ? bundleFields.length.value : '',
              width: bundleFields.width ? bundleFields.width.value : '',
              height: bundleFields.height ? bundleFields.height.value : '',
              weight: bundleFields.weight ? bundleFields.weight.value : ''
            });
            showSupplierRowSuccessToast();
            closeBundleModal();
            if (window.ftSupplierOffersReload) {
              await window.ftSupplierOffersReload();
            } else {
              window.location.reload();
            }
          } catch (err) {
            if (bundleFields.error) bundleFields.error.textContent = (err && err.message) ? err.message : 'Не удалось создать комплект.';
          } finally {
            if (submit) {
              submit.disabled = false;
              submit.textContent = oldText;
            }
          }
        });
      }

      const bulkBundleModal = document.querySelector('[data-bulk-bundle-modal]');
      const bulkBundleForm = bulkBundleModal ? bulkBundleModal.querySelector('[data-bulk-bundle-form]') : null;
      const bulkBundleFields = bulkBundleModal ? {
        qty: bulkBundleModal.querySelector('[data-bulk-bundle-qty]'),
        prefixEnabled: bulkBundleModal.querySelector('[data-bulk-bundle-prefix-enabled]'),
        prefix: bulkBundleModal.querySelector('[data-bulk-bundle-prefix]'),
        suffixEnabled: bulkBundleModal.querySelector('[data-bulk-bundle-suffix-enabled]'),
        suffix: bulkBundleModal.querySelector('[data-bulk-bundle-suffix]'),
        weightFixed: bulkBundleModal.querySelector('[data-bulk-bundle-weight-fixed]'),
        weightFactor: bulkBundleModal.querySelector('[data-bulk-bundle-weight-factor]'),
        lengthFixed: bulkBundleModal.querySelector('[data-bulk-bundle-length-fixed]'),
        widthFixed: bulkBundleModal.querySelector('[data-bulk-bundle-width-fixed]'),
        heightFixed: bulkBundleModal.querySelector('[data-bulk-bundle-height-fixed]'),
        sizeFactor: bulkBundleModal.querySelector('[data-bulk-bundle-size-factor]'),
        preview: bulkBundleModal.querySelector('[data-bulk-bundle-preview]'),
        error: bulkBundleModal.querySelector('[data-bulk-bundle-error]'),
        submit: bulkBundleModal.querySelector('[data-bulk-bundle-submit]')
      } : {};
      let bulkBundleSuffixAuto = true;

      function bulkBundleQty() {
        const qty = parseInt(String(bulkBundleFields.qty ? bulkBundleFields.qty.value : '0'), 10);
        return Number.isFinite(qty) ? qty : 0;
      }

      function bulkBundleScope() {
        return 'selected';
      }

      function bulkBundleMode(name, fallback) {
        const checked = bulkBundleModal ? bulkBundleModal.querySelector('input[name="' + name + '"]:checked') : null;
        return checked ? String(checked.value || fallback) : fallback;
      }

      function bulkBundleDefaultSuffix() {
        const qty = Math.max(2, bulkBundleQty() || 2);
        return ' комплект из ' + qty + ' шт';
      }

      function syncBulkBundleSuffix() {
        if (bulkBundleSuffixAuto && bulkBundleFields.suffix) {
          bulkBundleFields.suffix.value = bulkBundleDefaultSuffix();
        }
      }

      function updateBulkBundleInputs() {
        const weightMode = bulkBundleMode('supplier_bulk_bundle_weight_mode', 'keep');
        const sizeMode = bulkBundleMode('supplier_bulk_bundle_size_mode', 'keep');
        if (bulkBundleFields.weightFixed) bulkBundleFields.weightFixed.disabled = weightMode !== 'fixed';
        if (bulkBundleFields.weightFactor) bulkBundleFields.weightFactor.disabled = weightMode !== 'multiply';
        ['lengthFixed', 'widthFixed', 'heightFixed'].forEach(function(key) {
          if (bulkBundleFields[key]) bulkBundleFields[key].disabled = sizeMode !== 'fixed';
        });
        if (bulkBundleFields.sizeFactor) bulkBundleFields.sizeFactor.disabled = sizeMode !== 'multiply_min_side';
      }

      function updateBulkBundlePreview() {
        if (!bulkBundleFields.preview) return;
        syncBulkBundleSuffix();
        const qty = bulkBundleQty();
        const scope = bulkBundleScope();
        const selectedCount = selectedOfferIdsForBulkCategory().length;
        if (qty < 2) {
          bulkBundleFields.preview.textContent = 'Укажи количество больше 1.';
          return;
        }
        const scopeText = selectedCount > 0 ? ('для выбранных товаров: ' + selectedCount) : 'для выбранных товаров';
        const nameParts = [];
        if (bulkBundleFields.prefixEnabled && bulkBundleFields.prefixEnabled.checked && bulkBundleFields.prefix && bulkBundleFields.prefix.value !== '') {
          nameParts.push('добавить текст в начало');
        }
        if (bulkBundleFields.suffixEnabled && bulkBundleFields.suffixEnabled.checked && bulkBundleFields.suffix && bulkBundleFields.suffix.value !== '') {
          nameParts.push('добавить текст в конец');
        }
        bulkBundleFields.preview.textContent = 'Будут созданы артикулы формата ' + qty + '##исходный_артикул ' + scopeText + '. ' + (nameParts.length ? ('Название: ' + nameParts.join(', ') + '. ') : '') + 'Фото будет скопировано без изменений.';
      }

      function openBulkBundleModal() {
        if (!bulkBundleModal || !bulkBundleForm) return;
        if (bulkBundleFields.qty) bulkBundleFields.qty.value = '2';
        if (bulkBundleFields.prefixEnabled) bulkBundleFields.prefixEnabled.checked = false;
        if (bulkBundleFields.prefix) bulkBundleFields.prefix.value = '';
        if (bulkBundleFields.suffixEnabled) bulkBundleFields.suffixEnabled.checked = true;
        bulkBundleSuffixAuto = true;
        syncBulkBundleSuffix();
        if (bulkBundleFields.weightFixed) bulkBundleFields.weightFixed.value = '';
        if (bulkBundleFields.weightFactor) bulkBundleFields.weightFactor.value = '2';
        if (bulkBundleFields.lengthFixed) bulkBundleFields.lengthFixed.value = '';
        if (bulkBundleFields.widthFixed) bulkBundleFields.widthFixed.value = '';
        if (bulkBundleFields.heightFixed) bulkBundleFields.heightFixed.value = '';
        if (bulkBundleFields.sizeFactor) bulkBundleFields.sizeFactor.value = '2';
        if (bulkBundleFields.error) bulkBundleFields.error.textContent = '';
        if (bulkBundleModal.querySelector('input[name="supplier_bulk_bundle_weight_mode"][value="keep"]')) {
          bulkBundleModal.querySelector('input[name="supplier_bulk_bundle_weight_mode"][value="keep"]').checked = true;
        }
        if (bulkBundleModal.querySelector('input[name="supplier_bulk_bundle_size_mode"][value="keep"]')) {
          bulkBundleModal.querySelector('input[name="supplier_bulk_bundle_size_mode"][value="keep"]').checked = true;
        }
        updateBulkBundleInputs();
        updateBulkBundlePreview();
        bulkBundleModal.hidden = false;
        window.setTimeout(function() {
          if (bulkBundleFields.qty) bulkBundleFields.qty.focus();
        }, 0);
      }

      function closeBulkBundleModal() {
        if (!bulkBundleModal) return;
        bulkBundleModal.hidden = true;
        if (bulkBundleFields.error) bulkBundleFields.error.textContent = '';
      }

      function bulkBundleStatsMessage(stats) {
        stats = stats || {};
        const parts = [
          'создано: ' + (parseInt(String(stats.created || 0), 10) || 0),
          'уже были: ' + (parseInt(String(stats.skipped_existing || 0), 10) || 0),
          'пропущено комплектов: ' + (parseInt(String(stats.skipped_bundles || 0), 10) || 0)
        ];
        const failed = parseInt(String(stats.failed || 0), 10) || 0;
        if (failed > 0) parts.push('ошибок: ' + failed);
        return parts.join(', ');
      }

      if (bulkBundleModal) {
        bulkBundleModal.addEventListener('click', function(event) {
          if (event.target === bulkBundleModal || (event.target && event.target.closest && event.target.closest('[data-bulk-bundle-cancel]'))) {
            event.preventDefault();
            closeBulkBundleModal();
          }
        });
        bulkBundleModal.addEventListener('change', function(event) {
          const target = event.target;
          if (!target || !target.matches) return;
          if (target.matches('input[name="supplier_bulk_bundle_weight_mode"], input[name="supplier_bulk_bundle_size_mode"]')) {
            updateBulkBundleInputs();
          }
          updateBulkBundlePreview();
        });
        bulkBundleModal.addEventListener('input', function(event) {
          const target = event.target;
          if (target === bulkBundleFields.suffix) {
            bulkBundleSuffixAuto = false;
          }
          updateBulkBundlePreview();
        });
      }
      document.addEventListener('supplier-selection-change', function() {
        if (bulkBundleModal && !bulkBundleModal.hidden) {
          updateBulkBundlePreview();
        }
      });

      if (bulkBundleForm) {
        bulkBundleForm.addEventListener('submit', async function(event) {
          event.preventDefault();
          const qty = bulkBundleQty();
          const scope = bulkBundleScope();
          const offerIds = selectedOfferIdsForBulkCategory();
          if (qty < 2) {
            if (bulkBundleFields.error) bulkBundleFields.error.textContent = 'Количество в комплекте должно быть больше 1.';
            return;
          }
          if (!offerIds.length) {
            if (bulkBundleFields.error) bulkBundleFields.error.textContent = 'Сначала выбери товары для создания комплектов.';
            return;
          }
          const submit = bulkBundleFields.submit;
          const oldText = submit ? submit.textContent : '';
          if (submit) {
            submit.disabled = true;
            submit.textContent = 'Создаю...';
          }
          if (bulkBundleFields.error) bulkBundleFields.error.textContent = '';
          try {
            const data = await postJson({
              action: 'bulk_bundle_create',
              dataset_id: <?= json_encode((int)$row['id']) ?>,
              offer_ids: offerIds,
              scope: scope,
              qty: qty,
              options: {
                name_prefix_enabled: !!(bulkBundleFields.prefixEnabled && bulkBundleFields.prefixEnabled.checked),
                name_prefix_text: bulkBundleFields.prefix ? bulkBundleFields.prefix.value : '',
                name_suffix_enabled: !!(bulkBundleFields.suffixEnabled && bulkBundleFields.suffixEnabled.checked),
                name_suffix_text: bulkBundleFields.suffix ? bulkBundleFields.suffix.value : '',
                weight_mode: bulkBundleMode('supplier_bulk_bundle_weight_mode', 'keep'),
                weight_fixed: bulkBundleFields.weightFixed ? bulkBundleFields.weightFixed.value : '',
                weight_factor: bulkBundleFields.weightFactor ? bulkBundleFields.weightFactor.value : '',
                size_mode: bulkBundleMode('supplier_bulk_bundle_size_mode', 'keep'),
                length_fixed: bulkBundleFields.lengthFixed ? bulkBundleFields.lengthFixed.value : '',
                width_fixed: bulkBundleFields.widthFixed ? bulkBundleFields.widthFixed.value : '',
                height_fixed: bulkBundleFields.heightFixed ? bulkBundleFields.heightFixed.value : '',
                size_factor: bulkBundleFields.sizeFactor ? bulkBundleFields.sizeFactor.value : ''
              }
            });
            const message = bulkBundleStatsMessage(data.stats || {});
            showSupplierRowSuccessToast();
            if ((data.stats && (parseInt(String(data.stats.failed || 0), 10) || 0) > 0) || (data.errors && data.errors.length)) {
              const firstError = data.errors && data.errors.length ? (' Первая ошибка: ' + data.errors[0].offer_id + ': ' + data.errors[0].error) : '';
              if (bulkBundleFields.error) bulkBundleFields.error.textContent = message + '.' + firstError;
            } else {
              closeBulkBundleModal();
            }
            if (window.ftSupplierOffersReload) {
              await window.ftSupplierOffersReload();
            } else {
              window.location.reload();
            }
          } catch (err) {
            if (bulkBundleFields.error) bulkBundleFields.error.textContent = (err && err.message) ? err.message : 'Не удалось создать комплекты.';
          } finally {
            if (submit) {
              submit.disabled = false;
              submit.textContent = oldText;
            }
          }
        });
      }

      function formatOfferMoney(value) {
        if (value === null || typeof value === 'undefined' || value === '') return '';
        const num = Number(value);
        if (!Number.isFinite(num)) return String(value || '').trim();
        if (Math.abs(num - Math.round(num)) < 0.0001) return String(Math.round(num));
        return num.toFixed(2).replace(/\.?0+$/, '');
      }

      function applyOfferControlsResponse(row, product) {
        if (!row || !product) return;
        const controls = row.querySelector('[data-offer-control]');
        const enabled = Object.prototype.hasOwnProperty.call(product, 'marketplace_enabled') ? (Number(product.marketplace_enabled) !== 0) : null;
        if (controls && enabled !== null) {
          controls.classList.toggle('is-enabled', enabled);
          controls.classList.toggle('is-disabled', !enabled);
          const checkbox = controls.querySelector('[data-offer-control-enabled]');
          const label = controls.querySelector('.supplier-offer-sale-label');
          if (checkbox) checkbox.checked = enabled;
          if (label) label.textContent = enabled ? 'в продаже' : 'снят';
        }
        if (controls && Object.prototype.hasOwnProperty.call(product, 'stock_modifier')) {
          const stockInput = controls.querySelector('[data-offer-control-stock]');
          if (stockInput) stockInput.value = String(product.stock_modifier || 0);
        }
        if (controls && Object.prototype.hasOwnProperty.call(product, 'price_modifier')) {
          const priceInput = controls.querySelector('[data-offer-control-price]');
          if (priceInput) priceInput.value = String(product.price_modifier || '');
        }
        if (Object.prototype.hasOwnProperty.call(product, 'effective_stock')) {
          const stockCell = row.querySelector('[data-offer-stock-cell]');
          if (stockCell) stockCell.textContent = String(product.effective_stock || 0);
        }
        if (Object.prototype.hasOwnProperty.call(product, 'effective_price')) {
          const priceCell = row.querySelector('[data-offer-price-cell]');
          if (priceCell) {
            const text = formatOfferMoney(product.effective_price);
            priceCell.innerHTML = text ? text : '<span class="muted">—</span>';
          }
        }
      }

      function applyProductResponse(row, product) {
        if (!row || !product) return;
        const checkbox = row.querySelector('.offerChk');
        if (checkbox && Object.prototype.hasOwnProperty.call(product, 'offer_id')) {
          checkbox.dataset.offerId = String(product.offer_id || '');
          checkbox.disabled = String(product.offer_id || '').trim() === '';
        }
        if (Object.prototype.hasOwnProperty.call(product, 'brand_effective') || Object.prototype.hasOwnProperty.call(product, 'brand')) {
          row.dataset.brand = String(product.brand_effective || product.brand || '');
        }
        if (Object.prototype.hasOwnProperty.call(product, 'brand_ozon_effective') || Object.prototype.hasOwnProperty.call(product, 'brand_ozon')) {
          row.dataset.brandOzon = String(product.brand_ozon_effective || product.brand_ozon || product.brand_effective || product.brand || '');
        }
        if (Object.prototype.hasOwnProperty.call(product, 'brand_wb_effective') || Object.prototype.hasOwnProperty.call(product, 'brand_wb')) {
          row.dataset.brandWb = String(product.brand_wb_effective || product.brand_wb || product.brand_effective || product.brand || '');
        }
        if (Object.prototype.hasOwnProperty.call(product, 'brand_statuses')) {
          renderBrandStatuses(row, product.brand_statuses || {});
        }
        applyOfferControlsResponse(row, product);
      }

      function offerControlPayload(cell) {
        const row = cell ? cell.closest('tr[data-product-id]') : null;
        const productId = parseInt(String((cell && cell.dataset.productId) || (row && row.dataset.productId) || '0'), 10) || 0;
        const enabledInput = cell ? cell.querySelector('[data-offer-control-enabled]') : null;
        const stockInput = cell ? cell.querySelector('[data-offer-control-stock]') : null;
        const priceInput = cell ? cell.querySelector('[data-offer-control-price]') : null;
        return {
          action: 'offer_controls_update',
          product_id: productId,
          marketplace_enabled: enabledInput && enabledInput.checked ? 1 : 0,
          stock_modifier: stockInput ? String(stockInput.value || '').trim() : '0',
          price_modifier: priceInput ? String(priceInput.value || '').trim() : ''
        };
      }

      function setOfferControlState(cell, message, isError) {
        const state = cell ? cell.querySelector('[data-offer-control-state]') : null;
        if (!state) return;
        state.textContent = message || '';
        state.classList.toggle('is-error', !!isError);
      }

      async function saveOfferControls(cell) {
        if (!cell || cell.classList.contains('is-saving')) return;
        const payload = offerControlPayload(cell);
        if (!payload.product_id) return;
        cell.classList.add('is-saving');
        setOfferControlState(cell, 'сохраняю...', false);
        try {
          const data = await postJson(payload);
          applyProductResponse(cell.closest('tr'), data.product);
          setOfferControlState(cell, 'сохранено', false);
          window.setTimeout(function() {
            if (cell && !cell.querySelector('[data-offer-control-state].is-error')) {
              setOfferControlState(cell, '', false);
            }
          }, 1200);
          showSupplierRowSuccessToast();
        } catch (err) {
          setOfferControlState(cell, (err && err.message) ? err.message : 'Ошибка сохранения', true);
        } finally {
          cell.classList.remove('is-saving');
        }
      }

      document.addEventListener('change', function(event) {
        const target = event.target;
        if (!target || !target.closest) return;
        const cell = target.closest('[data-offer-control]');
        if (!cell) return;
        if (target.matches('[data-offer-control-enabled]')) {
          const enabled = !!target.checked;
          cell.classList.toggle('is-enabled', enabled);
          cell.classList.toggle('is-disabled', !enabled);
          const label = cell.querySelector('.supplier-offer-sale-label');
          if (label) label.textContent = enabled ? 'в продаже' : 'снят';
          saveOfferControls(cell);
        }
      });

      document.addEventListener('keydown', function(event) {
        const target = event.target;
        if (!target || !target.closest) return;
        if (!target.matches('[data-offer-control-stock], [data-offer-control-price]')) return;
        if (event.key === 'Enter') {
          event.preventDefault();
          saveOfferControls(target.closest('[data-offer-control]'));
          target.blur();
        }
      });

      document.addEventListener('blur', function(event) {
        const target = event.target;
        if (!target || !target.closest) return;
        if (!target.matches('[data-offer-control-stock], [data-offer-control-price]')) return;
        saveOfferControls(target.closest('[data-offer-control]'));
      }, true);

      function brandStatusLabel(status) {
        const map = {
          ok: 'OK',
          missing_brand: 'ошибка бренда',
          category_not_selected: 'категория не выбрана',
          category_mismatch: 'категория не подходит',
          not_found: 'бренд не существует'
        };
        return map[status] || status || '';
      }

      function marketplaceRowActionSummary(data, marketplace, mode) {
        const result = data && data.result ? data.result : {};
        const inline = result && result.summary_json_inline ? result.summary_json_inline : {};
        const metrics = inline && inline.metrics ? inline.metrics : {};
        const items = Array.isArray(inline.items) ? inline.items.map(function(item) {
          return String(item || '').trim();
        }).filter(Boolean) : [];
        const skipped = Array.isArray(metrics.skipped) ? metrics.skipped : [];
        const responseErrors = [];
        (Array.isArray(metrics.responses) ? metrics.responses : []).forEach(function(response) {
          if (response && response.error) responseErrors.push(String(response.error));
        });
        let tone = 'success';
        if (responseErrors.length) {
          tone = 'error';
        } else if (skipped.length || (marketplace === 'wb' && mode === 'push' && (parseInt(String(metrics.cards_created || 0), 10) || 0) > 0)) {
          tone = 'warn';
        }
        const lines = items.length ? items.slice(0, 10) : [
          (marketplace === 'wb' ? 'WB' : 'Ozon') + ': действие выполнено.'
        ];
        if (!items.length && skipped.length) {
          lines.push('Предупреждение: ' + String(skipped[0] || ''));
        }
        if (!items.length && responseErrors.length) {
          lines.push('Ошибка: ' + responseErrors[0]);
        }
        return { tone: tone, lines: lines };
      }

      function renderMarketplaceRowActionFeedback(group, summary) {
        if (!group || !summary) return;
        let box = group.querySelector('[data-market-row-feedback]');
        if (!box) {
          box = document.createElement('div');
          box.className = 'supplier-row-action-feedback';
          box.setAttribute('data-market-row-feedback', '1');
          group.appendChild(box);
        }
        box.hidden = false;
        box.className = 'supplier-row-action-feedback';
        if (summary.tone === 'warn') box.classList.add('supplier-row-action-feedback--warn');
        if (summary.tone === 'error') box.classList.add('supplier-row-action-feedback--error');
        box.textContent = (summary.lines || []).join('\n');
      }

      function showSupplierActionNotice(summary) {
        if (!summary || !summary.lines || !summary.lines.length) return;
        let notice = document.querySelector('.supplier-action-notice');
        if (!notice) {
          notice = document.createElement('div');
          notice.className = 'supplier-action-notice';
          notice.setAttribute('role', 'status');
          document.body.appendChild(notice);
        }
        if (notice._hideTimer) window.clearTimeout(notice._hideTimer);
        notice.className = 'supplier-action-notice';
        if (summary.tone === 'warn') notice.classList.add('supplier-action-notice--warn');
        if (summary.tone === 'error') notice.classList.add('supplier-action-notice--error');
        notice.textContent = summary.lines.join('\n');
        notice._hideTimer = window.setTimeout(function() {
          if (notice && notice.parentNode) notice.parentNode.removeChild(notice);
        }, summary.tone === 'success' ? 7000 : 16000);
      }

      async function runMarketplaceRowAction(button) {
        if (!button || button.disabled) return;
        const row = button.closest('tr');
        const productId = parseInt(button.dataset.productId || (row ? row.dataset.productId : '0') || '0', 10);
        const offerId = String(button.dataset.offerId || (row ? ((row.querySelector('.offerChk') || {}).dataset || {}).offerId : '') || '').trim();
        const marketplace = String(button.dataset.marketplace || '').trim();
        const mode = String(button.dataset.mode || '').trim();
        const connectionSelectId = marketplace === 'wb' ? 'datasetWbConnectionSelect' : 'datasetOzonConnectionSelect';
        const connectionSelect = document.getElementById(connectionSelectId);
        const connectionId = parseInt(String(connectionSelect ? connectionSelect.value : '0'), 10) || 0;
        if (!productId && !offerId) {
          alert('Не указан товар.');
          return;
        }
        if (connectionId <= 0) {
          alert((marketplace === 'wb' ? 'WB' : 'Ozon') + ': подключение не выбрано.');
          return;
        }
        const oldText = button.textContent;
        const group = button.closest('[data-market-row-actions]');
        const feedback = group ? group.querySelector('[data-market-row-feedback]') : null;
        if (feedback) feedback.hidden = true;
        const buttons = group ? Array.from(group.querySelectorAll('[data-market-row-action]')) : [button];
        buttons.forEach(function(btn) {
          btn.disabled = true;
        });
        button.classList.add('is-busy');
        button.textContent = 'выполняю...';
        try {
          const data = await postJson({
            action: 'marketplace_row_action',
            dataset_id: <?= json_encode((int)$row['id']) ?>,
            product_id: productId,
            offer_id: offerId,
            marketplace: marketplace,
            mode: mode,
            connection_id: connectionId
          });
          if (row && data.product) {
            applyProductResponse(row, data.product);
          }
          const summary = marketplaceRowActionSummary(data, marketplace, mode);
          renderMarketplaceRowActionFeedback(group, summary);
          showSupplierActionNotice(summary);
          if (summary.tone === 'success') {
            showSupplierRowSuccessToast();
          }
          if (window.ftSupplierOffersReload) {
            await window.ftSupplierOffersReload();
          }
        } catch (err) {
          const summary = {
            tone: 'error',
            lines: [(err && err.message) ? err.message : 'Не удалось выполнить действие.']
          };
          renderMarketplaceRowActionFeedback(group, summary);
          showSupplierActionNotice(summary);
        } finally {
          button.classList.remove('is-busy');
          button.textContent = oldText;
          buttons.forEach(function(btn) {
            btn.disabled = false;
          });
        }
      }

      function renderBrandStatuses(row, statuses) {
        if (!row) return;
        const box = row.querySelector('[data-brand-statuses]');
        if (!box) return;
        [
          ['ozon', 'Ozon'],
          ['wb', 'WB']
        ].forEach(function(pair) {
          const source = pair[0];
          const item = statuses && statuses[source] ? statuses[source] : null;
          const status = item ? String(item.status || '').trim() : '';
          const label = item ? String(item.label || brandStatusLabel(status)).trim() : '';
          const slot = box.querySelector('[data-brand-status-slot="' + source + '"]');
          if (!slot) return;
          slot.innerHTML = '';
          if (!status || !label) {
            const empty = document.createElement('span');
            empty.className = 'muted';
            empty.textContent = '—';
            slot.appendChild(empty);
            return;
          }
          const badge = document.createElement('span');
          badge.className = 'supplier-brand-status supplier-brand-status--' + status.replace(/_/g, '-').replace(/[^a-z0-9_-]+/gi, '-');
          badge.dataset.brandStatusSource = source;
          badge.dataset.brandStatus = status;
          badge.textContent = label;
          slot.appendChild(badge);
        });
      }

      function closeBrandSuggestionPanels() {
        document.querySelectorAll('.supplier-brand-suggest-panel.open').forEach(function(panel) {
          panel.classList.remove('open');
          panel.__brandSuggestEditor = null;
          panel.style.left = '';
          panel.style.right = '';
          panel.style.top = '';
          panel.style.bottom = '';
          panel.style.width = '';
          panel.style.maxHeight = '';
        });
      }

      function positionBrandSuggestionPanel(editor) {
        if (!editor) return;
        const panel = editor.querySelector('[data-brand-suggest-panel]');
        const row = brandEditorFieldRow(editor);
        const anchor = row ? (row.querySelector('.supplier-field-value') || row.querySelector('.supplier-field-display') || row) : (editor.querySelector('.supplier-brand-input-slot') || editor.querySelector('.supplier-brand-input-row'));
        if (!panel || !anchor || !anchor.getBoundingClientRect) return;
        const rect = anchor.getBoundingClientRect();
        const pad = 10;
        const gap = 5;
        const width = Math.min(Math.max(Math.round(rect.width), 190), Math.max(190, window.innerWidth - pad * 2));
        let left = Math.round(rect.left);
        if (left + width > window.innerWidth - pad) {
          left = window.innerWidth - pad - width;
        }
        if (left < pad) left = pad;

        panel.style.position = 'fixed';
        panel.style.width = width + 'px';
        panel.style.maxHeight = Math.min(280, Math.max(160, window.innerHeight - pad * 2)) + 'px';
        panel.style.left = left + 'px';
        panel.style.right = 'auto';
        panel.style.top = '0px';
        panel.style.bottom = 'auto';

        const panelHeight = Math.min(panel.getBoundingClientRect().height || 220, parseInt(panel.style.maxHeight || '280', 10) || 280);
        const below = window.innerHeight - rect.bottom - pad - gap;
        const above = rect.top - pad - gap;
        let top = rect.bottom + gap;
        if (below < Math.min(panelHeight, 180) && above > below) {
          top = Math.max(pad, rect.top - panelHeight - gap);
        } else {
          top = Math.min(top, window.innerHeight - pad - panelHeight);
        }
        panel.style.top = Math.max(pad, Math.round(top)) + 'px';
      }

      function brandEditorFieldRow(editor) {
        const fieldName = editor ? String(editor.dataset.brandFieldName || 'brand').trim() : 'brand';
        return editor ? editor.querySelector('.supplier-field-row[data-kind="standard"][data-field-name="' + fieldName.replace(/"/g, '\\"') + '"]') : null;
      }

      function brandEditorValue(editor) {
        const row = brandEditorFieldRow(editor);
        if (!row) return '';
        initFieldRow(row);
        const valueEl = row.querySelector('.supplier-field-value');
        return valueEl ? valueEl.textContent.trim() : fieldValueFromDisplay(row);
      }

      function brandEditorOriginalValue(editor) {
        const row = brandEditorFieldRow(editor);
        if (!row) return '';
        initFieldRow(row);
        const valueEl = row.querySelector('.supplier-field-value');
        return valueEl ? String(valueEl.dataset.originalValue || valueEl.textContent || '').trim() : brandEditorValue(editor);
      }

      function brandEditorProductId(editor) {
        const fieldsEditor = editor ? editor.querySelector('.supplier-fields-editor[data-product-id]') : null;
        if (fieldsEditor) return parseInt(fieldsEditor.dataset.productId || '0', 10) || 0;
        const tr = editor ? editor.closest('tr[data-product-id]') : null;
        return tr ? (parseInt(tr.dataset.productId || '0', 10) || 0) : 0;
      }

      function sameTextFold(a, b) {
        return String(a || '').trim().replace(/\s+/g, ' ') === String(b || '').trim().replace(/\s+/g, ' ');
      }

      function brandEditorCategoryContext(editor) {
        const row = editor ? editor.closest('tr') : null;
        const marketplace = editor ? String(editor.dataset.brandMarketplace || '').trim() : '';
        const ozon = row ? String(row.dataset.ozoncat || '').trim() : '';
        const wb = row ? String(row.dataset.wbcat || '').trim() : '';
        return {
          marketplace: marketplace,
          ozon: marketplace === 'wb' ? '' : ozon,
          wb: marketplace === 'ozon' ? '' : wb
        };
      }

      function setBrandSuggestStatus(editor, message, isError) {
        const results = editor ? editor.querySelector('[data-brand-suggest-results]') : null;
        if (!results) return;
        results.innerHTML = '';
        const box = document.createElement('div');
        box.className = 'muted';
        box.style.fontSize = '11px';
        box.style.color = isError ? '#b91c1c' : '';
        box.textContent = message || '';
        results.appendChild(box);
      }

      function renderBrandSuggestions(editor, items) {
        const results = editor ? editor.querySelector('[data-brand-suggest-results]') : null;
        if (!results) return;
        results.innerHTML = '';
        if (!items || !items.length) {
          setBrandSuggestStatus(editor, 'Ничего не найдено.', false);
          return;
        }
        items.forEach(function(item) {
          const name = String(item && item.name ? item.name : '').trim();
          if (!name) return;
          const option = document.createElement('button');
          option.type = 'button';
          option.className = 'supplier-brand-suggest-option';
          option.dataset.brandName = name;

          const nameEl = document.createElement('span');
          nameEl.className = 'supplier-brand-suggest-name';
          nameEl.textContent = name;
          option.appendChild(nameEl);

          const icons = document.createElement('span');
          icons.className = 'supplier-brand-suggest-icons';
          const sources = Array.isArray(item.sources) ? item.sources : [];
          [
            ['ozon', 'OZ'],
            ['wb', 'WB']
          ].forEach(function(pair) {
            if (sources.indexOf(pair[0]) < 0) return;
            const icon = document.createElement('span');
            icon.className = 'supplier-brand-source-icon supplier-brand-source-icon--' + pair[0];
            icon.textContent = pair[1];
            icons.appendChild(icon);
          });
          option.appendChild(icons);
          results.appendChild(option);
        });
      }

      async function loadBrandSuggestions(editor) {
        if (!editor) return;
        const query = brandEditorValue(editor);
        const categoryContext = brandEditorCategoryContext(editor);
        const seq = String(Date.now()) + ':' + String(Math.random());
        editor.dataset.brandSuggestSeq = seq;
        if (categoryContext.marketplace === 'ozon' && !categoryContext.ozon) {
          setBrandSuggestStatus(editor, 'Сначала выбери категорию Ozon.', false);
          return;
        }
        if (categoryContext.marketplace === 'wb' && !categoryContext.wb) {
          setBrandSuggestStatus(editor, 'Сначала выбери категорию WB.', false);
          return;
        }
        if (!categoryContext.marketplace && !categoryContext.ozon && !categoryContext.wb) {
          setBrandSuggestStatus(editor, 'Сначала выбери категорию Ozon или WB.', false);
          return;
        }
        setBrandSuggestStatus(editor, 'Ищу бренды для выбранных категорий...', false);
        try {
          const params = new URLSearchParams({
            q: query,
            limit: '24',
            marketplace: categoryContext.marketplace,
            ozon_category: categoryContext.ozon,
            wb_category: categoryContext.wb
          });
          const res = await fetch('supplier_brand_suggestions.php?' + params.toString(), {
            credentials: 'same-origin',
            headers: {
              'Accept': 'application/json'
            }
          });
          const data = await res.json().catch(function() {
            return null;
          });
          if (editor.dataset.brandSuggestSeq !== seq) return;
          if (!res.ok || !data || !data.ok) {
            throw new Error((data && data.error) ? data.error : 'Не удалось загрузить бренды.');
          }
          renderBrandSuggestions(editor, Array.isArray(data.items) ? data.items : []);
        } catch (e) {
          if (editor.dataset.brandSuggestSeq !== seq) return;
          setBrandSuggestStatus(editor, e.message || 'Не удалось загрузить бренды.', true);
        }
      }

      function scheduleBrandSuggestions(editor) {
        if (!editor) return;
        if (editor._brandSuggestTimer) window.clearTimeout(editor._brandSuggestTimer);
        editor._brandSuggestTimer = window.setTimeout(function() {
          loadBrandSuggestions(editor);
        }, 180);
      }

      function openBrandSuggestions(editor, options) {
        if (!editor) return;
        options = options || {};
        const panel = editor.querySelector('[data-brand-suggest-panel]');
        const row = brandEditorFieldRow(editor);
        if (!panel || !row) return;
        closeCategoryPickers();
        closeBulkCategoryPanels();
        closeBulkReplaceValuePanels();
        if (!panel.classList.contains('open')) {
          closeBrandSuggestionPanels();
        }
        beginFieldEdit(row, 'value');
        panel.classList.add('open');
        panel.__brandSuggestEditor = editor;
        positionBrandSuggestionPanel(editor);
        loadBrandSuggestions(editor);
      }

      function ensureBrandBulkReplaceModal() {
        let modal = document.querySelector('[data-brand-bulk-replace-modal]');
        if (modal) return modal;
        modal = document.createElement('div');
        modal.className = 'supplier-repair-modal';
        modal.hidden = true;
        modal.dataset.brandBulkReplaceModal = '1';
        modal.innerHTML = [
          '<div class="supplier-repair-modal-card" role="dialog" aria-modal="true" aria-labelledby="brandBulkReplaceTitle">',
          '<h3 class="supplier-repair-modal-title" id="brandBulkReplaceTitle">Заменить бренд в категории?</h3>',
          '<p class="supplier-repair-modal-text" data-brand-bulk-replace-text></p>',
          '<ul class="supplier-confirm-list" data-brand-bulk-replace-list></ul>',
          '<div class="supplier-repair-modal-actions">',
          '<button type="button" class="btn-secondary" data-brand-bulk-replace-cancel>Нет</button>',
          '<button type="button" class="btn-primary" data-brand-bulk-replace-run>Да, заменить</button>',
          '</div>',
          '</div>'
        ].join('');
        document.body.appendChild(modal);
        return modal;
      }

      function confirmBrandBulkReplace(info) {
        return new Promise(function(resolve) {
          const modal = ensureBrandBulkReplaceModal();
          const text = modal.querySelector('[data-brand-bulk-replace-text]');
          const list = modal.querySelector('[data-brand-bulk-replace-list]');
          const cancel = modal.querySelector('[data-brand-bulk-replace-cancel]');
          const run = modal.querySelector('[data-brand-bulk-replace-run]');
          const scope = info && info.scope ? info.scope : {};
          const count = parseInt(String(info && info.count ? info.count : 0), 10) || 0;
          const oldBrand = String(info && info.old_brand ? info.old_brand : '').trim();
          const newBrand = String(info && info.new_brand ? info.new_brand : '').trim();
          const marketplace = String(scope.marketplace || '').toUpperCase() || 'маркетплейса';
          const category = String(scope.category_value || '').trim();
          text.textContent = 'Заменить бренд "' + oldBrand + '" на "' + newBrand + '" для товаров в категории ' + marketplace + ' "' + category + '"?';
          list.innerHTML = '';
          [
            'Найдено товаров для замены: ' + count,
            'Будет изменен только бренд ' + marketplace + ', остальные бренды и категории останутся без изменений.'
          ].forEach(function(line) {
            const li = document.createElement('li');
            li.textContent = line;
            list.appendChild(li);
          });
          function finish(value) {
            modal.hidden = true;
            if (cancel) cancel.onclick = null;
            if (run) run.onclick = null;
            resolve(value);
          }
          if (cancel) cancel.onclick = function() { finish(false); };
          if (run) run.onclick = function() { finish(true); };
          modal.onclick = function(e) {
            if (e.target === modal) finish(false);
          };
          modal.hidden = false;
          if (run) run.focus();
        });
      }

      async function maybePromptBrandBulkReplace(editor, oldValue, newValue) {
        oldValue = String(oldValue || '').trim();
        newValue = String(newValue || '').trim();
        if (!editor || !oldValue || !newValue || sameTextFold(oldValue, newValue)) return;
        const marketplace = String(editor.dataset.brandMarketplace || '').trim();
        if (marketplace !== 'ozon' && marketplace !== 'wb') return;
        const productId = brandEditorProductId(editor);
        if (!productId) return;
        const preview = await postJson({
          action: 'brand_bulk_replace_preview',
          product_id: productId,
          marketplace: marketplace,
          old_brand: oldValue,
          new_brand: newValue
        });
        const count = parseInt(String(preview.count || '0'), 10) || 0;
        if (count <= 0 || !preview.scope || !preview.scope.category_value) return;
        const confirmed = await confirmBrandBulkReplace(preview);
        if (!confirmed) return;
        const result = await postJson({
          action: 'brand_bulk_replace_by_category',
          product_id: productId,
          marketplace: marketplace,
          old_brand: oldValue,
          new_brand: newValue
        });
        showSupplierRowSuccessToast();
        if (result.products_changed && window.ftSupplierOffersReload) {
          await window.ftSupplierOffersReload();
        }
      }

      async function selectBrandSuggestion(option) {
        const editor = option ? option.closest('[data-brand-editor]') : null;
        const row = brandEditorFieldRow(editor);
        const valueEl = row ? row.querySelector('.supplier-field-value') : null;
        const value = String(option ? (option.dataset.brandName || '') : '').trim();
        if (!row || !valueEl || !value) return;
        initFieldRow(row);
        const oldValue = brandEditorOriginalValue(editor);
        valueEl.textContent = value;
        await saveField(row, true);
        const saved = row.dataset.lastSaveOk === '1';
        closeFieldEdit(row);
        closeBrandSuggestionPanels();
        if (saved) {
          maybePromptBrandBulkReplace(editor, oldValue, value).catch(function(err) {
            if (err && err.message) alert(err.message);
          });
        }
      }

      function setPictureState(editor, message) {
        const state = editor ? editor.querySelector('.supplier-picture-state') : null;
        if (state) state.textContent = message || '';
      }

	      function pictureUrls(editor) {
	        return Array.from(editor.querySelectorAll('.supplier-picture-item')).map(function(item) {
	          return item.dataset.url || '';
	        }).filter(Boolean);
	      }

	      let transparentDragEl = null;
	      function setQuietDragImage(event) {
	        if (!event || !event.dataTransfer || !event.dataTransfer.setDragImage) return;
	        if (!transparentDragEl) {
	          transparentDragEl = document.createElement('div');
	          transparentDragEl.style.position = 'fixed';
	          transparentDragEl.style.left = '-1000px';
	          transparentDragEl.style.top = '-1000px';
	          transparentDragEl.style.width = '1px';
	          transparentDragEl.style.height = '1px';
	          transparentDragEl.style.opacity = '0';
	          document.body.appendChild(transparentDragEl);
	        }
	        event.dataTransfer.setDragImage(transparentDragEl, 0, 0);
	      }

	      function animatePictureReorder(container, move) {
	        if (!container || typeof move !== 'function') return;
	        const before = new Map();
	        Array.from(container.children).forEach(function(child) {
	          if (child && child.getBoundingClientRect) {
	            before.set(child, child.getBoundingClientRect());
	          }
	        });
	        move();
	        Array.from(container.children).forEach(function(child) {
	          const first = before.get(child);
	          if (!first || !child.getBoundingClientRect) return;
	          const last = child.getBoundingClientRect();
	          const dx = first.left - last.left;
	          const dy = first.top - last.top;
	          if (Math.abs(dx) < 1 && Math.abs(dy) < 1) return;
	          child.style.transition = 'none';
	          child.style.transform = 'translate(' + dx + 'px,' + dy + 'px)';
	          child.getBoundingClientRect();
	          requestAnimationFrame(function() {
	            child.style.transition = '';
	            child.style.transform = '';
	          });
	        });
	      }

	      let pictureModal = null;
	      let pictureModalEditor = null;
	      let pictureModalCurrentUrl = '';

	      function ensurePictureModal() {
	        if (pictureModal) return pictureModal;
	        pictureModal = document.createElement('div');
	        pictureModal.className = 'supplier-picture-modal';
	        pictureModal.hidden = true;
	        pictureModal.innerHTML = [
	          '<div class="supplier-picture-modal-card" role="dialog" aria-modal="true" aria-label="Фотографии товара">',
	          '<button type="button" class="supplier-picture-modal-close" aria-label="Закрыть">×</button>',
	          '<div class="supplier-picture-modal-main"></div>',
	          '<div class="supplier-picture-modal-strip"></div>',
	          '</div>'
	        ].join('');
	        document.body.appendChild(pictureModal);
	        pictureModal.addEventListener('click', function(e) {
	          if (e.target === pictureModal || (e.target && e.target.closest && e.target.closest('.supplier-picture-modal-close'))) {
	            closePictureModal();
	          }
	        });
	        return pictureModal;
	      }

	      function closePictureModal() {
	        if (!pictureModal) return;
	        pictureModal.hidden = true;
	        pictureModalEditor = null;
	        pictureModalCurrentUrl = '';
	        document.body.classList.remove('supplier-picture-modal-open');
	      }

	      function renderPictureModal() {
	        const modal = ensurePictureModal();
	        const main = modal.querySelector('.supplier-picture-modal-main');
	        const strip = modal.querySelector('.supplier-picture-modal-strip');
	        if (!main || !strip || !pictureModalEditor) return;
	        const urls = pictureUrls(pictureModalEditor);
	        if (!urls.length) {
	          pictureModalCurrentUrl = '';
	          main.innerHTML = '<div class="supplier-picture-modal-empty">Фото нет</div>';
	          strip.innerHTML = '';
	          return;
	        }
	        if (!pictureModalCurrentUrl || urls.indexOf(pictureModalCurrentUrl) < 0) {
	          pictureModalCurrentUrl = urls[0];
	        }
	        main.innerHTML = '';
	        const img = document.createElement('img');
	        img.src = pictureModalCurrentUrl;
	        img.alt = '';
	        img.referrerPolicy = 'no-referrer';
	        main.appendChild(img);
	        strip.innerHTML = '';
	        urls.forEach(function(url) {
	          const thumb = document.createElement('div');
	          thumb.className = 'supplier-picture-modal-thumb' + (url === pictureModalCurrentUrl ? ' is-active' : '');
	          thumb.draggable = true;
	          thumb.dataset.url = url;

	          const remove = document.createElement('button');
	          remove.type = 'button';
	          remove.className = 'supplier-picture-modal-remove';
	          remove.title = 'Удалить фото';
	          remove.textContent = '×';
	          thumb.appendChild(remove);

	          const thumbImg = document.createElement('img');
	          thumbImg.src = url;
	          thumbImg.alt = '';
	          thumbImg.loading = 'lazy';
	          thumbImg.referrerPolicy = 'no-referrer';
	          thumbImg.draggable = false;
	          thumb.appendChild(thumbImg);
	          strip.appendChild(thumb);
	        });
	      }

	      function openPictureModal(item) {
	        if (!item) return;
	        const editor = item.closest('.supplier-pictures-editor');
	        if (!editor) return;
	        pictureModalEditor = editor;
	        pictureModalCurrentUrl = item.dataset.url || pictureUrls(editor)[0] || '';
	        const modal = ensurePictureModal();
	        renderPictureModal();
	        modal.hidden = false;
	        document.body.classList.add('supplier-picture-modal-open');
	      }

	      function syncPictureModal(editor, preferredUrl) {
	        if (!pictureModal || pictureModal.hidden || !pictureModalEditor || pictureModalEditor !== editor) return;
	        if (preferredUrl) pictureModalCurrentUrl = preferredUrl;
	        renderPictureModal();
	      }

	      let videoCoverModal = null;

	      function ensureVideoCoverModal() {
	        if (videoCoverModal) return videoCoverModal;
	        videoCoverModal = document.createElement('div');
	        videoCoverModal.className = 'supplier-picture-modal supplier-video-cover-modal';
	        videoCoverModal.hidden = true;
	        videoCoverModal.innerHTML = [
	          '<div class="supplier-picture-modal-card" role="dialog" aria-modal="true" aria-label="Видео-обложка товара">',
	          '<button type="button" class="supplier-picture-modal-close" aria-label="Закрыть">×</button>',
	          '<div class="supplier-picture-modal-main"></div>',
	          '<a class="supplier-video-cover-modal-link" href="#" target="_blank" rel="noopener">открыть ссылку</a>',
	          '</div>'
	        ].join('');
	        document.body.appendChild(videoCoverModal);
	        videoCoverModal.addEventListener('click', function(e) {
	          if (e.target === videoCoverModal || (e.target && e.target.closest && e.target.closest('.supplier-picture-modal-close'))) {
	            closeVideoCoverModal();
	          }
	        });
	        return videoCoverModal;
	      }

	      function closeVideoCoverModal() {
	        if (!videoCoverModal) return;
	        const video = videoCoverModal.querySelector('video');
	        if (video) {
	          video.pause();
	          video.removeAttribute('src');
	          video.load();
	        }
	        videoCoverModal.querySelectorAll('iframe').forEach(function(frame) {
	          frame.removeAttribute('src');
	        });
	        videoCoverModal.hidden = true;
	        document.body.classList.remove('supplier-picture-modal-open');
	      }

	      function videoCoverUrlLooksDirect(url) {
	        const value = String(url || '').trim();
	        if (!value) return false;
	        return /\.(mp4|m4v|mov|webm|ogv|ogg)(?:$|[?#=&/])/i.test(value);
	      }

	      function videoCoverUrlLooksEmbeddable(url) {
	        const value = String(url || '').trim();
	        if (!/^https?:\/\//i.test(value)) return false;
	        return true;
	      }

	      function renderVideoCoverFallback(main, url, message) {
	        if (!main) return;
	        main.innerHTML = '';
	        const box = document.createElement('div');
	        box.className = 'supplier-video-cover-fallback';
	        const text = document.createElement('div');
	        text.textContent = message || 'Видео не удалось открыть во встроенном просмотре.';
	        const open = document.createElement('a');
	        open.href = url;
	        open.target = '_blank';
	        open.rel = 'noopener';
	        open.textContent = 'Открыть видео по ссылке';
	        box.appendChild(text);
	        box.appendChild(open);
	        main.appendChild(box);
	      }

	      function renderVideoCoverFrame(main, url) {
	        if (!main) return;
	        if (!videoCoverUrlLooksEmbeddable(url)) {
	          renderVideoCoverFallback(main, url, 'Ссылка на видео не подходит для встроенного просмотра.');
	          return;
	        }
	        main.innerHTML = '';
	        const frame = document.createElement('iframe');
	        frame.src = url;
	        frame.title = 'Видео товара';
	        frame.loading = 'lazy';
	        frame.allow = 'autoplay; encrypted-media; picture-in-picture; fullscreen';
	        frame.allowFullscreen = true;
	        frame.referrerPolicy = 'no-referrer-when-downgrade';
	        main.appendChild(frame);
	      }

	      function renderVideoCoverPlayer(main, url) {
	        if (!main) return;
	        main.innerHTML = '';
	        const video = document.createElement('video');
	        video.src = url;
	        video.controls = true;
	        video.autoplay = true;
	        video.muted = true;
	        video.playsInline = true;
	        video.preload = 'metadata';
	        video.addEventListener('error', function() {
	          renderVideoCoverFrame(main, url);
	        }, { once: true });
	        main.appendChild(video);
	      }

	      function openVideoCoverModal(card) {
	        const url = String(card ? (card.dataset.url || '') : '').trim();
	        if (!url) return;
	        const modal = ensureVideoCoverModal();
	        const main = modal.querySelector('.supplier-picture-modal-main');
	        const link = modal.querySelector('.supplier-video-cover-modal-link');
	        if (main) {
	          const kind = String(card ? (card.dataset.videoKind || '') : '');
	          if (kind === 'external' && !videoCoverUrlLooksDirect(url)) {
	            renderVideoCoverFrame(main, url);
	          } else if (videoCoverUrlLooksDirect(url) || kind === 'cover') {
	            renderVideoCoverPlayer(main, url);
	          } else {
	            renderVideoCoverFrame(main, url);
	          }
	        }
	        if (link) {
	          link.href = url;
	        }
	        modal.hidden = false;
	        document.body.classList.add('supplier-picture-modal-open');
	      }

	      function removeVideoCoverCard(editor, card) {
	        const target = card || (editor ? editor.querySelector('.supplier-video-cover-card:not(.supplier-video-card)') : null);
	        if (target) target.remove();
	      }

	      async function deleteVideoCover(card) {
	        if (!card) return;
	        const editor = card.closest('.supplier-pictures-editor');
	        const productId = parseInt(editor ? (editor.dataset.productId || '0') : '0', 10);
	        if (!editor || !productId) return;
	        if (!confirm('Удалить видео-обложку товара?')) return;
	        setPictureState(editor, '');
	        card.classList.add('is-saving');
	        try {
	          const data = await postJson({
	            action: 'video_cover_delete',
	            product_id: productId
	          });
	          removeVideoCoverCard(editor, card);
	          applyProductResponse(editor.closest('tr'), data.product);
	          closeVideoCoverModal();
	        } catch (e) {
	          setPictureState(editor, e.message || 'Не удалось удалить видео-обложку.');
	        } finally {
	          card.classList.remove('is-saving');
	        }
	      }

	      function modalPictureUrls() {
	        const modal = ensurePictureModal();
	        return Array.from(modal.querySelectorAll('.supplier-picture-modal-thumb')).map(function(item) {
	          return item.dataset.url || '';
	        }).filter(Boolean);
	      }

	      async function savePictureModalOrder() {
	        if (!pictureModalEditor) return;
	        const editor = pictureModalEditor;
	        const productId = parseInt(editor.dataset.productId || '0', 10);
	        if (!productId) return;
	        setPictureState(editor, '');
	        try {
	          const data = await postJson({
	            action: 'picture_reorder',
	            product_id: productId,
	            pictures: modalPictureUrls()
	          });
	          renderPictures(editor, data.pictures || []);
	          applyProductResponse(editor.closest('tr'), data.product);
	          syncPictureModal(editor, pictureModalCurrentUrl);
	        } catch (e) {
	          setPictureState(editor, e.message || 'Не удалось сохранить порядок фото.');
	          renderPictureModal();
	        }
	      }

	      async function deletePictureFromModal(thumb) {
	        if (!thumb || !pictureModalEditor) return;
	        const editor = pictureModalEditor;
	        const productId = parseInt(editor.dataset.productId || '0', 10);
	        if (!productId) return;
	        const thumbs = Array.from(ensurePictureModal().querySelectorAll('.supplier-picture-modal-thumb'));
	        const index = thumbs.indexOf(thumb);
	        if (index < 0) return;
	        const removedUrl = thumb.dataset.url || '';
	        const nextUrl = (thumbs[index + 1] && thumbs[index + 1].dataset.url) || (thumbs[index - 1] && thumbs[index - 1].dataset.url) || '';
	        setPictureState(editor, '');
	        try {
	          const data = await postJson({
	            action: 'picture_delete',
	            product_id: productId,
	            index: index
	          });
	          if (pictureModalCurrentUrl === removedUrl) pictureModalCurrentUrl = nextUrl;
	          renderPictures(editor, data.pictures || []);
	          applyProductResponse(editor.closest('tr'), data.product);
	          syncPictureModal(editor, pictureModalCurrentUrl);
	        } catch (e) {
	          setPictureState(editor, e.message || 'Не удалось удалить фото.');
	        }
	      }

	      function createPictureItem(url) {
	        const item = document.createElement('div');
        item.className = 'supplier-picture-item';
        item.draggable = true;
        item.dataset.url = url;

        const remove = document.createElement('button');
        remove.type = 'button';
        remove.className = 'supplier-picture-remove';
        remove.title = 'Удалить фото';
        remove.textContent = '×';
        item.appendChild(remove);

        const link = document.createElement('a');
        link.href = url;
        link.target = '_blank';
        link.rel = 'noopener';
        link.draggable = false;

        const img = document.createElement('img');
        img.src = url;
        img.alt = '';
        img.loading = 'lazy';
        img.referrerPolicy = 'no-referrer';
        img.className = 'supplier-picture-img';
        img.draggable = false;
        link.appendChild(img);
        item.appendChild(link);

        return item;
      }

      function renderPictures(editor, pictures) {
        if (!editor) return;
        const list = editor.querySelector('.supplier-picture-list');
        if (!list) return;
        const urls = Array.isArray(pictures) ? pictures.map(String).filter(function(url) {
          return url.trim() !== '';
        }) : [];
        list.innerHTML = '';
        if (!urls.length) {
          const empty = document.createElement('div');
          empty.className = 'supplier-pictures-empty muted';
          empty.textContent = '—';
          list.appendChild(empty);
        } else {
          urls.forEach(function(url, index) {
            const item = createPictureItem(url);
            if (index > 0) item.classList.add('is-extra');
            list.appendChild(item);
          });
        }
        let toggle = editor.querySelector('.supplier-picture-toggle');
        const extra = Math.max(0, urls.length - 1);
        if (extra > 0) {
          if (!toggle) {
            toggle = document.createElement('button');
            toggle.type = 'button';
            toggle.className = 'supplier-picture-toggle';
            const actions = editor.querySelector('.supplier-picture-actions');
            editor.insertBefore(toggle, actions || null);
          }
          toggle.textContent = editor.classList.contains('is-expanded') ? 'свернуть' : ('еще ' + extra);
	        } else if (toggle) {
	          toggle.remove();
	          editor.classList.remove('is-expanded');
	        }
	        syncPictureModal(editor, pictureModalCurrentUrl);
	      }

      async function savePictureOrder(editor) {
        if (!editor) return;
        const productId = parseInt(editor.dataset.productId || '0', 10);
        if (!productId) return;
        setPictureState(editor, '');
        try {
          const data = await postJson({
            action: 'picture_reorder',
            product_id: productId,
            pictures: pictureUrls(editor)
          });
          renderPictures(editor, data.pictures || []);
          applyProductResponse(editor.closest('tr'), data.product);
        } catch (e) {
          setPictureState(editor, e.message || 'Не удалось сохранить порядок фото.');
        }
      }

      async function deletePicture(item) {
        if (!item) return;
        const editor = item.closest('.supplier-pictures-editor');
        const productId = parseInt(editor ? (editor.dataset.productId || '0') : '0', 10);
        if (!editor || !productId) return;
        const index = Array.from(editor.querySelectorAll('.supplier-picture-item')).indexOf(item);
        if (index < 0) return;
        setPictureState(editor, '');
        try {
          const data = await postJson({
            action: 'picture_delete',
            product_id: productId,
            index: index
          });
          renderPictures(editor, data.pictures || []);
          applyProductResponse(editor.closest('tr'), data.product);
        } catch (e) {
          setPictureState(editor, e.message || 'Не удалось удалить фото.');
        }
      }

      async function addPictureUrl(editor) {
        if (!editor) return;
        const productId = parseInt(editor.dataset.productId || '0', 10);
        if (!productId) return;
        const url = window.prompt('Ссылка на фото');
        if (url === null) return;
        setPictureState(editor, '');
        try {
          const data = await postJson({
            action: 'picture_add_url',
            product_id: productId,
            url: url
          });
          editor.classList.add('is-expanded');
          editor.classList.remove('is-add-menu-open');
          renderPictures(editor, data.pictures || []);
          applyProductResponse(editor.closest('tr'), data.product);
        } catch (e) {
          setPictureState(editor, e.message || 'Не удалось добавить фото.');
        }
      }

      async function uploadPictureFile(editor, file) {
        if (!editor || !file) return;
        const productId = parseInt(editor.dataset.productId || '0', 10);
        if (!productId) return;
        const form = new FormData();
        form.append('action', 'picture_upload');
        form.append('product_id', String(productId));
        form.append('picture', file);
        setPictureState(editor, '');
        try {
          const res = await fetch(endpoint, {
            method: 'POST',
            credentials: 'same-origin',
            body: form
          });
          const data = await res.json().catch(function() {
            return null;
          });
          if (!res.ok || !data || !data.ok) {
            throw new Error((data && data.error) ? data.error : 'Не удалось загрузить фото.');
          }
          editor.classList.add('is-expanded');
          editor.classList.remove('is-add-menu-open');
          renderPictures(editor, data.pictures || []);
          applyProductResponse(editor.closest('tr'), data.product);
        } catch (e) {
          setPictureState(editor, e.message || 'Не удалось загрузить фото.');
        }
      }

      function beginRichEdit(editable) {
        if (!editable || editable.dataset.rich !== '1') return;
        const wrap = editable.closest('.supplier-edit-wrap');
        if (wrap) wrap.classList.add('is-rich-editing');
      }

      function closeRichEdit(wrap) {
        if (!wrap) return;
        const editable = wrap.querySelector('.supplier-inline-edit--rich');
        if (editable) {
          editable.style.width = '';
          editable.style.height = '';
        }
        wrap.classList.remove('is-rich-editing');
      }

      function closeRichEditors(exceptWrap) {
        document.querySelectorAll('.supplier-edit-wrap.is-rich-editing').forEach(function(wrap) {
          if (exceptWrap && wrap === exceptWrap) return;
          closeRichEdit(wrap);
        });
      }

      async function saveBasic(editable, force) {
        if (!editable) return;
        const wrap = editable.closest('.supplier-edit-wrap');
        const productId = parseInt(editable.dataset.productId || '0', 10);
        const field = editable.dataset.basicField || '';
        if (!productId || !field) return;

        const value = editableValue(editable);
        const original = editable.dataset.originalValue || '';
        if (!force && value === original) return;

        if (wrap) wrap.classList.add('is-saving');
        setState(wrap, 'сохраняю...', false);
        try {
          const data = await postJson({
            action: 'update_basic',
            product_id: productId,
            field: field,
            value: value
          });
          editable.dataset.originalValue = editableValue(editable);
          applyProductResponse(editable.closest('tr'), data.product);
          setState(wrap, 'сохранено', false);
          window.setTimeout(function() {
            if ((wrap && !wrap.classList.contains('is-error'))) setState(wrap, '', false);
          }, 1200);
        } catch (e) {
          setState(wrap, e.message || 'Ошибка сохранения', true);
        } finally {
          if (wrap) wrap.classList.remove('is-saving');
        }
      }

      async function saveSameModel(valueEl, force) {
        if (!valueEl) return;
        const wrap = valueEl.closest('.supplier-same-model');
        const productId = parseInt((wrap && wrap.dataset.productId) || '0', 10);
        if (!wrap || !productId) return;

        const value = valueEl.textContent.trim();
        const original = valueEl.dataset.originalValue || '';
        if (!force && value === original) return;

        wrap.classList.add('is-saving');
        setState(wrap, '', false);
        try {
          const data = await postJson({
            action: 'same_model_set',
            product_id: productId,
            value: value
          });
          const savedValue = String(data.value || '');
          wrap.dataset.fieldId = String(data.field_id || '');
          valueEl.textContent = savedValue;
          valueEl.dataset.originalValue = savedValue;
          applyProductResponse(wrap.closest('tr'), data.product);
          setState(wrap, '', false);
        } catch (e) {
          setState(wrap, e.message || 'Ошибка сохранения', true);
        } finally {
          wrap.classList.remove('is-saving');
        }
      }

      async function deleteSameModel(button) {
        const wrap = button ? button.closest('.supplier-same-model') : null;
        const valueEl = wrap ? wrap.querySelector('.supplier-same-model-value') : null;
        if (!wrap || !valueEl) return;
        valueEl.textContent = '';
        await saveSameModel(valueEl, true);
        wrap.classList.remove('is-editing');
      }

      function datasetHasValue(el, key) {
        return !!(el && el.dataset && Object.prototype.hasOwnProperty.call(el.dataset, key));
      }

      function fieldValueFromDisplay(row) {
        const display = row ? row.querySelector('.supplier-field-display') : null;
        if (!display) return '';
        const textNode = display.querySelector('.supplier-field-text');
        let text = '';
        if (textNode) {
          text = textNode.textContent || '';
        } else {
          const clone = display.cloneNode(true);
          clone.querySelectorAll('.supplier-field-kind, .supplier-edit-state').forEach(function(el) {
            el.remove();
          });
          text = clone.textContent || display.textContent || '';
        }
        const showLabel = row.dataset.displayLabel !== '0';
        const label = row.dataset.fieldLabel || row.dataset.fieldName || '';
        if (showLabel && label !== '') {
          const trimmedText = text.trimStart();
          const prefix = label + ':';
          if (trimmedText.indexOf(prefix) === 0) {
            text = trimmedText.slice(prefix.length);
          }
        }
        if (row.dataset.kind === 'standard' && text.trim() === '—') {
          return '';
        }
        return text.trim();
      }

      function hydrateFieldRow(row) {
        if (!row) return;
        if (row.dataset.fieldHydrated === '1') return;
        const nameEl = row.querySelector('.supplier-field-name');
        const valueEl = row.querySelector('.supplier-field-value');
        if (nameEl && nameEl.textContent.trim() === '') {
          nameEl.textContent = row.dataset.kind === 'standard'
            ? (row.dataset.fieldLabel || row.dataset.fieldName || '')
            : (row.dataset.fieldName || '');
        }
        if (valueEl && valueEl.textContent.trim() === '') {
          valueEl.textContent = fieldValueFromDisplay(row);
        }
        row.dataset.fieldHydrated = '1';
      }

      function initFieldRow(row) {
        if (!row) return;
        hydrateFieldRow(row);
        const nameEl = row.querySelector('.supplier-field-name');
        const valueEl = row.querySelector('.supplier-field-value');
        if (nameEl && !datasetHasValue(nameEl, 'originalValue')) {
          nameEl.dataset.originalValue = row.dataset.kind === 'standard' ? (row.dataset.fieldName || '') : nameEl.textContent.trim();
        }
        if (valueEl && !datasetHasValue(valueEl, 'originalValue')) valueEl.dataset.originalValue = valueEl.textContent.trim();
        updateFieldDisplay(row);
      }

      function updateFieldDisplay(row) {
        if (!row) return;
        const display = row.querySelector('.supplier-field-display');
        const nameEl = row.querySelector('.supplier-field-name');
        const valueEl = row.querySelector('.supplier-field-value');
        if (!display || !nameEl || !valueEl) return;
        const name = row.dataset.kind === 'standard' ? (row.dataset.fieldLabel || nameEl.textContent.trim()) : nameEl.textContent.trim();
        const value = valueEl.textContent.trim();
        const showLabel = row.dataset.displayLabel !== '0';
        const marketSource = row.dataset.marketSource || '';
        display.innerHTML = '';
        if (marketSource) {
          const badge = document.createElement('span');
          badge.className = 'supplier-field-kind supplier-field-kind--inline supplier-field-kind--' + marketSource;
          if (row.dataset.hasValueSuggestions === '1') {
            badge.classList.add('supplier-field-kind--has-dict');
          }
          badge.textContent = marketSource === 'wb' ? 'WB' : 'oz';
          if (row.dataset.hasValueSuggestions === '1') {
            const dict = document.createElement('span');
            dict.className = 'supplier-field-kind-dict';
            dict.textContent = 'С';
            badge.appendChild(dict);
          }
          display.appendChild(badge);
          display.appendChild(document.createTextNode(' '));
        }
        const text = document.createElement('span');
        text.className = 'supplier-field-text';
        if (showLabel && name !== '') {
          const strong = document.createElement('b');
          strong.textContent = name;
          text.appendChild(strong);
          text.appendChild(document.createTextNode(': '));
        }
        text.appendChild(document.createTextNode(value === '' ? '—' : value));
        display.appendChild(text);
      }

      function beginFieldEdit(row, focusPart) {
        if (!row) return;
        initFieldRow(row);
        row.classList.add('is-editing');
        const isVirtual = row.dataset.virtualField === '1';
        const target = (focusPart === 'value' || row.dataset.kind === 'standard' || isVirtual) ? row.querySelector('.supplier-field-value') : row.querySelector('.supplier-field-name');
        if (target) {
          target.focus();
          if (focusPart !== 'value' && row.dataset.kind !== 'standard') {
            try {
              const range = document.createRange();
              range.selectNodeContents(target);
              const sel = window.getSelection();
              if (sel) {
                sel.removeAllRanges();
                sel.addRange(range);
              }
            } catch (e) {}
          }
        }
      }

      function closeFieldEdit(row) {
        if (!row) return;
        updateFieldDisplay(row);
        row.classList.remove('is-editing');
        scheduleOfferDescriptionFit();
      }

      function updateFeatureEditorState(editor) {
        if (!editor || !editor.classList || !editor.classList.contains('supplier-fields-editor--features')) return;
        const max = Math.max(1, parseInt(editor.dataset.featureMax || '3', 10) || 3);
        const count = editor.querySelectorAll('.supplier-fields-list .supplier-field-row[data-kind="feature"]').length;
        const add = editor.querySelector('.supplier-field-add[data-kind="feature"]');
        if (add) {
          const atLimit = count >= max;
          add.disabled = atLimit;
          add.hidden = atLimit;
        }
      }

      async function saveField(row, force) {
        if (!row) return;
        initFieldRow(row);
        row.dataset.lastSaveOk = '';
        const fieldId = parseInt(row.dataset.fieldId || '0', 10);
        const nameEl = row.querySelector('.supplier-field-name');
        const valueEl = row.querySelector('.supplier-field-value');
        if (!nameEl || !valueEl) return;

        const isStandard = row.dataset.kind === 'standard';
        const name = isStandard ? (row.dataset.fieldName || '') : nameEl.textContent.trim();
        const value = valueEl.textContent.trim();
        const originalName = nameEl.dataset.originalValue || '';
        const originalValue = valueEl.dataset.originalValue || '';
        const isVirtual = row.dataset.virtualField === '1';
        if (!force && name === originalName && value === originalValue) return;
        if (!fieldId && !isStandard && !isVirtual) return;
        if (!fieldId && isStandard && value === '' && !['brand', 'brand_ozon', 'brand_wb'].includes(name)) return;
        if (!isStandard && name === '') {
          await deleteFieldRow(row, false);
          return;
        }

        row.classList.add('is-saving');
        setState(row, 'сохраняю...', false);
        let savedData = null;
        try {
          const editor = row.closest('.supplier-fields-editor');
          const productId = editor ? parseInt(editor.dataset.productId || '0', 10) : 0;
          const payload = fieldId
            ? { action: 'field_update', field_id: fieldId, name: name, value: value }
            : {
                action: 'field_add',
                product_id: productId,
                kind: isStandard ? 'standard' : (row.dataset.kind || 'param'),
                name: name,
                value: value
              };
          if (!fieldId && !payload.product_id) {
            throw new Error('Не удалось определить товар для сохранения.');
          }
          const data = await postJson(payload);
          savedData = data;
          if (data.deleted_field_id) {
            row.dataset.lastSaveOk = '1';
            row.remove();
            return data;
          }
          if (data.field) {
            row.dataset.fieldId = String(data.field.id || row.dataset.fieldId || '');
            if (row.dataset.virtualField === '1') {
              delete row.dataset.virtualField;
              row.classList.remove('supplier-field-row--virtual');
            }
            if (isStandard) {
              row.dataset.fieldName = data.field.field_name || row.dataset.fieldName || '';
              nameEl.textContent = row.dataset.fieldLabel || nameEl.textContent || row.dataset.fieldName || '';
            } else {
              row.dataset.kind = data.field.field_kind || row.dataset.kind || 'param';
              row.dataset.fieldName = data.field.field_name || row.dataset.fieldName || '';
              if (row.dataset.kind === 'feature') {
                row.dataset.fieldLabel = 'Фишка';
                row.dataset.displayLabel = '0';
              }
              nameEl.textContent = data.field.field_name || '';
              nameEl.contentEditable = row.dataset.kind === 'feature' ? 'false' : 'true';
            }
            valueEl.textContent = data.field.field_value || '';
          }
          nameEl.dataset.originalValue = isStandard ? (row.dataset.fieldName || '') : nameEl.textContent.trim();
          valueEl.dataset.originalValue = valueEl.textContent.trim();
          updateFieldDisplay(row);
          applyProductResponse(row.closest('tr'), data.product);
          row.dataset.lastSaveOk = '1';
          setState(row, 'сохранено', false);
          window.setTimeout(function() {
            if (!row.classList.contains('is-error')) setState(row, '', false);
          }, 1200);
        } catch (e) {
          row.dataset.lastSaveOk = '0';
          setState(row, e.message || 'Ошибка сохранения', true);
        } finally {
          row.classList.remove('is-saving');
        }
        return savedData;
      }

      function createFieldRow(field) {
        const row = document.createElement('div');
        const kind = String(field.field_kind || 'param');
        row.className = 'supplier-field-row' + (kind === 'feature' ? ' supplier-field-row--feature' : '');
        row.dataset.fieldId = String(field.id || '');
        row.dataset.kind = kind;
        row.dataset.fieldName = String(field.field_name || '');
        if (kind === 'feature') {
          row.dataset.fieldLabel = 'Фишка';
          row.dataset.displayLabel = '0';
        }

        const kindLabel = kind === 'wb_param' ? 'WB' : '';
        if (kindLabel) {
          const label = document.createElement('span');
          label.className = 'supplier-field-kind supplier-field-kind--wb';
          label.textContent = kindLabel;
          row.appendChild(label);
        }

        if (kind !== 'standard') {
          const deleteBtn = document.createElement('button');
          deleteBtn.type = 'button';
          deleteBtn.className = 'supplier-field-delete';
          deleteBtn.title = kind === 'feature' ? 'Удалить фишку' : 'Удалить характеристику';
          deleteBtn.setAttribute('aria-label', deleteBtn.title);
          deleteBtn.textContent = '×';
          row.appendChild(deleteBtn);
        }

        const name = document.createElement('span');
        name.className = 'supplier-field-name';
        name.contentEditable = kind === 'feature' ? 'false' : 'true';
        name.spellcheck = false;
        name.dataset.fieldPart = 'name';
        name.textContent = field.field_name || '';
        name.dataset.originalValue = name.textContent.trim();
        row.appendChild(name);

        const value = document.createElement('span');
        value.className = 'supplier-field-value';
        value.contentEditable = 'true';
        value.spellcheck = false;
        value.dataset.fieldPart = 'value';
        value.textContent = field.field_value || '';
        value.dataset.originalValue = value.textContent.trim();
        row.appendChild(value);

        const display = document.createElement('span');
        display.className = 'supplier-field-display';
        display.tabIndex = 0;
        row.insertBefore(display, name);

        const state = document.createElement('span');
        state.className = 'supplier-edit-state';
        state.setAttribute('aria-live', 'polite');
        row.appendChild(state);

        updateFieldDisplay(row);
        return row;
      }

      async function addField(button) {
        if (!button || button.disabled) return;
        const editor = button.closest('.supplier-fields-editor');
        if (!editor) return;
        updateFeatureEditorState(editor);
        if (button.disabled) return;
        const productId = parseInt(editor.dataset.productId || '0', 10);
        const kind = button.dataset.kind || 'param';
        if (!productId) return;
        const name = kind === 'param' ? 'Новая характеристика' : (kind === 'feature' ? 'feature' : 'field');

        button.disabled = true;
        try {
          const data = await postJson({
            action: 'field_add',
            product_id: productId,
            kind: kind,
            name: name,
            value: ''
          });
          const list = editor.querySelector('.supplier-fields-list');
          if (list && data.field) {
            const row = createFieldRow(data.field);
            list.appendChild(row);
            const nameEl = row.querySelector('.supplier-field-name');
            if (nameEl) {
              beginFieldEdit(row, kind === 'feature' ? 'value' : 'name');
            }
            updateFeatureEditorState(editor);
          }
          applyProductResponse(editor.closest('tr'), data.product);
        } catch (e) {
          alert(e.message || 'Не удалось добавить поле.');
        } finally {
          button.disabled = false;
          updateFeatureEditorState(editor);
        }
      }

      async function deleteFieldRow(row, askConfirm) {
        if (!row) return;
        if ((row.dataset.marketSource || '') !== '') {
          const valueEl = row.querySelector('.supplier-field-value');
          if (!valueEl) return;
          initFieldRow(row);
          valueEl.textContent = '';
          await saveField(row, true);
          closeFieldEdit(row);
          return;
        }
        const fieldId = parseInt(row.dataset.fieldId || '0', 10);
        if (!fieldId) return;
        if (askConfirm && !confirm('Удалить поле товара?')) return;
        row.classList.add('is-saving');
        setState(row, 'удаляю...', false);
        try {
          const data = await postJson({
            action: 'field_delete',
            field_id: fieldId
          });
          applyProductResponse(row.closest('tr'), data.product);
          const editor = row.closest('.supplier-fields-editor');
          row.remove();
          updateFeatureEditorState(editor);
        } catch (e) {
          setState(row, e.message || 'Ошибка удаления', true);
        } finally {
          row.classList.remove('is-saving');
        }
      }

      function setFieldValuesMessage(panel, message, isError) {
        if (!panel) return;
        const target = panel.querySelector('[data-field-values-results]') || panel;
        target.innerHTML = '';
        const box = document.createElement('span');
        box.className = 'muted';
        box.style.display = 'block';
        box.style.fontSize = '10px';
        box.style.color = isError ? '#b91c1c' : '';
        box.textContent = message || '';
        target.appendChild(box);
      }

      function isTnvedFieldRow(row) {
        return !!(row && (row.dataset.marketTnved === '1' || row.dataset.valuePickerMode === 'tnved'));
      }

      function splitTnvedValue(value) {
        const text = String(value || '').trim();
        const match = text.match(/^(\d{4,10})(?:\s*[-–—]\s*(.*))?$/u);
        if (!match) return { code: '', desc: text };
        return { code: match[1] || '', desc: String(match[2] || '').trim() };
      }

      function renderFieldAllowedValueItems(container, values, row) {
        if (!container) return;
        container.innerHTML = '';
        const list = Array.isArray(values) ? values : [];
        if (!list.length) {
          const box = document.createElement('span');
          box.className = 'muted';
          box.style.display = 'block';
          box.style.fontSize = '10px';
          box.textContent = isTnvedFieldRow(row)
            ? 'Введите код или слово из описания, чтобы найти значение ТН ВЭД.'
            : 'Для этой характеристики нет справочника значений.';
          container.appendChild(box);
          return;
        }
        list.forEach(function(item) {
          const value = String((item && item.value) || item || '').trim();
          if (!value) return;
          const button = document.createElement('button');
          button.type = 'button';
          button.className = 'supplier-field-value-option' + (isTnvedFieldRow(row) ? ' supplier-field-value-option--tnved' : '');
          button.dataset.value = value;
          if (isTnvedFieldRow(row)) {
            const parts = splitTnvedValue(value);
            const code = document.createElement('span');
            code.className = 'supplier-field-value-option-code';
            code.textContent = parts.code || 'код';
            const desc = document.createElement('span');
            desc.className = 'supplier-field-value-option-desc';
            desc.textContent = parts.desc || value;
            button.appendChild(code);
            button.appendChild(desc);
          } else {
            button.textContent = value;
          }
          container.appendChild(button);
        });
      }

      function renderFieldAllowedValues(panel, values, row, query) {
        if (!panel) return;
        const tnved = isTnvedFieldRow(row);
        panel.classList.toggle('supplier-field-values-panel--tnved', tnved);
        panel.innerHTML = '';
        if (!tnved) {
          renderFieldAllowedValueItems(panel, values, row);
          return;
        }

        const search = document.createElement('div');
        search.className = 'supplier-field-values-search';
        const input = document.createElement('input');
        input.type = 'search';
        input.autocomplete = 'off';
        input.placeholder = 'код или описание: 8507, аккумулятор, литий';
        input.value = String(query || '').trim();
        search.appendChild(input);
        const hint = document.createElement('div');
        hint.className = 'supplier-field-values-hint';
        hint.textContent = 'Ищет по справочнику маркетплейса: можно вводить первые цифры кода или слово из описания.';
        search.appendChild(hint);
        const results = document.createElement('div');
        results.className = 'supplier-field-values-results';
        results.dataset.fieldValuesResults = '1';
        panel.appendChild(search);
        panel.appendChild(results);
        renderFieldAllowedValueItems(results, values, row);

        let timer = 0;
        input.addEventListener('input', function() {
          const nextQuery = String(input.value || '').trim();
          window.clearTimeout(timer);
          timer = window.setTimeout(async function() {
            setFieldValuesMessage(panel, 'Ищу значения...', false);
            try {
              const nextValues = await loadFieldAllowedValues(row, nextQuery);
              renderFieldAllowedValueItems(results, nextValues, row);
              positionOpenFieldValuePanels();
            } catch (e) {
              setFieldValuesMessage(panel, (e && e.message) ? e.message : 'Не удалось загрузить значения.', true);
            }
          }, 220);
        });

        window.setTimeout(function() {
          input.focus();
          input.select();
        }, 0);
      }

      function positionFieldValuePanel(button, panel) {
        if (!button || !panel || !button.getBoundingClientRect) return;
        const wrap = button.closest('.supplier-field-value-wrap');
        const row = button.closest('.supplier-field-row');
        const tnved = isTnvedFieldRow(row);
        const anchor = wrap ? (wrap.querySelector('.supplier-field-value') || button) : button;
        const rect = anchor.getBoundingClientRect();
        const pad = 10;
        const gap = 4;
        const maxViewportWidth = Math.max(190, window.innerWidth - pad * 2);
        const width = Math.min(
          Math.max(Math.round(rect.width || 0), tnved ? 520 : 240),
          Math.min(tnved ? 760 : 380, maxViewportWidth)
        );
        let left = Math.round(rect.left);
        if (left + width > window.innerWidth - pad) {
          left = window.innerWidth - pad - width;
        }
        if (left < pad) left = pad;

        panel.__fieldValuesAnchor = button;
        panel.style.position = 'fixed';
        panel.style.left = left + 'px';
        panel.style.right = 'auto';
        panel.style.width = width + 'px';
        panel.style.maxHeight = Math.min(tnved ? 460 : 320, Math.max(150, window.innerHeight - pad * 2)) + 'px';
        panel.style.top = '0px';
        panel.style.bottom = 'auto';

        const panelHeight = Math.min(panel.getBoundingClientRect().height || 240, parseInt(panel.style.maxHeight || '320', 10) || 320);
        const below = window.innerHeight - rect.bottom - pad - gap;
        const above = rect.top - pad - gap;
        let top = rect.bottom + gap;
        if (below < Math.min(panelHeight, 180) && above > below) {
          top = rect.top - panelHeight - gap;
        } else {
          top = Math.min(top, window.innerHeight - pad - panelHeight);
        }
        panel.style.top = Math.max(pad, Math.round(top)) + 'px';
      }

      let fieldValuePanelPositionFrame = 0;
      function positionOpenFieldValuePanels() {
        if (fieldValuePanelPositionFrame) return;
        fieldValuePanelPositionFrame = window.requestAnimationFrame(function() {
          fieldValuePanelPositionFrame = 0;
          document.querySelectorAll('.supplier-field-values-panel.is-open').forEach(function(panel) {
            const anchor = panel.__fieldValuesAnchor || (panel.closest('.supplier-field-value-wrap') ? panel.closest('.supplier-field-value-wrap').querySelector('[data-field-values-toggle]') : null);
            positionFieldValuePanel(anchor, panel);
          });
        });
      }

      async function loadFieldAllowedValues(row, queryOverride) {
        if (!row) return [];
        const valueEl = row.querySelector('.supplier-field-value');
        let query = typeof queryOverride === 'string'
          ? queryOverride
          : String(valueEl ? (valueEl.textContent || '') : '').trim();
        if (query === '—') query = '';
        const cached = String(row.dataset.allowedValues || '').trim();
        const cachedQuery = String(row.dataset.allowedValuesQuery || '');
        if (cached && cachedQuery === query) {
          try {
            const parsed = JSON.parse(cached);
            if (Array.isArray(parsed)) {
              return parsed.map(function(value) { return { value: String(value || '').trim() }; }).filter(function(item) { return item.value !== ''; });
            }
          } catch (e) {}
        }
        const editor = row.closest('.supplier-fields-editor');
        const productId = editor ? parseInt(editor.dataset.productId || '0', 10) : 0;
        const source = String(row.dataset.marketSource || '').trim();
        const nameEl = row.querySelector('.supplier-field-name');
        const name = String(row.dataset.fieldName || (nameEl ? nameEl.textContent : '') || '').trim();
        if (!productId || !source || !name) return [];
        const connectionSelectId = source === 'ozon' ? 'datasetOzonConnectionSelect' : 'datasetWbConnectionSelect';
        const connectionSelect = document.getElementById(connectionSelectId);
        const connectionId = connectionSelect ? parseInt(connectionSelect.value || '0', 10) : 0;
        const data = await postJson({
          action: 'marketplace_characteristic_values',
          product_id: productId,
          source: source,
          name: name,
          connection_id: connectionId || 0,
          query: query
        });
        const values = Array.isArray(data.values) ? data.values : [];
        row.dataset.allowedValues = JSON.stringify(values.map(function(item) {
          return String((item && item.value) || '').trim();
        }).filter(Boolean));
        row.dataset.allowedValuesQuery = query;
        return values;
      }

      async function openFieldValueSuggestions(button) {
        const row = button ? button.closest('.supplier-field-row') : null;
        const wrap = button ? button.closest('.supplier-field-value-wrap') : null;
        const panel = wrap ? wrap.querySelector('[data-field-values-panel]') : null;
        if (!row || !panel) return;
        if (panel.classList.contains('is-open')) {
          closeFieldValuePanels();
          return;
        }
        closeCategoryPickers();
        closeBulkCategoryPanels();
        closeBulkReplaceValuePanels();
        closeFieldValuePanels();
        beginFieldEdit(row, 'value');
        panel.classList.add('is-open');
        positionFieldValuePanel(button, panel);
        setFieldValuesMessage(panel, 'Загружаю значения...', false);
        try {
          const valueEl = row.querySelector('.supplier-field-value');
          const currentValue = String(valueEl ? (valueEl.textContent || '') : '').trim();
          const tnvedQuery = isTnvedFieldRow(row)
            ? ((currentValue.match(/\d{4,10}/) || [''])[0] || '')
            : currentValue;
          renderFieldAllowedValues(panel, await loadFieldAllowedValues(row, isTnvedFieldRow(row) ? tnvedQuery : undefined), row, isTnvedFieldRow(row) ? tnvedQuery : '');
          positionFieldValuePanel(button, panel);
        } catch (e) {
          setFieldValuesMessage(panel, e.message || 'Не удалось загрузить значения.', true);
          positionFieldValuePanel(button, panel);
        }
      }

      async function selectFieldAllowedValue(option) {
        const row = option ? option.closest('.supplier-field-row') : null;
        const valueEl = row ? row.querySelector('.supplier-field-value') : null;
        if (!row || !valueEl) return;
        valueEl.textContent = option.dataset.value || '';
        await saveField(row, true);
        closeFieldValuePanels();
        closeFieldEdit(row);
      }

      function applyRichCommand(button) {
        const wrap = button.closest('.supplier-edit-wrap');
        const editable = wrap ? wrap.querySelector('.supplier-inline-edit--rich') : null;
        const command = button.dataset.richCommand || '';
        if (!editable || !command) return;
        editable.focus();
        try {
          document.execCommand(command, false, null);
        } catch (e) {}
        saveBasic(editable, true);
      }

      function categorySourceLabel(source) {
        return source === 'ozon' ? 'Ozon' : 'WB';
      }

      function splitCategoryLabel(label, value) {
        let text = String(label || '').trim();
        let code = String(value || '').trim();
        const codeMatch = text.match(/\s*\(([^()]*)\)\s*$/);
        if (codeMatch) {
          if (!code) code = String(codeMatch[1] || '').trim();
          text = text.replace(/\s*\([^()]*\)\s*$/, '').trim();
        }
        if (!text) return { leaf: code || '—', parents: [], code: code };
        const parts = text.split('>').map(function(part) {
          return part.trim();
        }).filter(Boolean);
        if (!parts.length) return { leaf: text, parents: [], code: code };
        return {
          leaf: parts[parts.length - 1],
          parents: parts.length > 1 ? parts.slice(0, -1) : [],
          code: code
        };
      }

      function categoryOptionInfo(opt) {
        const rawValue = String((opt && (opt.category_value || opt.value)) || '').trim();
        const kind = String((opt && opt.kind) || (rawValue.indexOf('node:') === 0 ? 'parent' : 'leaf'));
        let fullPath = String((opt && (opt.full_path || opt.label)) || rawValue || '').trim();
        fullPath = fullPath.replace(/\s*\([^()]*\)\s*$/, '').trim();
        const parts = fullPath.split('>').map(function(part) { return part.trim(); }).filter(Boolean);
        const explicitName = String((opt && opt.name) || '').trim();
        const name = explicitName || (parts.length ? parts[parts.length - 1] : (fullPath || rawValue || '—'));
        const depthRaw = parseInt(String((opt && opt.depth) || ''), 10);
        const depth = Number.isFinite(depthRaw) && depthRaw >= 0 ? depthRaw : Math.max(0, parts.length - 1);
        const parents = parts.length > 1 ? parts.slice(0, -1) : [];
        const code = String((opt && opt.code) || rawValue || '').replace(/^leaf:/, '').trim();
        const value = rawValue.replace(/^leaf:/, '');
	        return {
	          kind: kind === 'parent' ? 'parent' : 'leaf',
	          value: value,
	          label: value ? ((fullPath || name) + ' (' + value + ')') : (fullPath || name),
	          name: name,
	          fullPath: fullPath,
	          parentPath: parents.join(' › '),
	          code: code,
	          depth: Math.max(0, Math.min(8, depth)),
	          childrenCount: Math.max(0, parseInt(String((opt && opt.children_count) || '0'), 10) || 0)
	        };
	      }

	      function appendMarketplaceCategoryTree(results, options, config) {
	        config = config || {};
	        const tree = document.createElement('div');
	        tree.className = 'marketplace-category-tree';
	        results.appendChild(tree);
	        const query = String(config.query || '').trim();

	        function rowDepth(row) {
	          return Math.max(0, parseInt(String(row ? row.dataset.depth : '0'), 10) || 0);
	        }

	        function descendantRows(row) {
	          const depth = rowDepth(row);
	          const rows = [];
	          let next = row.nextElementSibling;
	          while (next && next.classList && next.classList.contains('marketplace-category-tree-row') && rowDepth(next) > depth) {
	            rows.push(next);
	            next = next.nextElementSibling;
	          }
	          return rows;
	        }

	        function setParentExpanded(row, expanded) {
	          if (!row) return;
	          row.dataset.expanded = expanded ? '1' : '0';
	          row.setAttribute('aria-expanded', expanded ? 'true' : 'false');
	          const icon = row.querySelector('.marketplace-category-tree-parent-icon');
	          if (icon) icon.textContent = expanded ? '⌄' : '›';
	        }

	        function setDescendantsHidden(row, hidden) {
	          descendantRows(row).forEach(function(child) {
	            child.hidden = hidden;
	            if (hidden && child.classList.contains('marketplace-category-tree-parent')) {
	              setParentExpanded(child, false);
	            }
	          });
	        }

	        function insertRowsAfter(row, childOptions) {
	          const fragment = document.createDocumentFragment();
	          appendRows(fragment, childOptions, { loadedParents: false, expandedParents: false });
	          let after = row;
	          const existing = descendantRows(row);
	          if (existing.length) after = existing[existing.length - 1];
	          tree.insertBefore(fragment, after.nextElementSibling);
	        }

	        async function toggleParent(row, info) {
	          const expanded = row.dataset.expanded === '1';
	          if (expanded) {
	            setParentExpanded(row, false);
	            setDescendantsHidden(row, true);
	            return;
	          }
	          setParentExpanded(row, true);
	          if (row.dataset.loaded !== '1' && typeof config.loadChildren === 'function' && info.fullPath) {
	            row.dataset.loading = '1';
	            try {
	              const childOptions = await config.loadChildren(info.fullPath);
	              if (Array.isArray(childOptions) && childOptions.length) {
	                insertRowsAfter(row, childOptions);
	              }
	              row.dataset.loaded = '1';
	            } catch (e) {
	              setParentExpanded(row, false);
	            } finally {
	              row.dataset.loading = '';
	            }
	            return;
	          }
	          setDescendantsHidden(row, false);
	        }

	        async function showAllInSection(button, row, info) {
	          if (!info.fullPath || typeof config.loadAllLeaves !== 'function') return;
	          const oldText = button.textContent;
	          button.disabled = true;
	          button.textContent = 'Загружаю...';
	          try {
	            const leaves = await config.loadAllLeaves(info.fullPath);
	            descendantRows(row).forEach(function(child) {
	              child.remove();
	            });
	            insertRowsAfter(row, Array.isArray(leaves) ? leaves : []);
	            row.dataset.loaded = '1';
	            setParentExpanded(row, true);
	            button.textContent = 'Показаны все';
	          } catch (e) {
	            button.disabled = false;
	            button.textContent = oldText;
	          }
	        }

	        function appendRows(container, rows, opts) {
	          opts = opts || {};
	          const loadedParents = !!opts.loadedParents;
	          const expandedParents = !!opts.expandedParents;

	          rows.forEach(function(opt) {
	            const info = categoryOptionInfo(opt);
	            if (info.kind === 'parent') {
	              const row = document.createElement('div');
	              row.className = 'marketplace-category-tree-row marketplace-category-tree-parent';
	              if (info.depth <= 0) row.classList.add('marketplace-category-tree-row--root');
	              row.style.setProperty('--cat-depth', String(info.depth));
	              row.dataset.depth = String(info.depth);
	              row.dataset.parentPath = info.fullPath;
	              row.dataset.loaded = loadedParents ? '1' : '0';
	              row.setAttribute('role', 'button');
	              row.tabIndex = 0;

		              const icon = document.createElement('span');
		              icon.className = 'marketplace-category-tree-parent-icon';
		              const title = document.createElement('span');
		              title.className = 'marketplace-category-tree-parent-title';
		              title.textContent = info.name;
	              const meta = document.createElement('span');
	              meta.className = 'marketplace-category-tree-meta';
	              meta.textContent = 'раздел';

	              row.appendChild(icon);
	              row.appendChild(title);
	              if (query && info.fullPath && typeof config.loadAllLeaves === 'function') {
	                const showAll = document.createElement('button');
	                showAll.type = 'button';
	                showAll.className = 'marketplace-category-tree-show-all';
	                showAll.textContent = 'Показать все';
	                showAll.addEventListener('click', function(event) {
	                  event.preventDefault();
	                  event.stopPropagation();
	                  showAllInSection(showAll, row, info);
	                });
	                row.appendChild(showAll);
	              }
	              row.appendChild(meta);
	              setParentExpanded(row, expandedParents);
	              row.addEventListener('click', function(event) {
	                if (event.target && event.target.closest && event.target.closest('button')) return;
	                toggleParent(row, info);
	              });
	              row.addEventListener('keydown', function(event) {
	                if (event.key !== 'Enter' && event.key !== ' ') return;
	                event.preventDefault();
	                toggleParent(row, info);
	              });
	              container.appendChild(row);
	              return;
	            }

	            if (!info.value) return;
	            const button = document.createElement('button');
	            button.type = 'button';
	            button.className = config.optionClass + ' marketplace-category-tree-row marketplace-category-tree-leaf';
	            if (info.depth <= 0) button.classList.add('marketplace-category-tree-row--root');
	            button.style.setProperty('--cat-depth', String(info.depth));
	            button.dataset.depth = String(info.depth);
	            button.dataset[config.valueDataset] = info.value;
	            button.dataset[config.labelDataset] = info.label;

	            const icon = document.createElement('span');
	            icon.className = 'marketplace-category-tree-leaf-icon';
	            icon.textContent = '↳';
	            const text = document.createElement('span');
	            const title = document.createElement('span');
	            title.className = 'marketplace-category-tree-leaf-title';
	            title.textContent = info.name;
	            text.appendChild(title);
	            if (info.parentPath) {
	              const path = document.createElement('span');
	              path.className = 'marketplace-category-tree-leaf-path';
	              path.textContent = info.parentPath;
	              text.appendChild(path);
	            }
		            const code = document.createElement('span');
		            code.className = 'marketplace-category-tree-code';
		            code.textContent = info.code || info.value;
		            code.title = info.code || info.value;

	            button.appendChild(icon);
	            button.appendChild(text);
	            button.appendChild(code);
	            container.appendChild(button);
	          });
	        }

	        appendRows(tree, options, { loadedParents: !!query, expandedParents: !!query });
	      }

      function closeCategoryPickers() {
        document.querySelectorAll('.supplier-category-panel.open').forEach(function(panel) {
          panel.classList.remove('open');
          panel.style.left = '';
          panel.style.right = '';
          panel.style.top = '';
          panel.style.bottom = '';
          panel.style.width = '';
          panel.style.maxHeight = '';
        });
      }

      function setCategoryStatus(picker, message, isError) {
        const results = picker ? picker.querySelector('.supplier-category-results') : null;
        if (results) {
          results.innerHTML = '';
          const box = document.createElement('div');
          box.className = 'muted';
          box.style.fontSize = '12px';
          box.style.color = isError ? '#b91c1c' : '';
          box.textContent = message || '';
          results.appendChild(box);
        }
      }

	      async function fetchMarketplaceCategoryOptions(source, query, opts) {
	        opts = opts || {};
	        const q = String(query || '').trim();
	        const parentPath = String(opts.parentPath || '').trim();
	        const allLeaves = !!opts.allLeaves;
	        const limit = Math.max(1, parseInt(String(opts.limit || (allLeaves ? 700 : (parentPath ? 240 : (q ? 260 : 160)))), 10) || 160);
	        let url = 'taxonomy/options.php?source=' + encodeURIComponent(source)
	          + '&q=' + encodeURIComponent(q)
	          + '&limit=' + encodeURIComponent(String(limit))
	          + '&include_parents=1&tree_picker=1';
	        if (parentPath) {
	          url += '&parent_path=' + encodeURIComponent(parentPath);
	        }
	        if (allLeaves) {
	          url += '&all_leaves=1';
	        }
	        const res = await fetch(url, {
	          credentials: 'same-origin',
	          headers: {
	            'Accept': 'application/json'
	          }
	        });
	        const data = await res.json().catch(function() {
	          return null;
	        });
	        if (!res.ok || !data || !data.ok) {
	          throw new Error((data && data.error) ? data.error : 'Не удалось загрузить категории.');
	        }
	        return Array.isArray(data.options) ? data.options : [];
	      }

	      function renderCategoryOptions(picker, options, query) {
	        const results = picker.querySelector('.supplier-category-results');
	        if (!results) return;
	        results.innerHTML = '';
	        if (!options.length) {
	          setCategoryStatus(picker, 'Ничего не найдено', false);
	          return;
	        }
	        const source = picker.dataset.source || '';
	        appendMarketplaceCategoryTree(results, options, {
	          optionClass: 'supplier-category-option',
	          valueDataset: 'value',
	          labelDataset: 'label',
	          query: query,
	          loadChildren: function(parentPath) {
	            return fetchMarketplaceCategoryOptions(source, '', { parentPath: parentPath, limit: 260 });
	          },
	          loadAllLeaves: function(parentPath) {
	            return fetchMarketplaceCategoryOptions(source, '', { parentPath: parentPath, allLeaves: true, limit: 900 });
	          }
	        });
	      }

      async function loadCategoryOptions(picker, query) {
        const source = picker.dataset.source || '';
        const seq = String(Date.now()) + ':' + String(Math.random());
        picker.dataset.loadSeq = seq;
	        setCategoryStatus(picker, 'Загружаем категории ' + categorySourceLabel(source) + '...', false);
	        const q = String(query || '').trim();
	        try {
	          const options = await fetchMarketplaceCategoryOptions(source, q, { limit: q ? 260 : 160 });
	          if (picker.dataset.loadSeq !== seq) return;
	          renderCategoryOptions(picker, options, q);
	        } catch (e) {
	          if (picker.dataset.loadSeq !== seq) return;
	          setCategoryStatus(picker, e.message || 'Не удалось загрузить категории.', true);
        }
      }

      function openCategoryPicker(picker) {
        if (!picker) return;
        const panel = picker.querySelector('.supplier-category-panel');
        const button = picker.querySelector('.supplier-category-button');
        const search = picker.querySelector('.supplier-category-search');
        if (!panel || !button || !search) return;
        if (panel.classList.contains('open')) {
          closeCategoryPickers();
          return;
        }
        closeCategoryPickers();
        closeBulkCategoryPanels();
        if (window.ftOpenDropdownPanel) {
          window.ftOpenDropdownPanel(panel, button);
        } else {
          panel.classList.add('open');
        }
        loadCategoryOptions(picker, search.value);
        search.focus();
      }

      function applyCategoryPickerDisplay(picker, source, value, label, product) {
        if (!picker) return null;
        const text = String(label || value || '—');
        picker.dataset.value = String(value || '');
        const button = picker.querySelector('.supplier-category-button');
        const labelEl = picker.querySelector('.supplier-category-label');
        const parts = splitCategoryLabel(text, value);
        if (labelEl) labelEl.textContent = parts.leaf || text;
        if (button) {
          button.title = text;
          button.classList.toggle('supplier-category-button--empty', !String(value || '').trim() && !String(label || '').trim());
        }
        let hierarchyToggle = picker.querySelector('.supplier-category-hierarchy-toggle');
        let detailsBox = picker.querySelector('.supplier-category-details');
        let codeBox = picker.querySelector('.supplier-category-code');
        const panel = picker.querySelector('.supplier-category-panel');
        const hasDetails = (parts.parents && parts.parents.length > 0) || !!parts.code;
        if (hasDetails) {
          if (!hierarchyToggle) {
            hierarchyToggle = document.createElement('button');
            hierarchyToggle.type = 'button';
            hierarchyToggle.className = 'supplier-category-hierarchy-toggle';
            hierarchyToggle.title = 'Показать иерархию и код';
            hierarchyToggle.setAttribute('aria-expanded', 'false');
            const dash = document.createElement('span');
            dash.className = 'supplier-category-toggle-dash';
            dash.textContent = '—';
            const arrow = document.createElement('span');
            arrow.className = 'supplier-category-toggle-arrow';
            arrow.textContent = '▾';
            hierarchyToggle.appendChild(dash);
            hierarchyToggle.appendChild(arrow);
            picker.insertBefore(hierarchyToggle, button || panel);
          }
          if (parts.parents && parts.parents.length > 0) {
            if (!detailsBox) {
              detailsBox = document.createElement('div');
              detailsBox.className = 'supplier-category-details';
              picker.insertBefore(detailsBox, button || panel);
            }
            detailsBox.innerHTML = '';
            parts.parents.forEach(function(parent) {
              const line = document.createElement('div');
              line.className = 'supplier-category-parent-line';
              line.textContent = parent;
              detailsBox.appendChild(line);
            });
          } else if (detailsBox) {
            detailsBox.remove();
            detailsBox = null;
          }
          if (parts.code) {
            if (!codeBox) {
              codeBox = document.createElement('div');
              codeBox.className = 'supplier-category-code';
              picker.insertBefore(codeBox, panel);
            }
            codeBox.textContent = 'Код: ' + parts.code;
          } else if (codeBox) {
            codeBox.remove();
            codeBox = null;
          }
        } else {
          if (hierarchyToggle) hierarchyToggle.remove();
          if (detailsBox) detailsBox.remove();
          if (codeBox) codeBox.remove();
          picker.classList.remove('is-parents-open');
        }
        const row = picker.closest('tr');
        if (row) {
          if (source === 'ozon') row.dataset.ozoncat = String(value || '');
          else row.dataset.wbcat = String(value || '');
          if (product) applyProductResponse(row, product);
        }
        return row;
      }

      async function setCategoryValue(picker, value, label) {
        if (!picker) return;
        const productId = parseInt(picker.dataset.productId || '0', 10);
        const source = picker.dataset.source || '';
        if (!productId || !source) return;
        const connectionSelectId = source === 'ozon' ? 'datasetOzonConnectionSelect' : 'datasetWbConnectionSelect';
        const connectionSelect = document.getElementById(connectionSelectId);
        const connectionId = connectionSelect ? parseInt(connectionSelect.value || '0', 10) : 0;
        const button = picker.querySelector('.supplier-category-button');
        if (button) button.disabled = true;
        try {
          const data = await postJson({
            action: 'category_set',
            product_id: productId,
            source: source,
            value: value,
            connection_id: connectionId || 0
          });
          applyCategoryPickerDisplay(picker, source, value, label, data.product);
          scheduleBulkReplaceCharacteristicsLoad();
          closeCategoryPickers();
          if (window.ftSupplierOffersReload) {
            await window.ftSupplierOffersReload();
          }
        } catch (e) {
          setCategoryStatus(picker, e.message || 'Не удалось сохранить категорию.', true);
        } finally {
          if (button) button.disabled = false;
        }
      }

	      function selectedOfferIdsForBulkCategory() {
	        const hidden = document.getElementById('offerIdsJson');
	        const raw = hidden ? String(hidden.value || '').trim() : '';
        if (!raw) return [];
        try {
          const parsed = JSON.parse(raw);
          if (!Array.isArray(parsed)) return [];
          return parsed.map(function(value) {
            return String(value || '').trim();
          }).filter(Boolean);
	        } catch (e) {
	          return [];
	        }
	      }

	      function bulkReplaceRoot(node) {
	        return node && node.closest ? node.closest('[data-bulk-replace-card]') : document.querySelector('[data-bulk-replace-card]');
	      }

	      function bulkReplaceScope(root) {
	        const scopeRoot = root || document;
	        const checked = scopeRoot.querySelector('input[name^="supplier_bulk_replace_scope"]:checked');
	        return checked && checked.value === 'all' ? 'all' : 'selected';
	      }

	      function selectedOfferIdsForBulkReplace(root) {
	        return bulkReplaceScope(root) === 'all' ? [] : selectedOfferIdsForBulkCategory();
	      }

	      const bulkCategoryWidgetStorageKey = 'feedtools.supplier_products.bulk_category_widget.<?= h((string)(int)$row['id']) ?>';
	      const bulkReplaceWidgetStorageKey = 'feedtools.supplier_products.bulk_replace_widget.<?= h((string)(int)$row['id']) ?>';

	      function bulkCategoryWidget() {
	        return document.querySelector('[data-bulk-category-widget]');
	      }

	      function bulkReplaceWidget() {
	        return document.querySelector('[data-bulk-replace-widget]');
	      }

	      function clampBulkCategoryWidget(widget, left, top) {
	        const rect = widget.getBoundingClientRect();
	        const margin = 12;
	        const maxLeft = Math.max(margin, window.innerWidth - rect.width - margin);
	        const maxTop = Math.max(margin, window.innerHeight - rect.height - margin);
	        return {
	          left: Math.min(Math.max(margin, left), maxLeft),
	          top: Math.min(Math.max(margin, top), maxTop)
	        };
	      }

	      function placeBulkCategoryWidget(widget, left, top) {
	        if (!widget) return;
	        const pos = clampBulkCategoryWidget(widget, left, top);
	        widget.style.left = pos.left + 'px';
	        widget.style.top = pos.top + 'px';
	        widget.style.right = 'auto';
	        widget.style.bottom = 'auto';
	      }

	      function restoreBulkCategoryWidgetPosition(widget) {
	        if (!widget) return;
	        try {
	          const saved = JSON.parse(localStorage.getItem(bulkCategoryWidgetStorageKey) || 'null');
	          if (saved && Number.isFinite(Number(saved.left)) && Number.isFinite(Number(saved.top))) {
	            placeBulkCategoryWidget(widget, Number(saved.left), Number(saved.top));
	            return;
	          }
	        } catch (e) {}
	        widget.style.left = '';
	        widget.style.top = '';
	        widget.style.right = '24px';
	        widget.style.bottom = '24px';
	      }

	      function saveBulkCategoryWidgetPosition(widget) {
	        if (!widget) return;
	        const rect = widget.getBoundingClientRect();
	        try {
	          localStorage.setItem(bulkCategoryWidgetStorageKey, JSON.stringify({
	            left: Math.round(rect.left),
	            top: Math.round(rect.top)
	          }));
	        } catch (e) {}
	      }

	      function openBulkCategoryWidget() {
	        const widget = bulkCategoryWidget();
	        if (!widget) return;
	        widget.hidden = false;
	        restoreBulkCategoryWidgetPosition(widget);
	        updateBulkCategoryButtonState();
	      }

	      function closeBulkCategoryWidget() {
	        const widget = bulkCategoryWidget();
	        if (!widget) return;
	        widget.hidden = true;
	        closeBulkCategoryPanels();
	      }

	      function clampFloatingWidget(widget, left, top) {
	        const rect = widget.getBoundingClientRect();
	        const margin = 12;
	        const maxLeft = Math.max(margin, window.innerWidth - rect.width - margin);
	        const maxTop = Math.max(margin, window.innerHeight - rect.height - margin);
	        return {
	          left: Math.min(Math.max(margin, left), maxLeft),
	          top: Math.min(Math.max(margin, top), maxTop)
	        };
	      }

	      function placeFloatingWidget(widget, left, top) {
	        if (!widget) return;
	        const pos = clampFloatingWidget(widget, left, top);
	        widget.style.left = pos.left + 'px';
	        widget.style.top = pos.top + 'px';
	        widget.style.right = 'auto';
	        widget.style.bottom = 'auto';
	      }

	      function restoreFloatingWidgetPosition(widget, storageKey) {
	        if (!widget) return;
	        try {
	          const saved = JSON.parse(localStorage.getItem(storageKey) || 'null');
	          if (saved && Number.isFinite(Number(saved.left)) && Number.isFinite(Number(saved.top))) {
	            placeFloatingWidget(widget, Number(saved.left), Number(saved.top));
	            return;
	          }
	        } catch (e) {}
	        widget.style.left = '';
	        widget.style.top = '';
	        widget.style.right = '24px';
	        widget.style.bottom = '24px';
	      }

	      function saveFloatingWidgetPosition(widget, storageKey) {
	        if (!widget) return;
	        const rect = widget.getBoundingClientRect();
	        try {
	          localStorage.setItem(storageKey, JSON.stringify({
	            left: Math.round(rect.left),
	            top: Math.round(rect.top)
	          }));
	        } catch (e) {}
	      }

	      function openBulkReplaceWidget() {
	        const widget = bulkReplaceWidget();
	        if (!widget) return;
	        widget.hidden = false;
	        restoreFloatingWidgetPosition(widget, bulkReplaceWidgetStorageKey);
	        scheduleBulkReplaceCharacteristicsLoad(widget);
