        box.textContent = message || '';
        results.appendChild(box);
      }

      function renderBrandCategoryOptions(root, options) {
        const results = root ? root.querySelector('.supplier-brand-category-results') : null;
        if (!results) return;
        results.innerHTML = '';
        if (!options.length) {
          const empty = document.createElement('div');
          empty.className = 'muted';
          empty.style.fontSize = '12px';
          empty.textContent = 'Ничего не найдено';
          results.appendChild(empty);
          return;
        }
        const selected = getBrandCategorySelection(root);
        const actions = document.createElement('div');
        actions.className = 'supplier-brand-category-actions';
        const selectAll = document.createElement('button');
        selectAll.type = 'button';
        selectAll.className = 'supplier-brand-category-action';
        selectAll.dataset.brandCategorySelectVisible = '1';
        selectAll.textContent = 'Выбрать все категории';
        const clearAll = document.createElement('button');
        clearAll.type = 'button';
        clearAll.className = 'supplier-brand-category-action secondary';
        clearAll.dataset.brandCategoryClear = '1';
        clearAll.textContent = 'Снять выбор';
        actions.appendChild(selectAll);
        actions.appendChild(clearAll);
        results.appendChild(actions);
        options.forEach(function(opt) {
          const value = String(opt.value || '');
          const label = String(opt.label || value);
          if (!value) return;
          const kind = String(opt.kind || (value.indexOf('node:') === 0 ? 'parent' : 'leaf'));
          const categoryValue = String(opt.category_value || '');
          const childrenCount = Math.max(0, parseInt(String(opt.children_count || '0'), 10) || 0);

          const row = document.createElement('label');
          row.className = 'supplier-brand-category-option';
          if (selected.has(value)) row.classList.add('is-selected');
          row.dataset.brandCategoryValue = value;
          row.dataset.brandCategoryLabel = label;
          row.dataset.brandCategoryKind = kind;
          row.dataset.brandCategoryValueRaw = categoryValue;
          row.dataset.brandCategoryChildren = String(childrenCount);

          const checkbox = document.createElement('input');
          checkbox.type = 'checkbox';
          checkbox.checked = selected.has(value);
          checkbox.setAttribute('aria-label', label);

          const text = document.createElement('span');
          const title = document.createElement('span');
          title.className = 'supplier-brand-category-option-title';
          title.textContent = label;
          const meta = document.createElement('span');
          meta.className = 'supplier-brand-category-option-meta';
          meta.textContent = kind === 'parent'
            ? 'ветка категорий, дочерних: ' + childrenCount
            : 'листовая категория';
          text.appendChild(title);
          text.appendChild(meta);

          row.appendChild(checkbox);
          row.appendChild(text);
          results.appendChild(row);
        });
      }

      async function loadBrandCategoryOptions(root, query) {
        const source = root ? String(root.dataset.brandCategorySource || '') : '';
        if (!source) return;
        const seq = String(Date.now()) + ':' + String(Math.random());
        root.dataset.loadSeq = seq;
        setBrandCategoryStatus(root, 'Загружаем категории ' + categorySourceLabel(source) + '...', false);
        const q = String(query || '').trim();
        const limit = q ? 160 : 900;
        try {
          let url = 'taxonomy/options.php?source=' + encodeURIComponent(source) + '&q=' + encodeURIComponent(q) + '&limit=' + encodeURIComponent(String(limit)) + '&include_parents=1';
          if (source === 'ozon') {
            url += '&max_depth=2&include_leaves=0';
          } else if (source === 'wildberries') {
            url += '&max_depth=2&include_leaves=0';
          }
          const res = await fetch(url, {
            credentials: 'same-origin',
            headers: { 'Accept': 'application/json' }
          });
          const data = await res.json().catch(function() { return null; });
          if (root.dataset.loadSeq !== seq) return;
          if (!res.ok || !data || !data.ok) {
            throw new Error((data && data.error) ? data.error : 'Не удалось загрузить категории.');
          }
          renderBrandCategoryOptions(root, Array.isArray(data.options) ? data.options : []);
        } catch (e) {
          if (root.dataset.loadSeq !== seq) return;
          setBrandCategoryStatus(root, e.message || 'Не удалось загрузить категории.', true);
        }
      }

      function openBrandCategoryPicker(root) {
        if (!root) return;
        const panel = root.querySelector('.supplier-bulk-category-panel');
        const button = root.querySelector('[data-brand-category-toggle]');
        const search = root.querySelector('.supplier-brand-category-search');
        if (!panel || !button || !search) return;
        if (panel.classList.contains('open')) {
          closeBulkCategoryPanels();
          return;
        }
        closeCategoryPickers();
        closeBulkCategoryPanels();
        if (window.ftOpenDropdownPanel) {
          window.ftOpenDropdownPanel(panel, button);
        } else {
          panel.classList.add('open');
        }
        loadBrandCategoryOptions(root, search.value);
        search.focus();
      }

      function brandCategoryShortLabel(label, value) {
        let text = String(label || '').trim();
        const codeMatch = text.match(/\s*\(([^()]*)\)\s*$/);
        if (codeMatch) {
          text = text.replace(/\s*\([^()]*\)\s*$/, '').trim();
        }
        const parts = text.split('>').map(function(part) { return part.trim(); }).filter(Boolean);
        let short = parts.length ? parts[parts.length - 1] : (text || String(value || '').trim());
        if (codeMatch && codeMatch[1]) short += ' (' + codeMatch[1] + ')';
        return short.length > 68 ? short.slice(0, 65) + '...' : short;
      }

      function getBrandCategorySelection(root) {
        if (!root) return new Map();
        if (!root._brandCategorySelection) {
          root._brandCategorySelection = new Map();
          const form = root.closest('[data-brand-category-sync-form]');
          const jsonInput = form ? form.querySelector('[data-brand-category-values-json]') : null;
          const raw = jsonInput ? String(jsonInput.value || '') : '';
          try {
            const decoded = JSON.parse(raw || '[]');
            if (Array.isArray(decoded)) {
              decoded.forEach(function(item) {
                if (!item) return;
                const value = String((typeof item === 'object' ? (item.value || item.category_value) : item) || '').trim();
                if (!value) return;
                root._brandCategorySelection.set(value, {
                  value: value,
                  label: String(typeof item === 'object' ? (item.label || value) : value),
                  kind: String(typeof item === 'object' ? (item.kind || '') : ''),
                  category_value: String(typeof item === 'object' ? (item.category_value || '') : ''),
                  children_count: Math.max(0, parseInt(String(typeof item === 'object' ? (item.children_count || '0') : '0'), 10) || 0)
                });
              });
            }
          } catch (e) {}
        }
        return root._brandCategorySelection;
      }

      function updateBrandCategoryForm(root) {
        const form = root ? root.closest('[data-brand-category-sync-form]') : null;
        if (!root || !form) return;
        const items = Array.from(getBrandCategorySelection(root).values());
        const input = form.querySelector('[data-brand-category-value]');
        const jsonInput = form.querySelector('[data-brand-category-values-json]');
        const submit = form.querySelector('[data-brand-category-submit]');
        const toggle = root.querySelector('[data-brand-category-toggle]');
        const first = items[0] || null;
        if (input) input.value = first ? String(first.category_value || first.value || '') : '';
        if (jsonInput) jsonInput.value = JSON.stringify(items);
        if (submit) submit.disabled = items.length === 0;
        if (toggle) {
          const source = String(root.dataset.brandCategorySource || '');
          if (items.length === 0) {
            toggle.textContent = source === 'ozon' ? 'Выбрать категории Ozon' : 'Выбрать категории WB';
            toggle.title = '';
          } else if (items.length === 1) {
            toggle.textContent = brandCategoryShortLabel(items[0].label, items[0].value);
            toggle.title = items[0].label || items[0].value || '';
          } else {
            toggle.textContent = 'Выбрано категорий: ' + items.length;
            toggle.title = items.slice(0, 30).map(function(item) { return item.label || item.value; }).join('\n') + (items.length > 30 ? '\n...' : '');
          }
        }
      }

      function toggleBrandCategoryOption(option) {
        const root = option ? option.closest('.supplier-brand-category-picker') : null;
        if (!root) return;
        const selected = getBrandCategorySelection(root);
        const value = String(option.dataset.brandCategoryValue || '').trim();
        if (!value) return;
        if (selected.has(value)) {
          selected.delete(value);
          option.classList.remove('is-selected');
        } else {
          selected.set(value, {
            value: value,
            label: String(option.dataset.brandCategoryLabel || option.textContent || value).trim(),
            kind: String(option.dataset.brandCategoryKind || ''),
            category_value: String(option.dataset.brandCategoryValueRaw || ''),
            children_count: Math.max(0, parseInt(String(option.dataset.brandCategoryChildren || '0'), 10) || 0)
          });
          option.classList.add('is-selected');
        }
        const checkbox = option.querySelector('input[type="checkbox"]');
        if (checkbox) checkbox.checked = selected.has(value);
        updateBrandCategoryForm(root);
      }

      function selectVisibleBrandCategoryOptions(root) {
        if (!root) return;
        const selected = getBrandCategorySelection(root);
        root.querySelectorAll('.supplier-brand-category-option[data-brand-category-value]').forEach(function(option) {
          const value = String(option.dataset.brandCategoryValue || '').trim();
          if (!value) return;
          selected.set(value, {
            value: value,
            label: String(option.dataset.brandCategoryLabel || option.textContent || value).trim(),
            kind: String(option.dataset.brandCategoryKind || ''),
            category_value: String(option.dataset.brandCategoryValueRaw || ''),
            children_count: Math.max(0, parseInt(String(option.dataset.brandCategoryChildren || '0'), 10) || 0)
          });
          option.classList.add('is-selected');
          const checkbox = option.querySelector('input[type="checkbox"]');
          if (checkbox) checkbox.checked = true;
        });
        updateBrandCategoryForm(root);
      }

      function clearBrandCategorySelection(root) {
        if (!root) return;
        getBrandCategorySelection(root).clear();
        root.querySelectorAll('.supplier-brand-category-option').forEach(function(option) {
          option.classList.remove('is-selected');
          const checkbox = option.querySelector('input[type="checkbox"]');
          if (checkbox) checkbox.checked = false;
        });
        updateBrandCategoryForm(root);
      }

      document.querySelectorAll('[data-brand-category-sync-form]').forEach(function(form) {
        const root = form.querySelector('.supplier-brand-category-picker');
        if (root) updateBrandCategoryForm(root);
        form.addEventListener('submit', function(e) {
          const picker = form.querySelector('.supplier-brand-category-picker');
          if (picker) updateBrandCategoryForm(picker);
          const jsonInput = form.querySelector('[data-brand-category-values-json]');
          let selected = [];
          try {
            selected = JSON.parse(String(jsonInput ? jsonInput.value : '[]') || '[]');
          } catch (err) {
            selected = [];
          }
          if (!Array.isArray(selected) || selected.length === 0) {
            e.preventDefault();
            e.stopImmediatePropagation();
            const source = String(form.dataset.brandCategorySource || '');
            alert('Выбери одну или несколько категорий ' + categorySourceLabel(source) + '.');
          }
        }, true);
      });

	      function showSupplierSuccessToast() {
	        let toast = document.querySelector('.supplier-success-toast');
	        if (!toast) {
	          toast = document.createElement('div');
	          toast.className = 'supplier-success-toast';
	          toast.setAttribute('aria-hidden', 'true');
	          document.body.appendChild(toast);
	        }
	        if (toast._hideTimer) window.clearTimeout(toast._hideTimer);
	        toast.classList.remove('is-busy');
	        toast.textContent = '✓';
	        toast.classList.add('is-visible');
	        toast._hideTimer = window.setTimeout(function() {
	          toast.classList.remove('is-visible');
	        }, 3800);
	      }

	      function showSupplierBusyToast() {
	        let toast = document.querySelector('.supplier-success-toast');
	        if (!toast) {
	          toast = document.createElement('div');
	          toast.className = 'supplier-success-toast';
	          toast.setAttribute('aria-hidden', 'true');
	          document.body.appendChild(toast);
	        }
	        if (toast._hideTimer) window.clearTimeout(toast._hideTimer);
	        toast.textContent = '';
	        toast.classList.add('is-busy', 'is-visible');
	      }

	      function hideSupplierBusyToast() {
	        const toast = document.querySelector('.supplier-success-toast');
	        if (!toast || !toast.classList.contains('is-busy')) return;
	        toast.classList.remove('is-visible', 'is-busy');
	        toast.textContent = '';
	      }

      function updateVisibleBulkCategoryRows(offerIds, source, value, label, products) {
        const selected = new Set(offerIds.map(String));
        const productByOfferId = {};
        (products || []).forEach(function(product) {
          const offerId = String(product.offer_id || '').trim();
          if (offerId) productByOfferId[offerId] = product;
        });
        document.querySelectorAll('input.offerChk[data-offer-id]').forEach(function(chk) {
          const offerId = String(chk.getAttribute('data-offer-id') || '').trim();
          if (!offerId || !selected.has(offerId)) return;
          const row = chk.closest('tr');
          if (!row) return;
          const pickerSource = source === 'ozon' ? 'ozon' : 'wildberries';
          const picker = row.querySelector('.supplier-category-picker[data-source="' + pickerSource + '"]');
          if (picker) {
            applyCategoryPickerDisplay(picker, pickerSource, value, label, productByOfferId[offerId] || null);
          }
        });
      }

      function updateBulkCategoryButtonState() {
        const hasSelection = selectedOfferIdsForBulkCategory().length > 0;
        document.querySelectorAll('[data-bulk-category-toggle]').forEach(function(button) {
          if (button.dataset.bulkBusy === '1') return;
          button.disabled = !hasSelection;
        });
      }

      function bulkOfferControlsRoot(node) {
        return node && node.closest ? node.closest('[data-bulk-offer-controls-card]') : document.querySelector('[data-bulk-offer-controls-card]');
      }

      function bulkOfferControlsScope(root) {
        const checked = (root || document).querySelector('input[name^="supplier_bulk_offer_controls_scope"]:checked');
        return checked && checked.value === 'all' ? 'all' : 'selected';
      }

      function selectedOfferIdsForBulkOfferControls(root) {
        return bulkOfferControlsScope(root) === 'all' ? [] : selectedOfferIdsForBulkCategory();
      }

      function setBulkOfferControlsStatus(root, message, isError) {
        const status = root ? root.querySelector('[data-bulk-offer-controls-status]') : null;
        if (!status) return;
        status.textContent = message || '';
        status.classList.toggle('is-error', !!isError);
      }

      function updateBulkOfferControlsButtonState(root) {
        const roots = root ? [root] : Array.from(document.querySelectorAll('[data-bulk-offer-controls-card]'));
        roots.forEach(function(item) {
          const disabled = bulkOfferControlsScope(item) === 'selected' && selectedOfferIdsForBulkOfferControls(item).length === 0;
          item.querySelectorAll('[data-bulk-offer-control-action]').forEach(function(button) {
            if (button.dataset.bulkBusy === '1') return;
            button.disabled = disabled;
          });
        });
      }

      async function runBulkOfferControls(root, action) {
        if (!root || !action) return;
        const scope = bulkOfferControlsScope(root);
        const offerIds = selectedOfferIdsForBulkOfferControls(root);
        if (scope === 'selected' && !offerIds.length) {
          window.alert('Сначала выбери товары в таблице.');
          return;
        }

        const updates = {};
        if (action === 'stock') {
          const input = root.querySelector('[data-bulk-offer-control-stock]');
          updates.stock_modifier = String(input ? input.value : '').trim();
        } else if (action === 'price') {
          const input = root.querySelector('[data-bulk-offer-control-price]');
          updates.price_modifier = String(input ? input.value : '').trim();
        } else if (action === 'enable') {
          updates.marketplace_enabled = 1;
        } else if (action === 'disable') {
          updates.marketplace_enabled = 0;
        } else {
          return;
        }

        const buttons = Array.from(root.querySelectorAll('[data-bulk-offer-control-action]'));
        buttons.forEach(function(button) {
          button.dataset.bulkBusy = '1';
          button.disabled = true;
        });
        setBulkOfferControlsStatus(root, 'Обновляю товары...', false);
        showSupplierBusyToast();
        try {
          const data = await postJson({
            action: 'bulk_offer_controls_update',
            dataset_id: <?= json_encode((int)$row['id']) ?>,
            offer_ids: offerIds,
            scope: scope,
            updates: updates
          });
          const changed = Number(data.products_changed || 0);
          const matched = Number(data.matched || 0);
          setBulkOfferControlsStatus(root, 'Обновлено товаров: ' + changed + ' из ' + matched + '.', false);
          showSupplierSuccessToast();
          if (window.ftSupplierOffersReload) {
            await window.ftSupplierOffersReload();
          }
        } catch (e) {
          hideSupplierBusyToast();
          setBulkOfferControlsStatus(root, e.message || 'Не удалось обновить товары.', true);
        } finally {
          buttons.forEach(function(button) {
            delete button.dataset.bulkBusy;
          });
          updateBulkOfferControlsButtonState(root);
        }
      }

	      async function applyBulkCategory(root, value, label) {
	        const source = root ? String(root.dataset.bulkCategorySource || '') : '';
	        const offerIds = selectedOfferIdsForBulkCategory();
        if (!source) return;
        if (!offerIds.length) {
          window.alert('Сначала выбери товары в таблице.');
          return;
        }
        const buttons = Array.from(document.querySelectorAll('[data-bulk-category-toggle]'));
	        buttons.forEach(function(button) {
	          button.dataset.bulkBusy = '1';
	          button.disabled = true;
	        });
	        showSupplierBusyToast();
	        const connectionSelectId = source === 'ozon' ? 'datasetOzonConnectionSelect' : 'datasetWbConnectionSelect';
	        const connectionSelect = document.getElementById(connectionSelectId);
	        const connectionId = connectionSelect ? parseInt(connectionSelect.value || '0', 10) : 0;
        try {
          const data = await postJson({
            action: 'category_bulk_set',
            dataset_id: <?= json_encode((int)$row['id']) ?>,
            source: source,
            value: value,
            offer_ids: offerIds,
            connection_id: connectionId || 0
          });
          updateVisibleBulkCategoryRows(offerIds, source, value, label, Array.isArray(data.products) ? data.products : []);
          closeBulkCategoryPanels();
          if (window.ftSupplierOffersReload) {
            await window.ftSupplierOffersReload();
          }
	          showSupplierSuccessToast();
	        } catch (e) {
	          hideSupplierBusyToast();
	          setBulkCategoryStatus(root, e.message || 'Не удалось присвоить категорию.', true);
	        } finally {
          buttons.forEach(function(button) {
            delete button.dataset.bulkBusy;
          });
	          updateBulkCategoryButtonState();
	        }
	      }

	      function bulkTnvedCard(node) {
	        return node && node.closest ? node.closest('[data-bulk-tnved-card]') : document.querySelector('[data-bulk-tnved-card]');
	      }

	      function closeBulkTnvedPanel() {
	        document.querySelectorAll('[data-bulk-tnved-panel].open').forEach(function(panel) {
	          panel.classList.remove('open');
	          panel.style.left = '';
	          panel.style.right = '';
	          panel.style.top = '';
	          panel.style.bottom = '';
	          panel.style.width = '';
	          panel.style.maxHeight = '';
	        });
	      }

	      function setBulkTnvedStatus(root, message, isError) {
	        const status = root ? root.querySelector('[data-bulk-tnved-status]') : null;
	        if (!status) return;
	        status.textContent = message || '';
	        status.classList.toggle('is-error', !!isError);
	      }

	      function setBulkTnvedMessage(root, message, isError) {
	        const results = root ? root.querySelector('[data-bulk-tnved-results]') : null;
	        if (!results) return;
	        results.innerHTML = '';
	        const box = document.createElement('div');
	        box.className = 'muted';
	        box.style.fontSize = '12px';
	        box.style.color = isError ? '#b91c1c' : '';
	        box.textContent = message || '';
	        results.appendChild(box);
	      }

	      function renderBulkTnvedOptions(root, values) {
	        const results = root ? root.querySelector('[data-bulk-tnved-results]') : null;
	        if (!results) return;
	        results.innerHTML = '';
	        const list = Array.isArray(values) ? values : [];
	        if (!list.length) {
	          setBulkTnvedMessage(root, 'Ничего не найдено. Можно назначить введённый код вручную.', false);
	          return;
	        }
	        list.forEach(function(item) {
	          const value = String((item && item.value) || item || '').trim();
	          if (!value) return;
	          const parts = splitTnvedValue(value);
	          const button = document.createElement('button');
	          button.type = 'button';
	          button.className = 'supplier-field-value-option supplier-field-value-option--tnved';
	          button.dataset.bulkTnvedValue = value;

	          const code = document.createElement('span');
	          code.className = 'supplier-field-value-option-code';
	          code.textContent = parts.code || value;
	          const desc = document.createElement('span');
	          desc.className = 'supplier-field-value-option-desc';
	          desc.textContent = parts.desc || (parts.code ? '' : value);
	          button.appendChild(code);
	          button.appendChild(desc);
	          results.appendChild(button);
	        });
	      }

	      async function loadBulkTnvedValues(root, query) {
	        const q = String(query || '').trim();
	        if (!root) return;
	        const offerIds = selectedOfferIdsForBulkCategory();
	        if (!offerIds.length) {
	          setBulkTnvedMessage(root, 'Сначала выбери товары в таблице.', true);
	          return;
	        }
	        if (q.length < 2) {
	          setBulkTnvedMessage(root, 'Введи минимум 2 символа: код или слово из описания.', false);
	          return;
	        }
	        const seq = String(Date.now()) + ':' + String(Math.random());
	        root.dataset.tnvedLoadSeq = seq;
	        setBulkTnvedMessage(root, 'Ищу значения ТН ВЭД...', false);
	        const connectionSelect = document.getElementById('datasetOzonConnectionSelect');
	        const connectionId = connectionSelect ? parseInt(connectionSelect.value || '0', 10) : 0;
	        try {
	          const data = await postJson({
	            action: 'tnved_bulk_values',
	            dataset_id: <?= json_encode((int)$row['id']) ?>,
	            offer_ids: offerIds,
	            query: q,
	            connection_id: connectionId || 0
	          });
	          if (root.dataset.tnvedLoadSeq !== seq) return;
	          renderBulkTnvedOptions(root, Array.isArray(data.values) ? data.values : []);
	        } catch (e) {
	          if (root.dataset.tnvedLoadSeq !== seq) return;
	          setBulkTnvedMessage(root, e.message || 'Не удалось загрузить значения ТН ВЭД.', true);
	        }
	      }

	      function openBulkTnvedPanel(root) {
	        if (!root) return;
	        const panel = root.querySelector('[data-bulk-tnved-panel]');
	        const input = root.querySelector('[data-bulk-tnved-input]');
	        if (!panel || !input) return;
	        closeCategoryPickers();
	        closeBulkCategoryPanels();
	        closeBulkReplaceValuePanels();
	        closeBulkTnvedPanel();
	        if (window.ftOpenDropdownPanel) {
	          window.ftOpenDropdownPanel(panel, input);
	        } else {
	          panel.classList.add('open');
	        }
	        loadBulkTnvedValues(root, input.value);
	        input.focus();
	      }

	      async function applyBulkTnved(root, value) {
	        if (!root) return;
	        const offerIds = selectedOfferIdsForBulkCategory();
	        if (!offerIds.length) {
	          window.alert('Сначала выбери товары в таблице.');
	          return;
	        }
	        const input = root.querySelector('[data-bulk-tnved-input]');
	        const nextValue = value !== undefined ? String(value || '') : String(input ? input.value : '').trim();
	        const buttons = Array.from(root.querySelectorAll('[data-bulk-tnved-apply], [data-bulk-tnved-clear], [data-bulk-tnved-toggle]'));
	        buttons.forEach(function(button) { button.disabled = true; });
	        setBulkTnvedStatus(root, nextValue === '' ? 'Очищаю ТН ВЭД...' : 'Назначаю ТН ВЭД...', false);
	        closeBulkTnvedPanel();
	        try {
	          const data = await postJson({
	            action: 'tnved_bulk_set',
	            dataset_id: <?= json_encode((int)$row['id']) ?>,
	            offer_ids: offerIds,
	            value: nextValue
	          });
	          const changed = Number(data.products_changed || 0);
	          setBulkTnvedStatus(root, 'Обновлено товаров: ' + changed + '.', false);
	          showSupplierSuccessToast();
	          if (window.ftSupplierOffersReload) {
	            await window.ftSupplierOffersReload();
	          }
		        } catch (e) {
		          setBulkTnvedStatus(root, e.message || 'Не удалось назначить ТН ВЭД.', true);
		        } finally {
		          buttons.forEach(function(button) { button.disabled = false; });
		          updateBulkTnvedButtonState();
		        }
		      }

	      function updateBulkTnvedButtonState() {
	        const hasSelection = selectedOfferIdsForBulkCategory().length > 0;
	        document.querySelectorAll('[data-bulk-tnved-card]').forEach(function(root) {
	          root.querySelectorAll('[data-bulk-tnved-apply], [data-bulk-tnved-clear], [data-bulk-tnved-toggle]').forEach(function(button) {
	            button.disabled = !hasSelection;
	          });
	        });
	      }

	      function setBulkReplaceStatus(message, isError, root) {
	        const status = (root || document).querySelector('[data-bulk-replace-status]');
	        if (!status) return;
	        status.textContent = message || '';
	        status.classList.toggle('is-error', !!isError);
	      }

	      function targetForBulkReplaceRow(row) {
	        if (!row) return null;
        const type = String(row.dataset.bulkReplaceType || '').trim();
        if (type === 'field') {
          const select = row.querySelector('[data-bulk-replace-characteristic]');
          const option = select ? select.options[select.selectedIndex] : null;
          const targetsJson = option ? String(option.dataset.targets || '').trim() : '';
          if (targetsJson) {
            try {
              const targets = JSON.parse(targetsJson)
                .filter(function(target) {
                  return target && String(target.kind || '').trim() && String(target.field || '').trim();
                })
                .map(function(target) {
                  return {
                    kind: String(target.kind || '').trim(),
                    field: String(target.field || '').trim()
                  };
                });
              if (targets.length) {
                return { type: 'field', targets: targets };
              }
            } catch (e) {}
          }
          const kind = option ? String(option.dataset.kind || '').trim() : '';
          const field = option ? String(option.dataset.fieldName || '').trim() : '';
          if (!kind || !field) {
            throw new Error('Выбери характеристику.');
          }
	          return { type: 'field', kind: kind, field: field };
	        }
	        const field = String(row.dataset.bulkReplaceField || '').trim();
	        if (!type || !field) {
	          throw new Error('Не выбрано поле для замены.');
	        }
	        return { type: type, field: field };
	      }

      function closeBulkReplaceValuePanels() {
        document.querySelectorAll('.supplier-bulk-replace-values-panel.is-open').forEach(function(panel) {
          panel.classList.remove('is-open');
        });
      }

      function closeFieldValuePanels() {
        document.querySelectorAll('.supplier-field-values-panel.is-open').forEach(function(panel) {
          panel.classList.remove('is-open');
          panel.__fieldValuesAnchor = null;
          panel.style.left = '';
          panel.style.right = '';
          panel.style.top = '';
          panel.style.bottom = '';
          panel.style.width = '';
          panel.style.maxHeight = '';
        });
      }

      let offerDescriptionFitFrame = 0;
      function fitOfferDescriptionPreviews() {
        const previews = Array.from(document.querySelectorAll('.supplier-description-cell .offer-description-preview'));
        previews.forEach(function(preview) {
          preview.style.removeProperty('--supplier-description-height');
          preview.style.removeProperty('--supplier-description-max-height');
        });
        window.requestAnimationFrame(function() {
          previews.forEach(function(preview) {
            const row = preview.closest('tr');
            const cell = preview.closest('.supplier-description-cell');
            if (!row || !cell || !row.getBoundingClientRect) return;
            const rowHeight = row.getBoundingClientRect().height || 0;
            const style = window.getComputedStyle ? window.getComputedStyle(cell) : null;
            const paddingTop = style ? (parseFloat(style.paddingTop) || 0) : 0;
            const paddingBottom = style ? (parseFloat(style.paddingBottom) || 0) : 0;
            const target = Math.floor(rowHeight - paddingTop - paddingBottom - 2);
            if (target <= 40) return;
            const height = Math.min(target, Math.max(220, Math.floor(window.innerHeight * 0.82)));
            preview.style.setProperty('--supplier-description-height', height + 'px');
            preview.style.setProperty('--supplier-description-max-height', height + 'px');
          });
        });
      }

      function scheduleOfferDescriptionFit() {
        if (offerDescriptionFitFrame) {
          window.cancelAnimationFrame(offerDescriptionFitFrame);
        }
        offerDescriptionFitFrame = window.requestAnimationFrame(function() {
          offerDescriptionFitFrame = 0;
          fitOfferDescriptionPreviews();
        });
      }

	      function bulkReplaceCharacteristicSelect(root) {
	        return (root || document).querySelector('[data-bulk-replace-characteristic]');
	      }

	      function setBulkReplaceCharacteristicOptions(select, options, placeholder, selectedKey) {
	        if (!select) return;
	        select.innerHTML = '';
	        const first = document.createElement('option');
	        first.value = '';
	        first.textContent = placeholder || 'характеристика';
	        select.appendChild(first);
	        (Array.isArray(options) ? options : []).forEach(function(item) {
	          const rawTargets = Array.isArray(item && item.targets) ? item.targets : [];
	          const targets = rawTargets
	            .filter(function(target) {
	              return target && String(target.kind || '').trim() && String(target.field || '').trim();
	            })
	            .map(function(target) {
	              return {
	                kind: String(target.kind || '').trim(),
	                field: String(target.field || '').trim()
	              };
	            });
	          const firstTarget = targets[0] || null;
	          const kind = String((item && item.kind) || (firstTarget && firstTarget.kind) || '').trim();
	          const name = String((item && item.name) || (firstTarget && firstTarget.field) || '').trim();
	          if (!kind || !name) return;
	          const option = document.createElement('option');
	          option.value = targets.length
	            ? targets.map(function(target) { return target.kind + '\n' + target.field; }).join('\n--\n')
	            : kind + '\n' + name;
	          option.dataset.kind = kind;
	          option.dataset.fieldName = name;
          if (targets.length) {
            option.dataset.targets = JSON.stringify(targets);
          }
          const allowedValues = Array.isArray(item && item.allowed_values)
            ? item.allowed_values.map(function(value) { return String(value || '').trim(); }).filter(Boolean)
            : [];
          if (allowedValues.length) {
            option.dataset.allowedValues = JSON.stringify(allowedValues);
          }
          const count = Number((item && item.count) || 0);
          option.textContent = String((item && item.label) || name) + (count > 0 ? (' (' + count + ')') : '');
          select.appendChild(option);
        });
        if (selectedKey) {
          select.value = selectedKey;
        }
        updateBulkReplaceAllowedToggle(select.closest('[data-bulk-replace-card]'));
      }

      function selectedBulkReplaceAllowedValues(row) {
        const select = row ? row.querySelector('[data-bulk-replace-characteristic]') : null;
        const option = select ? select.options[select.selectedIndex] : null;
        const raw = option ? String(option.dataset.allowedValues || '').trim() : '';
        if (!raw) return [];
        try {
          const values = JSON.parse(raw);
          return Array.isArray(values) ? values.map(function(value) {
            return String(value || '').trim();
          }).filter(Boolean) : [];
        } catch (e) {
          return [];
        }
      }

      function updateBulkReplaceAllowedToggle(root) {
        const scopeRoot = root || document;
        scopeRoot.querySelectorAll('[data-bulk-replace-row][data-bulk-replace-type="field"]').forEach(function(row) {
          const toggle = row.querySelector('[data-bulk-replace-allowed-toggle]');
          if (!toggle) return;
          const values = selectedBulkReplaceAllowedValues(row);
          toggle.hidden = values.length === 0;
          if (!values.length) {
            const panel = toggle.parentElement ? toggle.parentElement.querySelector('.supplier-bulk-replace-values-panel') : null;
            if (panel) panel.classList.remove('is-open');
          }
        });
      }

		      async function loadBulkReplaceCharacteristics(force, root) {
		        if (!root) {
		          const roots = Array.from(document.querySelectorAll('[data-bulk-replace-card]'));
		          for (const item of roots) {
		            await loadBulkReplaceCharacteristics(force, item);
		          }
		          return;
		        }
		        const select = bulkReplaceCharacteristicSelect(root);
		        if (!select) return;
		        const scope = bulkReplaceScope(root);
		        const offerIds = selectedOfferIdsForBulkReplace(root);
		        const idsKey = scope + ':' + JSON.stringify(offerIds);
		        if (!force && select.dataset.loadedForIds === idsKey) return;
		        closeBulkReplaceValuePanels();
		        const previousKey = String(select.value || '');
		        select.dataset.loadedForIds = idsKey;
		        if (scope === 'selected' && !offerIds.length) {
		          setBulkReplaceCharacteristicOptions(select, [], 'выбери товары', '');
		          return;
		        }
		        setBulkReplaceCharacteristicOptions(select, [], 'загружаю...', '');
	        try {
		          const data = await postJson({
		            action: 'bulk_replace_characteristics',
		            dataset_id: <?= json_encode((int)$row['id']) ?>,
		            offer_ids: offerIds,
		            scope: scope
		          });
	          const items = Array.isArray(data.characteristics) ? data.characteristics : [];
	          setBulkReplaceCharacteristicOptions(
	            select,
	            items,
	            items.length ? 'характеристика' : 'нет характеристик',
	            previousKey
	          );
	        } catch (e) {
	          setBulkReplaceCharacteristicOptions(select, [], 'ошибка загрузки', '');
	          setBulkReplaceStatus(e.message || 'Не удалось загрузить характеристики выбранных товаров.', true, root);
	        }
	      }

	      function scheduleBulkReplaceCharacteristicsLoad(root) {
	        if (scheduleBulkReplaceCharacteristicsLoad._timer) {
	          window.clearTimeout(scheduleBulkReplaceCharacteristicsLoad._timer);
	        }
	        scheduleBulkReplaceCharacteristicsLoad._timer = window.setTimeout(function() {
	          loadBulkReplaceCharacteristics(true, root || null);
	        }, 160);
	      }

	      function setBulkReplaceValuesMessage(panel, message, isError) {
	        if (!panel) return;
	        panel.innerHTML = '';
	        const box = document.createElement('div');
	        box.className = 'muted';
	        box.style.fontSize = '12px';
	        box.style.color = isError ? '#b91c1c' : '';
	        box.textContent = message || '';
	        panel.appendChild(box);
	      }

	      function renderBulkReplaceValues(panel, values) {
	        if (!panel) return;
	        panel.innerHTML = '';
	        const list = Array.isArray(values) ? values : [];
	        if (!list.length) {
	          setBulkReplaceValuesMessage(panel, 'У выбранных товаров нет значений для этого поля.', false);
	          return;
	        }
	        list.forEach(function(item) {
	          const value = String((item && item.value) || '').trim();
	          if (!value) return;
	          const count = Number((item && item.count) || 0);
	          const button = document.createElement('button');
	          button.type = 'button';
	          button.className = 'supplier-bulk-replace-value-option';
	          button.dataset.value = value;
	          const text = document.createElement('span');
	          text.textContent = value;
	          const badge = document.createElement('span');
	          badge.className = 'supplier-bulk-replace-value-count';
	          badge.textContent = count > 0 ? String(count) : '';
	          button.appendChild(text);
	          button.appendChild(badge);
	          panel.appendChild(button);
	        });
	        if (!panel.children.length) {
	          setBulkReplaceValuesMessage(panel, 'У выбранных товаров нет значений для этого поля.', false);
	        }
	      }

      function selectBulkReplaceValue(option) {
        if (!option) return;
        const wrap = option.closest('.supplier-bulk-replace-old-wrap, .supplier-bulk-replace-new-wrap');
        const input = wrap ? (wrap.querySelector('[data-bulk-replace-old]') || wrap.querySelector('[data-bulk-replace-new]')) : null;
        if (input) {
          input.value = option.dataset.value || '';
          input.dispatchEvent(new Event('input', { bubbles: true }));
          input.focus();
        }
        closeBulkReplaceValuePanels();
      }

      function openBulkReplaceAllowedValues(button) {
        const row = button ? button.closest('[data-bulk-replace-row]') : null;
        const wrap = button ? button.closest('.supplier-bulk-replace-new-wrap') : null;
        const panel = wrap ? wrap.querySelector('.supplier-bulk-replace-values-panel') : null;
        const root = bulkReplaceRoot(button);
        if (!row || !panel) return;
        if (panel.classList.contains('is-open')) {
          closeBulkReplaceValuePanels();
          return;
        }
        const values = selectedBulkReplaceAllowedValues(row).map(function(value) {
          return { value: value, count: 0 };
        });
        closeCategoryPickers();
        closeBulkCategoryPanels();
        closeBulkReplaceValuePanels();
        panel.classList.add('is-open');
        if (!values.length) {
          setBulkReplaceValuesMessage(panel, 'Для этой характеристики нет справочника значений.', false);
          updateBulkReplaceAllowedToggle(root);
          return;
        }
        renderBulkReplaceValues(panel, values);
      }

      async function openBulkReplaceValues(button) {
	        const row = button ? button.closest('[data-bulk-replace-row]') : null;
	        const wrap = button ? button.closest('.supplier-bulk-replace-old-wrap') : null;
	        const panel = wrap ? wrap.querySelector('.supplier-bulk-replace-values-panel') : null;
	        const root = bulkReplaceRoot(button);
	        if (!row || !panel) return;
	        if (panel.classList.contains('is-open')) {
	          closeBulkReplaceValuePanels();
	          return;
	        }
		        const scope = bulkReplaceScope(root);
		        const offerIds = selectedOfferIdsForBulkReplace(root);
		        if (scope === 'selected' && !offerIds.length) {
		          window.alert('Сначала выбери товары в таблице.');
		          return;
		        }
	        let target;
	        try {
	          target = targetForBulkReplaceRow(row);
	        } catch (e) {
	          setBulkReplaceStatus(e.message || 'Не выбрано поле для подбора значений.', true, root);
	          return;
	        }
	        closeCategoryPickers();
	        closeBulkCategoryPanels();
	        closeBulkReplaceValuePanels();
	        panel.classList.add('is-open');
	        setBulkReplaceValuesMessage(panel, 'Загружаю значения...', false);
	        try {
		          const data = await postJson({
		            action: 'bulk_replace_values',
		            dataset_id: <?= json_encode((int)$row['id']) ?>,
		            offer_ids: offerIds,
		            scope: scope,
		            target: target
		          });
	          renderBulkReplaceValues(panel, data.values || []);
	        } catch (e) {
	          setBulkReplaceValuesMessage(panel, e.message || 'Не удалось загрузить значения.', true);
	        }
	      }

	      async function runBulkReplace(button) {
	        const row = button ? button.closest('[data-bulk-replace-row]') : null;
	        const root = bulkReplaceRoot(button);
	        if (!row) return;
		        const scope = bulkReplaceScope(root);
		        const offerIds = selectedOfferIdsForBulkReplace(root);
		        if (scope === 'selected' && !offerIds.length) {
		          window.alert('Сначала выбери товары в таблице.');
		          return;
		        }
	        let target;
	        try {
	          target = targetForBulkReplaceRow(row);
	        } catch (e) {
	          setBulkReplaceStatus(e.message || 'Не выбрано поле для замены.', true, root);
	          return;
	        }
	        const oldInput = row.querySelector('[data-bulk-replace-old]');
	        const newInput = row.querySelector('[data-bulk-replace-new]');
	        const oldText = oldInput ? String(oldInput.value || '') : '';
	        const newText = newInput ? String(newInput.value || '') : '';
	        const buttons = Array.from(document.querySelectorAll('[data-bulk-replace-submit]'));
	        buttons.forEach(function(btn) {
	          btn.disabled = true;
	        });
	        setBulkReplaceStatus('Заменяю...', false, root);
	        closeBulkReplaceValuePanels();
	        try {
		          const data = await postJson({
		            action: 'bulk_replace_text',
		            dataset_id: <?= json_encode((int)$row['id']) ?>,
		            offer_ids: offerIds,
		            scope: scope,
		            target: target,
	            old_text: oldText,
	            new_text: newText
	          });
	          const changed = Number(data.products_changed || 0);
	          setBulkReplaceStatus('Обновлено товаров: ' + changed + '.', false, root);
	          showSupplierSuccessToast();
	          if (window.ftSupplierOffersReload) {
	            await window.ftSupplierOffersReload();
	          }
	        } catch (e) {
	          setBulkReplaceStatus(e.message || 'Не удалось выполнить замену.', true, root);
	        } finally {
	          buttons.forEach(function(btn) {
	            btn.disabled = false;
	          });
	        }
	      }

	      function bulkCopyRoot(node) {
	        return node && node.closest ? node.closest('[data-bulk-copy-card]') : document.querySelector('[data-bulk-copy-card]');
	      }

	      function bulkCopyScope(root) {
	        const checked = (root || document).querySelector('input[name^="supplier_bulk_copy_scope"]:checked');
	        return checked && checked.value === 'all' ? 'all' : 'selected';
	      }

	      function selectedOfferIdsForBulkCopy(root) {
	        return bulkCopyScope(root) === 'all' ? [] : selectedOfferIdsForBulkCategory();
	      }

	      function setBulkCopyStatus(root, message, isError) {
	        const status = root ? root.querySelector('[data-bulk-copy-status]') : null;
	        if (!status) return;
	        status.textContent = message || '';
	        status.classList.toggle('is-error', !!isError);
	      }

	      function updateBulkCopyButtonState(root) {
	        const roots = root ? [root] : Array.from(document.querySelectorAll('[data-bulk-copy-card]'));
	        roots.forEach(function(item) {
	          const button = item.querySelector('[data-bulk-copy-run]');
	          if (!button || button.dataset.bulkBusy === '1') return;
	          button.disabled = bulkCopyScope(item) === 'selected' && selectedOfferIdsForBulkCopy(item).length === 0;
	        });
	      }

	      function fieldRefFromBulkCopySelect(select) {
	        if (!select || !select.value) {
	          throw new Error('Выбери поле.');
	        }
	        const option = select.options[select.selectedIndex];
	        const raw = option ? String(option.dataset.ref || '').trim() : '';
	        if (!raw) {
	          throw new Error('Выбери поле.');
	        }
	        try {
	          const ref = JSON.parse(raw);
	          if (!ref || typeof ref !== 'object') throw new Error();
	          return ref;
	        } catch (e) {
	          throw new Error('Не удалось прочитать выбранное поле.');
	        }
	      }

	      function setBulkCopySelectOptions(select, options, placeholder, previousValue) {
	        if (!select) return;
	        select.innerHTML = '';
	        const first = document.createElement('option');
	        first.value = '';
	        first.textContent = placeholder || 'поле';
	        select.appendChild(first);

	        const groups = new Map();
	        (Array.isArray(options) ? options : []).forEach(function(item) {
	          const key = String((item && item.key) || '').trim();
	          const type = String((item && item.type) || '').trim();
	          const kind = String((item && item.kind) || '').trim();
	          const field = String((item && item.field) || '').trim();
	          if (!key || !type || !field) return;
	          const groupLabel = String((item && item.group) || 'Поля');
	          let group = groups.get(groupLabel);
	          if (!group) {
	            group = document.createElement('optgroup');
	            group.label = groupLabel;
	            groups.set(groupLabel, group);
	            select.appendChild(group);
	          }
	          const option = document.createElement('option');
	          option.value = key;
	          option.dataset.ref = JSON.stringify({ type: type, kind: kind, field: field });
	          const count = Number((item && item.count) || 0);
	          option.textContent = String((item && item.label) || field) + (count > 0 ? (' (' + count + ')') : '');
	          group.appendChild(option);
	        });

	        if (previousValue) {
	          select.value = previousValue;
	        }
	      }

	      async function loadBulkCopyOptions(force, root) {
	        if (!root) {
	          const roots = Array.from(document.querySelectorAll('[data-bulk-copy-card]'));
	          for (const item of roots) {
	            await loadBulkCopyOptions(force, item);
	          }
	          return;
	        }
	        const target = root.querySelector('[data-bulk-copy-target]');
	        const source = root.querySelector('[data-bulk-copy-source]');
	        if (!target || !source) return;
	        const scope = bulkCopyScope(root);
	        const offerIds = selectedOfferIdsForBulkCopy(root);
	        const idsKey = scope + ':' + JSON.stringify(offerIds);
	        if (!force && root.dataset.loadedCopyFieldsForIds === idsKey) return;
	        root.dataset.loadedCopyFieldsForIds = idsKey;
	        updateBulkCopyButtonState(root);
	        if (scope === 'selected' && !offerIds.length) {
	          setBulkCopySelectOptions(target, [], 'выбери товары', '');
	          setBulkCopySelectOptions(source, [], 'выбери товары', '');
	          setBulkCopyStatus(root, '', false);
	          return;
	        }

	        const previousTarget = String(target.value || '');
	        const previousSource = String(source.value || '');
	        setBulkCopySelectOptions(target, [], 'загружаю поля...', '');
	        setBulkCopySelectOptions(source, [], 'загружаю поля...', '');
	        try {
	          const data = await postJson({
	            action: 'bulk_copy_field_options',
	            dataset_id: <?= json_encode((int)$row['id']) ?>,
	            offer_ids: offerIds,
	            scope: scope
	          });
	          const items = Array.isArray(data.options) ? data.options : [];
	          const placeholder = items.length ? 'поле' : 'нет полей';
	          setBulkCopySelectOptions(target, items, placeholder, previousTarget);
	          setBulkCopySelectOptions(source, items, placeholder, previousSource);
	          setBulkCopyStatus(root, '', false);
	        } catch (e) {
	          setBulkCopySelectOptions(target, [], 'ошибка загрузки', '');
	          setBulkCopySelectOptions(source, [], 'ошибка загрузки', '');
	          setBulkCopyStatus(root, e.message || 'Не удалось загрузить список полей.', true);
	        }
	      }

	      function scheduleBulkCopyOptionsLoad(root) {
	        if (scheduleBulkCopyOptionsLoad._timer) {
	          window.clearTimeout(scheduleBulkCopyOptionsLoad._timer);
	        }
	        scheduleBulkCopyOptionsLoad._timer = window.setTimeout(function() {
	          loadBulkCopyOptions(true, root || null);
	        }, 160);
	      }

	      async function runBulkCopy(root) {
	        if (!root) return;
	        const scope = bulkCopyScope(root);
	        const offerIds = selectedOfferIdsForBulkCopy(root);
	        if (scope === 'selected' && !offerIds.length) {
	          window.alert('Сначала выбери товары в таблице.');
	          return;
	        }
	        const targetSelect = root.querySelector('[data-bulk-copy-target]');
	        const sourceSelect = root.querySelector('[data-bulk-copy-source]');
	        let target;
	        let source;
	        try {
	          target = fieldRefFromBulkCopySelect(targetSelect);
	          source = fieldRefFromBulkCopySelect(sourceSelect);
	          if (String(targetSelect.value || '') === String(sourceSelect.value || '')) {
	            throw new Error('Выбери разные поля: куда записать и откуда взять.');
	          }
	        } catch (e) {
	          setBulkCopyStatus(root, e.message || 'Выбери оба поля.', true);
	          return;
	        }

	        const button = root.querySelector('[data-bulk-copy-run]');
	        if (button) {
	          button.dataset.bulkBusy = '1';
	          button.disabled = true;
	        }
	        setBulkCopyStatus(root, 'Заполняю значения...', false);
	        showSupplierBusyToast();
	        try {
	          const skipEmpty = root.querySelector('[data-bulk-copy-skip-empty]');
	          const data = await postJson({
	            action: 'bulk_copy_field_values',
	            dataset_id: <?= json_encode((int)$row['id']) ?>,
	            offer_ids: offerIds,
	            scope: scope,
	            target: target,
	            source: source,
	            skip_empty: skipEmpty && skipEmpty.checked ? 1 : 0
	          });
	          const changed = Number(data.products_changed || 0);
	          const skipped = Number(data.empty_skipped || 0);
	          setBulkCopyStatus(root, 'Обновлено товаров: ' + changed + (skipped > 0 ? (', пустых пропущено: ' + skipped) : '') + '.', false);
	          showSupplierSuccessToast();
	          if (window.ftSupplierOffersReload) {
	            await window.ftSupplierOffersReload();
	          }
	          scheduleBulkCopyOptionsLoad(root);
	          scheduleBulkReplaceCharacteristicsLoad();
	        } catch (e) {
	          hideSupplierBusyToast();
	          setBulkCopyStatus(root, e.message || 'Не удалось заполнить значения.', true);
	        } finally {
	          if (button) {
	            delete button.dataset.bulkBusy;
	            button.disabled = false;
	          }
	          updateBulkCopyButtonState(root);
	        }
	      }

				      document.addEventListener('supplier-selection-change', function() {
				        updateBulkCategoryButtonState();
				        updateBulkTnvedButtonState();
				        scheduleBulkReplaceCharacteristicsLoad();
				        updateBulkOfferControlsButtonState();
				        updateBulkCopyButtonState();
				        scheduleBulkCopyOptionsLoad();
				      });
				      updateBulkCategoryButtonState();
				      updateBulkTnvedButtonState();
				      scheduleBulkReplaceCharacteristicsLoad();
				      updateBulkOfferControlsButtonState();
				      updateBulkCopyButtonState();
				      scheduleBulkCopyOptionsLoad();

		      let bulkCategoryWidgetDrag = null;
		      document.addEventListener('pointerdown', function(e) {
		        const handle = e.target && e.target.closest ? e.target.closest('[data-bulk-category-widget-handle]') : null;
		        if (!handle || (e.target && e.target.closest && e.target.closest('button'))) return;
		        const widget = handle.closest('[data-bulk-category-widget]');
		        if (!widget) return;
		        const rect = widget.getBoundingClientRect();
		        bulkCategoryWidgetDrag = {
		          widget: widget,
		          dx: e.clientX - rect.left,
		          dy: e.clientY - rect.top
		        };
		        widget.classList.add('is-dragging');
		        if (handle.setPointerCapture && e.pointerId !== undefined) {
		          try { handle.setPointerCapture(e.pointerId); } catch (err) {}
		        }
		        e.preventDefault();
		      });
		      document.addEventListener('pointermove', function(e) {
		        if (!bulkCategoryWidgetDrag) return;
		        placeBulkCategoryWidget(
		          bulkCategoryWidgetDrag.widget,
		          e.clientX - bulkCategoryWidgetDrag.dx,
		          e.clientY - bulkCategoryWidgetDrag.dy
		        );
		        e.preventDefault();
		      });
		      document.addEventListener('pointerup', function() {
		        if (!bulkCategoryWidgetDrag) return;
		        bulkCategoryWidgetDrag.widget.classList.remove('is-dragging');
		        saveBulkCategoryWidgetPosition(bulkCategoryWidgetDrag.widget);
		        bulkCategoryWidgetDrag = null;
		      });
		      let bulkReplaceWidgetDrag = null;
		      document.addEventListener('pointerdown', function(e) {
		        const handle = e.target && e.target.closest ? e.target.closest('[data-bulk-replace-widget-handle]') : null;
		        if (!handle || (e.target && e.target.closest && e.target.closest('button'))) return;
		        const widget = handle.closest('[data-bulk-replace-widget]');
		        if (!widget) return;
		        const rect = widget.getBoundingClientRect();
		        bulkReplaceWidgetDrag = {
		          widget: widget,
		          dx: e.clientX - rect.left,
		          dy: e.clientY - rect.top
		        };
		        widget.classList.add('is-dragging');
		        if (handle.setPointerCapture && e.pointerId !== undefined) {
		          try { handle.setPointerCapture(e.pointerId); } catch (err) {}
		        }
		        e.preventDefault();
		      });
		      document.addEventListener('pointermove', function(e) {
