	          return;
	        }

	        const modalPictureRemove = e.target && e.target.closest ? e.target.closest('.supplier-picture-modal-remove') : null;
	        if (modalPictureRemove) {
	          deletePictureFromModal(modalPictureRemove.closest('.supplier-picture-modal-thumb'));
	          return;
	        }

	        const modalPictureThumb = e.target && e.target.closest ? e.target.closest('.supplier-picture-modal-thumb') : null;
	        if (modalPictureThumb) {
	          pictureModalCurrentUrl = modalPictureThumb.dataset.url || '';
	          renderPictureModal();
	          return;
	        }

	        const pictureLink = e.target && e.target.closest ? e.target.closest('.supplier-picture-item a') : null;
	        if (pictureLink) {
	          e.preventDefault();
	          openPictureModal(pictureLink.closest('.supplier-picture-item'));
	          return;
	        }

        const fieldValuesToggle = e.target && e.target.closest ? e.target.closest('[data-field-values-toggle]') : null;
        if (fieldValuesToggle) {
          openFieldValueSuggestions(fieldValuesToggle);
          return;
        }

        const fieldValueOption = e.target && e.target.closest ? e.target.closest('.supplier-field-value-option') : null;
        if (fieldValueOption) {
          selectFieldAllowedValue(fieldValueOption).catch(function(err) {
            alert((err && err.message) ? err.message : 'Не удалось сохранить значение.');
          });
          return;
        }

        const fieldValueWrap = e.target && e.target.closest ? e.target.closest('.supplier-field-value-wrap') : null;
        if (fieldValueWrap) {
          return;
        }

		        const fieldDisplay = e.target && e.target.closest ? e.target.closest('.supplier-field-display') : null;
		        if (fieldDisplay) {
	          const brandEditor = fieldDisplay.closest('[data-brand-editor]');
	          beginFieldEdit(fieldDisplay.closest('.supplier-field-row'), 'value');
	          if (brandEditor) {
	            openBrandSuggestions(brandEditor, { keepOpen: true });
	          }
	          return;
        }

        const fieldDelete = e.target && e.target.closest ? e.target.closest('.supplier-field-delete') : null;
        if (fieldDelete) {
          deleteFieldRow(fieldDelete.closest('.supplier-field-row'), false);
          return;
        }

        const addFieldBtn = e.target && e.target.closest ? e.target.closest('.supplier-field-add') : null;
        if (addFieldBtn) {
          addField(addFieldBtn);
          return;
        }

		        closeCategoryPickers();
		        closeBulkCategoryPanels();
		        closeBulkReplaceValuePanels();
		        closeFieldValuePanels();
		        closeBrandSuggestionPanels();
	        if (!(e.target && e.target.closest && e.target.closest('.supplier-edit-wrap'))) {
	          closeRichEditors(null);
	        }
      });

		      document.addEventListener('change', function(e) {
        if (e.target && e.target.matches && e.target.matches('[data-bulk-replace-characteristic]')) {
          updateBulkReplaceAllowedToggle(bulkReplaceRoot(e.target));
        }
		        const input = e.target && e.target.matches ? (e.target.matches('.supplier-picture-file') ? e.target : null) : null;
		        if (!input) return;
        const file = input.files && input.files[0] ? input.files[0] : null;
        if (file) {
          uploadPictureFile(input.closest('.supplier-pictures-editor'), file);
        }
	        input.value = '';
	      });

	      document.addEventListener('keydown', function(e) {
		        if (e.key === 'Escape') {
		          closeBrandSuggestionPanels();
          closeBulkReplaceValuePanels();
          closeFieldValuePanels();
		          closePictureModal();
          closeVideoCoverModal();
          closeBundleModal();
		        }
	      });

	      window.addEventListener('resize', function() {
	        document.querySelectorAll('.supplier-brand-suggest-panel.open').forEach(function(panel) {
	          if (panel.__brandSuggestEditor) positionBrandSuggestionPanel(panel.__brandSuggestEditor);
	        });
	      });

	      window.addEventListener('scroll', function() {
	        document.querySelectorAll('.supplier-brand-suggest-panel.open').forEach(function(panel) {
	          if (panel.__brandSuggestEditor) positionBrandSuggestionPanel(panel.__brandSuggestEditor);
	        });
	      }, true);

	      document.addEventListener('dragstart', function(e) {
	        const modalThumb = e.target && e.target.closest ? e.target.closest('.supplier-picture-modal-thumb') : null;
	        if (modalThumb) {
	          modalThumb.classList.add('is-dragging');
	          if (e.dataTransfer) {
	            e.dataTransfer.effectAllowed = 'move';
	            e.dataTransfer.setData('text/plain', modalThumb.dataset.url || '');
	            setQuietDragImage(e);
	          }
	          return;
	        }

	        const item = e.target && e.target.closest ? e.target.closest('.supplier-picture-item') : null;
	        if (!item) return;
        const editor = item.closest('.supplier-pictures-editor');
        if (!editor || !editor.classList.contains('is-expanded')) {
          e.preventDefault();
          return;
        }
	        item.classList.add('is-dragging');
	        if (e.dataTransfer) {
	          e.dataTransfer.effectAllowed = 'move';
	          e.dataTransfer.setData('text/plain', item.dataset.url || '');
	          setQuietDragImage(e);
	        }
	      });

	      document.addEventListener('dragover', function(e) {
	        const modalOver = e.target && e.target.closest ? e.target.closest('.supplier-picture-modal-thumb') : null;
	        if (modalOver) {
	          const modal = modalOver.closest('.supplier-picture-modal');
	          const dragging = modal ? modal.querySelector('.supplier-picture-modal-thumb.is-dragging') : null;
	          if (!dragging || dragging === modalOver) return;
	          e.preventDefault();
	          modalOver.classList.add('is-drag-over');
	          const rect = modalOver.getBoundingClientRect();
	          const before = e.clientX < rect.left + rect.width / 2;
	          const next = before ? modalOver : modalOver.nextSibling;
	          if (next !== dragging) {
	            animatePictureReorder(modalOver.parentNode, function() {
	              modalOver.parentNode.insertBefore(dragging, next);
	            });
	          }
	          return;
	        }

	        const over = e.target && e.target.closest ? e.target.closest('.supplier-picture-item') : null;
	        if (!over) return;
        const editor = over.closest('.supplier-pictures-editor');
        const dragging = editor ? editor.querySelector('.supplier-picture-item.is-dragging') : null;
        if (!editor || !dragging || dragging === over) return;
	        e.preventDefault();
	        over.classList.add('is-drag-over');
	        const rect = over.getBoundingClientRect();
	        const before = e.clientY < rect.top + rect.height / 2;
	        const next = before ? over : over.nextSibling;
	        if (next !== dragging) {
	          animatePictureReorder(over.parentNode, function() {
	            over.parentNode.insertBefore(dragging, next);
	          });
	        }
	      });

	      document.addEventListener('dragleave', function(e) {
	        const modalThumb = e.target && e.target.closest ? e.target.closest('.supplier-picture-modal-thumb') : null;
	        if (modalThumb) modalThumb.classList.remove('is-drag-over');
	        const item = e.target && e.target.closest ? e.target.closest('.supplier-picture-item') : null;
	        if (item) item.classList.remove('is-drag-over');
	      });

	      document.addEventListener('drop', function(e) {
	        const modal = e.target && e.target.closest ? e.target.closest('.supplier-picture-modal') : null;
	        if (modal && modal.querySelector('.supplier-picture-modal-thumb.is-dragging')) {
	          e.preventDefault();
	          modal.querySelectorAll('.supplier-picture-modal-thumb').forEach(function(item) {
	            item.classList.remove('is-dragging', 'is-drag-over');
	          });
	          savePictureModalOrder();
	          return;
	        }

	        const editor = e.target && e.target.closest ? e.target.closest('.supplier-pictures-editor') : null;
	        if (!editor) return;
        e.preventDefault();
        editor.querySelectorAll('.supplier-picture-item').forEach(function(item) {
          item.classList.remove('is-dragging', 'is-drag-over');
        });
        savePictureOrder(editor);
	      });

	      document.addEventListener('dragend', function(e) {
	        if (pictureModal) {
	          pictureModal.querySelectorAll('.supplier-picture-modal-thumb').forEach(function(item) {
	            item.classList.remove('is-dragging', 'is-drag-over');
	          });
	        }
	        const editor = e.target && e.target.closest ? e.target.closest('.supplier-pictures-editor') : null;
	        if (!editor) return;
        editor.querySelectorAll('.supplier-picture-item').forEach(function(item) {
          item.classList.remove('is-dragging', 'is-drag-over');
        });
      });
    })();
  </script>

  <script>
    (function() {
      if (window.__ftOfferSelectionInit) return;
      window.__ftOfferSelectionInit = true;

      const datasetId = <?= json_encode((string)$row['id']) ?>;
      const storageKey = 'feedtools_selected_offers_' + datasetId;

      const initialSelectionTotal = <?= json_encode((int)$selectionOffersTotal) ?>;

      // Loaded on demand when the user selects the whole filtered set.
      let matchingIdsLoading = false;
      let matchingIdsCache = null;
      let selectionVersion = 0;
      let cachedSelectedIdsVersion = -1;
      let cachedSelectedIds = [];
      let cachedSelectedIdsJsonVersion = -1;
      let cachedSelectedIdsJson = '[]';
      let lastSavedSelectedIdsJson = null;
      let lastSelectionEventVersion = -1;


      function loadSet() {
        try {
          const raw = localStorage.getItem(storageKey);
          if (!raw) return new Set();
          const arr = JSON.parse(raw);
          if (!Array.isArray(arr)) return new Set();
          return new Set(arr.map(String));
        } catch (e) {
          return new Set();
        }
      }

      function markSelectionChanged() {
        selectionVersion += 1;
        cachedSelectedIdsVersion = -1;
        cachedSelectedIdsJsonVersion = -1;
      }

      function selectedIdsArray() {
        if (cachedSelectedIdsVersion !== selectionVersion) {
          cachedSelectedIds = Array.from(set.values());
          cachedSelectedIdsVersion = selectionVersion;
        }
        return cachedSelectedIds;
      }

      function selectedIdsJsonArray() {
        if (cachedSelectedIdsJsonVersion !== selectionVersion) {
          cachedSelectedIdsJson = JSON.stringify(selectedIdsArray());
          cachedSelectedIdsJsonVersion = selectionVersion;
        }
        return cachedSelectedIdsJson;
      }

      function saveSet() {
        try {
          const value = selectedIdsJsonArray();
          if (value === lastSavedSelectedIdsJson) return;
          localStorage.setItem(storageKey, value);
          lastSavedSelectedIdsJson = value;
        } catch (e) {}
      }

      const set = loadSet();

      function offersTableRegion() {
        return document.querySelector('[data-offers-table-region]');
      }

      function currentSelectionTotal() {
        const region = offersTableRegion();
        const raw = region && region.dataset ? region.dataset.selectionTotal : '';
        const value = parseInt(String(raw || ''), 10);
        return Number.isFinite(value) && value >= 0 ? value : initialSelectionTotal;
      }

      function parseMatchingIds(raw) {
        try {
          const parsed = JSON.parse(String(raw || '[]'));
          if (Array.isArray(parsed)) {
            return Array.from(new Set(parsed.map((id) => String(id || '').trim()).filter(Boolean)));
          }
        } catch (e) {}
        return [];
      }

      function currentMatchingIds() {
        if (Array.isArray(matchingIdsCache)) {
          return matchingIdsCache.slice();
        }
        const region = offersTableRegion();
        if (region && region.hasAttribute('data-matching-offer-ids')) {
          return parseMatchingIds(region.getAttribute('data-matching-offer-ids') || '[]');
        }
        return [];
      }

      function currentMatchingIdsTruncated() {
        const region = offersTableRegion();
        if (!region || !region.hasAttribute('data-matching-offer-ids-truncated')) return false;
        return String(region.getAttribute('data-matching-offer-ids-truncated') || '') === '1';
      }

      function currentMatchingIdsLoaded() {
        const region = offersTableRegion();
        return !!(region && String(region.getAttribute('data-matching-offer-ids-loaded') || '') === '1');
      }

      function matchingIdsEndpointUrl() {
        const url = new URL(window.location.href);
        url.searchParams.set('id', datasetId);
        url.searchParams.set('offers_ajax', 'matching_ids');
        return url.toString();
      }

      async function loadCurrentMatchingIds() {
        if (currentMatchingIdsLoaded() && Array.isArray(matchingIdsCache)) {
          return currentMatchingIds();
        }
        const region = offersTableRegion();
        if (!region) return [];
        const response = await fetch(matchingIdsEndpointUrl(), {
          method: 'GET',
          credentials: 'same-origin',
          headers: {
            'Accept': 'application/json',
            'X-Requested-With': 'XMLHttpRequest'
          }
        });
        if (!response.ok) {
          throw new Error('HTTP ' + response.status);
        }
        const payload = await response.json();
        if (!payload || payload.ok !== true) {
          throw new Error((payload && payload.error) ? String(payload.error) : 'Не удалось получить список товаров.');
        }
        if (payload.truncated) {
          region.setAttribute('data-matching-offer-ids-truncated', '1');
          throw new Error('Слишком много товаров для выбора всех сразу.');
        }
        const ids = Array.isArray(payload.ids)
          ? Array.from(new Set(payload.ids.map((id) => String(id || '').trim()).filter(Boolean)))
          : [];
        matchingIdsCache = ids;
        region.setAttribute('data-matching-offer-ids-loaded', '1');
        if (payload.selection_total !== undefined && region.dataset) {
          region.dataset.selectionTotal = String(payload.selection_total || '');
        }
        return ids;
      }

      function updateSelectAllButtonState() {
        const button = document.getElementById('btnSelectAllAllPages');
        if (!button) return;
        const truncated = currentMatchingIdsTruncated();
        button.disabled = truncated || matchingIdsLoading;
        button.title = truncated
          ? 'Слишком много товаров для выбора всех сразу'
          : 'Выбрать все товары из текущего набора (все страницы)';
      }

      function selectedHiddenInput() {
        return document.getElementById('offerIdsJson');
      }

      function contentScopeInputs() {
        return Array.from(document.querySelectorAll('input[name="supplier_content_scope"]'));
      }

      function currentContentScope() {
        const checked = contentScopeInputs().find(input => input.checked);
        return checked ? String(checked.value || 'selected') : 'selected';
      }

      function visibleOfferIds() {
        return Array.from(document.querySelectorAll('input.offerChk[data-offer-id]'))
          .filter(chk => !chk.disabled)
          .map(chk => String(chk.getAttribute('data-offer-id') || '').trim())
          .filter(Boolean);
      }

      function updateBadgeAndHidden() {
        const count = set.size;
        const txt = 'выбрано: ' + count + ' из ' + currentSelectionTotal();
        const idsValue = count ? selectedIdsJsonArray() : '';
        const contentScope = currentContentScope();
        const contentIdsValue = contentScope === 'selected' ? idsValue : '';
        document.querySelectorAll('.selectedCountBadge').forEach(el => {
          el.textContent = txt;
        });
        const hidden = selectedHiddenInput();
        if (hidden && hidden.value !== idsValue) hidden.value = idsValue;
        document.querySelectorAll('[data-offer-ids-json]').forEach(input => {
          if (input.value !== contentIdsValue) input.value = contentIdsValue;
        });
        if (lastSelectionEventVersion !== selectionVersion) {
          lastSelectionEventVersion = selectionVersion;
          document.dispatchEvent(new CustomEvent('supplier-selection-change', {
            detail: {
              count: count
            }
          }));
        }
      }

      function updateRowCheckboxesFromSet() {
        document.querySelectorAll('input.offerChk[data-offer-id]').forEach(chk => {
          const id = String(chk.getAttribute('data-offer-id') || '');
          if (!id) return;
          chk.checked = set.has(id);
        });
      }

      function updateMasterCheckboxState() {
        const chkAllPage = document.getElementById('chkAllPage');
        if (!chkAllPage) return;
        const pageBoxes = Array.from(document.querySelectorAll('input.offerChk[data-offer-id]')).filter(x => !x.disabled);
        const allChecked = pageBoxes.length > 0 && pageBoxes.every(x => x.checked);
        const anyChecked = pageBoxes.some(x => x.checked);
        chkAllPage.indeterminate = anyChecked && !allChecked;
        chkAllPage.checked = allChecked;
      }

      function renderAll() {
        updateRowCheckboxesFromSet();
        updateBadgeAndHidden();
        updateMasterCheckboxState();
        updateSelectAllButtonState();
      }

      document.addEventListener('change', function(ev) {
        const t = ev.target;
        if (!(t instanceof HTMLInputElement)) return;

        if (t.classList.contains('offerChk')) {
          const id = String(t.getAttribute('data-offer-id') || '');
          if (!id) return;

          const had = set.has(id);
          if (t.checked && !had) {
            set.add(id);
            markSelectionChanged();
          } else if (!t.checked && had) {
            set.delete(id);
            markSelectionChanged();
          }

          saveSet();
          updateBadgeAndHidden();
          updateMasterCheckboxState();
          return;
        }

        if (t.id === 'chkAllPage') {
          const pageBoxes = Array.from(document.querySelectorAll('input.offerChk[data-offer-id]')).filter(x => !x.disabled);
          let changed = false;
          if (t.checked) {
            pageBoxes.forEach(x => {
              const id = String(x.getAttribute('data-offer-id') || '').trim();
              if (id && !set.has(id)) {
                set.add(id);
                changed = true;
              }
            });
          } else {
            pageBoxes.forEach(x => {
              const id = String(x.getAttribute('data-offer-id') || '').trim();
              if (id && set.delete(id)) changed = true;
            });
          }
          if (changed) markSelectionChanged();
          saveSet();
          renderAll();
          return;
        }
      });

      document.addEventListener('click', async function(ev) {
        const target = ev.target && ev.target.closest ? ev.target.closest('#btnClearSelection, #btnSelectAllAllPages') : null;
        if (!target) return;
        ev.preventDefault();

        if (target.id === 'btnClearSelection') {
          if (set.size) {
            set.clear();
            markSelectionChanged();
          }
          saveSet();
          renderAll();
          return;
        }

        if (target.id === 'btnSelectAllAllPages') {
          const originalText = target.textContent;
          matchingIdsLoading = true;
          target.textContent = 'Выбираю...';
          updateSelectAllButtonState();
          let ids = [];
          try {
            ids = await loadCurrentMatchingIds();
          } catch (e) {
            alert((e && e.message) ? e.message : 'Не удалось выбрать товары из текущей выборки.');
            return;
          } finally {
            matchingIdsLoading = false;
            target.textContent = originalText;
            updateSelectAllButtonState();
          }
          if (!ids.length) ids = visibleOfferIds();
          if (!ids.length) return;
          set.clear();
          for (const id of ids) {
            const s = String(id || '').trim();
            if (s) set.add(s);
          }
          markSelectionChanged();
          saveSet();
          renderAll();
        }
      });

      document.querySelectorAll('form[data-queue-aware="1"]').forEach(function(form) {
        form.addEventListener('submit', function() {
          updateBadgeAndHidden();
        });
      });

      document.addEventListener('change', function(ev) {
        const t = ev.target;
        if (t instanceof HTMLInputElement && t.name === 'supplier_content_scope') {
          updateBadgeAndHidden();
        }
      });

      document.addEventListener('supplier-offers-table-replaced', function() {
        matchingIdsCache = null;
        renderAll();
      });
      renderAll();
    })();
  </script>

  <script>
    (function() {
      const forms = Array.from(document.querySelectorAll('form[data-queue-aware="1"]'));
      if (!forms.length) return;

      function formatWait(sec) {
        sec = Number(sec || 0);
        if (!isFinite(sec) || sec <= 0) return 'меньше минуты';
        sec = Math.round(sec);
        const h = Math.floor(sec / 3600);
        const m = Math.floor((sec % 3600) / 60);
        const s = sec % 60;
        if (h > 0) return h + ' ч ' + String(m).padStart(2, '0') + ' мин';
        if (m > 0) return m + ' мин ' + String(s).padStart(2, '0') + ' сек';
        return s + ' сек';
      }

      async function fetchQueueSummary(form, signal) {
        const datasetId = String(form.querySelector('[name="dataset_id"]')?.value || '').trim();
        const opField = form.querySelector('[name="op_type"]');
        const opType = String(form.dataset.opType || (opField ? opField.value : '') || '').trim();
        if (!datasetId) return null;

        const params = new URLSearchParams();
        params.set('dataset_id', datasetId);
        if (opType) params.set('op_type', opType);

        const options = {
          cache: 'no-store',
          headers: { 'X-Requested-With': 'XMLHttpRequest' }
        };
        if (signal) {
          options.signal = signal;
        }
        const res = await fetch('queue_status.php?' + params.toString(), options);
        if (!res.ok) {
          throw new Error('Queue status request failed');
        }
        return await res.json();
      }

      async function fetchQueueSummaryWithTimeout(form) {
        if (typeof AbortController === 'undefined') {
          return await fetchQueueSummary(form, null);
        }
        const controller = new AbortController();
        const timeout = window.setTimeout(function() {
          controller.abort();
        }, 3500);
        try {
          return await fetchQueueSummary(form, controller.signal);
        } finally {
          window.clearTimeout(timeout);
        }
      }

      function submitBypassingQueue(form) {
        form.dataset.queueBypass = '1';
        form.submit();
      }

      forms.forEach(function(form) {
        form.addEventListener('submit', async function(e) {
          if (form.dataset.queueBypass === '1') return;
          if (form.dataset.queueChecking === '1') {
            e.preventDefault();
            return;
          }

          e.preventDefault();
          form.dataset.queueChecking = '1';

          let summary = null;
          try {
            summary = await fetchQueueSummaryWithTimeout(form);
          } catch (err) {
            submitBypassingQueue(form);
            return;
          }

          if (!summary || !summary.will_wait) {
            submitBypassingQueue(form);
            return;
          }

          const lines = [
            summary.dataset_blocked
              ? 'Операция не начнётся сразу, потому что по этому датасету уже выполняется другая задача.'
              : 'Операция не начнётся сразу, потому что сейчас заняты worker-слоты.',
            ''
          ];

          const blocker = summary.dataset_blocker || summary.blocker || null;
          if (blocker && blocker.id) {
            let blockerLine = 'Сейчас работает операция #' + blocker.id;
            if (blocker.op_type) blockerLine += ' (' + blocker.op_type + ')';
            if (blocker.dataset_id) blockerLine += ' по датасету #' + blocker.dataset_id;
            lines.push(blockerLine);
          }

          if (Number(summary.ahead_count || 0) > 0) {
            lines.push('Операций впереди: ' + summary.ahead_count);
          }

          if (Number(summary.max_parallel || 0) > 0) {
            lines.push('Параллельных worker-слотов: ' + summary.max_parallel);
          }

          lines.push('Примерное ожидание старта: ' + formatWait(summary.estimated_wait_sec || 0));
          lines.push('');
          lines.push('Запустить и поставить задачу в очередь?');

          if (!window.confirm(lines.join('\n'))) {
            delete form.dataset.queueChecking;
            return;
          }

          submitBypassingQueue(form);
        });
      });
    })();
  </script>

  <script>
    (function() {
      if (window.__ftAssignOzonCategoryInit) return;
      window.__ftAssignOzonCategoryInit = true;

      const btnAssign = document.getElementById('btnAssignOzonCategory');
      const btnClear = document.getElementById('btnClearOzonCategory');
      const hint = document.getElementById('assignOzonCategoryHint');

      const catHidden = document.getElementById('ozonTaxonomySelected'); // выбранная категория (value)
      const selectedIdsHidden = document.getElementById('offerIdsJson'); // JSON выбранных offer id (из selection-скрипта)

      const form = document.getElementById('formAssignOzonCategory');
      const fIds = document.getElementById('assignOfferIdsJson');
      const fCat = document.getElementById('assignOzonCategoryValue');
      const fClear = document.getElementById('assignOzonCategoryClear');

      if (!btnAssign || !btnClear || !form || !fIds || !fCat || !fClear || !catHidden || !selectedIdsHidden) return;

      function setHint(text, isError) {
        if (!hint) return;
        hint.textContent = text || '';
        hint.style.color = isError ? '#b91c1c' : '';
      }

      function ensureSelection() {
        const idsJson = String(selectedIdsHidden.value || '').trim();
        if (!idsJson) {
          setHint('Нужно выбрать товары галочками (сейчас выбрано: 0 из <?= h((string)$selectionOffersTotal) ?>).', true);
          return '';
        }
        return idsJson;
      }

      btnAssign.addEventListener('click', function() {
